def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _crc32c_raw(data: bytes, seed: int = 0xFFFF_FFFF) -> int:
    crc = seed
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = (crc >> 1) ^ (0x82F63B78 if crc & 1 else 0)
    return crc & 0xFFFF_FFFF


def _write_sparse_bytes(
    path: Path, data: bytes | bytearray, *, durable: bool = False
) -> None:
    """Serialize exact bytes without allocating runs that are entirely zero."""
    view = memoryview(data)
    chunk_size = 64 * 1024
    with path.open("wb") as destination:
        destination.truncate(len(view))
        for offset in range(0, len(view), chunk_size):
            chunk = view[offset : offset + chunk_size]
            if not any(chunk):
                continue
            destination.seek(offset)
            written = destination.write(chunk)
            if written != len(chunk):
                raise OSError(
                    f"short sparse image write: {written} of {len(chunk)} bytes"
                )
        destination.flush()
        if durable:
            os.fsync(destination.fileno())


def _copy_sparse_file(source: Path, destination: Path) -> None:
    """Copy a disk image while preserving filesystem holes when supported."""
    size = source.stat().st_size
    if not hasattr(os, "SEEK_DATA") or not hasattr(os, "SEEK_HOLE"):
        shutil.copyfile(source, destination)
        return

    unsupported = {errno.EINVAL, errno.ENOTSUP, errno.EOPNOTSUPP}
    extents: list[tuple[int, int]] = []
    with source.open("rb") as source_file:
        offset = 0
        while offset < size:
            try:
                data_offset = os.lseek(source_file.fileno(), offset, os.SEEK_DATA)
            except OSError as error:
                if error.errno == errno.ENXIO:
                    break
                if error.errno in unsupported:
                    shutil.copyfile(source, destination)
                    return
                raise
            try:
                hole_offset = os.lseek(
                    source_file.fileno(), data_offset, os.SEEK_HOLE
                )
            except OSError as error:
                if error.errno == errno.ENXIO:
                    hole_offset = size
                elif error.errno in unsupported:
                    shutil.copyfile(source, destination)
                    return
                else:
                    raise
            extent_end = min(hole_offset, size)
            extents.append((data_offset, extent_end))
            offset = extent_end

        with destination.open("wb") as destination_file:
            destination_file.truncate(size)
            for extent_start, extent_end in extents:
                source_file.seek(extent_start)
                destination_file.seek(extent_start)
                remaining = extent_end - extent_start
                while remaining:
                    chunk = source_file.read(min(1 << 20, remaining))
                    if not chunk:
                        raise OSError("short sparse image read")
                    written = destination_file.write(chunk)
                    if written != len(chunk):
                        raise OSError(
                            "short sparse image copy: "
                            f"{written} of {len(chunk)} bytes"
                        )
                    remaining -= len(chunk)

    if destination.stat().st_size != size:
        raise OSError("sparse image copy changed the logical size")


def _jbd2_metadata_with_checksum(
    block: bytes | bytearray, journal_uuid: bytes
) -> bytes:
    """Stamp a checksum-v2/v3 descriptor or revoke block."""
    assert len(journal_uuid) == 16
    result = bytearray(block)
    assert len(result) >= 1024
    struct.pack_into(">I", result, len(result) - 4, 0)
    seed = _crc32c_raw(journal_uuid)
    struct.pack_into(">I", result, len(result) - 4, _crc32c_raw(result, seed))
    return bytes(result)


def _jbd2_commit_with_checksum(
    block: bytes | bytearray, journal_uuid: bytes, sequence: int
) -> bytes:
    """Restamp a checksum-v2/v3 commit block for one transaction ID."""
    assert len(journal_uuid) == 16
    result = bytearray(block)
    assert len(result) >= 1024
    assert struct.unpack_from(">II", result, 0x00) == (0xC03B3998, 2)
    struct.pack_into(">I", result, 0x08, sequence & 0xFFFF_FFFF)
    struct.pack_into(">I", result, 0x10, 0)
    seed = _crc32c_raw(journal_uuid)
    struct.pack_into(">I", result, 0x10, _crc32c_raw(result, seed))
    return bytes(result)


def _relocate_jbd2_transaction(
    source: Path,
    destination: Path,
    physical_map: dict[int, int],
    destination_slots: tuple[int, int, int],
) -> None:
    """Move one debugfs-authored descriptor/data/commit tuple unchanged."""
    block_size = 1024
    source_slots = (1, 2, 3)
    assert len(set(destination_slots)) == 3
    assert 0 not in destination_slots
    with source.open("rb") as image:
        transaction = []
        for logical in source_slots:
            image.seek(physical_map[logical] * block_size)
            transaction.append(image.read(block_size))
        image.seek(physical_map[0] * block_size)
        journal_superblock = bytearray(image.read(block_size))
    assert all(len(block) == block_size for block in transaction)
    assert struct.unpack_from(">I", transaction[0], 0x00)[0] == 0xC03B3998
    assert struct.unpack_from(">I", transaction[0], 0x04)[0] == 1
    assert struct.unpack_from(">I", transaction[2], 0x00)[0] == 0xC03B3998
    assert struct.unpack_from(">I", transaction[2], 0x04)[0] == 2
    assert struct.unpack_from(">I", transaction[0], 0x08)[0] == struct.unpack_from(
        ">I", transaction[2], 0x08
    )[0]

    _copy_sparse_file(source, destination)
    with destination.open("r+b") as image:
        for logical in source_slots:
            if logical not in destination_slots:
                image.seek(physical_map[logical] * block_size)
                image.write(bytes(block_size))
        for block, logical in zip(transaction, destination_slots, strict=True):
            image.seek(physical_map[logical] * block_size)
            image.write(block)
        struct.pack_into(">I", journal_superblock, 0x1C, destination_slots[0])
        struct.pack_into(">I", journal_superblock, 0xFC, 0)
        struct.pack_into(">I", journal_superblock, 0xFC, _crc32c_raw(journal_superblock))
        image.seek(physical_map[0] * block_size)
        image.write(journal_superblock)


def _ext4_super_with_checksum(superblock: bytes | bytearray) -> bytes:
    result = bytearray(superblock)
    assert len(result) == 1024
    struct.pack_into("<I", result, 0x3FC, _crc32c_raw(result[:0x3FC]))
    return bytes(result)


def _group_descriptor_with_checksum(
    superblock: bytes, descriptor: bytes | bytearray, group: int
) -> bytes:
    result = bytearray(descriptor)
    assert len(superblock) == 1024
    assert len(result) == 64
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    struct.pack_into("<H", result, 0x1E, 0)
    checksum = _crc32c_raw(struct.pack("<I", group), seed)
    checksum = _crc32c_raw(result, checksum)
    struct.pack_into("<H", result, 0x1E, checksum & 0xFFFF)
    return bytes(result)


def _inode_with_checksum(
    superblock: bytes, inode_number: int, inode: bytes | bytearray
) -> bytes:
    result = bytearray(inode)
    assert len(superblock) == 1024
    assert len(result) >= 128
    assert inode_number > 0
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    struct.pack_into("<H", result, 0x7C, 0)
    has_checksum_high = len(result) > 128
    if has_checksum_high:
        extra_size = struct.unpack_from("<H", result, 0x80)[0]
        assert extra_size >= 4 and extra_size % 4 == 0
        assert 128 + extra_size <= len(result)
        struct.pack_into("<H", result, 0x82, 0)
    checksum = _crc32c_raw(struct.pack("<I", inode_number), seed)
    checksum = _crc32c_raw(result[0x64:0x68], checksum)
    checksum = _crc32c_raw(result, checksum)
    struct.pack_into("<H", result, 0x7C, checksum & 0xFFFF)
    if has_checksum_high:
        struct.pack_into("<H", result, 0x82, checksum >> 16)
    return bytes(result)


def _external_xattr_block_with_checksum(
    superblock: bytes,
    physical_block: int,
    block: bytes | bytearray,
) -> bytes:
    """Validate and restamp one single-block external xattr container."""
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert len(superblock) == 1024
    assert len(block) == block_size
    assert physical_block > 0
    result = bytearray(block)
    magic, refcount, blocks = struct.unpack_from("<III", result, 0)
    assert magic == 0xEA020000
    assert refcount > 0
    assert blocks == 1
    assert struct.unpack_from("<III", result, 0x14) == (0, 0, 0)
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    struct.pack_into("<I", result, 0x10, 0)
    checksum = _crc32c_raw(struct.pack("<Q", physical_block), seed)
    checksum = _crc32c_raw(result, checksum)
    struct.pack_into("<I", result, 0x10, checksum)
    return bytes(result)


def _linear_directory_block_with_checksum(
    superblock: bytes,
    inode_number: int,
    generation: int,
    block: bytes | bytearray,
) -> bytes:
    """Restamp one metadata-checksummed linear directory block."""
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert len(superblock) == 1024
    assert len(block) == block_size
    assert inode_number > 0
    assert 0 <= generation <= 0xFFFF_FFFF
    tail_offset = block_size - 12
    result = bytearray(block)
    assert struct.unpack_from("<IHBB", result, tail_offset) == (
        0,
        12,
        0,
        0xDE,
    )
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    checksum = _crc32c_raw(struct.pack("<I", inode_number), seed)
    checksum = _crc32c_raw(struct.pack("<I", generation), checksum)
    checksum = _crc32c_raw(result[:tail_offset], checksum)
    struct.pack_into("<I", result, tail_offset + 8, checksum)
    return bytes(result)


def _checked_linear_directory_entries(
    superblock: bytes,
    inode_number: int,
    generation: int,
    block: bytes,
) -> tuple[tuple[int, int, int, int, bytes], ...]:
    """Validate one checksummed linear block and return its live dirents."""
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert len(block) == block_size
    assert block == _linear_directory_block_with_checksum(
        superblock, inode_number, generation, block
    )
    tail_offset = block_size - 12
    entries: list[tuple[int, int, int, int, bytes]] = []
    offset = 0
    while offset < tail_offset:
        entry_inode, record_length, name_length, file_type = (
            struct.unpack_from("<IHBB", block, offset)
        )
        assert record_length >= 12
        assert record_length % 4 == 0
        assert offset + record_length <= tail_offset
        assert name_length <= record_length - 8
        if entry_inode:
            assert name_length > 0
            name = block[offset + 8 : offset + 8 + name_length]
            assert b"\x00" not in name
            entries.append(
                (
                    offset,
                    entry_inode,
                    record_length,
                    file_type,
                    name,
                )
            )
        else:
            assert name_length == 0
            assert file_type == 0
        offset += record_length
    assert offset == tail_offset
    assert struct.unpack_from("<IHBB", block, tail_offset) == (
        0,
        12,
        0,
        0xDE,
    )
    return tuple(entries)


def _linear_directory_unlink_afterimage(
    superblock: bytes,
    *,
    parent_inode: int,
    parent_generation: int,
    original: bytes,
    target_inode: int,
    name: bytes,
) -> tuple[bytes, int, int]:
    """Apply ext4's immediate-predecessor linear UNLINK splice."""
    assert target_inode > 0
    assert name and len(name) <= 255
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert len(original) == block_size
    assert original == _linear_directory_block_with_checksum(
        superblock,
        parent_inode,
        parent_generation,
        original,
    )
    tail_offset = block_size - 12
    previous: tuple[int, int, int] | None = None
    target: tuple[int, int] | None = None
    offset = 0
    while offset < tail_offset:
        entry_inode, record_length, name_length, file_type = (
            struct.unpack_from("<IHBB", original, offset)
        )
        assert record_length >= 12
        assert record_length % 4 == 0
        assert offset + record_length <= tail_offset
        assert name_length <= record_length - 8
        entry_name = original[offset + 8 : offset + 8 + name_length]
        if entry_inode == target_inode and entry_name == name:
            assert target is None
            assert previous is not None and previous[1] != 0
            target = (offset, record_length)
            break
        previous = (offset, entry_inode, record_length)
        offset += record_length
    assert target is not None
    assert previous is not None
    previous_offset, _, previous_record = previous
    target_offset, target_record = target
    assert previous_offset + previous_record == target_offset
    result = bytearray(original)
    struct.pack_into(
        "<H", result, previous_offset + 4, previous_record + target_record
    )
    result[target_offset : target_offset + target_record] = bytes(
        target_record
    )
    expected = _linear_directory_block_with_checksum(
        superblock,
        parent_inode,
        parent_generation,
        result,
    )
    entries = _checked_linear_directory_entries(
        superblock,
        parent_inode,
        parent_generation,
        expected,
    )
    assert all(
        entry[1] != target_inode or entry[4] != name for entry in entries
    )
    return expected, previous_offset, target_offset


def _extent_node_with_checksum(
    superblock: bytes,
    inode_number: int,
    generation: int,
    node: bytes | bytearray,
) -> bytes:
    result = bytearray(node)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert len(result) == block_size
    assert inode_number > 0
    assert 0 <= generation <= 0xFFFF_FFFF
    tail_offset = 12 + ((block_size - 12) // 12) * 12
    assert tail_offset + 4 <= block_size
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    checksum = _crc32c_raw(struct.pack("<I", inode_number), seed)
    checksum = _crc32c_raw(struct.pack("<I", generation), checksum)
    checksum = _crc32c_raw(result[:tail_offset], checksum)
    struct.pack_into("<I", result, tail_offset, checksum)
    return bytes(result)


def _extent_leaf_entries(
    node: bytes,
) -> tuple[tuple[int, int, int, int], ...]:
    """Return the live entries from one checked external extent leaf."""
    magic, entries, entry_max, depth = struct.unpack_from("<HHHH", node, 0)
    assert magic == 0xF30A
    assert depth == 0
    assert 0 < entries <= entry_max
    assert 12 + entry_max * 12 + 4 <= len(node)
    return tuple(
        struct.unpack_from("<IHHI", node, 12 + index * 12)
        for index in range(entries)
    )


def _extent_leaf_with_entries(
    superblock: bytes,
    inode_number: int,
    generation: int,
    root_generation: int,
    entries: tuple[tuple[int, int, int, int], ...],
) -> bytes:
    """Build and checksum one external extent leaf from exact entries."""
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    entry_max = (block_size - 12) // 12
    assert 0 < len(entries) <= entry_max
    assert all(
        entries[index - 1][0] < entries[index][0]
        for index in range(1, len(entries))
    )
    result = bytearray(block_size)
    struct.pack_into(
        "<HHHHI",
        result,
        0,
        0xF30A,
        len(entries),
        entry_max,
        0,
        root_generation,
    )
    for index, entry in enumerate(entries):
        struct.pack_into("<IHHI", result, 12 + index * 12, *entry)
    return _extent_node_with_checksum(
        superblock,
        inode_number,
        generation,
        result,
    )


def _ext4_sparse_group(group: int) -> bool:
    if group in (0, 1):
        return True
    for base in (3, 5, 7):
        value = group
        while value > 1 and value % base == 0:
            value //= base
        if value == 1:
            return True
    return False


def _ext4_recovery_layout(path: Path) -> dict[str, int]:
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    blocks = struct.unpack_from("<I", superblock, 0x04)[0]
    assert struct.unpack_from("<I", superblock, 0x150)[0] == 0
    first = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    groups = (blocks - first + blocks_per_group - 1) // blocks_per_group
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    assert descriptor_size == 64
    witness_super = first + blocks_per_group
    witness_gdt = witness_super + 1
    witness_gdt_span = (
        groups * descriptor_size + block_size - 1
    ) // block_size
    with path.open("rb") as source:
        source.seek(witness_gdt * block_size)
        group0_descriptor = source.read(descriptor_size)
    assert len(group0_descriptor) == descriptor_size
    inode_size = struct.unpack_from("<H", superblock, 0x58)[0]
    inode_index = 7
    inode_table_base = struct.unpack_from("<I", group0_descriptor, 0x08)[0]
    journal_root = superblock[0x10C : 0x10C + 60]
    assert struct.unpack_from("<H", journal_root, 0x00)[0] == 0xF30A
    assert struct.unpack_from("<H", journal_root, 0x06)[0] == 0

    def map_journal_block(logical: int) -> int:
        entries = struct.unpack_from("<H", journal_root, 0x02)[0]
        for index in range(entries):
            entry = 0x0C + index * 0x0C
            first_logical = struct.unpack_from("<I", journal_root, entry)[0]
            raw_length = struct.unpack_from("<H", journal_root, entry + 0x04)[0]
            assert 0 < raw_length <= 0x8000
            if first_logical <= logical < first_logical + raw_length:
                first_physical = (
                    struct.unpack_from("<H", journal_root, entry + 0x06)[0]
                    << 32
                ) | struct.unpack_from("<I", journal_root, entry + 0x08)[0]
                return first_physical + logical - first_logical
        raise AssertionError(f"journal logical block {logical} is unmapped")

    journal_block = map_journal_block(0)
    journal_commit_block = map_journal_block(3)
    return {
        "block_size": block_size,
        "blocks": blocks,
        "first": first,
        "blocks_per_group": blocks_per_group,
        "groups": groups,
        "descriptor_size": descriptor_size,
        "inode_size": inode_size,
        "primary_super": 1 if block_size == 1024 else 0,
        "primary_gdt": 2 if block_size == 1024 else 1,
        "witness_super": witness_super,
        "witness_gdt": witness_gdt,
        "witness_gdt_span": witness_gdt_span,
        "block_bitmap": struct.unpack_from("<I", group0_descriptor, 0x00)[0],
        "inode_bitmap": struct.unpack_from("<I", group0_descriptor, 0x04)[0],
        "inode_table_base": inode_table_base,
        "journal_inode_block": (
            inode_table_base + inode_index * inode_size // block_size
        ),
        "journal_inode_offset": inode_index * inode_size % block_size,
        "journal_block": journal_block,
        "journal_commit_block": journal_commit_block,
    }


def _ext4_inode_record(path: Path, inode_number: int) -> tuple[bytes, bytes, int]:
    """Return the primary super, one inode record, and its byte offset."""
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    assert inode_number > 0
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_size = struct.unpack_from("<H", superblock, 0x58)[0]
    inodes_per_group = struct.unpack_from("<I", superblock, 0x28)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    assert descriptor_size == 64
    group, index = divmod(inode_number - 1, inodes_per_group)
    descriptor_table = 2 if block_size == 1024 else 1
    with path.open("rb") as source:
        source.seek(descriptor_table * block_size + group * descriptor_size)
        descriptor = source.read(descriptor_size)
    assert len(descriptor) == descriptor_size
    inode_table = (
        struct.unpack_from("<I", descriptor, 0x28)[0] << 32
    ) | struct.unpack_from("<I", descriptor, 0x08)[0]
    inode_offset = inode_table * block_size + index * inode_size
    with path.open("rb") as source:
        source.seek(inode_offset)
        inode = source.read(inode_size)
    assert len(inode) == inode_size
    return superblock, inode, inode_offset


def _ext4_block_allocation_state(
    path: Path,
    blocks: tuple[int, ...],
) -> dict[int, bool]:
    """Read primary block-bitmap allocation state for exact block homes."""
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_count = struct.unpack_from("<I", superblock, 0x04)[0] | (
        struct.unpack_from("<I", superblock, 0x150)[0] << 32
    )
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    assert descriptor_size >= 64
    descriptor_table = 2 if block_size == 1024 else 1
    result: dict[int, bool] = {}
    with path.open("rb") as source:
        for block in sorted(set(blocks)):
            assert first_data <= block < blocks_count
            group, index = divmod(block - first_data, blocks_per_group)
            source.seek(
                descriptor_table * block_size + group * descriptor_size
            )
            descriptor = source.read(descriptor_size)
            assert len(descriptor) == descriptor_size
            bitmap_home = struct.unpack_from("<I", descriptor, 0x00)[0] | (
                struct.unpack_from("<I", descriptor, 0x20)[0] << 32
            )
            source.seek(bitmap_home * block_size + index // 8)
            bitmap_byte = source.read(1)
            assert len(bitmap_byte) == 1
            result[block] = bool(bitmap_byte[0] & (1 << (index % 8)))
    return result


def _ext4_inode_allocation_state(
    path: Path,
    inode_numbers: tuple[int, ...],
) -> dict[int, bool]:
    """Read primary inode-bitmap allocation state for exact inode numbers."""
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_count = struct.unpack_from("<I", superblock, 0x00)[0]
    inodes_per_group = struct.unpack_from("<I", superblock, 0x28)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    assert descriptor_size >= 64
    descriptor_table = 2 if block_size == 1024 else 1
    result: dict[int, bool] = {}
    with path.open("rb") as source:
        for inode_number in sorted(set(inode_numbers)):
            assert 0 < inode_number <= inode_count
            group, index = divmod(inode_number - 1, inodes_per_group)
            source.seek(
                descriptor_table * block_size + group * descriptor_size
            )
            descriptor = source.read(descriptor_size)
            assert len(descriptor) == descriptor_size
            bitmap_home = struct.unpack_from("<I", descriptor, 0x04)[0] | (
                struct.unpack_from("<I", descriptor, 0x24)[0] << 32
            )
            source.seek(bitmap_home * block_size + index // 8)
            bitmap_byte = source.read(1)
            assert len(bitmap_byte) == 1
            result[inode_number] = bool(
                bitmap_byte[0] & (1 << (index % 8))
            )
    return result


def _ext4_group_counts(path: Path, group: int) -> dict[str, int]:
    """Return the primary descriptor's allocation counters for one group."""
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    blocks_count = struct.unpack_from("<I", superblock, 0x04)[0] | (
        struct.unpack_from("<I", superblock, 0x150)[0] << 32
    )
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    group_count = (
        blocks_count - first_data + blocks_per_group - 1
    ) // blocks_per_group
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    assert descriptor_size >= 64
    assert 0 <= group < group_count
    descriptor_table = 2 if block_size == 1024 else 1
    with path.open("rb") as source:
        source.seek(
            descriptor_table * block_size + group * descriptor_size
        )
        descriptor = source.read(descriptor_size)
    assert len(descriptor) == descriptor_size

    def counter(low: int, high: int) -> int:
        return struct.unpack_from("<H", descriptor, low)[0] | (
            struct.unpack_from("<H", descriptor, high)[0] << 16
        )

    return {
        "free_blocks": counter(0x0C, 0x2C),
        "free_inodes": counter(0x0E, 0x2E),
        "used_dirs": counter(0x10, 0x30),
        "itable_unused": counter(0x1C, 0x32),
    }


def _extent_root_physical(inode: bytes, logical_block: int) -> int:
    """Map one logical block through the fixture's inline depth-zero root."""
    root = inode[0x28 : 0x28 + 60]
    magic, entries, maximum, depth = struct.unpack_from("<HHHH", root, 0)
    assert magic == 0xF30A
    assert 0 < entries <= maximum <= 4
    assert depth == 0
    for index in range(entries):
        offset = 0x0C + index * 0x0C
        first_logical = struct.unpack_from("<I", root, offset)[0]
        raw_length = struct.unpack_from("<H", root, offset + 0x04)[0]
        length = raw_length - 0x8000 if raw_length > 0x8000 else raw_length
        assert length > 0
        if first_logical <= logical_block < first_logical + length:
            first_physical = (
                struct.unpack_from("<H", root, offset + 0x06)[0] << 32
            ) | struct.unpack_from("<I", root, offset + 0x08)[0]
            return first_physical + logical_block - first_logical
    raise AssertionError(f"logical block {logical_block} is unmapped")


def _modern_orphan_patches(
    path: Path,
    entries: tuple[int, ...],
    *,
    orphan_present: bool = True,
) -> tuple[tuple[int, bytes], ...]:
    """Create a checksum-valid modern orphan block and transient super state."""
    with path.open("rb") as source:
        source.seek(1024)
        superblock = bytearray(source.read(1024))
    assert len(superblock) == 1024
    orphan_inode_number = struct.unpack_from("<I", superblock, 0x280)[0]
    assert orphan_inode_number > 0
    _, orphan_inode, _ = _ext4_inode_record(path, orphan_inode_number)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    orphan_physical = _extent_root_physical(orphan_inode, 0)
    with path.open("rb") as source:
        source.seek(orphan_physical * block_size)
        orphan_block = bytearray(source.read(block_size))
    assert len(orphan_block) == block_size
    assert struct.unpack_from("<I", orphan_block, block_size - 8)[0] == 0x0B10CA04
    assert not any(orphan_block[: block_size - 8])
    assert len(entries) <= (block_size - 8) // 4
    for index, inode_number in enumerate(entries):
        assert 0 < inode_number <= 0xFFFF_FFFF
        struct.pack_into("<I", orphan_block, index * 4, inode_number)

    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    generation = struct.unpack_from("<I", orphan_inode, 0x64)[0]
    checksum = _crc32c_raw(
        struct.pack("<IIQ", orphan_inode_number, generation, orphan_physical),
        seed,
    )
    checksum = _crc32c_raw(orphan_block[: block_size - 8], checksum)
    struct.pack_into("<I", orphan_block, block_size - 4, checksum)

    ro_compat = struct.unpack_from("<I", superblock, 0x64)[0]
    if orphan_present:
        ro_compat |= 0x0001_0000
    else:
        ro_compat &= ~0x0001_0000
    struct.pack_into("<I", superblock, 0x64, ro_compat)
    return (
        (1024, _ext4_super_with_checksum(superblock)),
        (orphan_physical * block_size, bytes(orphan_block)),
    )


def _depth1_orphan_file_map_patches(
    path: Path,
    base_patches: tuple[tuple[int, bytes], ...],
) -> tuple[tuple[tuple[int, bytes], ...], int, bytes]:
    """Move the orphan file's last data block into a depth-1 leaf node."""
    patches = dict(base_patches)
    assert len(patches) == len(base_patches)
    superblock = patches[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    orphan_inode_number = struct.unpack_from("<I", superblock, 0x280)[0]
    _, raw_inode, inode_offset = _ext4_inode_record(
        path,
        orphan_inode_number,
    )
    inode = bytearray(patches.get(inode_offset, raw_inode))
    generation = struct.unpack_from("<I", inode, 0x64)[0]
    assert struct.unpack_from("<HHHH", inode, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    assert struct.unpack_from("<I", inode, 0x34)[0] == 0
    original_blocks = struct.unpack_from("<H", inode, 0x38)[0]
    assert original_blocks > 1
    assert struct.unpack_from("<H", inode, 0x3A)[0] == 0
    first_physical = struct.unpack_from("<I", inode, 0x3C)[0]
    assert struct.unpack_from("<I", inode, 0x04)[0] == (
        original_blocks * block_size
    )
    assert struct.unpack_from("<I", inode, 0x6C)[0] == 0
    assert struct.unpack_from("<I", inode, 0x1C)[0] == (
        original_blocks * sectors_per_block
    )
    assert struct.unpack_from("<H", inode, 0x74)[0] == 0

    data_blocks = original_blocks - 1
    node_physical = first_physical + data_blocks
    node_offset = node_physical * block_size
    assert node_offset not in patches
    node_max = (block_size - 12) // 12
    node = bytearray(block_size)
    struct.pack_into("<HHHHI", node, 0, 0xF30A, 1, node_max, 0, 0)
    struct.pack_into(
        "<IHHI",
        node,
        12,
        0,
        data_blocks,
        0,
        first_physical,
    )
    node = bytearray(
        _extent_node_with_checksum(
            superblock,
            orphan_inode_number,
            generation,
            node,
        )
    )

    inode[0x28:0x64] = bytes(60)
    struct.pack_into("<HHHHI", inode, 0x28, 0xF30A, 1, 4, 1, 0)
    struct.pack_into("<IIHH", inode, 0x34, 0, node_physical, 0, 0)
    struct.pack_into("<I", inode, 0x04, data_blocks * block_size)
    struct.pack_into("<I", inode, 0x6C, 0)
    inode = bytearray(
        _inode_with_checksum(
            superblock,
            orphan_inode_number,
            inode,
        )
    )
    assert struct.unpack_from("<I", inode, 0x1C)[0] == (
        (data_blocks + 1) * sectors_per_block
    )
    patches[inode_offset] = bytes(inode)
    patches[node_offset] = bytes(node)
    return tuple(patches.items()), node_physical, bytes(node)


def _depth2_orphan_file_map_patches(
    path: Path,
    base_patches: tuple[tuple[int, bytes], ...],
) -> tuple[tuple[tuple[int, bytes], ...], int, int]:
    """Place the orphan file behind valid depth-2 and depth-1 index nodes."""
    depth1_patches, leaf_physical, _ = _depth1_orphan_file_map_patches(
        path,
        base_patches,
    )
    patches = dict(depth1_patches)
    superblock = patches[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    orphan_inode_number = struct.unpack_from("<I", superblock, 0x280)[0]
    _, _, inode_offset = _ext4_inode_record(path, orphan_inode_number)
    inode = bytearray(patches[inode_offset])
    generation = struct.unpack_from("<I", inode, 0x64)[0]
    assert struct.unpack_from("<HHHH", inode, 0x28) == (
        0xF30A,
        1,
        4,
        1,
    )

    leaf_offset = leaf_physical * block_size
    leaf = bytearray(patches[leaf_offset])
    assert struct.unpack_from("<HHHH", leaf, 0)[:2] == (0xF30A, 1)
    assert struct.unpack_from("<H", leaf, 6)[0] == 0
    data_blocks = struct.unpack_from("<H", leaf, 16)[0]
    assert data_blocks > 1
    data_blocks -= 1
    struct.pack_into("<H", leaf, 16, data_blocks)
    leaf = bytearray(
        _extent_node_with_checksum(
            superblock,
            orphan_inode_number,
            generation,
            leaf,
        )
    )

    index_physical = leaf_physical - 1
    index_offset = index_physical * block_size
    assert index_offset not in patches
    node_max = (block_size - 12) // 12
    index = bytearray(block_size)
    struct.pack_into("<HHHHI", index, 0, 0xF30A, 1, node_max, 1, 0)
    struct.pack_into("<IIHH", index, 12, 0, leaf_physical, 0, 0)
    index = bytearray(
        _extent_node_with_checksum(
            superblock,
            orphan_inode_number,
            generation,
            index,
        )
    )

    inode[0x28:0x64] = bytes(60)
    struct.pack_into("<HHHHI", inode, 0x28, 0xF30A, 1, 4, 2, 0)
    struct.pack_into("<IIHH", inode, 0x34, 0, index_physical, 0, 0)
    struct.pack_into("<I", inode, 0x04, data_blocks * block_size)
    struct.pack_into("<I", inode, 0x6C, 0)
    inode = bytearray(
        _inode_with_checksum(
            superblock,
            orphan_inode_number,
            inode,
        )
    )
    assert struct.unpack_from("<I", inode, 0x1C)[0] == (
        (data_blocks + 2) * sectors_per_block
    )
    patches[inode_offset] = bytes(inode)
    patches[index_offset] = bytes(index)
    patches[leaf_offset] = bytes(leaf)
    return tuple(patches.items()), index_physical, leaf_physical


def _legacy_orphan_file_map_patches(
    path: Path,
    base_patches: tuple[tuple[int, bytes], ...],
) -> tuple[tuple[int, bytes], ...]:
    """Replace the orphan inode's extent root with one valid direct block."""
    patches = dict(base_patches)
    superblock = patches[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    orphan_inode_number = struct.unpack_from("<I", superblock, 0x280)[0]
    _, raw_inode, inode_offset = _ext4_inode_record(path, orphan_inode_number)
    inode = bytearray(patches.get(inode_offset, raw_inode))
    first_physical = _extent_root_physical(inode, 0)
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    struct.pack_into("<I", inode, 0x20, flags & ~0x0008_0000)
    inode[0x28:0x64] = bytes(60)
    struct.pack_into("<I", inode, 0x28, first_physical)
    struct.pack_into("<I", inode, 0x04, block_size)
    struct.pack_into("<I", inode, 0x6C, 0)
    struct.pack_into("<I", inode, 0x1C, sectors_per_block)
    struct.pack_into("<H", inode, 0x74, 0)
    patches[inode_offset] = _inode_with_checksum(
        superblock,
        orphan_inode_number,
        inode,
    )
    return tuple(patches.items())


def _orphan_xattr_map_alias_patches(
    path: Path,
) -> tuple[tuple[tuple[int, bytes], ...], int, int]:
    """Alias one valid orphan-file xattr block as preallocation."""
    base_patches, data_block = _one_block_unlinked_orphan_patches(
        path,
        protocol="modern",
    )
    patches = dict(base_patches)
    superblock = patches[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    orphan_inode_number = struct.unpack_from("<I", superblock, 0x280)[0]
    _, raw_orphan_inode, orphan_inode_offset = _ext4_inode_record(
        path,
        orphan_inode_number,
    )
    orphan_inode = bytearray(
        patches.get(orphan_inode_offset, raw_orphan_inode)
    )
    _, xattr_owner, _ = _ext4_inode_record(path, 14)
    xattr_block = struct.unpack_from("<I", xattr_owner, 0x68)[0]
    assert xattr_block > 0
    assert struct.unpack_from("<H", xattr_owner, 0x76)[0] == 0
    assert struct.unpack_from("<HHHH", orphan_inode, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    orphan_blocks = struct.unpack_from("<I", orphan_inode, 0x04)[0] // block_size
    assert struct.unpack_from("<H", orphan_inode, 0x38)[0] == orphan_blocks
    first_physical = struct.unpack_from("<I", orphan_inode, 0x3C)[0]
    assert not first_physical <= xattr_block < first_physical + orphan_blocks
    assert xattr_block != data_block
    assert struct.unpack_from("<I", orphan_inode, 0x68)[0] == 0
    assert struct.unpack_from("<H", orphan_inode, 0x76)[0] == 0

    struct.pack_into("<H", orphan_inode, 0x2A, 2)
    struct.pack_into(
        "<IHHI",
        orphan_inode,
        0x40,
        orphan_blocks,
        0x8001,
        0,
        xattr_block,
    )
    struct.pack_into("<I", orphan_inode, 0x68, xattr_block)
    struct.pack_into(
        "<I",
        orphan_inode,
        0x1C,
        struct.unpack_from("<I", orphan_inode, 0x1C)[0]
        + 2 * sectors_per_block,
    )
    patches[orphan_inode_offset] = _inode_with_checksum(
        superblock,
        orphan_inode_number,
        orphan_inode,
    )
    return tuple(patches.items()), data_block, xattr_block


def _zero_size_depth0_orphan_patches(
    path: Path,
) -> tuple[tuple[int, bytes], ...]:
    """Model a crash after inode 14's zero size reached disk first."""
    patches = list(_modern_orphan_patches(path, (14,)))
    superblock = patches[0][1]
    _, raw_inode, inode_offset = _ext4_inode_record(path, 14)
    inode = bytearray(raw_inode)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512

    assert struct.unpack_from("<H", inode, 0x00)[0] & 0xF000 == 0x8000
    assert struct.unpack_from("<H", inode, 0x1A)[0] == 2
    assert struct.unpack_from("<I", inode, 0x04)[0] == 54
    assert struct.unpack_from("<I", inode, 0x6C)[0] == 0
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    assert not flags & 0x0000_4000
    assert not flags & 0x0004_0000
    assert struct.unpack_from("<H", inode, 0x76)[0] == 0
    assert struct.unpack_from("<I", inode, 0x68)[0] != 0
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 2 * sectors_per_block
    assert struct.unpack_from("<H", inode, 0x74)[0] == 0
    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 1, 4, 0)
    assert struct.unpack_from("<I", inode, 0x34)[0] == 0
    raw_length = struct.unpack_from("<H", inode, 0x38)[0]
    assert raw_length == 1
    assert struct.unpack_from("<H", inode, 0x3A)[0] == 0

    struct.pack_into("<I", inode, 0x04, 0)
    struct.pack_into("<I", inode, 0x6C, 0)
    patches.append(
        (inode_offset, _inode_with_checksum(superblock, 14, inode))
    )
    return tuple(patches)


def _cross_group_depth0_orphan_patches(
    path: Path,
) -> tuple[tuple[int, bytes], ...]:
    """Move inode 14's retained extent across fixture groups 3 and 4."""
    patches = list(_zero_size_depth0_orphan_patches(path))
    superblock = bytearray(patches[0][1])
    inode_offset, raw_inode = patches[2]
    inode = bytearray(raw_inode)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert block_size == 1024
    sectors_per_block = block_size // 512
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    assert descriptor_size == 64
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    first_block = first_data + 4 * blocks_per_group - 1
    group_bits = ((3, blocks_per_group - 1), (4, 0))
    assert first_block == 32768

    def read_block(block: int) -> bytearray:
        with path.open("rb") as source:
            source.seek(block * block_size)
            result = bytearray(source.read(block_size))
        assert len(result) == block_size
        return result

    gdt_home = 2
    gdt = read_block(gdt_home)
    bitmap_patches: list[tuple[int, bytes]] = []
    for group, bit_index in group_bits:
        descriptor_offset = group * descriptor_size
        descriptor = bytearray(
            gdt[descriptor_offset : descriptor_offset + descriptor_size]
        )
        bitmap_home = struct.unpack_from("<I", descriptor, 0x00)[0]
        assert struct.unpack_from("<I", descriptor, 0x20)[0] == 0
        bitmap = read_block(bitmap_home)
        byte_index, bit_in_byte = divmod(bit_index, 8)
        assert bitmap[byte_index] & (1 << bit_in_byte) == 0
        bitmap[byte_index] |= 1 << bit_in_byte
        bitmap_checksum = _crc32c_raw(bitmap, seed)
        bitmap_patches.append((bitmap_home * block_size, bytes(bitmap)))

        flags = struct.unpack_from("<H", descriptor, 0x12)[0]
        if flags & 0x02:
            assert group == 4
            struct.pack_into("<H", descriptor, 0x12, flags & ~0x02)
        group_free = struct.unpack_from("<H", descriptor, 0x0C)[0] | (
            struct.unpack_from("<H", descriptor, 0x2C)[0] << 16
        )
        assert group_free > 0
        group_free -= 1
        struct.pack_into("<H", descriptor, 0x0C, group_free & 0xFFFF)
        struct.pack_into("<H", descriptor, 0x2C, group_free >> 16)
        struct.pack_into("<H", descriptor, 0x18, bitmap_checksum & 0xFFFF)
        struct.pack_into("<H", descriptor, 0x38, bitmap_checksum >> 16)
        descriptor = bytearray(
            _group_descriptor_with_checksum(superblock, descriptor, group)
        )
        gdt[descriptor_offset : descriptor_offset + descriptor_size] = descriptor

    super_free = struct.unpack_from("<I", superblock, 0x0C)[0]
    assert struct.unpack_from("<I", superblock, 0x158)[0] == 0
    assert super_free >= 2
    struct.pack_into("<I", superblock, 0x0C, super_free - 2)
    superblock = bytearray(_ext4_super_with_checksum(superblock))

    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 1, 4, 0)
    struct.pack_into("<H", inode, 0x38, 2)
    struct.pack_into("<H", inode, 0x3A, 0)
    struct.pack_into("<I", inode, 0x3C, first_block)
    struct.pack_into("<I", inode, 0x1C, 3 * sectors_per_block)
    struct.pack_into("<H", inode, 0x74, 0)
    inode = bytearray(_inode_with_checksum(superblock, 14, inode))

    patches[0] = (1024, bytes(superblock))
    patches[2] = (inode_offset, bytes(inode))
    patches.extend(bitmap_patches)
    patches.append((gdt_home * block_size, bytes(gdt)))
    return tuple(patches)


def _already_truncated_depth0_orphan_patches(
    path: Path,
) -> tuple[tuple[int, bytes], ...]:
    """Model a durable storage truncate whose modern slot remains active."""
    patches = list(_zero_size_depth0_orphan_patches(path))
    superblock = bytearray(patches[0][1])
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    inode_offset, raw_inode = patches[2]
    inode = bytearray(raw_inode)
    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 1, 4, 0)
    data_block = struct.unpack_from("<I", inode, 0x3C)[0]
    assert struct.unpack_from("<H", inode, 0x3A)[0] == 0
    assert struct.unpack_from("<H", inode, 0x38)[0] == 1
    group, data_index = divmod(data_block - first_data, blocks_per_group)
    assert group == 0

    gdt_home = 2 if block_size == 1024 else 1
    with path.open("rb") as source:
        source.seek(gdt_home * block_size)
        gdt = bytearray(source.read(block_size))
    assert len(gdt) == block_size
    descriptor_offset = group * descriptor_size % block_size
    descriptor = bytearray(
        gdt[descriptor_offset : descriptor_offset + descriptor_size]
    )
    bitmap_home = struct.unpack_from("<I", descriptor, 0x00)[0]
    with path.open("rb") as source:
        source.seek(bitmap_home * block_size)
        bitmap = bytearray(source.read(block_size))
    assert len(bitmap) == block_size
    data_byte, data_bit = divmod(data_index, 8)
    assert bitmap[data_byte] & (1 << data_bit)
    bitmap[data_byte] &= ~(1 << data_bit)
    bitmap_checksum = _crc32c_raw(bitmap, seed)

    group_free = struct.unpack_from("<H", descriptor, 0x0C)[0] | (
        struct.unpack_from("<H", descriptor, 0x2C)[0] << 16
    )
    group_free += 1
    struct.pack_into("<H", descriptor, 0x0C, group_free & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x2C, group_free >> 16)
    struct.pack_into("<H", descriptor, 0x18, bitmap_checksum & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x38, bitmap_checksum >> 16)
    descriptor = bytearray(
        _group_descriptor_with_checksum(superblock, descriptor, group)
    )
    gdt[descriptor_offset : descriptor_offset + descriptor_size] = descriptor

    super_free = struct.unpack_from("<I", superblock, 0x0C)[0] | (
        struct.unpack_from("<I", superblock, 0x158)[0] << 32
    )
    super_free += 1
    struct.pack_into("<I", superblock, 0x0C, super_free & 0xFFFF_FFFF)
    struct.pack_into("<I", superblock, 0x158, super_free >> 32)
    superblock = bytearray(_ext4_super_with_checksum(superblock))

    struct.pack_into("<H", inode, 0x2A, 0)
    inode[0x34:0x64] = bytes(48)
    struct.pack_into("<I", inode, 0x1C, sectors_per_block)
    struct.pack_into("<H", inode, 0x74, 0)
    inode = bytearray(_inode_with_checksum(superblock, 14, inode))

    patches[0] = (1024, bytes(superblock))
    patches[2] = (inode_offset, bytes(inode))
    patches.extend(
        (
            (bitmap_home * block_size, bytes(bitmap)),
            (gdt_home * block_size, bytes(gdt)),
        )
    )
    return tuple(patches)


def _legacy_orphan_patches(
    path: Path,
    head: int,
    links: tuple[tuple[int, int], ...],
    *,
    modern_entries: tuple[int, ...] = (),
    bad_checksum_inode: int | None = None,
) -> tuple[tuple[int, bytes], ...]:
    """Author a legacy orphan chain, optionally sharing modern discovery."""
    modern = _modern_orphan_patches(
        path, modern_entries, orphan_present=bool(modern_entries)
    )
    superblock = bytearray(modern[0][1])
    assert len(superblock) == 1024
    inode_count = struct.unpack_from("<I", superblock, 0x00)[0]
    assert 0 <= head <= inode_count
    struct.pack_into("<I", superblock, 0xE8, head)

    patches: list[tuple[int, bytes]] = [
        (1024, _ext4_super_with_checksum(superblock)),
        modern[1],
    ]
    seen: set[int] = set()
    for inode_number, next_inode in links:
        assert inode_number not in seen
        seen.add(inode_number)
        assert 0 < inode_number <= inode_count
        assert 0 <= next_inode <= 0xFFFF_FFFF
        primary_super, inode, inode_offset = _ext4_inode_record(
            path, inode_number
        )
        updated_inode = bytearray(inode)
        struct.pack_into("<I", updated_inode, 0x14, next_inode)
        updated_inode = bytearray(
            _inode_with_checksum(primary_super, inode_number, updated_inode)
        )
        if inode_number == bad_checksum_inode:
            updated_inode[0x7C] ^= 1
        patches.append((inode_offset, bytes(updated_inode)))
    if bad_checksum_inode is not None:
        assert bad_checksum_inode in seen
    return tuple(patches)


def _zero_size_depth0_legacy_orphan_patches(
    path: Path,
) -> tuple[tuple[int, bytes], ...]:
    """Model a linked singleton legacy orphan after its zero size is durable."""
    patches = list(_legacy_orphan_patches(path, 14, ((14, 0),)))
    assert len(patches) == 3
    assert patches[0][0] == 1024
    superblock = patches[0][1]
    assert struct.unpack_from("<I", superblock, 0xE8)[0] == 14
    assert not struct.unpack_from("<I", superblock, 0x64)[0] & 0x0001_0000
    _, raw_inode, inode_offset = _ext4_inode_record(path, 14)
    assert patches[2][0] == inode_offset
    assert len(patches[2][1]) == len(raw_inode)
    assert len({offset for offset, _ in patches}) == len(patches)
    inode = bytearray(patches[2][1])
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512

    assert struct.unpack_from("<H", inode, 0x00)[0] & 0xF000 == 0x8000
    assert struct.unpack_from("<I", inode, 0x14)[0] == 0
    assert struct.unpack_from("<H", inode, 0x1A)[0] == 2
    assert struct.unpack_from("<I", inode, 0x04)[0] == 54
    assert struct.unpack_from("<I", inode, 0x6C)[0] == 0
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    assert not flags & 0x0000_4000
    assert not flags & 0x0004_0000
    assert struct.unpack_from("<H", inode, 0x76)[0] == 0
    external_xattr = struct.unpack_from("<I", inode, 0x68)[0]
    assert external_xattr != 0
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 2 * sectors_per_block
    assert struct.unpack_from("<H", inode, 0x74)[0] == 0
    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 1, 4, 0)
    assert struct.unpack_from("<I", inode, 0x34)[0] == 0
    assert struct.unpack_from("<H", inode, 0x38)[0] == 1
    assert struct.unpack_from("<H", inode, 0x3A)[0] == 0

    struct.pack_into("<I", inode, 0x04, 0)
    struct.pack_into("<I", inode, 0x6C, 0)
    assert struct.unpack_from("<I", inode, 0x68)[0] == external_xattr
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 2 * sectors_per_block
    assert struct.unpack_from("<H", inode, 0x74)[0] == 0
    patches[2] = (
        inode_offset,
        _inode_with_checksum(superblock, 14, inode),
    )
    return tuple(patches)


def _already_truncated_depth0_legacy_orphan_patches(
    path: Path,
) -> tuple[tuple[int, bytes], ...]:
    """Model completed legacy storage truncation with its head still active."""
    legacy = list(_zero_size_depth0_legacy_orphan_patches(path))
    patches = list(_already_truncated_depth0_orphan_patches(path))
    assert len(legacy) == 3
    assert len(patches) == 5
    assert tuple(offset for offset, _ in legacy) == tuple(
        offset for offset, _ in patches[:3]
    )

    superblock = bytearray(patches[0][1])
    ro_compat = struct.unpack_from("<I", superblock, 0x64)[0]
    assert ro_compat & 0x0001_0000
    assert struct.unpack_from("<I", superblock, 0xE8)[0] == 0
    struct.pack_into("<I", superblock, 0x64, ro_compat & ~0x0001_0000)
    struct.pack_into("<I", superblock, 0xE8, 14)
    superblock = bytearray(_ext4_super_with_checksum(superblock))

    inode_offset, raw_inode = patches[2]
    assert inode_offset == legacy[2][0]
    inode = bytearray(raw_inode)
    legacy_inode = legacy[2][1]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    external_xattr = struct.unpack_from("<I", legacy_inode, 0x68)[0]
    assert external_xattr != 0
    assert struct.unpack_from("<I", inode, 0x04)[0] == 0
    assert struct.unpack_from("<I", inode, 0x6C)[0] == 0
    assert struct.unpack_from("<I", inode, 0x14)[0] == 0
    assert struct.unpack_from("<H", inode, 0x1A)[0] == 2
    assert struct.unpack_from("<I", inode, 0x68)[0] == external_xattr
    assert struct.unpack_from("<H", inode, 0x76)[0] == 0
    assert struct.unpack_from("<I", inode, 0x1C)[0] == sectors_per_block
    assert struct.unpack_from("<H", inode, 0x74)[0] == 0
    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 0, 4, 0)

    patches[0] = (1024, bytes(superblock))
    patches[1] = legacy[1]
    patches[2] = (
        inode_offset,
        _inode_with_checksum(superblock, 14, inode),
    )
    assert len({offset for offset, _ in patches}) == len(patches)
    return tuple(patches)


def _already_empty_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    inode_number: int = 18,
) -> tuple[tuple[int, bytes], ...]:
    """Allocate one namespace-free empty inode and retain its orphan record."""
    assert protocol in {"modern", "legacy"}
    if protocol == "modern":
        base = _modern_orphan_patches(path, (inode_number,))
    else:
        base = _modern_orphan_patches(path, (), orphan_present=False)
    patches = dict(base)
    superblock = bytearray(patches[1024])
    if protocol == "legacy":
        struct.pack_into("<I", superblock, 0xE8, inode_number)
        superblock = bytearray(_ext4_super_with_checksum(superblock))
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_size = struct.unpack_from("<H", superblock, 0x58)[0]
    inodes_per_group = struct.unpack_from("<I", superblock, 0x28)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    assert inode_size == 256
    assert descriptor_size == 64
    group, inode_index = divmod(inode_number - 1, inodes_per_group)
    assert group == 0

    _, free_inode, inode_offset = _ext4_inode_record(path, inode_number)
    assert not any(free_inode)
    _, source_inode, _ = _ext4_inode_record(path, 14)
    inode = bytearray(source_inode)
    assert struct.unpack_from("<H", inode, 0x00)[0] & 0xF000 == 0x8000
    assert struct.unpack_from("<H", inode, 0x80)[0] == 32
    struct.pack_into("<I", inode, 0x04, 0)
    struct.pack_into("<I", inode, 0x14, 0)
    struct.pack_into("<H", inode, 0x1A, 0)
    struct.pack_into("<I", inode, 0x1C, 0)
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    assert not flags & 0x0000_4000
    inode[0x28:0x64] = bytes(60)
    struct.pack_into("<HHHHI", inode, 0x28, 0xF30A, 0, 4, 0, 0)
    struct.pack_into("<I", inode, 0x64, 0x1818_1818)
    struct.pack_into("<I", inode, 0x68, 0)
    struct.pack_into("<I", inode, 0x6C, 0)
    struct.pack_into("<H", inode, 0x74, 0)
    struct.pack_into("<H", inode, 0x76, 0)
    inode[0xA0:0x100] = bytes(0x60)

    gdt_home = struct.unpack_from("<I", superblock, 0x14)[0] + 1
    with path.open("rb") as source:
        source.seek(gdt_home * block_size)
        gdt = bytearray(source.read(block_size))
    assert len(gdt) == block_size
    descriptor_offset = group * descriptor_size
    descriptor = bytearray(
        gdt[descriptor_offset : descriptor_offset + descriptor_size]
    )
    inode_bitmap_home = struct.unpack_from("<I", descriptor, 0x04)[0]
    with path.open("rb") as source:
        source.seek(inode_bitmap_home * block_size)
        inode_bitmap = bytearray(source.read(block_size))
    assert len(inode_bitmap) == block_size
    bitmap_byte, bitmap_bit = divmod(inode_index, 8)
    assert inode_bitmap[bitmap_byte] & (1 << bitmap_bit) == 0
    inode_bitmap[bitmap_byte] |= 1 << bitmap_bit
    inode_bitmap_checksum = _crc32c_raw(
        inode_bitmap[: inodes_per_group // 8],
        seed,
    )

    group_free = struct.unpack_from("<H", descriptor, 0x0E)[0] | (
        struct.unpack_from("<H", descriptor, 0x2E)[0] << 16
    )
    itable_unused = struct.unpack_from("<H", descriptor, 0x1C)[0] | (
        struct.unpack_from("<H", descriptor, 0x32)[0] << 16
    )
    assert group_free > 0
    assert itable_unused > 0
    group_free -= 1
    itable_unused -= 1
    struct.pack_into("<H", descriptor, 0x0E, group_free & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x2E, group_free >> 16)
    struct.pack_into("<H", descriptor, 0x1C, itable_unused & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x32, itable_unused >> 16)
    struct.pack_into(
        "<H", descriptor, 0x1A, inode_bitmap_checksum & 0xFFFF
    )
    struct.pack_into("<H", descriptor, 0x3A, inode_bitmap_checksum >> 16)
    descriptor = bytearray(
        _group_descriptor_with_checksum(superblock, descriptor, group)
    )
    gdt[descriptor_offset : descriptor_offset + descriptor_size] = descriptor

    super_free = struct.unpack_from("<I", superblock, 0x10)[0]
    assert super_free > 0
    struct.pack_into("<I", superblock, 0x10, super_free - 1)
    superblock = bytearray(_ext4_super_with_checksum(superblock))
    inode = bytearray(
        _inode_with_checksum(superblock, inode_number, inode)
    )

    patches[1024] = bytes(superblock)
    patches[inode_offset] = bytes(inode)
    patches[inode_bitmap_home * block_size] = bytes(inode_bitmap)
    patches[gdt_home * block_size] = bytes(gdt)
    assert len(patches) == 5
    return tuple(patches.items())


def _multi_empty_unlinked_orphan_patches(
    path: Path,
    *,
    legacy_chain: tuple[int, ...],
    modern_entries: tuple[int, ...],
) -> tuple[tuple[int, bytes], ...]:
    """Allocate two empty inodes behind one authenticated orphan union."""
    inode_numbers = legacy_chain + modern_entries
    assert len(inode_numbers) == 2
    assert set(inode_numbers) == {18, 21}
    assert len(set(inode_numbers)) == len(inode_numbers)

    patches = dict(
        _modern_orphan_patches(
            path,
            modern_entries,
            orphan_present=bool(modern_entries),
        )
    )
    superblock = bytearray(patches[1024])
    struct.pack_into(
        "<I",
        superblock,
        0xE8,
        legacy_chain[0] if legacy_chain else 0,
    )

    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_size = struct.unpack_from("<H", superblock, 0x58)[0]
    inodes_per_group = struct.unpack_from("<I", superblock, 0x28)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    checksum_seed = struct.unpack_from("<I", superblock, 0x270)[0]
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    assert block_size == 1024
    assert inode_size == 256
    assert descriptor_size == 64

    gdt_home = first_data + 1
    with path.open("rb") as source:
        source.seek(gdt_home * block_size)
        gdt = bytearray(source.read(block_size))
    assert len(gdt) == block_size
    descriptor = bytearray(gdt[:descriptor_size])
    inode_bitmap_home = struct.unpack_from("<I", descriptor, 0x04)[0]
    with path.open("rb") as source:
        source.seek(inode_bitmap_home * block_size)
        inode_bitmap = bytearray(source.read(block_size))
    assert len(inode_bitmap) == block_size

    group_free = struct.unpack_from("<H", descriptor, 0x0E)[0] | (
        struct.unpack_from("<H", descriptor, 0x2E)[0] << 16
    )
    itable_unused = struct.unpack_from("<H", descriptor, 0x1C)[0] | (
        struct.unpack_from("<H", descriptor, 0x32)[0] << 16
    )
    initialized = inodes_per_group - itable_unused
    highest_initialized = max(inode_numbers)
    assert initialized < 18
    assert highest_initialized == 21
    assert group_free >= len(inode_numbers)

    inode_offsets: dict[int, int] = {}
    for inode_number in inode_numbers:
        group, inode_index = divmod(inode_number - 1, inodes_per_group)
        assert group == 0
        _, free_inode, inode_offset = _ext4_inode_record(path, inode_number)
        assert not any(free_inode)
        bitmap_byte, bitmap_bit = divmod(inode_index, 8)
        bitmap_mask = 1 << bitmap_bit
        assert inode_bitmap[bitmap_byte] & bitmap_mask == 0
        inode_bitmap[bitmap_byte] |= bitmap_mask
        inode_offsets[inode_number] = inode_offset

    group_free -= len(inode_numbers)
    itable_unused = inodes_per_group - max(
        initialized,
        highest_initialized,
    )
    inode_bitmap_checksum = _crc32c_raw(
        inode_bitmap[: inodes_per_group // 8],
        checksum_seed,
    )
    struct.pack_into("<H", descriptor, 0x0E, group_free & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x2E, group_free >> 16)
    struct.pack_into("<H", descriptor, 0x1C, itable_unused & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x32, itable_unused >> 16)
    struct.pack_into(
        "<H",
        descriptor,
        0x1A,
        inode_bitmap_checksum & 0xFFFF,
    )
    struct.pack_into("<H", descriptor, 0x3A, inode_bitmap_checksum >> 16)

    super_free = struct.unpack_from("<I", superblock, 0x10)[0]
    assert super_free >= len(inode_numbers)
    struct.pack_into(
        "<I",
        superblock,
        0x10,
        super_free - len(inode_numbers),
    )
    superblock = bytearray(_ext4_super_with_checksum(superblock))
    descriptor = bytearray(
        _group_descriptor_with_checksum(superblock, descriptor, 0)
    )
    gdt[:descriptor_size] = descriptor

    _, source_inode, _ = _ext4_inode_record(path, 14)
    assert struct.unpack_from("<H", source_inode, 0x00)[0] & 0xF000 == 0x8000
    assert struct.unpack_from("<H", source_inode, 0x80)[0] == 32
    legacy_successors = {
        inode_number: (
            legacy_chain[index + 1]
            if index + 1 < len(legacy_chain)
            else 0
        )
        for index, inode_number in enumerate(legacy_chain)
    }
    generations = {18: 0x1818_1818, 21: 0x2121_2121}
    for inode_number in inode_numbers:
        inode = bytearray(source_inode)
        struct.pack_into("<I", inode, 0x04, 0)
        struct.pack_into(
            "<I",
            inode,
            0x14,
            legacy_successors.get(inode_number, 0),
        )
        struct.pack_into("<H", inode, 0x1A, 0)
        struct.pack_into("<I", inode, 0x1C, 0)
        flags = struct.unpack_from("<I", inode, 0x20)[0]
        assert flags & 0x0008_0000
        assert not flags & 0x0000_4000
        inode[0x28:0x64] = bytes(60)
        struct.pack_into("<HHHHI", inode, 0x28, 0xF30A, 0, 4, 0, 0)
        struct.pack_into("<I", inode, 0x64, generations[inode_number])
        struct.pack_into("<I", inode, 0x68, 0)
        struct.pack_into("<I", inode, 0x6C, 0)
        struct.pack_into("<H", inode, 0x74, 0)
        struct.pack_into("<H", inode, 0x76, 0)
        inode[0xA0:0x100] = bytes(0x60)
        patches[inode_offsets[inode_number]] = _inode_with_checksum(
            superblock,
            inode_number,
            inode,
        )

    patches[1024] = bytes(superblock)
    patches[inode_bitmap_home * block_size] = bytes(inode_bitmap)
    patches[gdt_home * block_size] = bytes(gdt)
    assert len(patches) == 6
    return tuple(patches.items())


def _multi_linked_orphan_patches(
    path: Path,
    *,
    protocol: str,
) -> tuple[tuple[int, bytes], ...]:
    """Retain two linked, already-empty inodes in one orphan protocol."""
    assert protocol in {"modern", "legacy"}
    legacy = protocol == "legacy"
    patches = dict(
        _multi_empty_unlinked_orphan_patches(
            path,
            legacy_chain=(18, 21) if legacy else (),
            modern_entries=() if legacy else (18, 21),
        )
    )
    superblock = patches[1024]
    assert struct.unpack_from("<I", superblock, 0xE8)[0] == (
        18 if legacy else 0
    )

    for inode_number, successor in (
        ((18, 21), (21, 0)) if legacy else ((18, 0), (21, 0))
    ):
        _, _, inode_offset = _ext4_inode_record(path, inode_number)
        inode = bytearray(patches[inode_offset])
        assert struct.unpack_from("<I", inode, 0x04)[0] == 0
        assert struct.unpack_from("<I", inode, 0x14)[0] == successor
        assert struct.unpack_from("<H", inode, 0x1A)[0] == 0
        assert struct.unpack_from("<HHHH", inode, 0x28) == (
            0xF30A,
            0,
            4,
            0,
        )
        struct.pack_into("<H", inode, 0x1A, 2)
        patches[inode_offset] = _inode_with_checksum(
            superblock,
            inode_number,
            inode,
        )

    return tuple(patches.items())


def _multi_linked_empty_legacy_map_orphan_patches(
    path: Path,
    *,
    protocol: str,
) -> tuple[tuple[int, bytes], ...]:
    """Retain two linked empty legacy-map inodes in one orphan protocol."""
    patches = dict(_multi_linked_orphan_patches(path, protocol=protocol))
    superblock = patches[1024]

    for inode_number, successor in (
        ((18, 21), (21, 0))
        if protocol == "legacy"
        else ((18, 0), (21, 0))
    ):
        _, _, inode_offset = _ext4_inode_record(path, inode_number)
        inode = bytearray(patches[inode_offset])
        assert struct.unpack_from("<I", inode, 0x04)[0] == 0
        assert struct.unpack_from("<I", inode, 0x6C)[0] == 0
        assert struct.unpack_from("<I", inode, 0x14)[0] == successor
        assert struct.unpack_from("<H", inode, 0x1A)[0] == 2
        assert struct.unpack_from("<I", inode, 0x1C)[0] == 0
        assert struct.unpack_from("<I", inode, 0x68)[0] == 0
        assert struct.unpack_from("<H", inode, 0x76)[0] == 0
        assert struct.unpack_from("<HHHH", inode, 0x28) == (
            0xF30A,
            0,
            4,
            0,
        )
        flags = struct.unpack_from("<I", inode, 0x20)[0]
        assert flags & 0x0008_0000
        struct.pack_into("<I", inode, 0x20, flags & ~0x0008_0000)
        inode[0x28:0x64] = bytes(60)
        patches[inode_offset] = _inode_with_checksum(
            superblock,
            inode_number,
            inode,
        )

    return tuple(patches.items())


def _linked_head_nlink2_extent_patches(
    path: Path,
    *,
    protocol: str,
    extent_count: int,
) -> tuple[tuple[tuple[int, bytes], ...], tuple[int, ...]]:
    """Give linked orphan head 18 exact separately described extents.

    Both inodes are filesystem-linked (``i_links_count == 2``), separately
    from the modern orphan-file or legacy list relationship. Recovery must
    truncate and advance the nonterminal head before completing the terminal
    record.
    """
    assert protocol in {"modern", "legacy"}
    assert 1 <= extent_count <= 4
    base = _multi_linked_orphan_patches(path, protocol=protocol)
    patches, first_data_block = _single_extent_unlinked_orphan_patches(
        path,
        protocol=protocol,
        inode_number=18,
        block_count=extent_count,
        seed_payloads=True,
        base_patches=base,
    )
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    _, _, inode18_offset = _ext4_inode_record(path, 18)
    _, _, inode21_offset = _ext4_inode_record(path, 21)
    inode18 = bytearray(patch_map[inode18_offset])
    inode21 = patch_map[inode21_offset]
    assert struct.unpack_from("<H", inode18, 0x1A)[0] == 2
    expected_successor = 21 if protocol == "legacy" else 0
    assert struct.unpack_from("<I", inode18, 0x14)[0] == expected_successor
    assert struct.unpack_from("<HHHH", inode18, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    assert struct.unpack_from("<I", inode18, 0x1C)[0] == (
        extent_count * sectors_per_block
    )
    data_blocks = tuple(
        range(first_data_block, first_data_block + extent_count)
    )
    if extent_count > 1:
        struct.pack_into("<H", inode18, 0x2A, extent_count)
        inode18[0x34:0x64] = bytes(48)
        for index, physical in enumerate(data_blocks):
            struct.pack_into(
                "<IHHI",
                inode18,
                0x34 + index * 12,
                index * 2,
                1,
                physical >> 32,
                physical & 0xFFFF_FFFF,
            )
        patch_map[inode18_offset] = _inode_with_checksum(
            superblock,
            18,
            inode18,
        )
    for index, physical in enumerate(data_blocks):
        assert _extent_root_physical(
            patch_map[inode18_offset],
            index * 2,
        ) == physical
    assert struct.unpack_from("<H", inode21, 0x1A)[0] == 2
    assert struct.unpack_from("<I", inode21, 0x14)[0] == 0
    assert struct.unpack_from("<HHHH", inode21, 0x28) == (
        0xF30A,
        0,
        4,
        0,
    )
    return tuple(patch_map.items()), data_blocks


def _mixed_union_with_later_unlinked_live_alias_patches(
    path: Path,
) -> tuple[tuple[tuple[int, bytes], ...], tuple[int, ...]]:
    """Place a later unlinked modern record whose fourth range is live-owned."""
    base = _multi_empty_unlinked_orphan_patches(
        path,
        legacy_chain=(21,),
        modern_entries=(18,),
    )
    patches, physical_ranges = _inline_depth0_unlinked_orphan_patches(
        path,
        protocol="modern",
        inode_number=18,
        extent_specs=(
            (0, 1, False),
            (2, 1, True),
            (4, 1, False),
        ),
        base_patches=base,
    )
    assert all(block_count == 1 for _, block_count in physical_ranges)
    physical_blocks = tuple(first for first, _ in physical_ranges)
    patch_map = dict(patches)
    assert len(patch_map) == 7
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    _, _, inode_offset = _ext4_inode_record(path, 18)
    inode = bytearray(patch_map[inode_offset])
    assert struct.unpack_from("<HHHH", inode, 0x28) == (
        0xF30A,
        3,
        4,
        0,
    )
    for index, physical in enumerate(physical_blocks):
        assert struct.unpack_from(
            "<IHHI",
            inode,
            0x34 + index * 12,
        ) == (
            index * 2,
            0x8001 if index == 1 else 1,
            physical >> 32,
            physical & 0xFFFF_FFFF,
        )
    assert struct.unpack_from("<I", inode, 0x04)[0] == 0
    assert struct.unpack_from("<H", inode, 0x1A)[0] == 0
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 3 * (block_size // 512)

    _, live_inode, _ = _ext4_inode_record(path, 14)
    assert struct.unpack_from("<H", live_inode, 0x1A)[0] > 0
    alias_physical = _extent_root_physical(live_inode, 0)
    assert alias_physical not in physical_blocks

    struct.pack_into("<H", inode, 0x2A, 4)
    struct.pack_into(
        "<IHHI",
        inode,
        0x58,
        6,
        0x8001,
        alias_physical >> 32,
        alias_physical & 0xFFFF_FFFF,
    )
    struct.pack_into("<I", inode, 0x1C, 4 * (block_size // 512))
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        18,
        inode,
    )
    for index, physical in enumerate((*physical_blocks, alias_physical)):
        assert _extent_root_physical(
            patch_map[inode_offset],
            index * 2,
        ) == physical
    return tuple(patch_map.items()), (*physical_blocks, alias_physical)


def _allocate_unlinked_extent_ranges(
    path: Path,
    *,
    protocol: str,
    extent_specs: tuple[tuple[int, int, bool], ...],
    inode_number: int = 18,
    data_group: int = 0,
    physical_starts: tuple[int, ...] | None = None,
    physical_gap: int = 1,
    seed_payloads: bool = False,
    seed_gap_payloads: bool = False,
    base_patches: tuple[tuple[int, bytes], ...] | None = None,
) -> tuple[tuple[tuple[int, bytes], ...], tuple[tuple[int, int], ...]]:
    """Allocate exact physical ranges without choosing an inode map shape."""
    assert protocol in {"modern", "legacy"}
    assert extent_specs
    assert physical_gap >= 0
    previous_logical_end = 0
    for index, (logical_start, block_count, unwritten) in enumerate(extent_specs):
        assert logical_start >= 0
        assert block_count > 0
        assert block_count <= (0x7FFF if unwritten else 0x8000)
        assert logical_start + block_count <= 0xFFFF_FFFF
        if index:
            assert logical_start >= previous_logical_end
        previous_logical_end = logical_start + block_count
    total_blocks = sum(block_count for _, block_count, _ in extent_specs)
    assert total_blocks > 0
    if physical_starts is not None:
        assert len(physical_starts) == len(extent_specs)
    if base_patches is None:
        patches = dict(
            _already_empty_unlinked_orphan_patches(
                path,
                protocol=protocol,
                inode_number=inode_number,
            )
        )
    else:
        patches = dict(base_patches)
        assert len(patches) == len(base_patches)
        _, _, existing_inode_offset = _ext4_inode_record(path, inode_number)
        assert 1024 in patches
        assert existing_inode_offset in patches
    superblock = bytearray(patches[1024])
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    blocks_count = struct.unpack_from("<I", superblock, 0x04)[0] | (
        struct.unpack_from("<I", superblock, 0x150)[0] << 32
    )
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    assert descriptor_size == 64
    assert first_data < blocks_count
    group_count = (
        blocks_count - first_data + blocks_per_group - 1
    ) // blocks_per_group
    assert 0 <= data_group < group_count
    descriptors_per_block = block_size // descriptor_size

    def read_block(block: int) -> bytearray:
        offset = block * block_size
        if offset in patches:
            result = bytearray(patches[offset])
        else:
            with path.open("rb") as source:
                source.seek(offset)
                result = bytearray(source.read(block_size))
        assert len(result) == block_size
        return result

    def descriptor_for(group: int) -> tuple[int, int, bytearray]:
        gdt_home = first_data + 1 + group // descriptors_per_block
        descriptor_offset = (
            group % descriptors_per_block
        ) * descriptor_size
        gdt = read_block(gdt_home)
        descriptor = bytearray(
            gdt[
                descriptor_offset : descriptor_offset + descriptor_size
            ]
        )
        assert len(descriptor) == descriptor_size
        return gdt_home, descriptor_offset, descriptor

    auto_physical = physical_starts is None
    if auto_physical:
        _, _, descriptor = descriptor_for(data_group)
        block_bitmap_home = struct.unpack_from(
            "<I", descriptor, 0x00
        )[0]
        block_bitmap = read_block(block_bitmap_home)
        group_first = first_data + data_group * blocks_per_group
        group_blocks = min(blocks_per_group, blocks_count - group_first)
        physical_span = total_blocks + physical_gap * (len(extent_specs) - 1)
        assert physical_span <= group_blocks
        data_index = next(
            index
            for index in range(group_blocks - physical_span + 1)
            if all(
                not block_bitmap[bit // 8] & (1 << (bit % 8))
                for bit in range(index, index + physical_span)
            )
        )
        next_physical = group_first + data_index
        derived_starts: list[int] = []
        for _, block_count, _ in extent_specs:
            derived_starts.append(next_physical)
            next_physical += block_count + physical_gap
        physical_starts = tuple(derived_starts)
    assert physical_starts is not None
    physical_ranges = tuple(
        (physical_start, block_count)
        for physical_start, (_, block_count, _) in zip(
            physical_starts,
            extent_specs,
            strict=True,
        )
    )
    for index, (physical_start, block_count) in enumerate(physical_ranges):
        assert physical_start >= first_data
        assert physical_start + block_count <= blocks_count
        assert physical_start <= 0xFFFF_FFFF
        for other_start, other_count in physical_ranges[:index]:
            assert physical_start + block_count <= other_start or (
                other_start + other_count <= physical_start
            )

    if seed_payloads:
        selected_blocks = tuple(
            physical
            for physical_start, block_count in physical_ranges
            for physical in range(physical_start, physical_start + block_count)
        )
        for ordinal, physical in enumerate(selected_blocks):
            token = (ordinal + 1).to_bytes(8, "little")
            payload = (token * ((block_size + len(token) - 1) // len(token)))[
                :block_size
            ]
            assert payload != bytes(block_size)
            offset = physical * block_size
            assert offset not in patches
            patches[offset] = payload

    if seed_gap_payloads:
        assert auto_physical
        for index in range(len(physical_ranges) - 1):
            gap_first = sum(physical_ranges[index])
            gap_end = physical_ranges[index + 1][0]
            assert gap_end - gap_first == physical_gap
            for ordinal, physical in enumerate(range(gap_first, gap_end)):
                token = (0x8000_0000 + index * physical_gap + ordinal).to_bytes(
                    8,
                    "little",
                )
                payload = (
                    token * ((block_size + len(token) - 1) // len(token))
                )[:block_size]
                offset = physical * block_size
                assert offset not in patches
                patches[offset] = payload

    for physical_start, range_blocks in physical_ranges:
        cursor = physical_start
        remaining = range_blocks
        while remaining:
            group, data_index = divmod(
                cursor - first_data,
                blocks_per_group,
            )
            assert 0 <= group < group_count
            group_first = first_data + group * blocks_per_group
            group_blocks = min(blocks_per_group, blocks_count - group_first)
            assert data_index < group_blocks
            chunk = min(remaining, group_blocks - data_index)
            gdt_home, descriptor_offset, descriptor = descriptor_for(group)
            gdt = read_block(gdt_home)
            block_bitmap_home = struct.unpack_from(
                "<I", descriptor, 0x00
            )[0]
            block_bitmap = read_block(block_bitmap_home)
            for bit in range(data_index, data_index + chunk):
                byte_index, bit_in_byte = divmod(bit, 8)
                mask = 1 << bit_in_byte
                assert block_bitmap[byte_index] & mask == 0
                block_bitmap[byte_index] |= mask
            block_bitmap_checksum = _crc32c_raw(block_bitmap, seed)

            flags = struct.unpack_from("<H", descriptor, 0x12)[0]
            if flags & 0x02:
                struct.pack_into("<H", descriptor, 0x12, flags & ~0x02)
            group_free_blocks = struct.unpack_from(
                "<H", descriptor, 0x0C
            )[0] | (struct.unpack_from("<H", descriptor, 0x2C)[0] << 16)
            assert group_free_blocks >= chunk
            group_free_blocks -= chunk
            struct.pack_into(
                "<H", descriptor, 0x0C, group_free_blocks & 0xFFFF
            )
            struct.pack_into(
                "<H", descriptor, 0x2C, group_free_blocks >> 16
            )
            struct.pack_into(
                "<H", descriptor, 0x18, block_bitmap_checksum & 0xFFFF
            )
            struct.pack_into(
                "<H", descriptor, 0x38, block_bitmap_checksum >> 16
            )
            descriptor = bytearray(
                _group_descriptor_with_checksum(
                    superblock,
                    descriptor,
                    group,
                )
            )
            gdt[
                descriptor_offset : descriptor_offset + descriptor_size
            ] = descriptor
            patches[block_bitmap_home * block_size] = bytes(block_bitmap)
            patches[gdt_home * block_size] = bytes(gdt)
            cursor += chunk
            remaining -= chunk

    super_free_blocks = struct.unpack_from("<I", superblock, 0x0C)[0] | (
        struct.unpack_from("<I", superblock, 0x158)[0] << 32
    )
    assert super_free_blocks >= total_blocks
    super_free_blocks -= total_blocks
    struct.pack_into(
        "<I", superblock, 0x0C, super_free_blocks & 0xFFFF_FFFF
    )
    struct.pack_into("<I", superblock, 0x158, super_free_blocks >> 32)
    superblock = bytearray(_ext4_super_with_checksum(superblock))

    patches[1024] = bytes(superblock)
    return tuple(patches.items()), physical_ranges


def _inline_depth0_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    extent_specs: tuple[tuple[int, int, bool], ...],
    inode_number: int = 18,
    data_group: int = 0,
    physical_starts: tuple[int, ...] | None = None,
    physical_gap: int = 1,
    seed_payloads: bool = False,
    seed_gap_payloads: bool = False,
    size_bytes: int = 0,
    base_patches: tuple[tuple[int, bytes], ...] | None = None,
) -> tuple[tuple[tuple[int, bytes], ...], tuple[tuple[int, int], ...]]:
    """Give one unlinked inode an exact inline depth-zero extent vector."""
    assert 1 <= len(extent_specs) <= 4
    assert 0 <= size_bytes < (1 << 63)
    allocated_patches, physical_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol=protocol,
        extent_specs=extent_specs,
        inode_number=inode_number,
        data_group=data_group,
        physical_starts=physical_starts,
        physical_gap=physical_gap,
        seed_payloads=seed_payloads,
        seed_gap_payloads=seed_gap_payloads,
        base_patches=base_patches,
    )
    patches = dict(allocated_patches)
    superblock = patches[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    total_blocks = sum(block_count for _, block_count, _ in extent_specs)

    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patches[inode_offset])
    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 0, 4, 0)
    struct.pack_into("<I", inode, 0x04, size_bytes & 0xFFFF_FFFF)
    struct.pack_into("<I", inode, 0x6C, size_bytes >> 32)
    struct.pack_into("<H", inode, 0x2A, len(extent_specs))
    inode[0x34:0x64] = bytes(48)
    for index, (
        (logical_start, block_count, unwritten),
        (physical_start, observed_count),
    ) in enumerate(zip(extent_specs, physical_ranges, strict=True)):
        assert observed_count == block_count
        raw_length = block_count | (0x8000 if unwritten else 0)
        struct.pack_into(
            "<IHHI",
            inode,
            0x34 + index * 12,
            logical_start,
            raw_length,
            physical_start >> 32,
            physical_start & 0xFFFF_FFFF,
        )
    sectors = total_blocks * sectors_per_block
    assert sectors <= 0xFFFF_FFFF
    struct.pack_into("<I", inode, 0x1C, sectors)
    struct.pack_into("<H", inode, 0x74, 0)
    inode = bytearray(
        _inode_with_checksum(superblock, inode_number, inode)
    )

    patches[1024] = bytes(superblock)
    patches[inode_offset] = bytes(inode)
    return tuple(patches.items()), physical_ranges


_DEPTH1_FOUR_LEAF_EXTENT_SPECS = (
    ((0, 1, False), (3, 2, True)),
    ((8, 1, False),),
    ((12, 2, True), (16, 1, False)),
    ((20, 1, False),),
)


def _depth1_external_leaves_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    inode_number: int = 18,
    leaf_extent_specs: tuple[
        tuple[tuple[int, int, bool], ...], ...
    ] = _DEPTH1_FOUR_LEAF_EXTENT_SPECS,
    physical_gap: int = 1,
    size_bytes: int = (1 << 32) + 777,
) -> tuple[
    tuple[tuple[int, bytes], ...],
    tuple[tuple[int, int], ...],
    tuple[int, ...],
]:
    """Give one unlinked inode a complete resident depth-one fanout."""
    assert protocol in {"modern", "legacy"}
    assert 1 <= len(leaf_extent_specs) <= 4
    assert all(leaf_extent_specs)
    assert physical_gap >= 0
    assert 0 <= size_bytes < (1 << 63)
    with path.open("rb") as source:
        source.seek(1024)
        source_superblock = source.read(1024)
    assert len(source_superblock) == 1024
    source_block_size = 1024 << struct.unpack_from(
        "<I", source_superblock, 0x18
    )[0]
    source_leaf_max = (source_block_size - 12) // 12
    assert all(
        len(extent_specs) <= source_leaf_max
        for extent_specs in leaf_extent_specs
    )
    flattened_specs = tuple(
        extent
        for extent_specs in leaf_extent_specs
        for extent in extent_specs
    )
    previous_logical_end = 0
    for leaf_index, extent_specs in enumerate(leaf_extent_specs):
        for extent_index, (logical_start, block_count, _) in enumerate(
            extent_specs
        ):
            if leaf_index or extent_index:
                assert logical_start >= previous_logical_end
            previous_logical_end = logical_start + block_count
    final_logical = max(
        logical_start + block_count
        for logical_start, block_count, _ in flattened_specs
    )
    leaf_allocation_specs = tuple(
        (final_logical + 1 + 2 * index, 1, False)
        for index in range(len(leaf_extent_specs))
    )
    allocation_specs = (*flattened_specs, *leaf_allocation_specs)
    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    patches, allocated_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol=protocol,
        inode_number=inode_number,
        extent_specs=allocation_specs,
        physical_gap=physical_gap,
        seed_payloads=True,
        seed_gap_payloads=True,
    )
    patch_map = dict(patches)
    data_count = len(flattened_specs)
    assert len(allocated_ranges) == data_count + len(leaf_extent_specs)
    data_ranges = allocated_ranges[:data_count]
    leaf_ranges = allocated_ranges[data_count:]
    assert all(count == 1 for _, count in leaf_ranges)
    leaf_blocks = tuple(first for first, _ in leaf_ranges)
    for expected, observed in zip(flattened_specs, data_ranges, strict=True):
        assert expected[1] == observed[1]

    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    leaf_max = (block_size - 12) // 12
    inode = bytearray(patch_map[inode_offset])
    generation = struct.unpack_from("<I", inode, 0x64)[0]
    data_index = 0
    for extent_specs, leaf_block in zip(
        leaf_extent_specs, leaf_blocks, strict=True
    ):
        assert len(extent_specs) <= leaf_max
        leaf = bytearray(block_size)
        struct.pack_into(
            "<HHHHI",
            leaf,
            0,
            0xF30A,
            len(extent_specs),
            leaf_max,
            0,
            0,
        )
        for leaf_entry, (logical_start, block_count, unwritten) in enumerate(
            extent_specs
        ):
            physical_start, observed_count = data_ranges[data_index]
            data_index += 1
            assert observed_count == block_count
            raw_length = block_count | (0x8000 if unwritten else 0)
            struct.pack_into(
                "<IHHI",
                leaf,
                12 + leaf_entry * 12,
                logical_start,
                raw_length,
                physical_start >> 32,
                physical_start & 0xFFFF_FFFF,
            )
        patch_map[leaf_block * block_size] = _extent_node_with_checksum(
            superblock,
            inode_number,
            generation,
            leaf,
        )
    assert data_index == len(data_ranges)
    sectors_per_block = block_size // 512
    total_blocks = sum(count for _, count in data_ranges) + len(leaf_blocks)
    sectors = total_blocks * sectors_per_block
    assert sectors <= 0xFFFF_FFFF
    struct.pack_into("<I", inode, 0x04, size_bytes & 0xFFFF_FFFF)
    struct.pack_into("<I", inode, 0x6C, size_bytes >> 32)
    struct.pack_into("<I", inode, 0x1C, sectors)
    struct.pack_into("<H", inode, 0x74, 0)
    struct.pack_into(
        "<HHHHI",
        inode,
        0x28,
        0xF30A,
        len(leaf_extent_specs),
        4,
        1,
        0,
    )
    inode[0x34:0x64] = bytes(48)
    for root_index, (extent_specs, leaf_block) in enumerate(
        zip(leaf_extent_specs, leaf_blocks, strict=True)
    ):
        struct.pack_into(
            "<IIHH",
            inode,
            0x34 + root_index * 12,
            extent_specs[0][0],
            leaf_block & 0xFFFF_FFFF,
            leaf_block >> 32,
            0,
        )
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    return tuple(patch_map.items()), data_ranges, leaf_blocks


def _malformed_depth1_external_leaves_unlinked_orphan_patches(
    path: Path,
    case: str,
) -> tuple[
    tuple[tuple[int, bytes], ...],
    tuple[tuple[int, int], ...],
    tuple[int, ...],
]:
    """Derive one checksum-coherent malformed depth-one fanout."""
    leaf_extent_specs = (
        ((0, 1, False), (3, 2, True)),
        ((8, 1, False),),
    )
    patches, data_ranges, leaf_blocks = (
        _depth1_external_leaves_unlinked_orphan_patches(
            path,
            protocol="modern",
            leaf_extent_specs=leaf_extent_specs,
        )
    )
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    _, _, inode_offset = _ext4_inode_record(path, 18)
    inode = bytearray(patch_map[inode_offset])
    generation = struct.unpack_from("<I", inode, 0x64)[0]

    if case == "cross-leaf-data-alias":
        leaf_offset = leaf_blocks[1] * block_size
        leaf = bytearray(patch_map[leaf_offset])
        alias = data_ranges[0][0]
        struct.pack_into("<H", leaf, 18, alias >> 32)
        struct.pack_into("<I", leaf, 20, alias & 0xFFFF_FFFF)
        patch_map[leaf_offset] = _extent_node_with_checksum(
            superblock,
            18,
            generation,
            leaf,
        )
    elif case == "leaf-data-alias":
        leaf_offset = leaf_blocks[0] * block_size
        leaf = bytearray(patch_map[leaf_offset])
        struct.pack_into("<H", leaf, 18, leaf_blocks[0] >> 32)
        struct.pack_into("<I", leaf, 20, leaf_blocks[0] & 0xFFFF_FFFF)
        patch_map[leaf_offset] = _extent_node_with_checksum(
            superblock,
            18,
            generation,
            leaf,
        )
    elif case == "leaf-to-other-leaf-alias":
        leaf_offset = leaf_blocks[0] * block_size
        leaf = bytearray(patch_map[leaf_offset])
        struct.pack_into("<H", leaf, 18, leaf_blocks[1] >> 32)
        struct.pack_into("<I", leaf, 20, leaf_blocks[1] & 0xFFFF_FFFF)
        patch_map[leaf_offset] = _extent_node_with_checksum(
            superblock,
            18,
            generation,
            leaf,
        )
    else:
        assert case == "other-inode-owns-leaf"
        _, raw_owner, owner_offset = _ext4_inode_record(path, 14)
        owner = bytearray(raw_owner)
        assert struct.unpack_from("<HHHH", owner, 0x28) == (
            0xF30A,
            1,
            4,
            0,
        )
        assert struct.unpack_from("<H", owner, 0x38)[0] == 1
        struct.pack_into("<H", owner, 0x3A, leaf_blocks[-1] >> 32)
        struct.pack_into("<I", owner, 0x3C, leaf_blocks[-1] & 0xFFFF_FFFF)
        patch_map[owner_offset] = _inode_with_checksum(
            superblock,
            14,
            owner,
        )
    return tuple(patch_map.items()), data_ranges, leaf_blocks


def _legacy_direct_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    direct_slots: tuple[int, ...],
    inode_number: int = 18,
    seed_payloads: bool = False,
    size_bytes: int = 0,
    base_patches: tuple[tuple[int, bytes], ...] | None = None,
) -> tuple[tuple[tuple[int, bytes], ...], tuple[tuple[int, int], ...]]:
    """Give one unlinked inode an exact direct-only legacy block map."""
    assert direct_slots
    assert tuple(sorted(set(direct_slots))) == direct_slots
    assert 0 <= direct_slots[0] and direct_slots[-1] < 12
    patches, allocated_ranges = _inline_depth0_unlinked_orphan_patches(
        path,
        protocol=protocol,
        extent_specs=((0, len(direct_slots), False),),
        inode_number=inode_number,
        physical_gap=0,
        seed_payloads=seed_payloads,
        size_bytes=size_bytes,
        base_patches=base_patches,
    )
    assert len(allocated_ranges) == 1
    first_physical, block_count = allocated_ranges[0]
    assert block_count == len(direct_slots)
    direct_ranges = tuple(
        (first_physical + index, 1) for index in range(block_count)
    )

    patch_map = dict(patches)
    superblock = patch_map[1024]
    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patch_map[inode_offset])
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    struct.pack_into("<I", inode, 0x20, flags & ~0x0008_0000)
    inode[0x28:0x64] = bytes(60)
    for slot, (physical, count) in zip(
        direct_slots,
        direct_ranges,
        strict=True,
    ):
        assert count == 1
        struct.pack_into("<I", inode, 0x28 + slot * 4, physical)
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    return tuple(patch_map.items()), direct_ranges


def _legacy_indirect_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    direct_slots: tuple[int, ...] = (0,),
    single_slots: tuple[int, ...] = (),
    double_children: tuple[tuple[int, tuple[int, ...]], ...] = (),
    empty_double_root: bool = False,
    empty_triple_root: bool = False,
    triple_child_slot: int | None = None,
    inode_number: int = 18,
    physical_gap: int = 1,
    seed_payloads: bool = False,
    seed_gap_payloads: bool = False,
    size_bytes: int = 0,
    base_patches: tuple[tuple[int, bytes], ...] | None = None,
) -> tuple[
    tuple[tuple[int, bytes], ...],
    tuple[tuple[int, int], ...],
    tuple[tuple[int, int], ...],
]:
    """Give one unlinked legacy inode an exact direct/indirect map.

    ``triple_child_slot`` selects the sole occupied triple-root slot and
    constructs its child as an allocated all-zero pointer block.
    """
    assert protocol in {"modern", "legacy"}
    assert tuple(sorted(set(direct_slots))) == direct_slots
    assert not direct_slots or (0 <= direct_slots[0] and direct_slots[-1] < 12)
    assert tuple(sorted(set(single_slots))) == single_slots
    double_outer_slots = tuple(outer for outer, _ in double_children)
    assert tuple(sorted(set(double_outer_slots))) == double_outer_slots
    assert not (empty_double_root and double_children)
    assert not (empty_triple_root and triple_child_slot is not None)
    has_triple_root = empty_triple_root or triple_child_slot is not None
    assert not (
        has_triple_root
        and (single_slots or double_children or empty_double_root)
    )
    assert physical_gap >= 0
    assert 0 <= size_bytes < (1 << 63)

    with path.open("rb") as source:
        source.seek(1024)
        source_superblock = source.read(1024)
    assert len(source_superblock) == 1024
    source_block_size = 1024 << struct.unpack_from(
        "<I", source_superblock, 0x18
    )[0]
    pointer_count = source_block_size // 4
    assert triple_child_slot is None or (
        0 <= triple_child_slot < pointer_count
    )
    assert not single_slots or (
        0 <= single_slots[0] and single_slots[-1] < pointer_count
    )
    for outer_slot, inner_slots in double_children:
        assert 0 <= outer_slot < pointer_count
        assert inner_slots
        assert tuple(sorted(set(inner_slots))) == inner_slots
        assert 0 <= inner_slots[0] and inner_slots[-1] < pointer_count

    double_data_count = sum(
        len(inner_slots) for _, inner_slots in double_children
    )
    has_double_root = empty_double_root or bool(double_children)
    data_count = len(direct_slots) + len(single_slots) + double_data_count
    triple_map_count = (
        2 if triple_child_slot is not None else int(has_triple_root)
    )
    map_count = (
        (1 if single_slots else 0)
        + (1 + len(double_children) if has_double_root else 0)
        + triple_map_count
    )
    assert data_count + map_count > 0
    allocation_specs = tuple(
        (2 * index, 1, False) for index in range(data_count + map_count)
    )
    patches, allocated_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol=protocol,
        extent_specs=allocation_specs,
        inode_number=inode_number,
        physical_gap=physical_gap,
        seed_payloads=seed_payloads,
        seed_gap_payloads=seed_gap_payloads,
        base_patches=base_patches,
    )
    assert len(allocated_ranges) == data_count + map_count
    assert all(count == 1 for _, count in allocated_ranges)
    data_ranges = allocated_ranges[:data_count]
    map_ranges = allocated_ranges[data_count:]

    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    assert block_size == source_block_size
    data_cursor = 0
    direct_ranges = data_ranges[data_cursor : data_cursor + len(direct_slots)]
    data_cursor += len(direct_slots)
    single_ranges = data_ranges[data_cursor : data_cursor + len(single_slots)]
    data_cursor += len(single_slots)
    double_range_sets: list[tuple[tuple[int, int], ...]] = []
    for _, inner_slots in double_children:
        inner_ranges = data_ranges[
            data_cursor : data_cursor + len(inner_slots)
        ]
        data_cursor += len(inner_slots)
        double_range_sets.append(inner_ranges)
    assert data_cursor == len(data_ranges)

    map_cursor = 0
    single_home = 0
    if single_slots:
        single_home = map_ranges[map_cursor][0]
        map_cursor += 1
        single_block = bytearray(block_size)
        for slot, (physical, count) in zip(
            single_slots,
            single_ranges,
            strict=True,
        ):
            assert count == 1
            struct.pack_into("<I", single_block, slot * 4, physical)
        patch_map[single_home * block_size] = bytes(single_block)

    double_home = 0
    if has_double_root:
        double_home = map_ranges[map_cursor][0]
        map_cursor += 1
        child_ranges = map_ranges[
            map_cursor : map_cursor + len(double_children)
        ]
        map_cursor += len(double_children)
        double_root = bytearray(block_size)
        for (outer_slot, inner_slots), child_range, inner_ranges in zip(
            double_children,
            child_ranges,
            double_range_sets,
            strict=True,
        ):
            child_home, child_count = child_range
            assert child_count == 1
            struct.pack_into("<I", double_root, outer_slot * 4, child_home)
            child_block = bytearray(block_size)
            for inner_slot, (physical, count) in zip(
                inner_slots,
                inner_ranges,
                strict=True,
            ):
                assert count == 1
                struct.pack_into("<I", child_block, inner_slot * 4, physical)
            patch_map[child_home * block_size] = bytes(child_block)
        patch_map[double_home * block_size] = bytes(double_root)

    triple_home = 0
    if has_triple_root:
        triple_home = map_ranges[map_cursor][0]
        map_cursor += 1
        triple_root = bytearray(block_size)
        if triple_child_slot is not None:
            triple_child_home, triple_child_count = map_ranges[map_cursor]
            map_cursor += 1
            assert triple_child_count == 1
            struct.pack_into(
                "<I",
                triple_root,
                triple_child_slot * 4,
                triple_child_home,
            )
            patch_map[triple_child_home * block_size] = bytes(block_size)
        patch_map[triple_home * block_size] = bytes(triple_root)
    assert map_cursor == len(map_ranges)

    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patch_map[inode_offset])
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    struct.pack_into("<I", inode, 0x20, flags & ~0x0008_0000)
    struct.pack_into("<I", inode, 0x04, size_bytes & 0xFFFF_FFFF)
    struct.pack_into("<I", inode, 0x6C, size_bytes >> 32)
    inode[0x28:0x64] = bytes(60)
    for slot, (physical, count) in zip(
        direct_slots,
        direct_ranges,
        strict=True,
    ):
        assert count == 1
        struct.pack_into("<I", inode, 0x28 + slot * 4, physical)
    struct.pack_into("<I", inode, 0x28 + 12 * 4, single_home)
    struct.pack_into("<I", inode, 0x28 + 13 * 4, double_home)
    struct.pack_into("<I", inode, 0x28 + 14 * 4, triple_home)
    sectors_per_block = block_size // 512
    assert struct.unpack_from("<H", inode, 0x76)[0] == 0
    xattr_blocks = 1 if struct.unpack_from("<I", inode, 0x68)[0] else 0
    struct.pack_into(
        "<I",
        inode,
        0x1C,
        (data_count + map_count + xattr_blocks) * sectors_per_block,
    )
    struct.pack_into("<H", inode, 0x74, 0)
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    return tuple(patch_map.items()), data_ranges, map_ranges


def _single_extent_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    inode_number: int = 18,
    data_group: int = 0,
    physical_start: int | None = None,
    logical_start: int = 0,
    block_count: int = 1,
    unwritten: bool = False,
    seed_payloads: bool = False,
    size_bytes: int = 0,
    base_patches: tuple[tuple[int, bytes], ...] | None = None,
) -> tuple[tuple[tuple[int, bytes], ...], int]:
    """Give one unlinked inode one contiguous inline depth-zero extent."""
    patches, ranges = _inline_depth0_unlinked_orphan_patches(
        path,
        protocol=protocol,
        extent_specs=((logical_start, block_count, unwritten),),
        inode_number=inode_number,
        data_group=data_group,
        physical_starts=(physical_start,) if physical_start is not None else None,
        physical_gap=0,
        seed_payloads=seed_payloads,
        size_bytes=size_bytes,
        base_patches=base_patches,
    )
    assert len(ranges) == 1
    assert ranges[0][1] == block_count
    return patches, ranges[0][0]


def _unlinked_orphan_external_xattr_patches(
    path: Path,
    *,
    protocol: str,
    data_blocks: int,
    inode_number: int = 18,
    data_group: int = 0,
) -> tuple[
    tuple[tuple[int, bytes], ...],
    tuple[tuple[int, int], ...],
    int,
]:
    """Give one unlinked orphan data plus one unique external xattr block."""
    assert data_blocks >= 0
    patches, first_physical = _single_extent_unlinked_orphan_patches(
        path,
        protocol=protocol,
        inode_number=inode_number,
        data_group=data_group,
        block_count=data_blocks + 1,
    )
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    xattr_block = first_physical + data_blocks

    _, source_inode, _ = _ext4_inode_record(path, 14)
    source_xattr = struct.unpack_from("<I", source_inode, 0x68)[0]
    assert source_xattr > 0 and source_xattr != xattr_block
    assert struct.unpack_from("<H", source_inode, 0x76)[0] == 0
    with path.open("rb") as source:
        source.seek(source_xattr * block_size)
        source_block = source.read(block_size)
    assert len(source_block) == block_size
    assert struct.unpack_from("<I", source_block, 0x04)[0] == 1
    assert _external_xattr_block_with_checksum(
        superblock,
        source_xattr,
        source_block,
    ) == source_block
    xattr_offset = xattr_block * block_size
    assert xattr_offset not in patch_map
    patch_map[xattr_offset] = _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        source_block,
    )

    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patch_map[inode_offset])
    assert struct.unpack_from("<HHHH", inode, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    assert struct.unpack_from("<H", inode, 0x38)[0] == data_blocks + 1
    assert struct.unpack_from("<I", inode, 0x3C)[0] == first_physical
    assert struct.unpack_from("<I", inode, 0x1C)[0] == (
        (data_blocks + 1) * sectors_per_block
    )
    assert struct.unpack_from("<I", inode, 0x68)[0] == 0
    assert struct.unpack_from("<H", inode, 0x76)[0] == 0
    if data_blocks:
        assert data_blocks <= 0x8000
        struct.pack_into("<H", inode, 0x38, data_blocks)
        data_ranges = ((first_physical, data_blocks),)
    else:
        struct.pack_into("<H", inode, 0x2A, 0)
        inode[0x34:0x64] = bytes(48)
        data_ranges = ()
    struct.pack_into("<I", inode, 0x68, xattr_block)
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    return tuple(patch_map.items()), data_ranges, xattr_block


def _unlinked_orphan_shared_external_xattr_patches(
    path: Path,
    *,
    protocol: str,
    data_blocks: int = 0,
    inode_number: int = 18,
) -> tuple[
    tuple[tuple[int, bytes], ...],
    tuple[tuple[int, int], ...],
    int,
]:
    """Share inode 14's real external xattr block with one orphan."""
    assert data_blocks >= 0
    if data_blocks:
        patches, first_physical = _single_extent_unlinked_orphan_patches(
            path,
            protocol=protocol,
            inode_number=inode_number,
            block_count=data_blocks,
        )
        data_ranges = ((first_physical, data_blocks),)
    else:
        patches = _already_empty_unlinked_orphan_patches(
            path,
            protocol=protocol,
            inode_number=inode_number,
        )
        data_ranges = ()

    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    _, source_inode, _ = _ext4_inode_record(path, 14)
    assert struct.unpack_from("<H", source_inode, 0x00)[0] & 0xF000 == 0x8000
    assert struct.unpack_from("<H", source_inode, 0x1A)[0] > 0
    inodes_per_group = struct.unpack_from("<I", superblock, 0x28)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    source_group, source_index = divmod(14 - 1, inodes_per_group)
    descriptor_table = 2 if block_size == 1024 else 1
    with path.open("rb") as source:
        source.seek(
            descriptor_table * block_size
            + source_group * descriptor_size
        )
        source_descriptor = source.read(descriptor_size)
    assert len(source_descriptor) == descriptor_size
    source_inode_bitmap = struct.unpack_from(
        "<I", source_descriptor, 0x04
    )[0] | (
        struct.unpack_from("<I", source_descriptor, 0x24)[0] << 32
    )
    with path.open("rb") as source:
        source.seek(source_inode_bitmap * block_size + source_index // 8)
        source_bitmap_byte = source.read(1)
    assert len(source_bitmap_byte) == 1
    assert source_bitmap_byte[0] & (1 << (source_index % 8))
    xattr_block = struct.unpack_from("<I", source_inode, 0x68)[0]
    assert xattr_block > 0
    assert struct.unpack_from("<H", source_inode, 0x76)[0] == 0
    xattr_offset = xattr_block * block_size
    assert xattr_offset not in patch_map
    with path.open("rb") as source:
        source.seek(xattr_offset)
        xattr = bytearray(source.read(block_size))
    assert len(xattr) == block_size
    assert struct.unpack_from("<I", xattr, 0x04)[0] == 1
    assert _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        xattr,
    ) == bytes(xattr)
    canonical_xattr = bytes(xattr)
    struct.pack_into("<I", xattr, 0x04, 2)
    shared_xattr = _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        xattr,
    )
    restored_xattr = bytearray(shared_xattr)
    struct.pack_into("<I", restored_xattr, 0x04, 1)
    assert _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        restored_xattr,
    ) == canonical_xattr
    patch_map[xattr_offset] = shared_xattr

    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patch_map[inode_offset])
    assert struct.unpack_from("<I", inode, 0x68)[0] == 0
    assert struct.unpack_from("<H", inode, 0x76)[0] == 0
    assert struct.unpack_from("<I", inode, 0x1C)[0] == (
        data_blocks * sectors_per_block
    )
    struct.pack_into("<I", inode, 0x68, xattr_block)
    struct.pack_into(
        "<I",
        inode,
        0x1C,
        (data_blocks + 1) * sectors_per_block,
    )
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    return tuple(patch_map.items()), data_ranges, xattr_block


def _unlinked_orphan_refcount_one_two_owner_xattr_patches(
    path: Path,
    *,
    protocol: str,
) -> tuple[tuple[int, bytes], ...]:
    """Give one valid refcount-one xattr block two semantic owners."""
    patches, data_ranges, xattr_block = (
        _unlinked_orphan_shared_external_xattr_patches(
            path,
            protocol=protocol,
            data_blocks=0,
        )
    )
    assert data_ranges == ()
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    xattr_offset = xattr_block * block_size
    xattr = bytearray(patch_map[xattr_offset])
    assert struct.unpack_from("<I", xattr, 0x04)[0] == 2
    struct.pack_into("<I", xattr, 0x04, 1)
    refcount_one_xattr = _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        xattr,
    )
    assert struct.unpack_from("<I", refcount_one_xattr, 0x04)[0] == 1
    with path.open("rb") as source:
        source.seek(xattr_offset)
        assert source.read(block_size) == refcount_one_xattr

    _, live_inode, _ = _ext4_inode_record(path, 14)
    _, _, target_offset = _ext4_inode_record(path, 18)
    target_inode = patch_map[target_offset]
    assert struct.unpack_from("<I", live_inode, 0x68)[0] == xattr_block
    assert struct.unpack_from("<I", target_inode, 0x68)[0] == xattr_block
    patch_map[xattr_offset] = refcount_one_xattr
    return tuple(patch_map.items())


def _multi_unlinked_orphan_shared_external_xattr_patches(
    path: Path,
) -> tuple[tuple[tuple[int, bytes], ...], int]:
    """Give two modern unlinked orphans one freshly allocated xattr block."""
    base_patches = _multi_empty_unlinked_orphan_patches(
        path,
        legacy_chain=(),
        modern_entries=(18, 21),
    )
    patches, allocated_ranges = _inline_depth0_unlinked_orphan_patches(
        path,
        protocol="modern",
        extent_specs=((0, 1, False),),
        inode_number=18,
        physical_gap=0,
        base_patches=base_patches,
    )
    assert len(allocated_ranges) == 1
    xattr_block, allocated_count = allocated_ranges[0]
    assert allocated_count == 1

    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    _, source_inode, _ = _ext4_inode_record(path, 14)
    source_xattr = struct.unpack_from("<I", source_inode, 0x68)[0]
    assert source_xattr > 0 and source_xattr != xattr_block
    assert struct.unpack_from("<H", source_inode, 0x76)[0] == 0
    with path.open("rb") as source:
        source.seek(source_xattr * block_size)
        canonical_xattr = source.read(block_size)
    assert len(canonical_xattr) == block_size
    assert struct.unpack_from("<I", canonical_xattr, 0x04)[0] == 1
    assert _external_xattr_block_with_checksum(
        superblock,
        source_xattr,
        canonical_xattr,
    ) == canonical_xattr

    xattr_offset = xattr_block * block_size
    assert xattr_offset not in patch_map
    shared_xattr = bytearray(
        _external_xattr_block_with_checksum(
            superblock,
            xattr_block,
            canonical_xattr,
        )
    )
    struct.pack_into("<I", shared_xattr, 0x04, 2)
    shared_xattr = bytearray(
        _external_xattr_block_with_checksum(
            superblock,
            xattr_block,
            shared_xattr,
        )
    )
    restored_xattr = bytearray(shared_xattr)
    struct.pack_into("<I", restored_xattr, 0x04, 1)
    expected_retained_xattr = _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        restored_xattr,
    )
    assert expected_retained_xattr == _external_xattr_block_with_checksum(
        superblock,
        xattr_block,
        canonical_xattr,
    )
    patch_map[xattr_offset] = bytes(shared_xattr)

    for inode_number in (18, 21):
        _, _, inode_offset = _ext4_inode_record(path, inode_number)
        inode = bytearray(patch_map[inode_offset])
        assert struct.unpack_from("<I", inode, 0x68)[0] == 0
        assert struct.unpack_from("<H", inode, 0x76)[0] == 0
        if inode_number == 18:
            assert struct.unpack_from("<HHHH", inode, 0x28) == (
                0xF30A,
                1,
                4,
                0,
            )
            struct.pack_into("<H", inode, 0x2A, 0)
            inode[0x34:0x64] = bytes(48)
            assert struct.unpack_from("<I", inode, 0x1C)[0] == (
                sectors_per_block
            )
        else:
            assert struct.unpack_from("<HHHH", inode, 0x28) == (
                0xF30A,
                0,
                4,
                0,
            )
            assert struct.unpack_from("<I", inode, 0x1C)[0] == 0
            struct.pack_into("<I", inode, 0x1C, sectors_per_block)
        struct.pack_into("<I", inode, 0x68, xattr_block)
        patch_map[inode_offset] = _inode_with_checksum(
            superblock,
            inode_number,
            inode,
        )

    return tuple(patch_map.items()), xattr_block


def _legacy_direct_unlinked_external_xattr_patches(
    path: Path,
    *,
    protocol: str,
    inode_number: int = 18,
) -> tuple[
    tuple[tuple[int, bytes], ...],
    tuple[tuple[int, int], ...],
    int,
]:
    """Fill all direct slots and add the independent unique xattr block."""
    patches, extent_ranges, xattr_block = (
        _unlinked_orphan_external_xattr_patches(
            path,
            protocol=protocol,
            data_blocks=12,
            inode_number=inode_number,
        )
    )
    assert len(extent_ranges) == 1
    first_physical, block_count = extent_ranges[0]
    assert block_count == 12
    direct_ranges = tuple(
        (first_physical + index, 1) for index in range(block_count)
    )
    assert xattr_block == first_physical + block_count

    patch_map = dict(patches)
    superblock = patch_map[1024]
    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patch_map[inode_offset])
    flags = struct.unpack_from("<I", inode, 0x20)[0]
    assert flags & 0x0008_0000
    assert struct.unpack_from("<I", inode, 0x68)[0] == xattr_block
    inode[0x28:0x64] = bytes(60)
    struct.pack_into("<I", inode, 0x20, flags & ~0x0008_0000)
    for slot, (physical, count) in enumerate(direct_ranges):
        assert count == 1
        struct.pack_into("<I", inode, 0x28 + slot * 4, physical)
    patch_map[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    return tuple(patch_map.items()), direct_ranges, xattr_block


def _unlinked_orphan_external_xattr_refusal_patches(
    path: Path,
    *,
    protocol: str,
    case: str,
) -> tuple[tuple[int, bytes], ...]:
    """Build authenticated external-xattr shapes outside release authority."""
    assert case in {"shared-refcount", "bad-checksum", "value-inode"}
    patches, data_ranges, xattr_block = (
        _unlinked_orphan_external_xattr_patches(
            path,
            protocol=protocol,
            data_blocks=0,
        )
    )
    assert data_ranges == ()
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    xattr_offset = xattr_block * block_size
    xattr = bytearray(patch_map[xattr_offset])
    if case == "shared-refcount":
        struct.pack_into("<I", xattr, 0x04, 2)
        xattr = bytearray(
            _external_xattr_block_with_checksum(
                superblock,
                xattr_block,
                xattr,
            )
        )
    elif case == "value-inode":
        assert struct.unpack_from("<I", xattr, 0x20)[0] != 0
        assert struct.unpack_from("<I", xattr, 0x24)[0] == 0
        struct.pack_into("<I", xattr, 0x24, 14)
        xattr = bytearray(
            _external_xattr_block_with_checksum(
                superblock,
                xattr_block,
                xattr,
            )
        )
    else:
        assert case == "bad-checksum"
        xattr[0x10] ^= 1
    patch_map[xattr_offset] = bytes(xattr)
    return tuple(patch_map.items())


def _later_linked_live_alias_orphan_patches(
    path: Path,
    *,
    protocol: str,
) -> tuple[tuple[tuple[int, bytes], ...], tuple[int, ...]]:
    """Put a linked live-data alias in the later selected orphan record."""
    assert protocol in {"modern", "legacy"}
    extent_count = 2 if protocol == "modern" else 4
    legacy_chain = (21,) if protocol == "modern" else (21, 18)
    modern_entries = (18,) if protocol == "modern" else ()
    base = _multi_empty_unlinked_orphan_patches(
        path,
        legacy_chain=legacy_chain,
        modern_entries=modern_entries,
    )
    patches, first_physical = _single_extent_unlinked_orphan_patches(
        path,
        protocol=protocol,
        inode_number=18,
        block_count=extent_count - 1,
        base_patches=base,
    )
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512

    _, live_inode, _ = _ext4_inode_record(path, 14)
    assert struct.unpack_from("<H", live_inode, 0x00)[0] & 0xF000 == 0x8000
    assert struct.unpack_from("<H", live_inode, 0x1A)[0] > 0
    assert struct.unpack_from("<HHHH", live_inode, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    alias_physical = _extent_root_physical(live_inode, 0)
    owned_physical = tuple(
        range(first_physical, first_physical + extent_count - 1)
    )
    assert alias_physical not in owned_physical

    _, _, target_offset = _ext4_inode_record(path, 18)
    target = bytearray(patch_map[target_offset])
    assert struct.unpack_from("<I", target, 0x04)[0] == 0
    assert struct.unpack_from("<I", target, 0x14)[0] == 0
    assert struct.unpack_from("<H", target, 0x1A)[0] == 0
    assert struct.unpack_from("<I", target, 0x6C)[0] == 0
    assert struct.unpack_from("<H", target, 0x74)[0] == 0
    assert struct.unpack_from("<I", target, 0x68)[0] == 0
    assert struct.unpack_from("<HHHH", target, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    assert struct.unpack_from("<I", target, 0x1C)[0] == (
        (extent_count - 1) * sectors_per_block
    )

    struct.pack_into("<H", target, 0x1A, 2)
    struct.pack_into("<H", target, 0x2A, extent_count)
    target[0x34:0x64] = bytes(48)
    physical_blocks = (*owned_physical, alias_physical)
    for logical, physical in enumerate(physical_blocks):
        struct.pack_into(
            "<IHHI",
            target,
            0x34 + logical * 12,
            logical,
            1,
            physical >> 32,
            physical & 0xFFFF_FFFF,
        )
    struct.pack_into("<I", target, 0x1C, extent_count * sectors_per_block)
    patch_map[target_offset] = _inode_with_checksum(
        superblock,
        18,
        target,
    )
    assert struct.unpack_from(
        "<HHHH", patch_map[target_offset], 0x28
    ) == (0xF30A, extent_count, 4, 0)
    for logical, physical in enumerate(physical_blocks):
        assert _extent_root_physical(
            patch_map[target_offset], logical
        ) == physical
    return tuple(patch_map.items()), physical_blocks


def _one_block_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    inode_number: int = 18,
    data_group: int = 0,
) -> tuple[tuple[tuple[int, bytes], ...], int]:
    """Give the singleton unlinked inode one exact allocated data block."""
    return _single_extent_unlinked_orphan_patches(
        path,
        protocol=protocol,
        inode_number=inode_number,
        data_group=data_group,
    )


def _existing_block_unlinked_orphan_patches(
    path: Path,
    *,
    protocol: str,
    data_block: int,
    inode_number: int = 18,
) -> tuple[tuple[int, bytes], ...]:
    """Point one unlinked inode at an already allocated owner block."""
    patches = dict(
        _already_empty_unlinked_orphan_patches(
            path,
            protocol=protocol,
            inode_number=inode_number,
        )
    )
    superblock = patches[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_count = struct.unpack_from("<I", superblock, 0x04)[0] | (
        struct.unpack_from("<I", superblock, 0x150)[0] << 32
    )
    assert first_data <= data_block < blocks_count

    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    inode = bytearray(patches[inode_offset])
    assert struct.unpack_from("<HHHH", inode, 0x28) == (0xF30A, 0, 4, 0)
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 0
    assert struct.unpack_from("<H", inode, 0x74)[0] == 0
    struct.pack_into("<H", inode, 0x2A, 1)
    struct.pack_into("<IHHI", inode, 0x34, 0, 1, 0, data_block)
    struct.pack_into("<I", inode, 0x1C, block_size // 512)
    patches[inode_offset] = _inode_with_checksum(
        superblock,
        inode_number,
        inode,
    )
    assert len(patches) == 5
    return tuple(patches.items())


def _unlinked_orphan_ownership_patches(
    path: Path,
    *,
    protocol: str,
    case: str,
    inode_number: int = 18,
) -> tuple[tuple[int, bytes], ...]:
    """Add authenticated ownership variants to an unlinked orphan."""
    assert case in {
        "nonzero-i-blocks",
        "inline-xattr",
        "inline-xattr-value-inode",
        "one-block-high-word",
        "one-block-data-xattr-alias",
        "one-block-inline-xattr",
        "one-block-orphan-storage-alias",
        "one-block-free-data",
        "one-block-live-data-alias",
        "one-block-live-xattr-alias",
        "two-block-second-free-data",
        "three-block-interior-live-data-alias",
    }
    exact_alias_cases = {
        "one-block-orphan-storage-alias",
        "one-block-live-data-alias",
        "one-block-live-xattr-alias",
    }
    range_admission_cases = {
        "two-block-second-free-data",
        "three-block-interior-live-data-alias",
    }
    one_block_case = case.startswith("one-block-")
    data_block: int | None = None
    if case in exact_alias_cases:
        if case == "one-block-orphan-storage-alias":
            superblock, _, _ = _ext4_inode_record(path, inode_number)
            orphan_inode_number = struct.unpack_from(
                "<I", superblock, 0x280
            )[0]
            _, owner_inode, _ = _ext4_inode_record(path, orphan_inode_number)
            data_block = _extent_root_physical(owner_inode, 0)
        else:
            _, owner_inode, _ = _ext4_inode_record(path, 14)
            assert (
                struct.unpack_from("<H", owner_inode, 0x00)[0] & 0xF000
                == 0x8000
            )
            assert struct.unpack_from("<H", owner_inode, 0x1A)[0] > 0
            if case == "one-block-live-data-alias":
                assert struct.unpack_from("<HHHH", owner_inode, 0x28) == (
                    0xF30A,
                    1,
                    4,
                    0,
                )
                assert struct.unpack_from("<I", owner_inode, 0x34)[0] == 0
                assert struct.unpack_from("<H", owner_inode, 0x38)[0] == 1
                assert struct.unpack_from("<H", owner_inode, 0x3A)[0] == 0
                data_block = _extent_root_physical(owner_inode, 0)
            else:
                assert struct.unpack_from("<H", owner_inode, 0x76)[0] == 0
                data_block = struct.unpack_from("<I", owner_inode, 0x68)[0]
                assert data_block != 0
        assert data_block is not None
        patches = list(
            _existing_block_unlinked_orphan_patches(
                path,
                protocol=protocol,
                data_block=data_block,
                inode_number=inode_number,
            )
        )
    elif case == "two-block-second-free-data":
        extent_patches, data_block = _single_extent_unlinked_orphan_patches(
            path,
            protocol=protocol,
            inode_number=inode_number,
            block_count=2,
        )
        one_block_patches, observed_data_block = (
            _single_extent_unlinked_orphan_patches(
                path,
                protocol=protocol,
                inode_number=inode_number,
                physical_start=data_block,
                block_count=1,
            )
        )
        assert observed_data_block == data_block
        extent_map = dict(extent_patches)
        patch_map = dict(one_block_patches)
        _, _, inode_offset = _ext4_inode_record(path, inode_number)
        patch_map[inode_offset] = extent_map[inode_offset]
        patches = list(patch_map.items())
    elif case == "three-block-interior-live-data-alias":
        range_patches, data_block = _single_extent_unlinked_orphan_patches(
            path,
            protocol=protocol,
            inode_number=inode_number,
            block_count=3,
        )
        patch_map = dict(range_patches)
        superblock = patch_map[1024]
        _, live_inode_bytes, live_inode_offset = _ext4_inode_record(path, 14)
        live_inode = bytearray(live_inode_bytes)
        assert struct.unpack_from("<HHHH", live_inode, 0x28) == (
            0xF30A,
            1,
            4,
            0,
        )
        assert struct.unpack_from("<H", live_inode, 0x38)[0] == 1
        struct.pack_into("<H", live_inode, 0x3A, 0)
        struct.pack_into("<I", live_inode, 0x3C, data_block + 1)
        assert live_inode_offset not in patch_map
        patch_map[live_inode_offset] = _inode_with_checksum(
            superblock,
            14,
            live_inode,
        )
        patches = list(patch_map.items())
    elif one_block_case:
        one_block_patches, data_block = _one_block_unlinked_orphan_patches(
            path,
            protocol=protocol,
            inode_number=inode_number,
        )
        patch_map = dict(one_block_patches)
        if case == "one-block-free-data":
            empty_map = dict(
                _already_empty_unlinked_orphan_patches(
                    path,
                    protocol=protocol,
                    inode_number=inode_number,
                )
            )
            superblock = patch_map[1024]
            block_size = 1024 << struct.unpack_from(
                "<I", superblock, 0x18
            )[0]
            first_data = struct.unpack_from("<I", superblock, 0x14)[0]
            gdt_offset = (first_data + 1) * block_size
            descriptor = patch_map[gdt_offset][:64]
            block_bitmap_home = struct.unpack_from("<I", descriptor, 0x00)[0]
            del patch_map[block_bitmap_home * block_size]
            patch_map[1024] = empty_map[1024]
            patch_map[gdt_offset] = empty_map[gdt_offset]
        patches = list(patch_map.items())
    else:
        patches = list(
            _already_empty_unlinked_orphan_patches(
                path,
                protocol=protocol,
                inode_number=inode_number,
            )
        )
    superblock = dict(patches)[1024]
    _, _, inode_offset = _ext4_inode_record(path, inode_number)
    patch_index = next(
        index
        for index, (offset, _) in enumerate(patches)
        if offset == inode_offset
    )
    inode = bytearray(patches[patch_index][1])
    if case == "nonzero-i-blocks":
        struct.pack_into("<I", inode, 0x1C, 2)
        struct.pack_into("<H", inode, 0x74, 0)
    elif case == "one-block-high-word":
        assert data_block is not None
        struct.pack_into("<H", inode, 0x3A, 1)
    elif case == "one-block-data-xattr-alias":
        assert data_block is not None
        struct.pack_into("<I", inode, 0x68, data_block)
    elif case in exact_alias_cases | range_admission_cases:
        assert data_block is not None
    else:
        if case != "one-block-free-data":
            _, source_inode, _ = _ext4_inode_record(path, 14)
            assert (
                struct.unpack_from("<I", source_inode, 0xA0)[0]
                == 0xEA02_0000
            )
            inode[0xA0:0x100] = source_inode[0xA0:0x100]
            if case == "inline-xattr-value-inode":
                assert struct.unpack_from("<I", inode, 0xA8)[0] == 0
                struct.pack_into("<I", inode, 0xA8, 14)
    patches[patch_index] = (
        inode_offset,
        _inode_with_checksum(superblock, inode_number, inode),
    )
    assert len({offset for offset, _ in patches}) == len(patches)
    return tuple(patches)


def _ext4_journal_physical_map(
    path: Path, logical_blocks: tuple[int, ...]
) -> dict[int, int]:
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    journal_root = superblock[0x10C : 0x10C + 60]
    assert struct.unpack_from("<H", journal_root, 0x00)[0] == 0xF30A
    assert struct.unpack_from("<H", journal_root, 0x06)[0] == 0
    entries = struct.unpack_from("<H", journal_root, 0x02)[0]
    maximum = struct.unpack_from("<H", journal_root, 0x04)[0]
    assert 1 <= entries <= maximum <= 4
    journal_bytes = (
        struct.unpack_from("<I", superblock, 0x10C + 60)[0] << 32
    ) | struct.unpack_from("<I", superblock, 0x10C + 64)[0]
    assert journal_bytes > 0 and journal_bytes % block_size == 0
    journal_blocks = journal_bytes // block_size

    result: dict[int, int] = {}
    for logical in logical_blocks:
        assert 0 <= logical < journal_blocks
        for index in range(entries):
            entry = 0x0C + index * 0x0C
            first_logical = struct.unpack_from("<I", journal_root, entry)[0]
            raw_length = struct.unpack_from("<H", journal_root, entry + 0x04)[0]
            assert 0 < raw_length <= 0x8000
            if first_logical <= logical < first_logical + raw_length:
                first_physical = (
                    struct.unpack_from("<H", journal_root, entry + 0x06)[0]
                    << 32
                ) | struct.unpack_from("<I", journal_root, entry + 0x08)[0]
                result[logical] = first_physical + logical - first_logical
                break
        else:
            raise AssertionError(f"journal logical block {logical} is unmapped")
    return result


def _jbd2_ring_advance(
    logical: int, count: int, *, first: int, maxlen: int
) -> int:
    """Advance within the usable JBD2 ring without assuming contiguous media."""
    assert 0 < first < maxlen
    assert first <= logical < maxlen
    assert count >= 0
    return first + (logical - first + count) % (maxlen - first)


def _jbd2_super_with_checksum(block: bytes | bytearray) -> bytes:
    """Stamp the standard CRC32C in a 1024-byte JBD2 superblock."""
    result = bytearray(block)
    assert len(result) == 1024
    struct.pack_into(">I", result, 0xFC, 0)
    struct.pack_into(">I", result, 0xFC, _crc32c_raw(result))
    return bytes(result)


def _jbd2_block_with_super_checksum(block: bytes | bytearray) -> bytes:
    """Stamp only the 1024-byte JBD2 super while preserving block padding."""
    result = bytearray(block)
    assert len(result) >= 1024
    result[:1024] = _jbd2_super_with_checksum(result[:1024])
    return bytes(result)


def _jbd2_super_checksum_valid(block: bytes) -> bool:
    if len(block) != 1024:
        return False
    stored = struct.unpack_from(">I", block, 0xFC)[0]
    unstamped = bytearray(block)
    struct.pack_into(">I", unstamped, 0xFC, 0)
    return stored == _crc32c_raw(unstamped)


def _sequential_prefix_merge(
    new: bytes, old: bytes, observed: bytes
) -> bool:
    """Match one new-image prefix followed by the untouched old suffix."""
    if not (len(new) == len(old) == len(observed)):
        return False
    old_phase = False
    for new_byte, old_byte, observed_byte in zip(
        new, old, observed, strict=True
    ):
        if new_byte == old_byte:
            if observed_byte != new_byte:
                return False
        elif old_phase:
            if observed_byte != old_byte:
                return False
        elif observed_byte == old_byte:
            old_phase = True
        elif observed_byte != new_byte:
            return False
    return True


def _build_jbd2_activation_fixture(path: Path) -> dict[str, object]:
    """Derive independent AKW1 activation images from one clean fixture."""
    layout = _ext4_recovery_layout(path)
    block_size = layout["block_size"]
    assert block_size == 1024
    journal0_physical = layout["journal_block"]
    with path.open("rb") as source:
        source.seek(layout["primary_super"] * block_size)
        clean_super = source.read(1024)
        source.seek(journal0_physical * block_size)
        source_journal = source.read(block_size)
    assert len(clean_super) == 1024
    assert len(source_journal) == block_size
    assert clean_super == _ext4_super_with_checksum(clean_super)
    assert struct.unpack_from("<I", clean_super, 0x60)[0] & 0x04 == 0
    assert struct.unpack_from(">II", source_journal, 0x00) == (
        0xC03B3998,
        4,
    )
    assert struct.unpack_from(">I", source_journal, 0x1C)[0] == 0
    assert struct.unpack_from(">I", source_journal, 0x28)[0] == 0
    assert source_journal[0x50:0x58] == bytes(8)
    assert source_journal[0x5C:0x88] == bytes(0x2C)
    assert struct.unpack_from(">I", source_journal, 0xFC)[0] == 0

    first = struct.unpack_from(">I", source_journal, 0x14)[0]
    maxlen = struct.unpack_from(">I", source_journal, 0x10)[0]
    assert struct.unpack_from(">I", source_journal, 0x58)[0] == 0
    guard_logical = first + 1
    assert 0 < first < guard_logical < maxlen
    old_journal_buffer = bytearray(source_journal)
    struct.pack_into(">I", old_journal_buffer, 0x58, guard_logical)
    old_journal = bytes(old_journal_buffer)
    source_patches = (
        (
            journal0_physical * block_size + 0x58,
            struct.pack(">I", guard_logical),
        ),
    )
    journal_map = _ext4_journal_physical_map(
        path, (0, guard_logical)
    )
    guard_physical = journal_map[guard_logical]
    with path.open("rb") as source:
        source.seek(guard_physical * block_size)
        old_guard = source.read(block_size)
    assert len(old_guard) == block_size

    dirty_super = bytearray(clean_super)
    struct.pack_into(
        "<I",
        dirty_super,
        0x60,
        struct.unpack_from("<I", dirty_super, 0x60)[0] | 0x04,
    )
    struct.pack_into("<H", dirty_super, 0x3A, 1)
    dirty_super = _ext4_super_with_checksum(dirty_super)

    clean_checksum = struct.unpack_from("<I", clean_super, 0x3FC)[0]
    dirty_checksum = struct.unpack_from("<I", dirty_super, 0x3FC)[0]
    anchor = bytearray(old_journal)
    anchor[0x78:0x7C] = old_journal[0x28:0x2C]
    anchor[0x7C:0x80] = old_journal[0x58:0x5C]
    anchor[0x80:0x84] = old_journal[0x50:0x54]
    anchor[0x84:0x88] = old_journal[0xFC:0x100]
    struct.pack_into(">I", anchor, 0x1C, 0)
    struct.pack_into(">I", anchor, 0x28, 0x13)
    anchor[0x50:0x54] = b"\x04\x00\x00\x00"
    struct.pack_into(">I", anchor, 0x54, 0)
    struct.pack_into(">I", anchor, 0x58, guard_logical)
    struct.pack_into(">I", anchor, 0x5C, 0x414B5731)
    struct.pack_into(">I", anchor, 0x60, clean_checksum)
    struct.pack_into(">I", anchor, 0x64, clean_checksum ^ 0xFFFF_FFFF)
    struct.pack_into(">I", anchor, 0x68, guard_logical)
    struct.pack_into(">I", anchor, 0x6C, guard_logical ^ 0xFFFF_FFFF)
    struct.pack_into(">I", anchor, 0x70, dirty_checksum)
    struct.pack_into(">I", anchor, 0x74, dirty_checksum ^ 0xFFFF_FFFF)
    anchor = _jbd2_super_with_checksum(anchor)

    preseed = bytearray(anchor)
    preseed[0] = 0
    standard = bytearray(anchor)
    standard[0x5C:0x88] = bytes(0x2C)
    standard = _jbd2_super_with_checksum(standard)

    success_trace = (
        ("write", guard_physical * 2, 2),
        ("flush", 0, 0),
        ("write", guard_physical * 2, 2),
        ("flush", 0, 0),
        ("write", journal0_physical * 2, 2),
        ("flush", 0, 0),
        ("write", 2, 2),
        ("flush", 0, 0),
        ("write", journal0_physical * 2, 2),
        ("flush", 0, 0),
        ("write", guard_physical * 2, 2),
        ("flush", 0, 0),
    )
    return {
        "image": path,
        "layout": layout,
        "journal0_physical": journal0_physical,
        "guard_logical": guard_logical,
        "guard_physical": guard_physical,
        "source_patches": source_patches,
        "clean_super": clean_super,
        "dirty_super": dirty_super,
        "old_journal": old_journal,
        "old_guard": old_guard,
        "anchor": anchor,
        "preseed": bytes(preseed),
        "standard": standard,
        "success_trace": success_trace,
    }


def _read_jbd2_activation_media(
    path: Path, fixture: dict[str, object]
) -> tuple[bytes, bytes, bytes]:
    layout = fixture["layout"]
    journal0_physical = fixture["journal0_physical"]
    guard_physical = fixture["guard_physical"]
    assert isinstance(layout, dict)
    assert isinstance(journal0_physical, int)
    assert isinstance(guard_physical, int)
    block_size = layout["block_size"]
    assert block_size == 1024
    with path.open("rb") as source:
        source.seek(layout["primary_super"] * block_size)
        superblock = source.read(1024)
        source.seek(journal0_physical * block_size)
        journal = source.read(block_size)
        source.seek(guard_physical * block_size)
        guard = source.read(block_size)
    assert len(superblock) == len(journal) == len(guard) == block_size
    return superblock, journal, guard


def _assert_activation_cleanup_trace(
    trace: tuple[tuple[str, int, int], ...],
    *,
    journal0_physical: int,
    guard_physical: int,
) -> None:
    allowed_writes = {
        ("write", 2, 2),
        ("write", journal0_physical * 2, 2),
        ("write", guard_physical * 2, 2),
    }
    for index, event in enumerate(trace):
        assert event[0] in {"write", "flush"}
        if event[0] != "write":
            continue
        assert event in allowed_writes
        assert index + 1 < len(trace)
        assert trace[index + 1] == ("flush", 0, 0)


def _jbd2_writer_activation_trace(
    path: Path,
) -> tuple[tuple[str, int, int], ...]:
    """Derive the exact activation prefix from this image's journal head."""
    with path.open("rb") as source:
        source.seek(1024)
        superblock = source.read(1024)
    assert len(superblock) == 1024
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    sectors_per_block = block_size // 512
    journal0_physical = _ext4_journal_physical_map(path, (0,))[0]
    with path.open("rb") as source:
        source.seek(journal0_physical * block_size)
        journal_super = source.read(block_size)
    assert len(journal_super) == block_size
    guard_logical = struct.unpack_from(">I", journal_super, 0x58)[0]
    if guard_logical == 0:
        guard_logical = struct.unpack_from(">I", journal_super, 0x18)[0]
    assert guard_logical > 0
    guard_physical = _ext4_journal_physical_map(
        path,
        (guard_logical,),
    )[guard_logical]
    return (
        ("write", guard_physical * sectors_per_block, sectors_per_block),
        ("flush", 0, 0),
        ("write", guard_physical * sectors_per_block, sectors_per_block),
        ("flush", 0, 0),
        ("write", journal0_physical * sectors_per_block, sectors_per_block),
        ("flush", 0, 0),
        ("write", 2, 2),
        ("flush", 0, 0),
        ("write", journal0_physical * sectors_per_block, sectors_per_block),
        ("flush", 0, 0),
        ("write", guard_physical * sectors_per_block, sectors_per_block),
        ("flush", 0, 0),
    )


def _activation_resolved_mount_lines(
    marker: str, expected_features: int
) -> list[str]:
    return [
        "T-ARENA T-VOLUME EXT4-NEW CONSTANT _M-IOR CONSTANT _V",
        "_V _EXT4-CTX CONSTANT _AR-CTX",
        (
            "_M-IOR 0= _V V.LIFECYCLE @ VFS-L-MOUNTED = AND "
            "_V _EXT4-READY? AND "
            "_AR-CTX _EXT4-C.RECOVERY + @ 0= AND "
            "_AR-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0= AND "
            "_AR-CTX _EXT4-C.J.FEATURES + @ "
            f"{expected_features} = AND "
            "_AR-CTX _EXT4-C.J.START + @ 0= AND "
            "_AR-CTX _EXT4-C.J.WITNESS + @ _EXT4-JW-NONE = AND "
            "_AR-CTX _EXT4-C.J.WITNESS-CHECKSUM + @ 0= AND "
            "_AR-CTX _EXT4-C.J.WITNESS-NEW-CHECKSUM + @ 0= AND "
            "_AR-CTX _EXT4-C.J.ANCHOR + @ 0= AND "
            "_AR-CTX _EXT4-C.J.CLEANUP + @ _EXT4-JC-NONE = AND "
            "_AR-CTX _EXT4-C.SUPER-TORN + @ 0= AND "
            "_AR-CTX _EXT4-C.J.PRIMARY-TORN + @ 0= AND "
            "_AR-CTX _EXT4-C.J.HOME-WRITES + @ 0= AND "
            "_AR-CTX _EXT4-C.SB + _EXT4-SUPER-CHECKSUM? 0= AND AND "
            "_AR-CTX _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ "
            "_EXT4-INCOMPAT-RECOVER AND 0= AND "
            f'IF ." {marker}" THEN'
        ),
    ]


def _assert_activation_landed_media(
    path: Path,
    fixture: dict[str, object],
    *,
    expected_features: int,
) -> None:
    clean_super = fixture["clean_super"]
    old_journal = fixture["old_journal"]
    guard_logical = fixture["guard_logical"]
    assert isinstance(clean_super, bytes)
    assert isinstance(old_journal, bytes)
    assert isinstance(guard_logical, int)

    superblock, journal, guard = _read_jbd2_activation_media(path, fixture)
    assert superblock == clean_super
    if expected_features == 0:
        assert journal == old_journal
        return

    assert expected_features == 0x13
    assert struct.unpack_from(">II", journal, 0x00) == (0xC03B3998, 4)
    assert struct.unpack_from(">I", journal, 0x0C)[0] == 1024
    assert journal[0x10:0x18] == old_journal[0x10:0x18]
    assert struct.unpack_from(">I", journal, 0x1C)[0] == 0
    assert struct.unpack_from(">I", journal, 0x28)[0] == expected_features
    assert journal[0x2C:0x50] == old_journal[0x2C:0x50]
    assert journal[0x50:0x54] == b"\x04\x00\x00\x00"
    assert struct.unpack_from(">I", journal, 0x54)[0] == 0
    assert struct.unpack_from(">I", journal, 0x58)[0] == guard_logical
    assert journal[0x5C:0x88] == bytes(0x2C)
    assert _jbd2_super_checksum_valid(journal)
    assert guard == bytes(1024)


def _journal_metadata_alias_patches(
    image: Path, target_block: int
) -> tuple[tuple[tuple[int, bytes], ...], str]:
    """Relocate one committed journal data block onto ext4 metadata."""
    layout = _ext4_recovery_layout(image)
    block_size = layout["block_size"]
    assert block_size == 1024
    media = image.read_bytes()

    def read_block(block: int) -> bytes:
        start = block * block_size
        result = media[start : start + block_size]
        assert len(result) == block_size
        return result

    primary_super = read_block(layout["primary_super"])
    assert struct.unpack_from("<I", primary_super, 0x3FC)[0] == _crc32c_raw(
        primary_super[:0x3FC]
    )
    assert struct.unpack_from("<I", primary_super, 0x60)[0] & 0x04
    original_tuple = primary_super[0x10C : 0x10C + 68]
    original_root = original_tuple[:60]
    assert struct.unpack_from("<H", original_root, 0x00)[0] == 0xF30A
    assert struct.unpack_from("<H", original_root, 0x02)[0] == 1
    assert struct.unpack_from("<H", original_root, 0x04)[0] == 4
    assert struct.unpack_from("<H", original_root, 0x06)[0] == 0
    assert struct.unpack_from("<I", original_root, 0x0C)[0] == 0
    journal_bytes = (
        struct.unpack_from("<I", original_tuple, 0x3C)[0] << 32
    ) | struct.unpack_from("<I", original_tuple, 0x40)[0]
    assert journal_bytes > 3 * block_size
    assert journal_bytes % block_size == 0
    journal_blocks = journal_bytes // block_size
    assert struct.unpack_from("<H", original_root, 0x10)[0] == journal_blocks
    assert struct.unpack_from("<H", original_root, 0x12)[0] == 0
    journal_base = struct.unpack_from("<I", original_root, 0x14)[0]
    assert journal_base == layout["journal_block"]
    assert journal_base + journal_blocks <= layout["blocks"]
    assert 0 < target_block < layout["blocks"]
    assert not journal_base <= target_block < journal_base + journal_blocks

    physical_group = (target_block - layout["first"]) // layout[
        "blocks_per_group"
    ]
    assert 0 <= physical_group < layout["groups"]
    descriptor_offset = (
        layout["witness_gdt"] * block_size
        + physical_group * layout["descriptor_size"]
    )
    descriptor = media[
        descriptor_offset : descriptor_offset + layout["descriptor_size"]
    ]
    assert descriptor == _group_descriptor_with_checksum(
        primary_super, descriptor, physical_group
    )
    block_bitmap = struct.unpack_from("<I", descriptor, 0x00)[0]
    group_first = layout["first"] + physical_group * layout[
        "blocks_per_group"
    ]
    target_index = target_block - group_first
    bitmap = read_block(block_bitmap)
    assert bitmap[target_index // 8] & (1 << (target_index % 8))

    descriptor_block = read_block(journal_base + 1)
    journal_data = read_block(journal_base + 2)
    commit_block = read_block(journal_base + 3)
    assert read_block(target_block) != journal_data
    assert struct.unpack_from(">II", descriptor_block, 0x00) == (
        0xC03B3998,
        1,
    )
    assert struct.unpack_from(">II", commit_block, 0x00) == (
        0xC03B3998,
        2,
    )
    assert struct.unpack_from(">I", descriptor_block, 0x08)[0] == (
        struct.unpack_from(">I", commit_block, 0x08)[0]
    )

    relocated_root = bytearray(original_root)
    relocated_root[0x0C:] = bytes(48)
    struct.pack_into("<H", relocated_root, 0x02, 3)
    struct.pack_into(
        "<IHHI", relocated_root, 0x0C, 0, 2, 0, journal_base
    )
    struct.pack_into(
        "<IHHI", relocated_root, 0x18, 2, 1, 0, target_block
    )
    struct.pack_into(
        "<IHHI",
        relocated_root,
        0x24,
        3,
        journal_blocks - 3,
        0,
        journal_base + 3,
    )

    patches: list[tuple[int, bytes]] = []
    for group in range(layout["groups"]):
        if not _ext4_sparse_group(group):
            continue
        super_block = (
            layout["primary_super"]
            if group == 0
            else layout["first"] + group * layout["blocks_per_group"]
        )
        superblock = bytearray(read_block(super_block))
        assert struct.unpack_from("<H", superblock, 0x5A)[0] == group
        assert struct.unpack_from("<I", superblock, 0x3FC)[0] == _crc32c_raw(
            superblock[:0x3FC]
        )
        assert superblock[0x10C : 0x10C + 68] == original_tuple
        superblock[0x10C : 0x10C + 60] = relocated_root
        updated_super = _ext4_super_with_checksum(superblock)
        assert struct.unpack_from("<I", updated_super, 0x3FC)[0] == (
            _crc32c_raw(updated_super[:0x3FC])
        )
        assert updated_super[0x10C : 0x10C + 60] == relocated_root
        patches.append((super_block * block_size, updated_super))

    inode_block = bytearray(read_block(layout["journal_inode_block"]))
    inode_start = layout["journal_inode_offset"]
    inode_end = inode_start + layout["inode_size"]
    inode = bytearray(inode_block[inode_start:inode_end])
    assert len(inode) == layout["inode_size"]
    assert inode == _inode_with_checksum(primary_super, 8, inode)
    assert inode[0x28 : 0x28 + 60] == original_root
    assert struct.unpack_from("<I", inode, 0x04)[0] == (
        struct.unpack_from("<I", original_tuple, 0x40)[0]
    )
    assert struct.unpack_from("<I", inode, 0x6C)[0] == (
        struct.unpack_from("<I", original_tuple, 0x3C)[0]
    )
    inode[0x28 : 0x28 + 60] = relocated_root
    updated_inode = _inode_with_checksum(primary_super, 8, inode)
    assert updated_inode == _inode_with_checksum(
        primary_super, 8, updated_inode
    )
    assert updated_inode[0x28 : 0x28 + 60] == relocated_root
    inode_block[inode_start:inode_end] = updated_inode
    patches.append(
        (layout["journal_inode_block"] * block_size, bytes(inode_block))
    )

    # Apply this last when TARGET is itself a sparse-super/GDT block: the
    # intended hostile alias, rather than a stale tuple, is the sole damage.
    patches.append((target_block * block_size, journal_data))
    expected = bytearray(media)
    for offset, payload in patches:
        expected[offset : offset + len(payload)] = payload
    assert expected[
        target_block * block_size : (target_block + 1) * block_size
    ] == journal_data
    return tuple(patches), hashlib.sha256(expected).hexdigest()


def _author_jbd2_transactions(
    *,
    debugfs: Path,
    env: dict[str, str],
    source: Path,
    directory: Path,
    name: str,
    block_size: int,
    transactions: tuple[tuple[tuple[int, ...], bytes], ...],
) -> Path:
    image = directory / f"{name}.img"
    _copy_sparse_file(source, image)
    commands = ["journal_open -c -v 3"]
    for index, (blocks, payload) in enumerate(transactions):
        assert blocks
        assert len(payload) == len(blocks) * block_size
        payload_path = directory / f"{name}-{index}.bin"
        payload_path.write_bytes(payload)
        block_list = ",".join(str(block) for block in blocks)
        commands.append(f"journal_write -b {block_list} {payload_path}")
    commands.extend(("journal_close", "close"))
    command_path = directory / f"{name}.cmd"
    command_path.write_text("\n".join(commands) + "\n", encoding="utf-8")
    authored = subprocess.run(
        [str(debugfs), "-w", "-f", str(command_path), str(image)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert authored.returncode == 0, authored.stdout + authored.stderr
    assert "Command not found" not in authored.stdout + authored.stderr
    return image


def _assert_e2fsck_clean(
    image: Path, jbd2_toolchain: dict[str, object]
) -> None:
    e2fsck = jbd2_toolchain["e2fsck"]
    env = jbd2_toolchain["env"]
    assert isinstance(e2fsck, Path)
    assert isinstance(env, dict)
    checked = subprocess.run(
        [str(e2fsck), "-f", "-n", str(image)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert checked.returncode == 0, checked.stdout + checked.stderr


def _recover_with_e2fsck(
    source: Path,
    destination: Path,
    jbd2_toolchain: dict[str, object],
) -> None:
    e2fsck = jbd2_toolchain["e2fsck"]
    env = jbd2_toolchain["env"]
    assert isinstance(e2fsck, Path)
    assert isinstance(env, dict)
    _copy_sparse_file(source, destination)
    recovered = subprocess.run(
        [str(e2fsck), "-E", "journal_only", "-y", str(destination)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert recovered.returncode in (0, 1), recovered.stdout + recovered.stderr
    _assert_e2fsck_clean(destination, jbd2_toolchain)


def _feed_until_idle(system, payload: bytes, max_steps: int) -> int:
    position = 0
    steps = 0
    while steps < max_steps:
        if system.cpu.halted:
            break
        if system.cpu.idle and not system.uart.has_rx_data:
            if position < len(payload):
                chunk = fat_harness._next_line_chunk(payload, position)
                system.uart.inject_input(chunk)
                position += len(chunk)
            else:
                break
            continue
        batch = system.run_batch(min(100_000, max_steps - steps))
        steps += max(batch, 1)
    return steps


def _assert_no_forth_diagnostics(output: str) -> None:
    found = [marker for marker in FORTH_DIAGNOSTICS if marker.lower() in output.lower()]
    snippets: list[str] = []
    lowered = output.lower()
    for marker in found:
        offset = lowered.find(marker.lower())
        snippets.append(output[max(0, offset - 1000):offset + 1000])
    assert not found, (
        f"Forth diagnostics {found}:\n"
        + "\n--- diagnostic context ---\n".join(snippets)
        + f"\n--- transcript tail ---\n{output[-4000:]}"
    )


def _compact_source_load_lines(lines: list[str]) -> list[str]:
    """Preserve Forth tokens while amortizing per-line UART prompt work."""
    result: list[str] = []
    pending = ""
    for raw_line in lines:
        # vfs-ext4.f uses backslash only for Forth line comments.  Remove the
        # comment before packing so its prose is not echoed through the UART.
        # Its balanced parenthesized forms are likewise stack-effect comments,
        # never executable strings, and need not consume source-loader steps.
        source = raw_line.split("\\", 1)[0]
        source = re.sub(r"\([^)]*\)", " ", source)
        line = source.strip() if '"' in source else " ".join(source.split())
        if not line:
            continue
        line_size = len(line.encode("utf-8"))
        assert line_size <= 255, (
            "one ext4 Forth source unit exceeds the MegaPad BIOS TIB: "
            f"{line_size} bytes"
        )
        joined = f"{pending} {line}" if pending else line
        # MegaPad's BIOS TIB holds at most 255 source bytes; never rely on its
        # silent overflow behavior.
        if pending and len(joined.encode("utf-8")) > 255:
            result.append(pending)
            pending = line
        else:
            pending = joined
    if pending:
        result.append(pending)
    return result


def _ext4_source_stage_modules() -> tuple[str, ...]:
    """Return ext4's dependency order minus the already staged foundation."""
    already_staged = set(
        dependency_order(
            AKASHIC_ROOT,
            (VFS_MODULE, CRC_MODULE, BITSET_MODULE),
        )
    )
    return tuple(
        module
        for module in dependency_order(AKASHIC_ROOT, (EXT4_MODULE,))
        if module not in already_staged
    )


def _ext4_source_stage_lines() -> list[str]:
    """Load every not-yet-staged ext4 source unit in dependency order."""
    lines: list[str] = []
    for module in _ext4_source_stage_modules():
        lines.extend(fat_harness._load_forth_lines(str(AKASHIC_ROOT / module)))
    return _compact_source_load_lines(lines)


def _ext4_source_text() -> str:
    """Return the same ordered ext4 source closure used by static contracts."""
    return "\n".join(
        (AKASHIC_ROOT / module).read_text(encoding="utf-8")
        for module in _ext4_source_stage_modules()
    )


def build_snapshot():
    """Extend the proven FAT/VFS snapshot with the ext4 binding once."""
    global _snapshot
    if _snapshot is not None:
        return _snapshot

    fat_harness.build_snapshot()
    bios, memory, cpu_state, ext_memory = fat_harness._snapshot
    # Keep this a real cold source build without making UART echo volume an
    # accidental implementation-size ceiling.  The BIOS reserves R2/2 as its
    # FSLOAD source-buffer address: the data stack grows down from that point,
    # while source extends upward below the return stack.  Host-inject each
    # physical line there, then execute an IMMEDIATE checked-evaluator shim so
    # multi-line definitions retain their compiler state without transmitting
    # the source itself through the UART.
    crc_source_ready = "CRC-SOURCE-READY"
    bitset_source_ready = "BITSET-SOURCE-READY"
    ext4_source_ready = "EXT4-SOURCE-READY"
    crc_lines = _compact_source_load_lines(
        fat_harness._load_forth_lines(str(CRC_F))
    )
    bitset_lines = _compact_source_load_lines(
        fat_harness._load_forth_lines(str(BITSET_F))
    )
    ext4_modules = _ext4_source_stage_modules()
    ext4_lines = _ext4_source_stage_lines()

    system = fat_harness.MegapadSystem(
        ram_size=1024 * 1024,
        ext_mem_size=fat_harness.VFS_EXT_MEM_SIZE,
        storage_image=fat_harness._boot_img_path,
    )
    uart = fat_harness.capture_uart(system)
    system.load_binary(0, bios)
    system.boot()
    for _ in range(5_000_000):
        if system.cpu.idle and not system.uart.has_rx_data:
            break
        system.run_batch(10_000)
    system.cpu.mem[: len(memory)] = memory
    system._ext_mem[: len(ext_memory)] = ext_memory
    fat_harness.restore_cpu_state(system.cpu, cpu_state)
    uart.clear()

    source_addr = system.cpu.regs[2] // 2
    source_size_addr = source_addr + 256
    source_end = source_size_addr + 1
    source_limit = system.cpu.regs[15] - 128
    assert source_end <= source_limit, (
        "ext4 source exceeds the BIOS's checked RAM source-buffer span: "
        f"{source_end - source_addr} bytes available={source_limit - source_addr}"
    )
    bootstrap = "\n".join(
        [
            f"{source_addr} CONSTANT _EXT4-SOURCE-A",
            f"{source_size_addr} CONSTANT _EXT4-SOURCE-U",
            "VARIABLE _EXT4-SOURCE-N 0 _EXT4-SOURCE-N !",
            ": _EXT4-SOURCE-DIAGNOSTIC",
            'CR ." [EXT4-SOURCE-STATUS " DUP . EVAL-LINE @ .',
            'EVAL-COLUMN @ . EVAL-TOKEN TYPE ."  THROW "',
            'EVAL-THROW @ . ." ]" ;',
            ": _EXT4-SOURCE-LINE",
            "1 _EXT4-SOURCE-N +! _EXT4-SOURCE-N @ EVAL-LINE !",
            "_EXT4-SOURCE-A _EXT4-SOURCE-U C@ EVALUATE-CHECKED",
            "DUP IF _EXT4-SOURCE-DIAGNOSTIC THEN DROP ; IMMEDIATE",
            ": _EXT4-SOURCE-FINISH",
            "EVALUATE-FINISH DUP IF _EXT4-SOURCE-DIAGNOSTIC THEN DROP ;",
            "IMMEDIATE",
        ]
    ).encode() + b"\n"
    # Qualify the required utility modules and the ext4 driver as distinct
    # cold source stages.  This preserves the existing measured ext4 watchdog
    # instead of hiding dependency compilation inside a larger cap.
    max_crc_source_steps = 150_000_000
    max_bitset_source_steps = 150_000_000
    # Indexed full-leaf splitting measures 1,592,943,041 cold source steps.
    # Retain a narrow deterministic watchdog margin without conflating source
    # compilation with the independently bounded recovery journey.
    max_ext4_source_steps = 1_600_000_000
    bootstrap_steps = _feed_until_idle(system, bootstrap, max_crc_source_steps)

    def load_source_stage(
        stage: str,
        stage_lines: list[str],
        ready_marker: str,
        max_steps: int,
        initial_steps: int = 0,
    ) -> int:
        lines = [*stage_lines, f'." {ready_marker}"']
        source_steps = initial_steps
        source_lines_loaded = 0
        uart_offset = len(uart)
        for line in lines:
            encoded = line.encode()
            assert len(encoded) <= 255
            if source_steps >= max_steps:
                break
            system.load_binary(source_addr, encoded)
            system.load_binary(source_size_addr, bytes([len(encoded)]))
            source_steps += _feed_until_idle(
                system,
                b"_EXT4-SOURCE-LINE\n",
                max_steps - source_steps,
            )
            source_lines_loaded += 1
            new_output = fat_harness.uart_text(uart[uart_offset:])
            uart_offset = len(uart)
            if "[EXT4-SOURCE-STATUS" in new_output:
                break
        if source_steps < max_steps:
            source_steps += _feed_until_idle(
                system,
                b"_EXT4-SOURCE-FINISH\n",
                max_steps - source_steps,
            )
        transcript = fat_harness.uart_text(uart)
        _assert_no_forth_diagnostics(transcript)
        assert f"\r\n{ready_marker} ok\r\n" in transcript, (
            f"{stage} source load exceeded its checked-in step budget "
            f"after {source_lines_loaded}/{len(lines)} packed lines and "
            f"{source_steps}/{max_steps} steps:\n"
            + transcript[-4000:]
        )
        return source_steps

    crc_source_steps = load_source_stage(
        "CRC",
        crc_lines,
        crc_source_ready,
        max_crc_source_steps,
        bootstrap_steps,
    )
    bitset_source_steps = load_source_stage(
        "bitset",
        bitset_lines,
        bitset_source_ready,
        max_bitset_source_steps,
    )
    ext4_source_steps = load_source_stage(
        "ext4",
        ext4_lines,
        ext4_source_ready,
        max_ext4_source_steps,
    )
    if os.environ.get("EXT4_REPORT_STEPS"):
        print(
            "[*] CRC/bitset/ext4 cold source load: "
            f"CRC={crc_source_steps:,}/{max_crc_source_steps:,} steps "
            f"across {len(crc_lines):,} packed lines; "
            f"bitset={bitset_source_steps:,}/{max_bitset_source_steps:,} "
            f"steps across {len(bitset_lines):,} packed lines; "
            f"ext4={ext4_source_steps:,}/{max_ext4_source_steps:,} steps "
            f"across {len(ext4_lines):,} packed lines from "
            f"{len(ext4_modules):,} source units"
        )

    _snapshot = (
        bios,
        bytes(system.cpu.mem),
        fat_harness.save_cpu_state(system.cpu),
        bytes(system._ext_mem),
    )
    return _snapshot


def run_forth(
    image: Path,
    lines: list[str],
    *,
    patches: tuple[tuple[int, bytes], ...] = (),
    storage_faults: tuple[dict, ...] = (),
    max_steps: int = 800_000_000,
    configure=None,
    expected_read_requests: int | None = None,
) -> str:
    """Run against a COW mapping so even the 512 MiB fixture stays bounded."""
    bios, memory, cpu_state, ext_memory = build_snapshot()
    system = fat_harness.MegapadSystem(
        ram_size=1024 * 1024,
        ext_mem_size=fat_harness.VFS_EXT_MEM_SIZE,
        storage_image=fat_harness._boot_img_path,
    )
    uart = fat_harness.capture_uart(system)
    system.load_binary(0, bios)
    system.boot()
    for _ in range(5_000_000):
        if system.cpu.idle and not system.uart.has_rx_data:
            break
        system.run_batch(10_000)
    system.cpu.mem[: len(memory)] = memory
    system._ext_mem[: len(ext_memory)] = ext_memory
    fat_harness.restore_cpu_state(system.cpu, cpu_state)
    if configure is not None:
        configure(system)

    with image.open("rb") as source, mmap.mmap(
        source.fileno(), 0, access=mmap.ACCESS_COPY
    ) as mapped:
        for offset, data in patches:
            mapped[offset : offset + len(data)] = data
        system.storage._replace_media(mapped, str(image))
        system.storage.write_protected = False
        read_requests = 0
        write_requests = 0
        flush_requests = 0
        start_dma = system.storage._start_dma
        run_flush = system.storage._run_flush

        def track_dma(request, phase):
            nonlocal read_requests, write_requests
            if phase == "write":
                write_requests += 1
            elif phase == "read":
                read_requests += 1
            return start_dma(request, phase)

        def track_flush(request):
            nonlocal flush_requests
            flush_requests += 1
            return run_flush(request)

        system.storage._start_dma = track_dma
        system.storage._run_flush = track_flush
        for fault in storage_faults:
            system.storage.inject_fault(**fault)
        uart.clear()
        stack_check = (
            'DEPTH DUP 0= IF DROP ." EXT4-STACK-CLEAN" '
            'ELSE ." EXT4-STACK-LEAK " . THEN'
        )
        payload = ("\n".join((*lines, stack_check, "BYE")) + "\n").encode()
        journey_steps = _feed_until_idle(system, payload, max_steps)
        if os.environ.get("EXT4_REPORT_STEPS"):
            print(
                "[*] ext4 Forth journey: "
                f"{journey_steps:,}/{max_steps:,} steps ({image.name})"
            )
        output = fat_harness.uart_text(uart)
        _assert_no_forth_diagnostics(output)
        if not system.cpu.halted or not output.endswith("Bye!\r\n"):
            raise AssertionError(
                "ext4 Forth journey did not consume BYE and halt "
                f"after {journey_steps:,}/{max_steps:,} steps:\n"
                + output[-2000:]
            )
        assert write_requests == 0
        assert flush_requests == 0
        if expected_read_requests is not None:
            assert read_requests == expected_read_requests
        _assert_emitted(output, "EXT4-STACK-CLEAN")
        return output


def run_recovery_forth(
    image: Path,
    backing: Path,
    lines: list[str],
    *,
    patches: tuple[tuple[int, bytes], ...] = (),
    write_protected: bool = False,
    storage_faults: tuple[dict, ...] = (),
    write_faults_by_ordinal: dict[int, dict] | None = None,
    flush_faults_by_ordinal: dict[int, dict] | None = None,
    read_faults_by_write_and_ordinal: (
        dict[tuple[int, int], dict] | None
    ) = None,
    capture_media: Path | None = None,
    capture_prior_flush_media: Path | None = None,
    max_steps: int = 1_200_000_000,
) -> tuple[str, tuple[tuple[str, int, int], ...], str]:
    """Run recovery on private mutable media and return its ordered I/O trace."""
    assert (
        capture_prior_flush_media is None or flush_faults_by_ordinal
    ), "prior-fence capture requires an ordinal flush fault"
    pending_flush_faults = dict(flush_faults_by_ordinal or {})
    assert all(ordinal > 0 for ordinal in pending_flush_faults)
    for target_fault in pending_flush_faults.values():
        assert target_fault.get("stage") == "flush"
        assert (
            target_fault.get("command", STORAGE_CMD_FLUSH)
            == STORAGE_CMD_FLUSH
        )
        assert target_fault.get("action", "fail") == "fail"
        assert target_fault.get("result", 0) != STORAGE_RESULT_OK
    if pending_flush_faults:
        assert not any(
            fault.get("stage") == "flush" for fault in storage_faults
        )
    if capture_prior_flush_media is not None:
        assert len(pending_flush_faults) == 1
        capture_paths = [image, backing, capture_prior_flush_media]
        if capture_media is not None:
            capture_paths.append(capture_media)
        assert len({path.resolve() for path in capture_paths}) == len(
            capture_paths
        ), "flush durability captures must use distinct paths"
    bios, memory, cpu_state, ext_memory = build_snapshot()
    system = fat_harness.MegapadSystem(
        ram_size=1024 * 1024,
        ext_mem_size=fat_harness.VFS_EXT_MEM_SIZE,
        storage_image=fat_harness._boot_img_path,
    )
    uart = fat_harness.capture_uart(system)
    system.load_binary(0, bios)
    system.boot()
    for _ in range(5_000_000):
        if system.cpu.idle and not system.uart.has_rx_data:
            break
        system.run_batch(10_000)
    system.cpu.mem[: len(memory)] = memory
    system._ext_mem[: len(ext_memory)] = ext_memory
    fat_harness.restore_cpu_state(system.cpu, cpu_state)

    media = bytearray(image.read_bytes())
    for offset, data in patches:
        media[offset : offset + len(data)] = data
    if capture_prior_flush_media is not None and 1 in pending_flush_faults:
        _write_sparse_bytes(capture_prior_flush_media, media, durable=True)
    system.storage._replace_media(media, str(backing))
    system.storage.write_protected = write_protected

    def save_sparse_media() -> None:
        if (
            system.storage.image_path is not None
            and system.storage.status & STORAGE_STATUS_PRESENT
        ):
            _write_sparse_bytes(
                Path(system.storage.image_path),
                system.storage._image_data,
                durable=True,
            )

    system.storage.save_image = save_sparse_media
    trace: list[tuple[str, int, int]] = []
    start_dma = system.storage._start_dma
    run_flush = system.storage._run_flush
    write_ordinal = 0
    flush_ordinal = 0
    pending_read_faults = dict(read_faults_by_write_and_ordinal or {})
    read_ordinals: dict[int, int] = {}

    def track_dma(request, phase):
        nonlocal write_ordinal
        if phase == "write":
            write_ordinal += 1
            trace.append(("write", request[1], request[3]))
            if write_faults_by_ordinal and write_ordinal in write_faults_by_ordinal:
                system.storage.inject_fault(
                    **write_faults_by_ordinal[write_ordinal]
                )
        elif phase == "read":
            read_ordinal = read_ordinals.get(write_ordinal, 0) + 1
            read_ordinals[write_ordinal] = read_ordinal
            fault = pending_read_faults.pop(
                (write_ordinal, read_ordinal), None
            )
            if fault is not None:
                system.storage.inject_fault(**fault)
        return start_dma(request, phase)

    def track_flush(request):
        nonlocal flush_ordinal
        flush_ordinal += 1
        trace.append(("flush", 0, 0))
        fault = pending_flush_faults.pop(flush_ordinal, None)
        if fault is not None:
            if capture_prior_flush_media is not None:
                if flush_ordinal > 1:
                    assert system.storage.image_path is not None
                    durable_path = Path(system.storage.image_path)
                    assert durable_path.is_file(), (
                        "a prior successful flush did not publish backing media"
                    )
                    _copy_sparse_file(durable_path, capture_prior_flush_media)
            system.storage.inject_fault(**fault)
        return run_flush(request)

    system.storage._start_dma = track_dma
    system.storage._run_flush = track_flush
    for fault in storage_faults:
        system.storage.inject_fault(**fault)
    uart.clear()
    stack_check = (
        'DEPTH DUP 0= IF DROP ." EXT4-STACK-CLEAN" '
        'ELSE ." EXT4-STACK-LEAK " . THEN'
    )
    payload = ("\n".join((*lines, stack_check, "BYE")) + "\n").encode()
    journey_steps = _feed_until_idle(system, payload, max_steps)
    if os.environ.get("EXT4_REPORT_STEPS"):
        print(
            "[*] ext4 recovery journey: "
            f"{journey_steps:,}/{max_steps:,} steps "
            f"({image.name} -> {backing.name})"
        )
    output = fat_harness.uart_text(uart)
    _assert_no_forth_diagnostics(output)
    if not system.cpu.halted or not output.endswith("Bye!\r\n"):
        raise AssertionError(
            "ext4 recovery journey did not consume BYE and halt "
            f"after {journey_steps:,}/{max_steps:,} steps:\n"
            + output[-2000:]
        )
    _assert_emitted(output, "EXT4-STACK-CLEAN")
    if capture_media is not None:
        _write_sparse_bytes(capture_media, media)
    if capture_prior_flush_media is not None:
        assert capture_prior_flush_media.is_file()
    assert not pending_flush_faults, (
        f"unreached ordinal flush faults: {sorted(pending_flush_faults)}"
    )
    return output, tuple(trace), hashlib.sha256(media).hexdigest()


def _assert_emitted(output: str, marker: str) -> None:
    """Require executed output, not the marker text echoed in Forth source."""
    assert f"\r\n{marker} ok\r\n" in output, output[-4000:]


def _forth_conjunction(checks: list[str]) -> str:
    """Join nonempty Forth predicates with postfix AND operations."""
    assert checks
    return " ".join((checks[0], *(f"{check} AND" for check in checks[1:])))


def _forth_accumulated_conjunction(
    name: str, checks: list[str]
) -> tuple[str, ...]:
    """Accumulate predicates without exceeding MegaPad's 255-byte TIB."""
    assert name and checks
    first_failure = f"{name}-FIRST-FAILURE"
    lines = [
        f"VARIABLE {name}",
        f"VARIABLE {first_failure}",
        f"-1 {name} ! -1 {first_failure} !",
    ]
    for index, check in enumerate(checks):
        line = (
            f"{check} DUP 0= {first_failure} @ -1 = AND IF "
            f"{index} {first_failure} ! THEN {name} @ AND {name} !"
        )
        assert len(line.encode("utf-8")) <= 255
        lines.append(line)
    return tuple(lines)


def _forth_cp_delete_vector_checks(
    writer: str,
    ranges: tuple[tuple[int, int], ...],
) -> list[str]:
    """Return exact checkpoint data-range authority predicates."""
    checks = [
        (
            f"{writer} _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ "
            f"{len(ranges)} ="
        ),
        (
            f"{writer} _EXT4-JWR.CP-DELETE-BLOCKS + @ "
            f"{sum(count for _, count in ranges)} ="
        ),
    ]
    for index, (first, count) in enumerate(ranges):
        checks.extend(
            (
                (
                    f"{index} {writer} _EXT4-JWR-CP-DELETE-RANGE @ "
                    f"{first} ="
                ),
                (
                    f"{index} {writer} _EXT4-JWR-CP-DELETE-RANGE "
                    f"CELL+ @ {count} ="
                ),
            )
        )
    checks.append(
        (
            f"{writer} _EXT4-JWR-CP-DELETE-RANGES "
            f"{len(ranges) * 2} CELLS + "
            f"{writer} _EXT4-JWR.CP-DELETE-RANGE-CAP + @ "
            f"{len(ranges)} - "
            "2* CELLS _EXT4-BYTES-ZERO?"
        )
    )
    return checks


_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH = (
    "_EXT4-MUTATION-OWNER-RANGES @ 0=",
    "_EXT4-MUTATION-OWNER-RANGE-CAP @ 0=",
    "_EXT4-MUTATION-OWNER-RANGE-COUNT @ 0=",
    "_EXT4-MUTATION-OWNER-BOUND-FIRST @ 0=",
    "_EXT4-MUTATION-OWNER-BOUND-LIMIT @ 0=",
    "_EXT4-MUTATION-EA-REF-ACTIVE @ 0=",
    "_EXT4-MUTATION-EA-REF-HOME @ 0=",
    "_EXT4-MUTATION-EA-REF-HITS @ 0=",
)


def _ext4_dedicated_writer_profile_forth(
    prefix: str,
    vfs: str,
    metadata_capacity: int = 1,
    data_capacity: int = 1,
    revoke_capacity: int = 0,
) -> tuple[str, ...]:
    """Build and bind one exact caller-owned writer profile."""
    return (
        (
            f"{metadata_capacity} {data_capacity} {revoke_capacity} "
            f"{vfs} EXT4-WRITER-WORKSPACE-BYTES? "
            f"CONSTANT {prefix}-SIZE-IOR CONSTANT {prefix}-SIZE"
        ),
        f"{prefix}-SIZE A-XMEM ARENA-NEW THROW CONSTANT {prefix}-ARENA",
        f"{prefix}-ARENA A.BASE @ CONSTANT {prefix}-BASE",
        (
            f"{prefix}-ARENA {metadata_capacity} {data_capacity} "
            f"{revoke_capacity} {vfs} "
            f"EXT4-BIND-WRITER-ARENA? CONSTANT {prefix}-BIND-IOR"
        ),
        f"{prefix}-ARENA ARENA-USED CONSTANT {prefix}-USED",
    )


_EXT4_AUTH_ONLY_BINDING_FORTH = (
    (
        ": _EXT4-TEST-AUTH-MOUNT "
        "0 _EXT4-MOUNT-AUTHENTICATE ?DUP IF EXIT THEN "
        "EXT4-D-RECOVERY _EXT4-UNSUPPORTED ;"
    ),
    "CREATE _EXT4-TEST-AUTH-OPS VFS-OPS-SIZE ALLOT",
    "EXT4-OPS _EXT4-TEST-AUTH-OPS VFS-OPS-SIZE CMOVE",
    (
        "' _EXT4-TEST-AUTH-MOUNT _EXT4-TEST-AUTH-OPS "
        "VFS-OP-MOUNT CELLS + !"
    ),
    "CREATE _EXT4-TEST-AUTH-BINDING VFS-BINDING-DESC-SIZE ALLOT",
    (
        "EXT4-BINDING _EXT4-TEST-AUTH-BINDING "
        "VFS-BINDING-DESC-SIZE CMOVE"
    ),
    "_EXT4-TEST-AUTH-OPS _EXT4-TEST-AUTH-BINDING VB.OPS !",
    (
        ": EXT4-TEST-AUTH-NEW "
        "_EXT4-TEST-AUTH-BINDING SWAP VFS-NEW ;"
    ),
)


