@pytest.fixture(scope="session")
def replay_fixture(
    canonical_images: dict[str, Path],
    jbd2_toolchain: dict[str, object],
    tmp_path_factory: pytest.TempPathFactory,
) -> dict[str, object]:
    debugfs = jbd2_toolchain["debugfs"]
