@pytest.mark.parametrize("protocol", ("modern", "legacy"))
@pytest.mark.parametrize(
    "extent_case",
    (
        "one-block",
        "initialized-offset",
        "cross-group-unwritten-offset",
    ),
)
def test_single_extent_unlinked_cleanup_measures_and_seals_exact_certificate(
    canonical_images: dict[str, Path],
    protocol: str,
    extent_case: str,
) -> None:
    path = canonical_images["primary-1k-i256"]
    if extent_case == "one-block":
        data_count = 1
        expected_credit = 6 if protocol == "modern" else 5
        patches, data_block = _one_block_unlinked_orphan_patches(
            path,
            protocol=protocol,
        )
    elif extent_case == "initialized-offset":
        data_count = 3
        expected_credit = 6 if protocol == "modern" else 5
        patches, data_block = _single_extent_unlinked_orphan_patches(
            path,
            protocol=protocol,
            logical_start=7,
            block_count=data_count,
        )
    else:
        assert extent_case == "cross-group-unwritten-offset"
        with path.open("rb") as source:
            source.seek(1024)
            superblock = source.read(1024)
        first_data = struct.unpack_from("<I", superblock, 0x14)[0]
        blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
        data_block = first_data + 4 * blocks_per_group - 1
        assert data_block == 32768
        data_count = 2
        expected_credit = 7 if protocol == "modern" else 6
        patches, observed_data_block = (
            _single_extent_unlinked_orphan_patches(
                path,
                protocol=protocol,
                physical_start=data_block,
                logical_start=11,
                block_count=data_count,
                unwritten=True,
            )
        )
        assert observed_data_block == data_block
    _, _, inode_offset = _ext4_inode_record(path, 18)
    with path.open("rb") as source:
        source.seek((inode_offset // 1024) * 1024)
        expected_target_home = source.read(1024)
    assert len(expected_target_home) == 1024
    expected_target_crc = _crc32c_raw(expected_target_home)
    expected_mode = (
        "_EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL"
        if protocol == "modern"
        else "_EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL"
    )
    marker = (
        f"EXT4-{protocol.upper()}-{extent_case.upper()}-"
        "UNLINKED-FINAL-SEALED"
    )
    aborted_marker = f"{marker}-ABORTED"

    output = run_forth(
        path,
        [
            *_EXT4_AUTH_ONLY_BINDING_FORTH,
            "T-ARENA CONSTANT _UD-ARENA",
            (
                "_UD-ARENA T-VOLUME EXT4-TEST-AUTH-NEW "
                "CONSTANT _UD-MOUNT-IOR CONSTANT _UD-V"
            ),
            "_UD-V _EXT4-CTX CONSTANT _UD-CTX",
            (
                "_UD-CTX _EXT4-FIND-SELECTED-ORPHAN "
                "CONSTANT _UD-FIND-IOR CONSTANT _UD-RECORD"
            ),
            "_UD-CTX _EXT4-VALIDATE-JOURNAL CONSTANT _UD-JOURNAL-IOR",
            (
                "_UD-RECORD _UD-CTX "
                "_EXT4-MEASURE-ORPHAN-CLEANUP NIP "
                "CONSTANT _UD-MEASURE-IOR CONSTANT _UD-CREDIT"
            ),
            (
                "_UD-CREDIT 0 0 _UD-CTX _EXT4-JTX-PREFLIGHT-CAPACITY "
                "CONSTANT _UD-CAPACITY-IOR"
            ),
            "-1 _UD-CTX _EXT4-C.J.WRITER-CURRENT + !",
            (
                "_UD-CREDIT 0 0 _UD-CTX _EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _UD-WRITER-IOR CONSTANT _UD-WRITER"
            ),
            (
                "_UD-CREDIT 0 0 _UD-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _UD-BEGIN-IOR CONSTANT _UD-TX"
            ),
            "DEPTH CONSTANT _UD-DEPTH-BEFORE-STAGE",
            (
                "_UD-RECORD _UD-TX "
                "_EXT4-JTX-STAGE-ORPHAN-CLEANUP "
                "CONSTANT _UD-STAGE-IOR"
            ),
            "DEPTH CONSTANT _UD-DEPTH-AFTER-STAGE",
            (
                "2000 _UD-TX _EXT4-JTX-DATA-ZERO "
                "CONSTANT _UD-MUTATE-IOR"
            ),
            (
                _forth_conjunction(
                    [
                        (
                            "_UD-MOUNT-IOR VFS-IOR-REASON "
                            "VFS-R-UNSUPPORTED ="
                        ),
                        (
                            "_UD-MOUNT-IOR VFS-IOR-DETAIL "
                            "EXT4-D-RECOVERY ="
                        ),
                        "_UD-FIND-IOR 0=",
                        "_UD-JOURNAL-IOR 0=",
                        "_UD-MEASURE-IOR 0=",
                        f"_UD-CREDIT {expected_credit} =",
                        "_UD-CAPACITY-IOR 0=",
                        "_UD-WRITER-IOR 0=",
                        "_UD-BEGIN-IOR 0=",
                        "_UD-STAGE-IOR 0=",
                        (
                            "_UD-DEPTH-BEFORE-STAGE "
                            "_UD-DEPTH-AFTER-STAGE ="
                        ),
                        "_UD-MUTATE-IOR VFS-E-BUSY =",
                        (
                            "_UD-WRITER _EXT4-JWR.STATE + @ "
                            "_EXT4-JWR-STAGING ="
                        ),
                        (
                            "_UD-WRITER _EXT4-JWR.META-CREDIT + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_UD-WRITER _EXT4-JWR.META-USED + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_UD-WRITER _EXT4-JWR.META-ACTIVE + @ "
                            f"{expected_credit} ="
                        ),
                        "_UD-WRITER _EXT4-JWR.DATA-USED + @ 0=",
                        "_UD-WRITER _EXT4-JWR.REVOKE-USED + @ 0=",
                        (
                            "_UD-WRITER _EXT4-JWR.CP-MODE + @ "
                            f"{expected_mode} ="
                        ),
                        "_UD-WRITER _EXT4-JWR.CP-O-INO + @ 18 =",
                        (
                            "_UD-WRITER _EXT4-JWR.CP-TARGET-GEN + @ "
                            "0x18181818 ="
                        ),
                        "_UD-WRITER _EXT4-JWR.CP-TARGET-HOME + @ 279 =",
                        "_UD-WRITER _EXT4-JWR.CP-TARGET-OFF + @ 256 =",
                        "_UD-WRITER _EXT4-JWR.CP-TARGET-ENTRIES + @ 1 =",
                        (
                            "_UD-WRITER _EXT4-JWR.CP-TARGET-CRC + @ "
                            f"{expected_target_crc} ="
                        ),
                        *_forth_cp_delete_vector_checks(
                            "_UD-WRITER",
                            ((data_block, data_count),),
                        ),
                        (
                            "_UD-WRITER _EXT4-JWR.CP-INODE-BITMAP-HOME + @ "
                            "267 ="
                        ),
                        (
                            "_UD-WRITER _EXT4-JWR.CP-INODE-GDT-HOME + @ "
                            "2 ="
                        ),
                        (
                            "_UD-WRITER _EXT4-JWR.CP-INODE-GDT-OFF + @ "
                            "0="
                        ),
                        "_UD-WRITER _EXT4-JWR-CP-AUTHORITY?",
                        "_UD-WRITER _EXT4-JTX-TABLES-VALID?",
                        "_UD-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                    ]
                )
                + f' IF ." {marker}" THEN'
            ),
            "_UD-TX _EXT4-JTX-ABORT CONSTANT _UD-ABORT-IOR",
            (
                _forth_conjunction(
                    [
                        "_UD-ABORT-IOR 0=",
                        (
                            "_UD-WRITER _EXT4-JWR.STATE + @ "
                            "_EXT4-JWR-IDLE ="
                        ),
                        "_UD-WRITER _EXT4-JWR-TRANSACTION-CLEAN?",
                        "_UD-WRITER _EXT4-JWR-VALID?",
                    ]
                )
                + f' IF ." {aborted_marker}" THEN'
            ),
        ],
        patches=patches,
    )
    _assert_emitted(output, marker)
    _assert_emitted(output, aborted_marker)


def _assert_unlinked_external_xattr_cleanup_seals_exact_release_authority(
    canonical_images: dict[str, Path],
    protocol: str,
    data_blocks: int,
    map_format: str,
) -> None:
    assert map_format in {"extents", "legacy-direct"}
    path = canonical_images["primary-1k-i256"]
    if map_format == "legacy-direct":
        assert data_blocks == 12
        patches, data_ranges, xattr_block = (
            _legacy_direct_unlinked_external_xattr_patches(
                path,
                protocol=protocol,
            )
        )
        expected_data_map_kind = "_EXT4-JDM-LEGACY-DIRECT"
    else:
        patches, data_ranges, xattr_block = (
            _unlinked_orphan_external_xattr_patches(
                path,
                protocol=protocol,
                data_blocks=data_blocks,
            )
        )
        expected_data_map_kind = "_EXT4-JDM-INLINE-EXTENTS"
    patch_map = dict(patches)
    superblock = patch_map[1024]
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    total_blocks = struct.unpack_from("<I", superblock, 0x04)[0] | (
        struct.unpack_from("<I", superblock, 0x150)[0] << 32
    )
    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    group_blocks = min(blocks_per_group, total_blocks - first_data)
    assert (xattr_block - first_data) // blocks_per_group == 0
    descriptor_home = first_data + 1
    descriptor = patch_map[descriptor_home * block_size][:64]
    block_bitmap_home = struct.unpack_from("<I", descriptor, 0x00)[0]
    released_blocks = tuple(
        physical
        for first, count in data_ranges
        for physical in range(first, first + count)
    ) + (xattr_block,)
    assert all(
        (physical - first_data) // blocks_per_group == 0
        for physical in released_blocks
    )
    expected_credit = 6 if protocol == "modern" else 5
    if data_ranges:
        expected_mode = (
            "_EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL"
            if protocol == "modern"
            else "_EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL"
        )
    else:
        expected_mode = (
            "_EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL"
            if protocol == "modern"
            else "_EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL"
        )
    if map_format == "legacy-direct":
        shape = "LEGACY-DIRECT-MAX-EA"
    else:
        shape = "EA-ONLY" if not data_ranges else "DATA-EA"
    marker = f"EXT4-{protocol.upper()}-{shape}-UNLINKED-SEALED"
    clean_marker = f"{marker}-ABORTED"

    output = run_forth(
        path,
        [
            *_EXT4_AUTH_ONLY_BINDING_FORTH,
            (
                "T-ARENA T-VOLUME EXT4-TEST-AUTH-NEW "
                "CONSTANT _UX-MOUNT-IOR CONSTANT _UX-V"
            ),
            "_UX-V _EXT4-CTX CONSTANT _UX-CTX",
            (
                "_UX-CTX _EXT4-FIND-SELECTED-ORPHAN "
                "CONSTANT _UX-FIND-IOR CONSTANT _UX-RECORD"
            ),
            "_UX-CTX _EXT4-VALIDATE-JOURNAL CONSTANT _UX-JOURNAL-IOR",
            "_EXT4-JFO-CERT-BEGIN CONSTANT _UX-CERT-BEGIN-IOR",
            (
                "_UX-RECORD _UX-CTX _EXT4-MEASURE-ORPHAN-CLEANUP "
                "CONSTANT _UX-MEASURE-IOR CONSTANT _UX-REVOKE "
                "CONSTANT _UX-CREDIT"
            ),
            "-1 _UX-CTX _EXT4-C.J.WRITER-CURRENT + !",
            (
                "_UX-CREDIT 0 _UX-REVOKE _UX-CTX "
                "_EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _UX-WRITER-IOR CONSTANT _UX-WRITER"
            ),
            (
                "_UX-CREDIT 0 _UX-REVOKE _UX-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _UX-BEGIN-IOR CONSTANT _UX-TX"
            ),
            "DEPTH CONSTANT _UX-DEPTH-BEFORE",
            (
                "_UX-RECORD _UX-TX _EXT4-JTX-STAGE-ORPHAN-CLEANUP "
                "CONSTANT _UX-STAGE-IOR"
            ),
            "DEPTH CONSTANT _UX-DEPTH-AFTER",
            (
                f"{block_bitmap_home} _UX-WRITER _EXT4-JFC-FIND-META "
                "CONSTANT _UX-BITMAP-IOR"
            ),
            "_EXT4-JFC-FOUND @ CONSTANT _UX-BITMAP-FOUND",
            "_EXT4-JFC-IMAGE @ CONSTANT _UX-BITMAP-IMAGE",
            (
                _forth_conjunction(
                    [
                        (
                            "_UX-MOUNT-IOR VFS-IOR-REASON "
                            "VFS-R-UNSUPPORTED ="
                        ),
                        "_UX-FIND-IOR 0=",
                        "_UX-JOURNAL-IOR 0=",
                        "_UX-CERT-BEGIN-IOR 0=",
                        "_UX-MEASURE-IOR 0=",
                        f"_UX-CREDIT {expected_credit} =",
                        "_UX-REVOKE 1 =",
                        "_UX-WRITER-IOR 0=",
                        "_UX-BEGIN-IOR 0=",
                        "_UX-STAGE-IOR 0=",
                        "_UX-DEPTH-BEFORE _UX-DEPTH-AFTER =",
                        (
                            "_UX-WRITER _EXT4-JWR.META-USED + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.META-ACTIVE + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.REVOKE-CREDIT + @ "
                            "_UX-REVOKE ="
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.REVOKE-USED + @ "
                            "_UX-REVOKE ="
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.REVOKE-ACTIVE + @ "
                            "_UX-REVOKE ="
                        ),
                        (
                            "0 _UX-WRITER _EXT4-JWR-REVOKE-ENTRY @ "
                            f"{xattr_block} ="
                        ),
                        (
                            "0 _UX-WRITER _EXT4-JWR-REVOKE-ENTRY "
                            "CELL+ @ _EXT4-JE-ACTIVE ="
                        ),
                        "_UX-WRITER _EXT4-JFI-REVOKES-EXACT?",
                        (
                            "_UX-WRITER _EXT4-JWR.CP-MODE + @ "
                            f"{expected_mode} ="
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.CP-TARGET-ENTRIES + @ "
                            f"{len(data_ranges)} ="
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.CP-DATA-MAP-KIND + @ "
                            f"{expected_data_map_kind} ="
                        ),
                        *_forth_cp_delete_vector_checks(
                            "_UX-WRITER",
                            data_ranges,
                        ),
                        (
                            "_UX-WRITER _EXT4-JWR.CP-EA-HOME + @ "
                            f"{xattr_block} ="
                        ),
                        f"_EXT4-JFI-EA @ {xattr_block} =",
                        f"_EXT4-JFI-EA-RANGE @ {xattr_block} =",
                        "_EXT4-JFI-EA-RANGE CELL+ @ 1 =",
                        (
                            "_EXT4-JFI-RELEASE-RANGE-COUNT "
                            f"{len(data_ranges) + 1} ="
                        ),
                        (
                            "_EXT4-JFI-RELEASE-BLOCKS "
                            f"{data_blocks + 1} ="
                        ),
                        "_EXT4-JFO-CERT-VALID @ 0<>",
                        f"_EXT4-JFO-CERT-EA @ {xattr_block} =",
                        (
                            "_EXT4-JFO-CERT-RANGE-COUNT @ "
                            f"{len(data_ranges)} ="
                        ),
                        (
                            "_EXT4-JFO-CERT-DATA-MAP-KIND @ "
                            f"{expected_data_map_kind} ="
                        ),
                        "_EXT4-JFO-CERT-MATCH?",
                        "_UX-WRITER _EXT4-JFI-CP-RANGES-MATCH?",
                        "_UX-WRITER _EXT4-JWR-CP-AUTHORITY?",
                        "_UX-BITMAP-IOR 0=",
                        "_UX-BITMAP-FOUND 0<>",
                        *[
                            (
                                f"_UX-BITMAP-IMAGE {group_blocks} "
                                f"{physical - first_data} 1 "
                                "BITSET-ALL-CLEAR? AND"
                            )
                            for physical in released_blocks
                        ],
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        "_UX-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                    ]
                )
                + f' IF ." {marker}" THEN'
            ),
            "_UX-TX _EXT4-JTX-ABORT CONSTANT _UX-ABORT-IOR",
            "_EXT4-JFO-CERT-END",
            (
                _forth_conjunction(
                    [
                        "_UX-ABORT-IOR 0=",
                        (
                            "_UX-WRITER _EXT4-JWR.STATE + @ "
                            "_EXT4-JWR-IDLE ="
                        ),
                        "_UX-WRITER _EXT4-JWR-TRANSACTION-CLEAN?",
                        "_UX-WRITER _EXT4-JWR-VALID?",
                        "_EXT4-JFO-CERT-SCOPE @ 0=",
                        "_EXT4-JFO-CERT-VALID @ 0=",
                        "_UX-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                    ]
                )
                + f' IF ." {clean_marker}" THEN'
            ),
        ],
        patches=patches,
    )
    _assert_emitted(output, marker)
    _assert_emitted(output, clean_marker)


@pytest.mark.parametrize("protocol", ("modern", "legacy"))
@pytest.mark.parametrize("data_blocks", (0, 1), ids=("ea-only", "data-plus-ea"))
def test_unlinked_external_xattr_cleanup_seals_exact_release_authority(
    canonical_images: dict[str, Path],
    protocol: str,
    data_blocks: int,
) -> None:
    _assert_unlinked_external_xattr_cleanup_seals_exact_release_authority(
        canonical_images,
        protocol,
        data_blocks,
        "extents",
    )


def test_legacy_direct_maximum_release_owner_vector_seals_exactly(
    canonical_images: dict[str, Path],
) -> None:
    _assert_unlinked_external_xattr_cleanup_seals_exact_release_authority(
        canonical_images,
        "modern",
        12,
        "legacy-direct",
    )


@pytest.mark.parametrize("protocol", ("modern", "legacy"))
@pytest.mark.parametrize("data_blocks", (0, 1), ids=("ea-only", "data-plus-ea"))
def test_shared_external_xattr_cleanup_seals_refcount_decrement(
    canonical_images: dict[str, Path],
    protocol: str,
    data_blocks: int,
) -> None:
    path = canonical_images["primary-1k-i256"]
    patches, data_ranges, xattr_block = (
        _unlinked_orphan_shared_external_xattr_patches(
            path,
            protocol=protocol,
            data_blocks=data_blocks,
        )
    )
    assert len(data_ranges) == (1 if data_blocks else 0)
    expected_credit = (6 if protocol == "modern" else 5) + (
        1 if data_ranges else 0
    )
    if data_ranges:
        expected_mode = (
            "_EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL"
            if protocol == "modern"
            else "_EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL"
        )
        shape = "DATA-EA"
    else:
        expected_mode = (
            "_EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL"
            if protocol == "modern"
            else "_EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL"
        )
        shape = "EA-ONLY"
    marker = (
        f"EXT4-{protocol.upper()}-{shape}-"
        "SHARED-XATTR-REFDEC-SEALED"
    )
    clean_marker = f"{marker}-ABORTED"

    output = run_forth(
        path,
        [
            *_EXT4_AUTH_ONLY_BINDING_FORTH,
            (
                "T-ARENA T-VOLUME EXT4-TEST-AUTH-NEW "
                "CONSTANT _SX-MOUNT-IOR CONSTANT _SX-V"
            ),
            "_SX-V _EXT4-CTX CONSTANT _SX-CTX",
            (
                "_SX-CTX _EXT4-FIND-SELECTED-ORPHAN "
                "CONSTANT _SX-FIND-IOR CONSTANT _SX-RECORD"
            ),
            "_SX-CTX _EXT4-VALIDATE-JOURNAL CONSTANT _SX-JOURNAL-IOR",
            "_EXT4-JFO-CERT-BEGIN CONSTANT _SX-CERT-BEGIN-IOR",
            (
                "_SX-RECORD _SX-CTX _EXT4-MEASURE-ORPHAN-CLEANUP NIP "
                "CONSTANT _SX-MEASURE-IOR CONSTANT _SX-CREDIT"
            ),
            (
                "_SX-CREDIT _EXT4-MQ-CAPACITY-CREDIT "
                "CONSTANT _SX-CAP-IOR CONSTANT _SX-CAP"
            ),
            "-1 _SX-CTX _EXT4-C.J.WRITER-CURRENT + !",
            (
                "_SX-CREDIT 0 0 _SX-CTX _EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _SX-WRITER-IOR CONSTANT _SX-WRITER"
            ),
            (
                "_SX-CREDIT 0 0 _SX-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _SX-BEGIN-IOR CONSTANT _SX-TX"
            ),
            (
                "_SX-RECORD _SX-TX _EXT4-JTX-STAGE-ORPHAN-CLEANUP "
                "CONSTANT _SX-STAGE-IOR"
            ),
            (
                f"{xattr_block} _SX-WRITER _EXT4-JFC-FIND-META "
                "CONSTANT _SX-EA-FIND-IOR"
            ),
            "_EXT4-JFC-FOUND @ CONSTANT _SX-EA-FOUND",
            "_EXT4-JFC-ENTRY @ CONSTANT _SX-EA-ENTRY",
            "_EXT4-JFC-IMAGE @ CONSTANT _SX-EA-IMAGE",
            "_SX-EA-ENTRY 2 CELLS + @ CONSTANT _SX-EA-CRC",
            "0 _EXT4-JFI-EA-AFTER-CRC !",
            "-1 _EXT4-JFI-EA-AFTER-VERIFIED !",
            "0 _SX-WRITER _EXT4-JWR.CP-EA-CRC + !",
            (
                "_SX-WRITER _EXT4-JFI-CP-RANGES-MATCH? "
                "CONSTANT _SX-ZERO-CRC-MATCH"
            ),
            "1 _SX-WRITER _EXT4-JWR.CP-EA-CRC + !",
            (
                "_SX-WRITER _EXT4-JFI-CP-RANGES-MATCH? 0= "
                "CONSTANT _SX-ZERO-CRC-TAMPER-REJECTED"
            ),
            (
                "_SX-EA-CRC DUP _EXT4-JFI-EA-AFTER-CRC ! "
                "_SX-WRITER _EXT4-JWR.CP-EA-CRC + !"
            ),
            (
                _forth_conjunction(
                    [
                        (
                            "_SX-MOUNT-IOR VFS-IOR-REASON "
                            "VFS-R-UNSUPPORTED ="
                        ),
                        "_SX-FIND-IOR 0=",
                        "_SX-JOURNAL-IOR 0=",
                        "_SX-CERT-BEGIN-IOR 0=",
                        "_SX-MEASURE-IOR 0=",
                        f"_SX-CREDIT {expected_credit} =",
                        "_SX-CAP-IOR 0=",
                        f"_SX-CAP {expected_credit + 1} =",
                        "_SX-WRITER-IOR 0=",
                        "_SX-BEGIN-IOR 0=",
                        "_SX-STAGE-IOR 0=",
                        (
                            "_SX-WRITER _EXT4-JWR.META-CREDIT + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.META-USED + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.META-ACTIVE + @ "
                            f"{expected_credit} ="
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.CP-MODE + @ "
                            f"{expected_mode} ="
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.CP-TARGET-ENTRIES + @ "
                            f"{len(data_ranges)} ="
                        ),
                        *_forth_cp_delete_vector_checks(
                            "_SX-WRITER",
                            data_ranges,
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.CP-DATA-MAP-KIND + @ "
                            "_EXT4-JDM-INLINE-EXTENTS ="
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.CP-EA-HOME + @ "
                            f"{xattr_block} ="
                        ),
                        (
                            "_SX-WRITER _EXT4-JWR.CP-EA-ACTION + @ "
                            "_EXT4-JEA-REFDEC ="
                        ),
                        "_SX-WRITER _EXT4-JWR.CP-EA-REFCOUNT + @ 1 =",
                        (
                            "_SX-WRITER _EXT4-JWR.CP-EA-CRC + @ "
                            "_SX-EA-ENTRY 2 CELLS + @ ="
                        ),
                        "_SX-EA-FIND-IOR 0=",
                        "_SX-EA-FOUND 0<>",
                        "_SX-EA-IMAGE L@ _EXT4-XATTR-MAGIC =",
                        "_SX-EA-IMAGE 4 + L@ 1 =",
                        "_EXT4-JFI-EA-ACTION @ _EXT4-JEA-REFDEC =",
                        "_EXT4-JFI-EA-REFCOUNT @ 2 =",
                        "_EXT4-JFI-EA-AFTER-CRC @ _SX-EA-ENTRY 2 CELLS + @ =",
                        "_EXT4-JFI-EA-AFTER-VERIFIED @ 0<>",
                        "_SX-ZERO-CRC-MATCH 0<>",
                        "_SX-ZERO-CRC-TAMPER-REJECTED 0<>",
                        (
                            "_EXT4-JFI-RELEASE-RANGE-COUNT "
                            f"{len(data_ranges)} ="
                        ),
                        f"_EXT4-JFI-RELEASE-BLOCKS {data_blocks} =",
                        (
                            "_EXT4-JFI-ACCOUNTED-BLOCKS "
                            f"{data_blocks + 1} ="
                        ),
                        (
                            "_EXT4-JFI-OWNER-RANGE-COUNT "
                            f"{len(data_ranges) + 1} ="
                        ),
                        "_EXT4-JFO-CERT-VALID @ 0<>",
                        f"_EXT4-JFO-CERT-EA @ {xattr_block} =",
                        (
                            "_EXT4-JFO-CERT-RANGE-COUNT @ "
                            f"{len(data_ranges)} ="
                        ),
                        "_EXT4-JFO-CERT-EA-ACTION @ _EXT4-JEA-REFDEC =",
                        "_EXT4-JFO-CERT-EA-REFCOUNT @ 2 =",
                        "_EXT4-JFO-CERT-MATCH?",
                        "_SX-WRITER _EXT4-JFI-CP-RANGES-MATCH?",
                        "_SX-WRITER _EXT4-JWR-CP-AUTHORITY?",
                        "_SX-WRITER _EXT4-JTX-TABLES-VALID?",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        "_SX-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                    ]
                )
                + f' IF ." {marker}" THEN'
            ),
            "_SX-TX _EXT4-JTX-ABORT CONSTANT _SX-ABORT-IOR",
            "_EXT4-JFO-CERT-END",
            (
                _forth_conjunction(
                    [
                        "_SX-ABORT-IOR 0=",
                        "_SX-WRITER _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE =",
                        "_SX-WRITER _EXT4-JWR-TRANSACTION-CLEAN?",
                        "_SX-WRITER _EXT4-JWR-VALID?",
                        "_EXT4-JFO-CERT-SCOPE @ 0=",
                        "_EXT4-JFO-CERT-VALID @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        "_SX-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                    ]
                )
                + f' IF ." {clean_marker}" THEN'
            ),
        ],
        patches=patches,
    )
    _assert_emitted(output, marker)
    _assert_emitted(output, clean_marker)


def test_shared_external_xattr_semantic_verifier_rejects_coherent_hash_tamper(
    canonical_images: dict[str, Path],
) -> None:
    path = canonical_images["primary-1k-i256"]
    patches, data_ranges, xattr_block = (
        _unlinked_orphan_shared_external_xattr_patches(
            path,
            protocol="modern",
            data_blocks=0,
        )
    )
    assert data_ranges == ()
    marker = "EXT4-SHARED-XATTR-COHERENT-HASH-TAMPER-REJECTED"
    clean_marker = f"{marker}-ABORTED"

    output = run_forth(
        path,
        [
            *_EXT4_AUTH_ONLY_BINDING_FORTH,
            (
                "T-ARENA T-VOLUME EXT4-TEST-AUTH-NEW "
                "CONSTANT _XT-MOUNT-IOR CONSTANT _XT-V"
            ),
            "_XT-V _EXT4-CTX CONSTANT _XT-CTX",
            (
                "_XT-CTX _EXT4-FIND-SELECTED-ORPHAN "
                "CONSTANT _XT-FIND-IOR CONSTANT _XT-RECORD"
            ),
            "_XT-CTX _EXT4-VALIDATE-JOURNAL CONSTANT _XT-JOURNAL-IOR",
            "_EXT4-JFO-CERT-BEGIN CONSTANT _XT-CERT-BEGIN-IOR",
            (
                "_XT-RECORD _XT-CTX _EXT4-MEASURE-ORPHAN-CLEANUP NIP "
                "CONSTANT _XT-MEASURE-IOR CONSTANT _XT-CREDIT"
            ),
            "-1 _XT-CTX _EXT4-C.J.WRITER-CURRENT + !",
            (
                "_XT-CREDIT 0 0 _XT-CTX _EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _XT-WRITER-IOR CONSTANT _XT-WRITER"
            ),
            (
                "_XT-CREDIT 0 0 _XT-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _XT-BEGIN-IOR CONSTANT _XT-TX"
            ),
            (
                "_XT-RECORD _XT-TX _EXT4-JTX-STAGE-ORPHAN-CLEANUP "
                "CONSTANT _XT-STAGE-IOR"
            ),
            (
                f"{xattr_block} _XT-WRITER _EXT4-JFC-FIND-META "
                "CONSTANT _XT-EA-FIND-IOR"
            ),
            "_EXT4-JFC-FOUND @ CONSTANT _XT-EA-FOUND",
            "_EXT4-JFC-ENTRY @ CONSTANT _XT-EA-ENTRY",
            "_EXT4-JFC-IMAGE @ CONSTANT _XT-EA-IMAGE",
            "_XT-EA-IMAGE 0x0C + C@ CONSTANT _XT-HASH-BEFORE",
            (
                "_XT-EA-IMAGE 0x0C + DUP C@ 1 XOR SWAP C! "
                f"_XT-EA-IMAGE {xattr_block} _XT-CTX "
                "_EXT4-STAMP-XATTR-BLOCK CONSTANT _XT-STAMP-IOR"
            ),
            (
                "_XT-EA-IMAGE _XT-WRITER _EXT4-JTX-IMAGE-CRC "
                "CONSTANT _XT-FORGED-CRC-IOR "
                "CONSTANT _XT-FORGED-CRC"
            ),
            "_XT-FORGED-CRC _XT-EA-ENTRY 2 CELLS + !",
            (
                "_XT-FORGED-CRC _XT-WRITER "
                "_EXT4-JWR.CP-EA-CRC + !"
            ),
            (
                "_XT-WRITER _EXT4-JTX-TABLES-VALID? "
                "CONSTANT _XT-TABLES-VALID"
            ),
            (
                "_XT-WRITER _EXT4-JWR-CP-AUTHORITY? "
                "CONSTANT _XT-CP-AUTHORITY"
            ),
            "_XT-WRITER _EXT4-JWR-VALID? CONSTANT _XT-WRITER-VALID",
            (
                "_XT-RECORD _XT-WRITER _EXT4-JFD-VERIFY-STAGED "
                "CONSTANT _XT-VERIFY-IOR"
            ),
            (
                _forth_conjunction(
                    [
                        (
                            "_XT-MOUNT-IOR VFS-IOR-REASON "
                            "VFS-R-UNSUPPORTED ="
                        ),
                        "_XT-FIND-IOR 0=",
                        "_XT-JOURNAL-IOR 0=",
                        "_XT-CERT-BEGIN-IOR 0=",
                        "_XT-MEASURE-IOR 0=",
                        "_XT-CREDIT 6 =",
                        "_XT-WRITER-IOR 0=",
                        "_XT-BEGIN-IOR 0=",
                        "_XT-STAGE-IOR 0=",
                        "_XT-EA-FIND-IOR 0=",
                        "_XT-STAMP-IOR 0=",
                        "_XT-FORGED-CRC-IOR 0=",
                        "_XT-EA-FOUND 0<>",
                        "_XT-EA-IMAGE 4 + L@ 1 =",
                        (
                            "_XT-EA-IMAGE 0x0C + C@ "
                            "_XT-HASH-BEFORE 1 XOR ="
                        ),
                        "_XT-TABLES-VALID",
                        "_XT-CP-AUTHORITY",
                        "_XT-WRITER-VALID",
                        "_XT-VERIFY-IOR VFS-E-CORRUPT =",
                        "_XT-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                    ]
                )
                + f' IF ." {marker}" THEN'
            ),
            "_XT-TX _EXT4-JTX-ABORT CONSTANT _XT-ABORT-IOR",
            "_EXT4-JFO-CERT-END",
            (
                _forth_conjunction(
                    [
                        "_XT-ABORT-IOR 0=",
                        "_XT-WRITER _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE =",
                        "_XT-WRITER _EXT4-JWR-TRANSACTION-CLEAN?",
                        "_XT-WRITER _EXT4-JWR-VALID?",
                        "_EXT4-JFO-CERT-SCOPE @ 0=",
                        "_EXT4-JFO-CERT-VALID @ 0=",
                        "_XT-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                    ]
                )
                + f' IF ." {clean_marker}" THEN'
            ),
        ],
        patches=patches,
    )
    _assert_emitted(output, marker)
    _assert_emitted(output, clean_marker)


