def _assert_sparse_triple_root_unlinked_cleanup_result(
    result: dict[str, object],
    *,
    expected_direct_slots: tuple[int, ...],
    expected_child_slot: int | None = None,
) -> None:
    protocol = result["protocol"]
    source = result["source"]
    patches = result["patches"]
    output = result["output"]
    trace = result["success_trace"]
    clean_image = result["clean_image"]
    clean_sha256 = result["clean_sha256"]
    block_size = result["block_size"]
    inode_home = result["inode_home"]
    block_bitmap_home = result["block_bitmap_home"]
    inode_bitmap_home = result["inode_bitmap_home"]
    gdt_home = result["gdt_home"]
    root_home = result["triple_root_home"]
    child_slot = result["triple_child_slot"]
    child_home = result["triple_child_home"]
    orphan_home = result["orphan_home"]
    direct_slots = result["direct_slots"]
    data_ranges = result["data_ranges"]
    map_ranges = result["map_ranges"]
    release_ranges = result["release_ranges"]
    extent_case = result["extent_case"]
    stable_output = result["stable_output"]
    stable_image = result["stable_image"]

    assert protocol in {"modern", "legacy"}
    assert isinstance(source, Path)
    assert isinstance(patches, tuple)
    assert isinstance(output, str)
    assert isinstance(trace, tuple)
    assert isinstance(clean_image, Path)
    assert isinstance(clean_sha256, str)
    assert isinstance(block_size, int)
    assert isinstance(inode_home, int)
    assert isinstance(block_bitmap_home, int)
    assert isinstance(inode_bitmap_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(root_home, int)
    assert child_slot is None or isinstance(child_slot, int)
    assert child_home is None or isinstance(child_home, int)
    assert isinstance(orphan_home, int)
    assert isinstance(direct_slots, tuple)
    assert isinstance(data_ranges, tuple)
    assert isinstance(map_ranges, tuple)
    assert isinstance(release_ranges, tuple)
    assert isinstance(extent_case, str)
    assert isinstance(stable_output, str)
    assert isinstance(stable_image, Path)
    assert expected_direct_slots in {(), (5,)}
    assert expected_child_slot is None or not expected_direct_slots
    expected_extent_case = "legacy-empty-triple-root"
    if expected_direct_slots:
        expected_extent_case = "legacy-direct-empty-triple-root"
    elif expected_child_slot is not None:
        expected_extent_case = "legacy-one-child-triple-root"
    assert extent_case == expected_extent_case
    assert direct_slots == expected_direct_slots
    assert child_slot == expected_child_slot
    assert len(data_ranges) == len(expected_direct_slots)
    assert all(count == 1 for _, count in data_ranges)
    if expected_child_slot is None:
        assert child_home is None
        assert map_ranges == ((root_home, 1),)
    else:
        assert isinstance(child_home, int)
        assert child_home == root_home + 1
        assert map_ranges == ((root_home, 1), (child_home, 1))
    assert release_ranges == (*data_ranges, *map_ranges)
    released_homes = tuple(home for home, _ in release_ranges)
    assert all(count == 1 for _, count in release_ranges)
    assert released_homes == tuple(
        range(released_homes[0], released_homes[0] + len(released_homes))
    )
    assert result["data_block"] == released_homes[0]
    assert result["data_count"] == len(released_homes)
    _assert_emitted(
        output,
        f"EXT4-{protocol.upper()}-UNLINKED-ORPHAN-RECLAIMED",
    )
    assert clean_image.is_file()
    assert _sha256(clean_image) == clean_sha256

    expected_home_writes = 6 if protocol == "modern" else 5
    expected_write_count = 37 if protocol == "modern" else 35
    assert result["expected_home_writes"] == expected_home_writes
    assert sum(kind == "write" for kind, _, _ in trace) == (
        expected_write_count
    )
    assert sum(kind == "flush" for kind, _, _ in trace) == 24

    assert len(
        _write_ordinals_for_ext4_home(
            trace,
            1,
            block_size=block_size,
        )
    ) == 3
    single_write_homes = [
        gdt_home,
        block_bitmap_home,
        inode_bitmap_home,
        inode_home,
    ]
    if protocol == "modern":
        single_write_homes.append(orphan_home)
    for home in single_write_homes:
        assert len(
            _write_ordinals_for_ext4_home(
                trace,
                home,
                block_size=block_size,
            )
        ) == 1
    if protocol == "legacy":
        assert not _write_ordinals_for_ext4_home(
            trace,
            orphan_home,
            block_size=block_size,
        )
    for released_home in released_homes:
        assert not _write_ordinals_for_ext4_home(
            trace,
            released_home,
            block_size=block_size,
        )

    _assert_emitted(
        stable_output,
        (
            f"EXT4-{protocol.upper()}-{extent_case.upper()}-"
            "UNLINKED-STABLE-REMOUNT"
        ),
    )
    assert stable_image.is_file()
    assert result["stable_trace"] == ()
    assert result["stable_sha256"] == clean_sha256
    assert _sha256(stable_image) == clean_sha256


