                        "_EXT4-JFO-CERT-SCOPE @ 0<>",
                        "_EXT4-JFO-CERT-VALID @ 0<>",
                        (
                            "_EXT4-JFO-CERT-KIND @ "
                            "_EXT4-JFO-CERT-JFI ="
                        ),
                        "_EXT4-JFO-CERT-RANGE-COUNT @ 1 =",
                        f"0 _EXT4-JFO-CERT-RANGE @ {data_block} =",
