def test_staged_public_cross_gdt_page_eof_passes_external_oracles(
    staged_public_cross_gdt_page_eof_growth_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    fixture = staged_public_cross_gdt_page_eof_growth_fixture
    image = fixture["image"]
    expected_file = fixture["expected_file"]
    inode_number = fixture["inode_number"]
    candidate = fixture["candidate"]
    data_block = fixture["data_block"]
    xattr_block = fixture["xattr_block"]
    ballast_inode_number = fixture["ballast_inode_number"]
    ballast_leaf_home = fixture["ballast_leaf_home"]
    ballast_i_blocks = fixture["ballast_i_blocks"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(candidate, int)
    assert isinstance(data_block, int)
    assert isinstance(xattr_block, int)
    assert isinstance(ballast_inode_number, int)
    assert isinstance(ballast_leaf_home, int)
    assert isinstance(ballast_i_blocks, int)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    for target in ("/fixture/payload.txt", "/fixture/hardlink.txt"):
        readback = subprocess.run(
            [str(debugfs), "-R", f"cat {target}", str(image)],
            env=env,
            capture_output=True,
            check=False,
        )
        assert readback.returncode == 0, readback.stdout + readback.stderr
        assert readback.stdout == expected_file

    for logical, physical in ((0, data_block), (1, candidate)):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/payload.txt {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == physical

    stat = subprocess.run(
        [str(debugfs), "-R", "stat /fixture/payload.txt", str(image)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert re.search(r"Links:\s+2\s+Blockcount:\s+6", stat.stdout)
    assert f"File ACL: {xattr_block}" in stat.stdout
    assert f"(0):{data_block}" in stat.stdout
    assert f"(1):{candidate}" in stat.stdout

    ballast_stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            f"stat <{ballast_inode_number}>",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert ballast_stat.returncode == 0, (
        ballast_stat.stdout + ballast_stat.stderr
    )
    assert "Size: 3072" in ballast_stat.stdout
    assert f"Blockcount: {ballast_i_blocks}" in ballast_stat.stdout
    assert f"(ETB0):{ballast_leaf_home}" in ballast_stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def test_staged_public_cross_group_eof_passes_external_oracles(
    staged_public_cross_group_eof_growth_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    fixture = staged_public_cross_group_eof_growth_fixture
    image = fixture["image"]
    expected_file = fixture["expected_file"]
    inode_number = fixture["inode_number"]
    candidate = fixture["candidate"]
    data_block = fixture["data_block"]
    xattr_block = fixture["xattr_block"]
    ballast_inode_number = fixture["ballast_inode_number"]
    ballast_start = fixture["ballast_start"]
    ballast_blocks = fixture["ballast_blocks"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(candidate, int)
    assert isinstance(data_block, int)
    assert isinstance(xattr_block, int)
    assert isinstance(ballast_inode_number, int)
    assert isinstance(ballast_start, int)
    assert isinstance(ballast_blocks, int)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    for target in ("/fixture/payload.txt", "/fixture/hardlink.txt"):
        readback = subprocess.run(
            [str(debugfs), "-R", f"cat {target}", str(image)],
            env=env,
            capture_output=True,
            check=False,
        )
        assert readback.returncode == 0, readback.stdout + readback.stderr
        assert readback.stdout == expected_file

    for logical, physical in ((0, data_block), (1, candidate)):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/payload.txt {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == physical

    stat = subprocess.run(
        [str(debugfs), "-R", "stat /fixture/payload.txt", str(image)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert re.search(r"Links:\s+2\s+Blockcount:\s+6", stat.stdout)
    assert f"File ACL: {xattr_block}" in stat.stdout
    assert f"(0):{data_block}" in stat.stdout
    assert f"(1):{candidate}" in stat.stdout

    ballast_stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            f"stat <{ballast_inode_number}>",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert ballast_stat.returncode == 0, (
        ballast_stat.stdout + ballast_stat.stderr
    )
    assert "Size: 3072" in ballast_stat.stdout
    assert f"Blockcount: {4 + ballast_blocks * 2}" in ballast_stat.stdout
    assert f"(3-{2 + ballast_blocks}[u]):{ballast_start}-" in ballast_stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def _staged_cross_group_fault_write_lines(
    *,
    prefix: str,
    marker: str,
    epoch_ms: int,
    block_size: int,
    candidate: int,
    candidate_group: int,
    bitmap_home: int,
    expected_actual: int,
    expected_size: int,
    expected_blocks: int,
    expected_phase: str,
    expected_home_writes: int,
) -> list[str]:
    """Build the shared public journey for one cross-group write fault."""
    replacement = _STAGED_ALIGNED_APPEND_REPLACEMENT.decode("ascii")
    return [
        f"VARIABLE {prefix}-CLOCK-CALLS",
        (
            f": {prefix}-NOW ( context -- epoch-ms ior ) "
            f"DROP 1 {prefix}-CLOCK-CALLS +! {epoch_ms} 0 ;"
        ),
        f"T-ARENA CONSTANT {prefix}-ARENA",
        (
            f"{prefix}-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
            f"CONSTANT {prefix}-MOUNT-IOR CONSTANT {prefix}-V"
        ),
        f"{prefix}-V _EXT4-CTX CONSTANT {prefix}-CTX",
        (
            f"' {prefix}-NOW 0 {prefix}-V EXT4-BIND-WRITE-CLOCK? "
            f"CONSTANT {prefix}-CLOCK-IOR"
        ),
        *_ext4_dedicated_writer_profile_forth(
            f"{prefix}-PROFILE", f"{prefix}-V", 4, 1, 0
        ),
        (
            'S" /fixture/hardlink.txt" '
            "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
            f"{prefix}-V VFS-OPEN? "
            f"CONSTANT {prefix}-OPEN-IOR CONSTANT {prefix}-FD"
        ),
        f"{prefix}-FD FD.INODE @ D.VNODE @ CONSTANT {prefix}-VN",
        f"{prefix}-FD FD.CUR-LO @ CONSTANT {prefix}-INITIAL-CURSOR",
        (
            f'S" {replacement}" {prefix}-FD VFS-WRITE? '
            f"CONSTANT {prefix}-WRITE-IOR CONSTANT {prefix}-ACTUAL"
        ),
        f"{prefix}-FD FD.CUR-LO @ CONSTANT {prefix}-CURSOR",
        f"{prefix}-V V.LAST-IOR @ CONSTANT {prefix}-LAST-IOR",
        f"{prefix}-CTX _EXT4-C.J.WRITER + @ CONSTANT {prefix}-WRITER",
        (
            f"{prefix}-CTX _EXT4-C.J.HOME-WRITES + @ "
            f"CONSTANT {prefix}-HOMES"
        ),
        f"{prefix}-FD VFS-CLOSE? CONSTANT {prefix}-CLOSE-IOR",
        (
            _forth_conjunction(
                [
                    f"{prefix}-MOUNT-IOR 0=",
                    f"{prefix}-CLOCK-IOR 0=",
                    f"{prefix}-PROFILE-SIZE-IOR 0=",
                    f"{prefix}-PROFILE-BIND-IOR 0=",
                    f"{prefix}-OPEN-IOR 0=",
                    f"{prefix}-INITIAL-CURSOR {block_size} =",
                    f"{prefix}-ACTUAL {expected_actual} =",
                    (
                        f"{prefix}-WRITE-IOR VFS-IOR-DOMAIN "
                        "VFS-IOR-D-VOLUME ="
                    ),
                    (
                        f"{prefix}-WRITE-IOR VFS-IOR-REASON "
                        "VFS-R-IO ="
                    ),
                    (
                        f"{prefix}-WRITE-IOR VFS-IOR-FLAGS "
                        "VFS-IOR-F-PARTIAL VFS-IOR-F-READONLY OR ="
                    ),
                    f"{prefix}-LAST-IOR {prefix}-WRITE-IOR =",
                    f"{prefix}-CURSOR {block_size + expected_actual} =",
                    f"{prefix}-CLOCK-CALLS @ 1 =",
                    f"{prefix}-VN VN.SIZE-LO @ {expected_size} =",
                    f"{prefix}-VN VN.SIZE-HI @ 0=",
                    f"{prefix}-VN VN.BLOCKS @ {expected_blocks} =",
                    f"{prefix}-WRITER {prefix}-PROFILE-BASE =",
                    (
                        f"{prefix}-WRITER _EXT4-JWR.STATE + @ "
                        "_EXT4-JWR-FAULTED ="
                    ),
                    (
                        f"{prefix}-WRITER _EXT4-JWR.PHASE + @ "
                        f"{expected_phase} ="
                    ),
                    f"{prefix}-HOMES {expected_home_writes} =",
                    f"{prefix}-CTX _EXT4-C.J.COMMITTED + @ 1 =",
                    f"{prefix}-WRITER _EXT4-JWR.META-ACTIVE + @ 4 =",
                    f"{prefix}-WRITER _EXT4-JWR.DATA-ACTIVE + @ 1 =",
                    f"{prefix}-WRITER _EXT4-JWR.REVOKE-ACTIVE + @ 0=",
                    f"{prefix}-CTX _EXT4-C.RECOVERY + @ 0<>",
                    f"{prefix}-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0<>",
                    f"{prefix}-V V.FLAGS @ VFS-F-RO AND 0<>",
                    f"{prefix}-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                    f"_XH-CANDIDATE @ {candidate} =",
                    f"_XH-CANDIDATE-GROUP @ {candidate_group} =",
                    f"_XH-BITMAP-HOME @ {bitmap_home} =",
                    "_XH-PUBLISHED @ 0<",
                    f"_EXT4-WR-ACTUAL @ {expected_actual} =",
                    f"_EXT4-MOW-ACTUAL @ {expected_actual} =",
                    f"{prefix}-CLOSE-IOR 0=",
                    (
                        "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                        "_EXT4-BYTES-ZERO?"
                    ),
                    "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                ]
            )
            + f' IF ." {marker}" THEN'
        ),
    ]


def test_staged_public_cross_group_allocation_refuses_actual_bitmap_alias(
    staged_cross_group_allocation_geometry: dict[str, object],
    tmp_path: Path,
) -> None:
    """The owner certificate covers the selected group's real bitmap home."""
    geometry = staged_cross_group_allocation_geometry
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    ballast_inode_offset = geometry["ballast_inode_offset"]
    ballast_inode_number = geometry["ballast_inode_number"]
    ballast_inode_home = geometry["ballast_inode_home"]
    ballast_blocks = geometry["ballast_blocks"]
    block_size = geometry["block_size"]
    candidate = geometry["candidate"]
    candidate_group = geometry["candidate_group"]
    bitmap_home = geometry["bitmap_home"]
    group0_bitmap_home = geometry["group0_bitmap_home"]
    group0_bitmap_home = geometry["group0_bitmap_home"]
    gdt_home = geometry["gdt_home"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(ballast_inode_offset, int)
    assert isinstance(ballast_inode_number, int)
    assert isinstance(ballast_inode_home, int)
    assert isinstance(ballast_blocks, int)
    assert isinstance(block_size, int)
    assert isinstance(candidate, int)
    assert isinstance(candidate_group, int)
    assert isinstance(bitmap_home, int)
    assert isinstance(group0_bitmap_home, int)
    assert isinstance(group0_bitmap_home, int)
    assert isinstance(gdt_home, int)

    patch_map = dict(input_patches)
    alias_inode = bytearray(patch_map[ballast_inode_offset])
    assert struct.unpack_from("<HHHH", alias_inode, 0x28) == (
        0xF30A,
        3,
        4,
        0,
    )
    alias_logical = 3 + ballast_blocks + 1
    struct.pack_into("<H", alias_inode, 0x2A, 4)
    struct.pack_into(
        "<IHHI",
        alias_inode,
        0x58,
        alias_logical,
        0x8001,
        0,
        bitmap_home,
    )
    struct.pack_into(
        "<I",
        alias_inode,
        0x1C,
        struct.unpack_from("<I", alias_inode, 0x1C)[0]
        + block_size // 512,
    )
    alias_inode[:] = _inode_with_checksum(
        superblock, ballast_inode_number, alias_inode
    )
    assert struct.unpack_from("<H", alias_inode, 0x2A)[0] == 4
    assert _extent_root_physical(
        alias_inode, alias_logical
    ) == bitmap_home
    patch_map[ballast_inode_offset] = bytes(alias_inode)
    alias_patches = tuple(patch_map.items())

    original_candidate = bytes((0xA5,)) * block_size
    original_target_home = _patched_ext4_home(
        path, alias_patches, inode_home, block_size=block_size
    )
    original_ballast_home = _patched_ext4_home(
        path, alias_patches, ballast_inode_home, block_size=block_size
    )
    original_bitmap = _patched_ext4_home(
        path, alias_patches, bitmap_home, block_size=block_size
    )
    original_group0_bitmap = _patched_ext4_home(
        path, alias_patches, group0_bitmap_home, block_size=block_size
    )
    original_gdt = _patched_ext4_home(
        path, alias_patches, gdt_home, block_size=block_size
    )
    media_path = tmp_path / "staged-public-cross-group-bitmap-alias.img"
    epoch_ms = 3_000_000_423_456
    output, trace, _ = run_recovery_forth(
        path,
        media_path,
        [
            "VARIABLE _CA-CLOCK-CALLS",
            (
                ": _CA-NOW ( context -- epoch-ms ior ) "
                "DROP 1 _CA-CLOCK-CALLS +! "
                f"{epoch_ms} 0 ;"
            ),
            "T-ARENA CONSTANT _CA-ARENA",
            (
                "_CA-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                "CONSTANT _CA-MOUNT-IOR CONSTANT _CA-V"
            ),
            "_CA-V _EXT4-CTX CONSTANT _CA-CTX",
            (
                "' _CA-NOW 0 _CA-V EXT4-BIND-WRITE-CLOCK? "
                "CONSTANT _CA-CLOCK-IOR"
            ),
            *_ext4_dedicated_writer_profile_forth(
                "_CA-PROFILE", "_CA-V", 4, 1, 0
            ),
            (
                'S" /fixture/hardlink.txt" '
                "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                "_CA-V VFS-OPEN? CONSTANT _CA-OPEN-IOR CONSTANT _CA-FD"
            ),
            "_CA-FD FD.CUR-LO @ CONSTANT _CA-INITIAL-CURSOR",
            (
                f'S" {_STAGED_ALIGNED_APPEND_REPLACEMENT.decode("ascii")}" '
                "_CA-FD VFS-WRITE-EXACT CONSTANT _CA-EXACT-IOR"
            ),
            "_CA-FD FD.CUR-LO @ CONSTANT _CA-CURSOR",
            "_CA-CTX _EXT4-C.J.WRITER + @ CONSTANT _CA-WRITER",
            "_CA-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _CA-HOMES",
            (
                _forth_conjunction(
                    [
                        "_CA-MOUNT-IOR 0=",
                        "_CA-CLOCK-IOR 0=",
                        "_CA-PROFILE-SIZE-IOR 0=",
                        "_CA-PROFILE-BIND-IOR 0=",
                        "_CA-OPEN-IOR 0=",
                        f"_CA-INITIAL-CURSOR {block_size} =",
                        (
                            "_CA-EXACT-IOR VFS-IOR-REASON "
                            "VFS-R-CORRUPT ="
                        ),
                        (
                            "_CA-EXACT-IOR VFS-IOR-DOMAIN "
                            "VFS-IOR-D-FORMAT ="
                        ),
                        (
                            "_CA-EXACT-IOR VFS-IOR-FLAGS "
                            "VFS-IOR-F-CORRUPT ="
                        ),
                        (
                            "_CA-EXACT-IOR VFS-IOR-DETAIL "
                            "EXT4-D-DATA-MAP ="
                        ),
                        "_CA-V V.LAST-IOR @ _CA-EXACT-IOR =",
                        f"_CA-CURSOR {block_size} =",
                        "_CA-CLOCK-CALLS @ 1 =",
                        "_CA-HOMES 0=",
                        "_CA-WRITER _CA-PROFILE-BASE =",
                        "_CA-WRITER _EXT4-JWR-IDLE-CLEAN?",
                        "_XH-PUBLISHED @ 0=",
                        f"_XH-CANDIDATE @ {candidate} =",
                        f"_XH-CANDIDATE-GROUP @ {candidate_group} =",
                        f"_XH-BITMAP-HOME @ {bitmap_home} =",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                    ]
                )
                + ' IF ." EXT4-CROSS-GROUP-BITMAP-ALIAS-REFUSED" THEN'
            ),
            "_CA-FD VFS-CLOSE? CONSTANT _CA-CLOSE-IOR",
            "0 _CA-V VFS-UNMOUNT CONSTANT _CA-UNMOUNT-IOR",
            (
                "_CA-CLOSE-IOR 0= _CA-UNMOUNT-IOR 0= AND "
                "_CA-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                'IF ." EXT4-CROSS-GROUP-BITMAP-ALIAS-UNMOUNT" THEN'
            ),
        ],
        patches=alias_patches
        + ((candidate * block_size, original_candidate),),
        capture_media=media_path,
    )
    _assert_emitted(output, "EXT4-CROSS-GROUP-BITMAP-ALIAS-REFUSED")
    _assert_emitted(output, "EXT4-CROSS-GROUP-BITMAP-ALIAS-UNMOUNT")
    assert trace == ()
    assert not _ext4_block_allocation_state(
        media_path, (candidate,)
    )[candidate]
    assert _read_ext4_home(
        media_path, candidate, block_size=block_size
    ) == original_candidate
    assert _read_ext4_home(
        media_path, inode_home, block_size=block_size
    ) == original_target_home
    assert _read_ext4_home(
        media_path, ballast_inode_home, block_size=block_size
    ) == original_ballast_home
    assert _read_ext4_home(
        media_path, bitmap_home, block_size=block_size
    ) == original_bitmap
    assert _read_ext4_home(
        media_path, group0_bitmap_home, block_size=block_size
    ) == original_group0_bitmap
    assert _read_ext4_home(
        media_path, gdt_home, block_size=block_size
    ) == original_gdt
    final_superblock, final_inode, _ = _ext4_inode_record(
        media_path, inode_number
    )
    assert final_superblock == superblock
    assert final_inode == inode


def test_staged_public_cross_group_bitmap_tear_replays_actual_group_homes(
    staged_cross_group_allocation_geometry: dict[str, object],
    staged_public_cross_group_eof_growth_fixture: dict[str, object],
    tmp_path: Path,
) -> None:
    """Replay a committed tear at the selected group's bitmap checkpoint."""
    geometry = staged_cross_group_allocation_geometry
    success = staged_public_cross_group_eof_growth_fixture
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    ballast_inode_home = geometry["ballast_inode_home"]
    block_size = geometry["block_size"]
    candidate = geometry["candidate"]
    candidate_group = geometry["candidate_group"]
    candidate_index = geometry["candidate_index"]
    bitmap_home = geometry["bitmap_home"]
    group0_bitmap_home = geometry["group0_bitmap_home"]
    gdt_home = geometry["gdt_home"]
    super_home = geometry["super_home"]
    data_block = geometry["data_block"]
    success_trace = success["trace"]
    success_image = success["image"]
    expected_file = success["expected_file"]
    epoch_ms = success["epoch_ms"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(ballast_inode_home, int)
    assert isinstance(block_size, int)
    assert isinstance(candidate, int)
    assert isinstance(candidate_group, int)
    assert isinstance(candidate_index, int)
    assert isinstance(bitmap_home, int)
    assert isinstance(group0_bitmap_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(super_home, int)
    assert isinstance(data_block, int)
    assert isinstance(success_trace, tuple)
    assert isinstance(success_image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(epoch_ms, int)

    original_inode_home = _patched_ext4_home(
        path, input_patches, inode_home, block_size=block_size
    )
    original_ballast_inode_home = _patched_ext4_home(
        path, input_patches, ballast_inode_home, block_size=block_size
    )
    original_bitmap = _patched_ext4_home(
        path, input_patches, bitmap_home, block_size=block_size
    )
    original_group0_bitmap = _patched_ext4_home(
        path, input_patches, group0_bitmap_home, block_size=block_size
    )
    original_gdt = _patched_ext4_home(
        path, input_patches, gdt_home, block_size=block_size
    )
    expected_candidate = _read_ext4_home(
        success_image, candidate, block_size=block_size
    )
    expected_bitmap = _read_ext4_home(
        success_image, bitmap_home, block_size=block_size
    )
    expected_gdt = _read_ext4_home(
        success_image, gdt_home, block_size=block_size
    )
    expected_super = _read_ext4_home(
        success_image, super_home, block_size=block_size
    )
    expected_inode_home = _read_ext4_home(
        success_image, inode_home, block_size=block_size
    )
    assert expected_candidate == _STAGED_ALIGNED_APPEND_REPLACEMENT + bytes(
        block_size - len(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    )
    candidate_byte = candidate_index // 8
    assert candidate_byte == 32
    assert expected_bitmap[: candidate_byte + 1] != (
        original_bitmap[: candidate_byte + 1]
    )
    assert expected_bitmap[candidate_byte + 1 :] == (
        original_bitmap[candidate_byte + 1 :]
    )
    expected_torn_bitmap = (
        expected_bitmap[: candidate_byte + 1]
        + original_bitmap[candidate_byte + 1 :]
    )
    assert expected_torn_bitmap == expected_bitmap

    bitmap_ordinals = _write_ordinals_for_ext4_home(
        success_trace, bitmap_home, block_size=block_size
    )
    assert bitmap_ordinals == (19,)
    bitmap_event_index = _trace_event_index_for_ordinal(
        success_trace, "write", bitmap_ordinals[0]
    )
    assert success_trace[bitmap_event_index] == (
        "write",
        bitmap_home * 2,
        2,
    )

    faulted = tmp_path / "staged-cross-group-w19-faulted.img"
    recovered = tmp_path / "staged-cross-group-w19-recovered.img"
    stable = tmp_path / "staged-cross-group-w19-stable.img"
    try:
        output, failed_trace, _ = run_recovery_forth(
            path,
            faulted,
            _staged_cross_group_fault_write_lines(
                prefix="_CGW19",
                marker="EXT4-CROSS-GROUP-W19-FAULT",
                epoch_ms=epoch_ms,
                block_size=block_size,
                candidate=candidate,
                candidate_group=candidate_group,
                bitmap_home=bitmap_home,
                expected_actual=len(_STAGED_ALIGNED_APPEND_REPLACEMENT),
                expected_size=len(expected_file),
                expected_blocks=6,
                expected_phase="_EXT4-JWP-CHECKPOINT-HOME",
                expected_home_writes=0,
            ),
            patches=input_patches
            + ((candidate * block_size, bytes((0xA5,)) * block_size),),
            write_faults_by_ordinal={
                bitmap_ordinals[0]: {
                    "stage": "media",
                    "sector_index": 0,
                    "byte_index": candidate_byte + 1,
                    "result": STORAGE_RESULT_MEDIA_FAILURE,
                    "command": STORAGE_CMD_WRITE,
                }
            },
            capture_media=faulted,
        )
        _assert_emitted(output, "EXT4-CROSS-GROUP-W19-FAULT")
        assert failed_trace == success_trace[: bitmap_event_index + 1]
        assert _read_ext4_home(
            faulted, candidate, block_size=block_size
        ) == expected_candidate
        assert _read_ext4_home(
            faulted, bitmap_home, block_size=block_size
        ) == expected_torn_bitmap
        assert _read_ext4_home(
            faulted, group0_bitmap_home, block_size=block_size
        ) == original_group0_bitmap
        assert _read_ext4_home(
            faulted, gdt_home, block_size=block_size
        ) == original_gdt
        assert _read_ext4_home(
            faulted, inode_home, block_size=block_size
        ) == original_inode_home
        assert _read_ext4_home(
            faulted, ballast_inode_home, block_size=block_size
        ) == original_ballast_inode_home
        faulted_superblock, faulted_inode, _ = _ext4_inode_record(
            faulted, inode_number
        )
        assert struct.unpack_from("<I", faulted_superblock, 0x0C)[0] == (
            struct.unpack_from("<I", superblock, 0x0C)[0]
        )
        assert faulted_inode == inode
        assert _ext4_block_allocation_state(
            faulted, (candidate,)
        )[candidate]

        _, recovery_trace, recovery_sha256 = (
            _staged_write_recovery_readback(
                faulted,
                recovered,
                expected_file=expected_file,
                expected_epoch_ms=epoch_ms,
                expected_home_writes=4,
                expected_replayed=True,
                expected_blocks=6,
                prefix="_CGW19-R",
                marker="EXT4-CROSS-GROUP-W19-RECOVERED",
            )
        )
        assert not _write_ordinals_for_ext4_home(
            recovery_trace, candidate, block_size=block_size
        )
        assert not _write_ordinals_for_ext4_home(
            recovery_trace, group0_bitmap_home, block_size=block_size
        )
        assert not _write_ordinals_for_ext4_home(
            recovery_trace, ballast_inode_home, block_size=block_size
        )
        for home in (bitmap_home, gdt_home, inode_home):
            assert len(
                _write_ordinals_for_ext4_home(
                    recovery_trace, home, block_size=block_size
                )
            ) == 1
        recovered_superblock, recovered_inode, _ = _ext4_inode_record(
            recovered, inode_number
        )
        assert recovered_superblock == expected_super
        assert _ext4_block_allocation_state(
            recovered, (candidate,)
        )[candidate]
        assert _read_ext4_home(
            recovered, candidate, block_size=block_size
        ) == expected_candidate
        assert _read_ext4_home(
            recovered, bitmap_home, block_size=block_size
        ) == expected_bitmap
        assert _read_ext4_home(
            recovered, group0_bitmap_home, block_size=block_size
        ) == original_group0_bitmap
        assert _read_ext4_home(
            recovered, gdt_home, block_size=block_size
        ) == expected_gdt
        assert _read_ext4_home(
            recovered, inode_home, block_size=block_size
        ) == expected_inode_home
        assert _read_ext4_home(
            recovered, ballast_inode_home, block_size=block_size
        ) == original_ballast_inode_home
        assert recovered_inode == expected_inode_home[
            geometry["inode_block_offset"] :
            geometry["inode_block_offset"] + len(inode)
        ]
        assert _extent_root_physical(recovered_inode, 0) == data_block
        assert _extent_root_physical(recovered_inode, 1) == candidate

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            recovered,
            stable,
            expected_file=expected_file,
            expected_epoch_ms=epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=6,
            prefix="_CGW19-S",
            marker="EXT4-CROSS-GROUP-W19-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == recovery_sha256
        assert _sha256(stable) == stable_sha256
    finally:
        faulted.unlink(missing_ok=True)
        recovered.unlink(missing_ok=True)
        stable.unlink(missing_ok=True)


def test_staged_public_cross_gdt_page_tear_replays_second_descriptor_page(
    staged_cross_gdt_page_allocation_geometry: dict[str, object],
    staged_public_cross_gdt_page_eof_growth_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
    tmp_path: Path,
) -> None:
    """Replay a committed tear in descriptor 16 on primary GDT block 3."""
    geometry = staged_cross_gdt_page_allocation_geometry
    success = staged_public_cross_gdt_page_eof_growth_fixture
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    inode_block_offset = geometry["inode_block_offset"]
    ballast_inode_home = geometry["ballast_inode_home"]
    ballast_leaf_home = geometry["ballast_leaf_home"]
    block_size = geometry["block_size"]
    candidate = geometry["candidate"]
    candidate_group = geometry["candidate_group"]
    bitmap_home = geometry["bitmap_home"]
    group0_bitmap_home = geometry["group0_bitmap_home"]
    local_gdt_home = geometry["local_gdt_home"]
    gdt_home = geometry["gdt_home"]
    super_home = geometry["super_home"]
    data_block = geometry["data_block"]
    success_trace = success["trace"]
    success_image = success["image"]
    expected_file = success["expected_file"]
    epoch_ms = success["epoch_ms"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(inode_block_offset, int)
    assert isinstance(ballast_inode_home, int)
    assert isinstance(ballast_leaf_home, int)
    assert isinstance(block_size, int)
    assert isinstance(candidate, int)
    assert isinstance(candidate_group, int)
    assert isinstance(bitmap_home, int)
    assert isinstance(group0_bitmap_home, int)
    assert isinstance(local_gdt_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(super_home, int)
    assert isinstance(data_block, int)
    assert isinstance(success_trace, tuple)
    assert isinstance(success_image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(epoch_ms, int)
    assert candidate_group == 16
    assert local_gdt_home == 2
    assert gdt_home == 3

    original_inode_home = _patched_ext4_home(
        path, input_patches, inode_home, block_size=block_size
    )
    original_ballast_inode_home = _patched_ext4_home(
        path, input_patches, ballast_inode_home, block_size=block_size
    )
    original_ballast_leaf = _patched_ext4_home(
        path, input_patches, ballast_leaf_home, block_size=block_size
    )
    original_bitmap = _patched_ext4_home(
        path, input_patches, bitmap_home, block_size=block_size
    )
    original_local_gdt = _patched_ext4_home(
        path, input_patches, local_gdt_home, block_size=block_size
    )
    original_gdt = _patched_ext4_home(
        path, input_patches, gdt_home, block_size=block_size
    )
    expected_candidate = _read_ext4_home(
        success_image, candidate, block_size=block_size
    )
    expected_bitmap = _read_ext4_home(
        success_image, bitmap_home, block_size=block_size
    )
    expected_gdt = _read_ext4_home(
        success_image, gdt_home, block_size=block_size
    )
    expected_super = _read_ext4_home(
        success_image, super_home, block_size=block_size
    )
    expected_inode_home = _read_ext4_home(
        success_image, inode_home, block_size=block_size
    )
    assert expected_candidate == _STAGED_ALIGNED_APPEND_REPLACEMENT + bytes(
        block_size - len(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    )
    assert expected_bitmap != original_bitmap
    assert expected_gdt != original_gdt
    assert _read_ext4_home(
        success_image, local_gdt_home, block_size=block_size
    ) == original_local_gdt

    gdt_ordinals = _write_ordinals_for_ext4_home(
        success_trace, gdt_home, block_size=block_size
    )
    assert gdt_ordinals == (20,)
    gdt_event_index = _trace_event_index_for_ordinal(
        success_trace, "write", gdt_ordinals[0]
    )
    assert success_trace[gdt_event_index] == ("write", gdt_home * 2, 2)
    tear_byte_index = 13
    expected_torn_gdt = (
        expected_gdt[:tear_byte_index] + original_gdt[tear_byte_index:]
    )
    assert expected_torn_gdt not in {original_gdt, expected_gdt}
    assert expected_torn_gdt[0x0C] == expected_gdt[0x0C]
    assert expected_torn_gdt[0x0D:] == original_gdt[0x0D:]

    faulted = tmp_path / "staged-cross-gdt-page-w20-faulted.img"
    recovered = tmp_path / "staged-cross-gdt-page-w20-recovered.img"
    stable = tmp_path / "staged-cross-gdt-page-w20-stable.img"
    try:
        output, failed_trace, _ = run_recovery_forth(
            path,
            faulted,
            _staged_cross_group_fault_write_lines(
                prefix="_XGW20",
                marker="EXT4-CROSS-GDT-W20-FAULT",
                epoch_ms=epoch_ms,
                block_size=block_size,
                candidate=candidate,
                candidate_group=candidate_group,
                bitmap_home=bitmap_home,
                expected_actual=len(_STAGED_ALIGNED_APPEND_REPLACEMENT),
                expected_size=len(expected_file),
                expected_blocks=6,
                expected_phase="_EXT4-JWP-CHECKPOINT-HOME",
                expected_home_writes=1,
            ),
            patches=input_patches
            + ((candidate * block_size, bytes((0xA5,)) * block_size),),
            write_faults_by_ordinal={
                gdt_ordinals[0]: {
                    "stage": "media",
                    "sector_index": 0,
                    "byte_index": tear_byte_index,
                    "result": STORAGE_RESULT_MEDIA_FAILURE,
                    "command": STORAGE_CMD_WRITE,
                }
            },
            capture_media=faulted,
        )
        _assert_emitted(output, "EXT4-CROSS-GDT-W20-FAULT")
        assert failed_trace == success_trace[: gdt_event_index + 1]
        assert _read_ext4_home(
            faulted, candidate, block_size=block_size
        ) == expected_candidate
        assert _read_ext4_home(
            faulted, bitmap_home, block_size=block_size
        ) == expected_bitmap
        assert _read_ext4_home(
            faulted, local_gdt_home, block_size=block_size
        ) == original_local_gdt
        assert _read_ext4_home(
            faulted, gdt_home, block_size=block_size
        ) == expected_torn_gdt
        assert _read_ext4_home(
            faulted, inode_home, block_size=block_size
        ) == original_inode_home
        assert _read_ext4_home(
            faulted, ballast_inode_home, block_size=block_size
        ) == original_ballast_inode_home
        assert _read_ext4_home(
            faulted, ballast_leaf_home, block_size=block_size
        ) == original_ballast_leaf
        faulted_superblock, faulted_inode, _ = _ext4_inode_record(
            faulted, inode_number
        )
        assert struct.unpack_from("<I", faulted_superblock, 0x0C)[0] == (
            struct.unpack_from("<I", superblock, 0x0C)[0]
        )
        assert faulted_inode == inode
        assert _ext4_block_allocation_state(
            faulted, (candidate,)
        )[candidate]

        _, recovery_trace, recovery_sha256 = (
            _staged_write_recovery_readback(
                faulted,
                recovered,
                expected_file=expected_file,
                expected_epoch_ms=epoch_ms,
                expected_home_writes=4,
                expected_replayed=True,
                expected_blocks=6,
                prefix="_XGW20-R",
                marker="EXT4-CROSS-GDT-W20-RECOVERED",
            )
        )
        for untouched_home in (
            candidate,
            group0_bitmap_home,
            local_gdt_home,
            ballast_inode_home,
            ballast_leaf_home,
        ):
            assert not _write_ordinals_for_ext4_home(
                recovery_trace, untouched_home, block_size=block_size
            )
        assert _write_ordinals_for_ext4_home(
            recovery_trace,
            bitmap_home,
            block_size=block_size,
        ) == (1,)
        assert _write_ordinals_for_ext4_home(
            recovery_trace,
            gdt_home,
            block_size=block_size,
        ) == (2,)
        assert _write_ordinals_for_ext4_home(
            recovery_trace,
            super_home,
            block_size=block_size,
        ) == (3, 8)
        assert _write_ordinals_for_ext4_home(
            recovery_trace,
            inode_home,
            block_size=block_size,
        ) == (4,)
        recovered_superblock, recovered_inode, _ = _ext4_inode_record(
            recovered, inode_number
        )
        assert recovered_superblock == expected_super
        assert recovered_inode == expected_inode_home[
            inode_block_offset : inode_block_offset + len(inode)
        ]
        assert _extent_root_physical(recovered_inode, 0) == data_block
        assert _extent_root_physical(recovered_inode, 1) == candidate
        assert _ext4_block_allocation_state(
            recovered, (candidate,)
        )[candidate]
        for home, expected in (
            (candidate, expected_candidate),
            (bitmap_home, expected_bitmap),
            (local_gdt_home, original_local_gdt),
            (gdt_home, expected_gdt),
            (inode_home, expected_inode_home),
            (ballast_inode_home, original_ballast_inode_home),
            (ballast_leaf_home, original_ballast_leaf),
        ):
            assert _read_ext4_home(
                recovered, home, block_size=block_size
            ) == expected

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            recovered,
            stable,
            expected_file=expected_file,
            expected_epoch_ms=epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=6,
            prefix="_XGW20-S",
            marker="EXT4-CROSS-GDT-W20-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == recovery_sha256
        assert _sha256(stable) == stable_sha256
        _assert_e2fsck_clean(stable, jbd2_toolchain)
    finally:
        faulted.unlink(missing_ok=True)
        recovered.unlink(missing_ok=True)
        stable.unlink(missing_ok=True)


@pytest.fixture(scope="session")
def staged_public_multi_allocated_eof_fixture(
    writer_activation_fixture: dict[str, object],
    tmp_path_factory: pytest.TempPathFactory,
) -> dict[str, object]:
    """Grow aligned EOF through two independently committed allocations."""
    path = writer_activation_fixture["image"]
    source_patches = writer_activation_fixture["source_patches"]
    activation_trace = writer_activation_fixture["success_trace"]
    assert isinstance(path, Path)
    assert isinstance(source_patches, tuple)
    assert isinstance(activation_trace, tuple)

    inode_number = 14
    candidates = (1351, 1352)
    bitmap_home = 259
    gdt_home = 2
    superblock, inode, inode_offset = _ext4_inode_record(path, inode_number)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_home = inode_offset // block_size
    data_block = _extent_root_physical(inode, 0)
    xattr_block = struct.unpack_from("<I", inode, 0x68)[0]
    old_blocks = struct.unpack_from("<I", inode, 0x1C)[0]
    free_blocks_before = struct.unpack_from("<I", superblock, 0x0C)[0]
    assert block_size == 1024
    assert inode_home == 278
    assert data_block == 1346
    assert xattr_block == 1349
    assert old_blocks == 4
    assert not any(_ext4_block_allocation_state(path, candidates).values())

    patched_inode = bytearray(inode)
    struct.pack_into("<I", patched_inode, 0x04, block_size)
    struct.pack_into("<I", patched_inode, 0x6C, 0)
    patched_inode[:] = _inode_with_checksum(
        superblock, inode_number, patched_inode
    )
    input_patches = source_patches + ((inode_offset, bytes(patched_inode)),)
    original_data = _patched_ext4_home(
        path, input_patches, data_block, block_size=block_size
    )

    first_byte = 0x51
    first_append = bytes((first_byte,)) * block_size
    second_append = _STAGED_ALIGNED_APPEND_REPLACEMENT
    replacement = first_append + second_append
    expected_second_candidate = second_append + bytes(
        block_size - len(second_append)
    )
    expected_file = original_data + replacement
    expected_file_crc = _crc32c_raw(expected_file)
    new_size = len(expected_file)
    epoch_ms = 3_000_000_223_456
    published_epoch_ms = epoch_ms + 2
    seconds, milliseconds = divmod(published_epoch_ms, 1000)
    nanoseconds = milliseconds * 1_000_000

    directory = tmp_path_factory.mktemp("ext4-public-multi-allocated-eof")
    media_path = directory / "staged-public-multi-allocated-eof.img"
    stable_path = directory / "staged-public-multi-allocated-eof-stable.img"
    try:
        output, trace, media_sha256 = run_recovery_forth(
            path,
            media_path,
            [
                f"CREATE _MG-SOURCE {len(replacement)} ALLOT",
                f"_MG-SOURCE {block_size} {first_byte} FILL",
                (
                    f'S" {second_append.decode("ascii")}" '
                    f"_MG-SOURCE {block_size} + SWAP MOVE"
                ),
                f"CREATE _MG-READ {new_size} ALLOT",
                "CREATE _MG-STAT VFS-STATFS-SIZE ALLOT",
                f"CREATE _MG-CLOCK {epoch_ms} , 0 , 0 ,",
                (
                    ": _MG-NOW ( clock -- epoch-ms ior ) "
                    "DUP 2 CELLS + DUP @ 1+ SWAP ! "
                    "DUP @ SWAP 2 CELLS + @ + 0 ;"
                ),
                "T-ARENA CONSTANT _MG-ARENA",
                (
                    "_MG-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _MG-MOUNT-IOR CONSTANT _MG-V"
                ),
                "_MG-V _EXT4-CTX CONSTANT _MG-CTX",
                (
                    "' _MG-NOW _MG-CLOCK _MG-V "
                    "EXT4-BIND-WRITE-CLOCK? CONSTANT _MG-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_MG-PROFILE", "_MG-V", 4, 1, 0
                ),
                (
                    'S" /fixture/payload.txt" _MG-V VFS-RESOLVE? '
                    "CONSTANT _MG-P-IOR CONSTANT _MG-P"
                ),
                (
                    'S" /fixture/hardlink.txt" _MG-V VFS-RESOLVE? '
                    "CONSTANT _MG-H-IOR CONSTANT _MG-H"
                ),
                (
                    'S" /fixture/hardlink.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                    "_MG-V VFS-OPEN? CONSTANT _MG-OPEN-IOR CONSTANT _MG-FD"
                ),
                "_MG-FD FD.INODE @ D.VNODE @ CONSTANT _MG-VN",
                "_MG-FD FD.CUR-LO @ CONSTANT _MG-INITIAL-CURSOR",
                "_MG-VN VN.BLOCKS @ CONSTANT _MG-OLD-BLOCKS",
                (
                    "_MG-STAT VFS-STATFS-SIZE _MG-V VFS-STATFS "
                    "CONSTANT _MG-STAT-BEFORE-IOR"
                ),
                "_MG-STAT VSF.BFREE @ CONSTANT _MG-FREE-BEFORE",
                (
                    f"_MG-SOURCE {len(replacement)} _MG-FD "
                    "VFS-WRITE-EXACT CONSTANT _MG-EXACT-IOR"
                ),
                "_MG-FD FD.CUR-LO @ CONSTANT _MG-CURSOR",
                "_MG-CTX _EXT4-C.J.WRITER + @ CONSTANT _MG-WRITER",
                "_MG-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _MG-HOMES",
                (
                    "_MG-STAT VFS-STATFS-SIZE _MG-V VFS-STATFS "
                    "CONSTANT _MG-STAT-AFTER-IOR"
                ),
                "_MG-STAT VSF.BFREE @ CONSTANT _MG-FREE-AFTER",
                "0 _MG-FD VFS-SEEK? CONSTANT _MG-READ-SEEK-IOR",
                (
                    f"_MG-READ {new_size} _MG-FD VFS-READ? "
                    "CONSTANT _MG-READ-IOR CONSTANT _MG-READ-ACTUAL"
                ),
                "0xFFFFFFFF _EXT4-CRC-START",
                (
                    f"_MG-READ {new_size} _EXT4-CRC-ADD "
                    "CONSTANT _MG-CRC-IOR"
                ),
                "_EXT4-CRC@ CONSTANT _MG-CRC",
                (
                    _forth_conjunction(
                        [
                            "_MG-MOUNT-IOR 0=",
                            "_MG-CLOCK-IOR 0=",
                            "_MG-PROFILE-SIZE-IOR 0=",
                            "_MG-PROFILE-BIND-IOR 0=",
                            "_MG-PROFILE-USED _MG-PROFILE-SIZE =",
                            "_MG-P-IOR 0=",
                            "_MG-H-IOR 0=",
                            "_MG-P D.VNODE @ _MG-H D.VNODE @ =",
                            "_MG-OPEN-IOR 0=",
                            f"_MG-INITIAL-CURSOR {block_size} =",
                            "_MG-EXACT-IOR 0=",
                            "_MG-V V.LAST-IOR @ 0=",
                            f"_MG-CURSOR {new_size} =",
                            "_MG-CLOCK 2 CELLS + @ 2 =",
                            f"_MG-VN VN.SIZE-LO @ {new_size} =",
                            "_MG-VN VN.SIZE-HI @ 0=",
                            "_MG-OLD-BLOCKS 4 =",
                            "_MG-VN VN.BLOCKS @ 8 =",
                            f"_MG-VN VN.MTIME @ {seconds} =",
                            f"_MG-VN VN.MTIME-NS @ {nanoseconds} =",
                            f"_MG-VN VN.CTIME @ {seconds} =",
                            f"_MG-VN VN.CTIME-NS @ {nanoseconds} =",
                            "_MG-STAT-BEFORE-IOR 0=",
                            "_MG-STAT-AFTER-IOR 0=",
                            "_MG-FREE-AFTER _MG-FREE-BEFORE 2 - =",
                            "_MG-WRITER _MG-PROFILE-BASE =",
                            "_MG-WRITER _EXT4-JWR-IDLE-CLEAN?",
                            "_MG-HOMES 4 =",
                            (
                                "_EXT4-WR-KIND @ "
                                "_EXT4-WRK-ALIGNED-APPEND ="
                            ),
                            f"_EXT4-WR-COUNT @ {len(second_append)} =",
                            f"_EXT4-WR-OFFSET @ {2 * block_size} =",
                            f"_EXT4-WR-REQUEST-END @ {new_size} =",
                            f"_EXT4-WR-CHUNK @ {len(second_append)} =",
                            f"_EXT4-WR-ACTUAL @ {len(second_append)} =",
                            f"_EXT4-MOW-ACTUAL @ {len(second_append)} =",
                            f"_XH-CANDIDATE @ {candidates[1]} =",
                            "_XH-EDIT @ _XH-EDIT-MERGE-LEFT =",
                            "_XH-ENTRIES @ 2 =",
                            "_MG-READ-SEEK-IOR 0=",
                            "_MG-READ-IOR 0=",
                            f"_MG-READ-ACTUAL {new_size} =",
                            "_MG-CRC-IOR 0=",
                            f"_MG-CRC {expected_file_crc} =",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                        ]
                    )
                    + ' IF ." EXT4-PUBLIC-MULTI-ALLOCATED-EOF" THEN'
                ),
                "_MG-FD VFS-CLOSE? CONSTANT _MG-CLOSE-IOR",
                "0 _MG-V VFS-UNMOUNT CONSTANT _MG-UNMOUNT-IOR",
                (
                    "_MG-CLOSE-IOR 0= _MG-UNMOUNT-IOR 0= AND "
                    "_MG-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                    "_MG-PROFILE-ARENA ARENA-USED 0= AND "
                    "_MG-PROFILE-ARENA A.PTR @ _MG-PROFILE-BASE = AND "
                    'IF ." EXT4-PUBLIC-MULTI-ALLOCATED-EOF-UNMOUNT" THEN'
                ),
            ],
            patches=input_patches
            + tuple(
                (
                    candidate * block_size,
                    bytes((0xA5 if index == 0 else 0x5A,)) * block_size,
                )
                for index, candidate in enumerate(candidates)
            ),
            capture_media=media_path,
            max_steps=1_500_000_000,
        )
        _assert_emitted(output, "EXT4-PUBLIC-MULTI-ALLOCATED-EOF")
        _assert_emitted(output, "EXT4-PUBLIC-MULTI-ALLOCATED-EOF-UNMOUNT")
        assert trace[: len(activation_trace)] == activation_trace
        first_candidate_event = ("write", candidates[0] * 2, 2)
        second_candidate_event = ("write", candidates[1] * 2, 2)
        bitmap_event = ("write", bitmap_home * 2, 2)
        gdt_event = ("write", gdt_home * 2, 2)
        inode_event = ("write", inode_home * 2, 2)
        assert tuple(
            event
            for event in trace
            if event
            in {
                first_candidate_event,
                second_candidate_event,
                bitmap_event,
                gdt_event,
                inode_event,
            }
        ) == (
            first_candidate_event,
            bitmap_event,
            gdt_event,
            inode_event,
            second_candidate_event,
            bitmap_event,
            gdt_event,
            inode_event,
        )
        assert trace.count(("write", data_block * 2, 2)) == 0
        assert trace.count(("write", xattr_block * 2, 2)) == 0
        assert all(
            _ext4_block_allocation_state(media_path, candidates).values()
        )

        final_superblock, final_inode, _ = _ext4_inode_record(
            media_path, inode_number
        )
        assert struct.unpack_from("<I", final_superblock, 0x0C)[0] == (
            free_blocks_before - 2
        )
        assert struct.unpack_from("<I", final_inode, 0x04)[0] == new_size
        assert struct.unpack_from("<I", final_inode, 0x6C)[0] == 0
        assert struct.unpack_from("<I", final_inode, 0x1C)[0] == 8
        assert struct.unpack_from("<HHHH", final_inode, 0x28) == (
            0xF30A,
            2,
            4,
            0,
        )
        assert struct.unpack_from("<IHHI", final_inode, 0x34) == (
            0,
            1,
            0,
            data_block,
        )
        assert struct.unpack_from("<IHHI", final_inode, 0x40) == (
            1,
            2,
            0,
            candidates[0],
        )
        assert _extent_root_physical(final_inode, 1) == candidates[0]
        assert _extent_root_physical(final_inode, 2) == candidates[1]
        assert _read_ext4_home(
            media_path, candidates[0], block_size=block_size
        ) == first_append
        assert _read_ext4_home(
            media_path, candidates[1], block_size=block_size
        ) == expected_second_candidate

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            media_path,
            stable_path,
            expected_file=expected_file,
            expected_epoch_ms=published_epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=8,
            prefix="_MG-S",
            marker="EXT4-PUBLIC-MULTI-ALLOCATED-EOF-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == media_sha256
        return {
            "image": stable_path,
            "expected_file": expected_file,
            "inode_number": inode_number,
            "data_block": data_block,
            "candidates": candidates,
            "xattr_block": xattr_block,
            "trace": trace,
        }
    finally:
        media_path.unlink(missing_ok=True)


def test_staged_public_exact_growth_allocates_additional_eof_blocks(
    staged_public_multi_allocated_eof_fixture: dict[str, object],
) -> None:
    image = staged_public_multi_allocated_eof_fixture["image"]
    expected_file = staged_public_multi_allocated_eof_fixture["expected_file"]
    candidates = staged_public_multi_allocated_eof_fixture["candidates"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(candidates, tuple)
    assert image.is_file()
    assert len(expected_file) == 2048 + len(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    assert candidates == (1351, 1352)


def test_staged_public_multi_allocated_eof_passes_external_oracles(
    staged_public_multi_allocated_eof_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    image = staged_public_multi_allocated_eof_fixture["image"]
    expected_file = staged_public_multi_allocated_eof_fixture["expected_file"]
    inode_number = staged_public_multi_allocated_eof_fixture["inode_number"]
    data_block = staged_public_multi_allocated_eof_fixture["data_block"]
    candidates = staged_public_multi_allocated_eof_fixture["candidates"]
    xattr_block = staged_public_multi_allocated_eof_fixture["xattr_block"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(data_block, int)
    assert isinstance(candidates, tuple)
    assert isinstance(xattr_block, int)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    for target in ("/fixture/payload.txt", "/fixture/hardlink.txt"):
        readback = subprocess.run(
            [str(debugfs), "-R", f"cat {target}", str(image)],
            env=env,
            capture_output=True,
            check=False,
        )
        assert readback.returncode == 0, readback.stdout + readback.stderr
        assert readback.stdout == expected_file

    for logical, physical in (
        (0, data_block),
        (1, candidates[0]),
        (2, candidates[1]),
    ):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/payload.txt {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == physical

    stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            "stat /fixture/payload.txt",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert "Flags: 0x80000" in stat.stdout
    assert re.search(r"Links:\s+2\s+Blockcount:\s+8", stat.stdout)
    assert f"File ACL: {xattr_block}" in stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def test_staged_public_multi_allocated_eof_preserves_prefix_on_profile_capacity_refusal(
    writer_activation_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
    tmp_path: Path,
) -> None:
    """A five-home second leg preserves the first block under profile four."""
    path = writer_activation_fixture["image"]
    source_patches = writer_activation_fixture["source_patches"]
    activation_trace = writer_activation_fixture["success_trace"]
    assert isinstance(path, Path)
    assert isinstance(source_patches, tuple)
    assert isinstance(activation_trace, tuple)

    inode_number = 14
    first_candidate = 1351
    second_candidate = 1354
    bitmap_home = 259
    gdt_home = 2
    superblock, inode, inode_offset = _ext4_inode_record(path, inode_number)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_home = inode_offset // block_size
    data_block = _extent_root_physical(inode, 0)
    xattr_block = struct.unpack_from("<I", inode, 0x68)[0]
    assert block_size == 1024
    assert inode_home == 278
    assert data_block == 1346
    assert xattr_block == 1349

    allocated_patches, physical_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol="modern",
        extent_specs=((0, 2, False),),
        inode_number=inode_number,
        physical_starts=(1352,),
        seed_payloads=True,
        base_patches=((1024, superblock), (inode_offset, inode)),
    )
    assert physical_ranges == ((1352, 2),)
    patch_map = dict(allocated_patches)
    old_size = 5 * block_size
    committed_size = 6 * block_size
    requested_size = 7 * block_size
    old_blocks = 8
    committed_blocks = 10
    full_inode = bytearray(inode)
    full_inode[0x34:0x64] = bytes(4 * 12)
    struct.pack_into("<I", full_inode, 0x04, old_size)
    struct.pack_into("<I", full_inode, 0x6C, 0)
    struct.pack_into("<I", full_inode, 0x1C, old_blocks)
    struct.pack_into("<H", full_inode, 0x74, 0)
    struct.pack_into("<H", full_inode, 0x2A, 3)
    entries = (
        (0, 1, data_block),
        (2, 1, 1352),
        (4, 1, 1353),
    )
    for index, (logical, length, physical) in enumerate(entries):
        struct.pack_into(
            "<IHHI",
            full_inode,
            0x34 + index * 12,
            logical,
            length,
            physical >> 32,
            physical & 0xFFFF_FFFF,
        )
    full_inode[:] = _inode_with_checksum(
        patch_map[1024], inode_number, full_inode
    )
    patch_map[inode_offset] = bytes(full_inode)
    patch_map[second_candidate * block_size] = bytes((0x5A,)) * block_size
    input_patches = source_patches + tuple(patch_map.items())

    allocation_state = _ext4_block_allocation_state(
        path, (first_candidate, second_candidate)
    )
    assert not allocation_state[first_candidate]
    assert not allocation_state[second_candidate]
    original_data = _patched_ext4_home(
        path, input_patches, data_block, block_size=block_size
    )
    second_extent_data = _patched_ext4_home(
        path, input_patches, 1352, block_size=block_size
    )
    fourth_extent_data = _patched_ext4_home(
        path, input_patches, 1353, block_size=block_size
    )
    original_second_candidate = _patched_ext4_home(
        path, input_patches, second_candidate, block_size=block_size
    )
    first_append = bytes((0x61,)) * block_size
    expected_file = (
        original_data
        + bytes(block_size)
        + second_extent_data
        + bytes(block_size)
        + fourth_extent_data
        + first_append
    )
    assert len(expected_file) == committed_size
    free_blocks_before = struct.unpack_from("<I", patch_map[1024], 0x0C)[0]
    epoch_ms = 3_000_000_323_456
    committed_epoch_ms = epoch_ms + 1
    committed_seconds, committed_milliseconds = divmod(
        committed_epoch_ms, 1000
    )
    committed_nanoseconds = committed_milliseconds * 1_000_000

    backing = tmp_path / "staged-multi-allocated-eof-profile-capacity.img"
    stable = tmp_path / "staged-multi-allocated-eof-profile-capacity-stable.img"
    try:
        output, trace, media_sha256 = run_recovery_forth(
            path,
            backing,
            [
                f"CREATE _MR-SOURCE {2 * block_size} ALLOT",
                f"_MR-SOURCE {block_size} 0x61 FILL",
                f"_MR-SOURCE {block_size} + {block_size} 0x62 FILL",
                "CREATE _MR-STAT VFS-STATFS-SIZE ALLOT",
                f"CREATE _MR-CLOCK {epoch_ms} , 0 , 0 ,",
                (
                    ": _MR-NOW ( clock -- epoch-ms ior ) "
                    "DUP 2 CELLS + DUP @ 1+ SWAP ! "
                    "DUP @ SWAP 2 CELLS + @ + 0 ;"
                ),
                "T-ARENA CONSTANT _MR-ARENA",
                (
                    "_MR-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _MR-MOUNT-IOR CONSTANT _MR-V"
                ),
                "_MR-V _EXT4-CTX CONSTANT _MR-CTX",
                (
                    "' _MR-NOW _MR-CLOCK _MR-V "
                    "EXT4-BIND-WRITE-CLOCK? CONSTANT _MR-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_MR-PROFILE", "_MR-V", 4, 1, 0
                ),
                (
                    'S" /fixture/hardlink.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                    "_MR-V VFS-OPEN? CONSTANT _MR-OPEN-IOR CONSTANT _MR-FD"
                ),
                "_MR-FD FD.INODE @ D.VNODE @ CONSTANT _MR-VN",
                "_MR-FD FD.CUR-LO @ CONSTANT _MR-INITIAL-CURSOR",
                "_MR-VN VN.ATIME @ CONSTANT _MR-OLD-ATIME",
                "_MR-VN VN.ATIME-NS @ CONSTANT _MR-OLD-ATIME-NS",
                "_MR-VN VN.GEN @ CONSTANT _MR-OLD-GEN",
                "_MR-VN VN.NLINK @ CONSTANT _MR-OLD-NLINK",
                (
                    "_MR-STAT VFS-STATFS-SIZE _MR-V VFS-STATFS "
                    "CONSTANT _MR-STAT-BEFORE-IOR"
                ),
                "_MR-STAT VSF.BFREE @ CONSTANT _MR-FREE-BEFORE",
                (
                    f"_MR-SOURCE {2 * block_size} _MR-FD "
                    "VFS-WRITE-EXACT CONSTANT _MR-EXACT-IOR"
                ),
                "_MR-V V.LAST-IOR @ CONSTANT _MR-LAST-IOR",
                "_MR-FD FD.CUR-LO @ CONSTANT _MR-CURSOR",
                "_MR-CTX _EXT4-C.J.WRITER + @ CONSTANT _MR-WRITER",
                "_MR-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _MR-HOMES",
                (
                    "_MR-STAT VFS-STATFS-SIZE _MR-V VFS-STATFS "
                    "CONSTANT _MR-STAT-AFTER-IOR"
                ),
                "_MR-STAT VSF.BFREE @ CONSTANT _MR-FREE-AFTER",
                (
                    _forth_conjunction(
                        [
                            "_MR-MOUNT-IOR 0=",
                            "_MR-CLOCK-IOR 0=",
                            "_MR-PROFILE-SIZE-IOR 0=",
                            "_MR-PROFILE-BIND-IOR 0=",
                            "_MR-OPEN-IOR 0=",
                            f"_MR-INITIAL-CURSOR {old_size} =",
                            "_MR-EXACT-IOR VFS-E-NOSPC =",
                            "_MR-EXACT-IOR VFS-IOR-FLAGS 0=",
                            "_MR-LAST-IOR _MR-EXACT-IOR =",
                            f"_MR-CURSOR {committed_size} =",
                            "_MR-CLOCK 2 CELLS + @ 2 =",
                            f"_MR-VN VN.SIZE-LO @ {committed_size} =",
                            "_MR-VN VN.SIZE-HI @ 0=",
                            f"_MR-VN VN.BLOCKS @ {committed_blocks} =",
                            "_MR-VN VN.GEN @ _MR-OLD-GEN =",
                            "_MR-VN VN.NLINK @ _MR-OLD-NLINK =",
                            f"_MR-VN VN.MTIME @ {committed_seconds} =",
                            (
                                f"_MR-VN VN.MTIME-NS @ "
                                f"{committed_nanoseconds} ="
                            ),
                            f"_MR-VN VN.CTIME @ {committed_seconds} =",
                            (
                                f"_MR-VN VN.CTIME-NS @ "
                                f"{committed_nanoseconds} ="
                            ),
                            "_MR-VN VN.ATIME @ _MR-OLD-ATIME =",
                            "_MR-VN VN.ATIME-NS @ _MR-OLD-ATIME-NS =",
                            "_MR-STAT-BEFORE-IOR 0=",
                            "_MR-STAT-AFTER-IOR 0=",
                            "_MR-FREE-AFTER _MR-FREE-BEFORE 1- =",
                            "_MR-WRITER _MR-PROFILE-BASE =",
                            "_MR-WRITER _EXT4-JWR-IDLE-CLEAN?",
                            "_MR-WRITER _EXT4-JWR.FAULT + @ 0=",
                            "_MR-HOMES 4 =",
                            f"_EXT4-WR-COUNT @ {block_size} =",
                            f"_EXT4-WR-OFFSET @ {committed_size} =",
                            f"_EXT4-WR-REQUEST-END @ {requested_size} =",
                            f"_EXT4-WR-CHUNK @ {block_size} =",
                            "_EXT4-WR-ACTUAL @ 0=",
                            "_EXT4-MOW-ACTUAL @ 0=",
                            "_EXT4-WR-NEW-BLOCKS @ 10 =",
                            f"_XH-SIZE @ {committed_size} =",
                            "_XH-LOGICAL @ 6 =",
                            f"_XH-CANDIDATE @ {second_candidate} =",
                            "_XH-LEAF-CANDIDATE @ 1355 =",
                            "_XH-ROOT-GROW @ 0<",
                            "_XH-META-CREDIT @ 5 =",
                            "_EXT4-MOW-CREDIT @ -5 =",
                            "_XH-ENTRIES @ 4 =",
                            "_MR-V V.FLAGS @ VFS-F-RO AND 0=",
                            "_MR-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                            *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        ]
                    )
                    + ' IF ." EXT4-MULTI-ALLOCATED-EOF-PROFILE-CAPACITY" THEN'
                ),
                "_MR-FD VFS-CLOSE? CONSTANT _MR-CLOSE-IOR",
                "0 _MR-V VFS-UNMOUNT CONSTANT _MR-UNMOUNT-IOR",
                (
                    "_MR-CLOSE-IOR 0= _MR-UNMOUNT-IOR 0= AND "
                    "_MR-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                    "_MR-PROFILE-ARENA ARENA-USED 0= AND "
                    "_MR-PROFILE-ARENA A.PTR @ _MR-PROFILE-BASE = AND "
                    'IF ." EXT4-MULTI-ALLOCATED-EOF-PROFILE-UNMOUNT" THEN'
                ),
            ],
            patches=input_patches,
            capture_media=backing,
        )
        _assert_emitted(output, "EXT4-MULTI-ALLOCATED-EOF-PROFILE-CAPACITY")
        _assert_emitted(output, "EXT4-MULTI-ALLOCATED-EOF-PROFILE-UNMOUNT")
        assert trace[: len(activation_trace)] == activation_trace
        assert trace.count(("write", first_candidate * 2, 2)) == 1
        assert trace.count(("write", second_candidate * 2, 2)) == 0
        assert trace.count(("write", bitmap_home * 2, 2)) == 1
        assert trace.count(("write", gdt_home * 2, 2)) == 1
        assert trace.count(("write", inode_home * 2, 2)) == 1
        assert trace.count(("write", data_block * 2, 2)) == 0
        assert trace.count(("write", xattr_block * 2, 2)) == 0

        final_superblock, final_inode, _ = _ext4_inode_record(
            backing, inode_number
        )
        assert struct.unpack_from("<I", final_superblock, 0x0C)[0] == (
            free_blocks_before - 1
        )
        assert struct.unpack_from("<I", final_inode, 0x04)[0] == committed_size
        assert struct.unpack_from("<I", final_inode, 0x1C)[0] == committed_blocks
        assert struct.unpack_from("<HHHH", final_inode, 0x28) == (
            0xF30A,
            4,
            4,
            0,
        )
        assert _extent_root_physical(final_inode, 5) == first_candidate
        with pytest.raises(AssertionError, match="logical block 6 is unmapped"):
            _extent_root_physical(final_inode, 6)
        final_allocation = _ext4_block_allocation_state(
            backing, (first_candidate, second_candidate)
        )
        assert final_allocation[first_candidate]
        assert not final_allocation[second_candidate]
        assert _read_ext4_home(
            backing, first_candidate, block_size=block_size
        ) == first_append
        assert _read_ext4_home(
            backing, second_candidate, block_size=block_size
        ) == original_second_candidate

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            backing,
            stable,
            expected_file=expected_file,
            expected_epoch_ms=committed_epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=committed_blocks,
            prefix="_MR-S",
            marker="EXT4-MULTI-ALLOCATED-EOF-PROFILE-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == media_sha256
        _assert_e2fsck_clean(stable, jbd2_toolchain)
    finally:
        backing.unlink(missing_ok=True)
        stable.unlink(missing_ok=True)


@pytest.fixture(scope="session")
def staged_public_extent_root_growth_prestate(
    writer_activation_fixture: dict[str, object],
) -> dict[str, object]:
    """Build one linked, full, unmergeable resident extent root."""
    path = writer_activation_fixture["image"]
    source_patches = writer_activation_fixture["source_patches"]
    activation_trace = writer_activation_fixture["success_trace"]
    journal0_physical = writer_activation_fixture["journal0_physical"]
    guard_physical = writer_activation_fixture["guard_physical"]
    assert isinstance(path, Path)
    assert isinstance(source_patches, tuple)
    assert isinstance(activation_trace, tuple)
    assert isinstance(journal0_physical, int)
    assert isinstance(guard_physical, int)

    inode_number = 14
    data_candidate = 1354
    leaf_candidate = 1355
    superblock, inode, inode_offset = _ext4_inode_record(path, inode_number)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_size = struct.unpack_from("<H", superblock, 0x58)[0]
    inode_home, inode_block_offset = divmod(inode_offset, block_size)
    data_block = _extent_root_physical(inode, 0)
    xattr_block = struct.unpack_from("<I", inode, 0x68)[0]
    generation = struct.unpack_from("<I", inode, 0x64)[0]
    links = struct.unpack_from("<H", inode, 0x1A)[0]
    assert block_size == 1024
    assert inode_size == 256
    assert inode_home == 278
    assert inode_block_offset == 256
    assert data_block == 1346
    assert xattr_block == 1349
    assert generation == 0
    assert links == 2
    assert struct.unpack_from("<I", inode, 0x04)[0] == 54
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 4
    assert struct.unpack_from("<HHHH", inode, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    assert not any(
        _ext4_block_allocation_state(
            path,
            (1351, 1352, 1353, data_candidate, leaf_candidate),
        ).values()
    )

    allocated_patches, physical_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol="modern",
        extent_specs=((0, 3, False),),
        inode_number=inode_number,
        physical_starts=(1351,),
        seed_payloads=True,
        base_patches=((1024, superblock), (inode_offset, inode)),
    )
    assert physical_ranges == ((1351, 3),)
    patch_map = dict(allocated_patches)
    prepared_super = patch_map[1024]
    old_size = 6 * block_size
    old_blocks = 10
    generation = 0x1357_9BDF
    root_generation = 0x2468_ACE0
    extent_entries = (
        (0, 1, data_block),
        (2, 1, 1352),
        (4, 1, 1353),
        (5, 1, 1351),
    )
    prepared_inode = bytearray(inode)
    struct.pack_into("<I", prepared_inode, 0x04, old_size)
    struct.pack_into("<I", prepared_inode, 0x6C, 0)
    struct.pack_into("<I", prepared_inode, 0x1C, old_blocks)
    struct.pack_into("<I", prepared_inode, 0x30, root_generation)
    struct.pack_into("<I", prepared_inode, 0x64, generation)
    struct.pack_into("<H", prepared_inode, 0x74, 0)
    prepared_inode[0x34:0x64] = bytes(48)
    struct.pack_into("<H", prepared_inode, 0x2A, len(extent_entries))
    for index, (logical, length, physical) in enumerate(extent_entries):
        struct.pack_into(
            "<IHHI",
            prepared_inode,
            0x34 + index * 12,
            logical,
            length,
            physical >> 32,
            physical & 0xFFFF_FFFF,
        )
    prepared_inode[:] = _inode_with_checksum(
        prepared_super,
        inode_number,
        prepared_inode,
    )
    patch_map[inode_offset] = bytes(prepared_inode)
    original_data_candidate = bytes((0xA5,)) * block_size
    original_leaf_candidate = bytes((0x5A,)) * block_size
    patch_map[data_candidate * block_size] = original_data_candidate
    patch_map[leaf_candidate * block_size] = original_leaf_candidate
    input_patches = source_patches + tuple(patch_map.items())

    original_blocks = {
        physical: _patched_ext4_home(
            path,
            input_patches,
            physical,
            block_size=block_size,
        )
        for physical in (data_block, 1351, 1352, 1353, xattr_block)
    }
    expected_file_prefix = b"".join(
        (
            original_blocks[data_block],
            bytes(block_size),
            original_blocks[1352],
            bytes(block_size),
            original_blocks[1353],
            original_blocks[1351],
        )
    )
    assert len(expected_file_prefix) == old_size
    assert struct.unpack_from("<HHHH", prepared_inode, 0x28) == (
        0xF30A,
        4,
        4,
        0,
    )
    assert struct.unpack_from("<I", prepared_inode, 0x04)[0] == old_size
    assert struct.unpack_from("<I", prepared_inode, 0x1C)[0] == old_blocks
    assert struct.unpack_from("<I", prepared_inode, 0x30)[0] == root_generation
    assert struct.unpack_from("<I", prepared_inode, 0x64)[0] == generation
    assert root_generation != generation
    assert not any(
        _ext4_block_allocation_state(
            path,
            (data_candidate, leaf_candidate),
        ).values()
    )
    return {
        "path": path,
        "input_patches": input_patches,
        "activation_trace": activation_trace,
        "journal0_physical": journal0_physical,
        "guard_physical": guard_physical,
        "superblock": prepared_super,
        "inode": bytes(prepared_inode),
        "inode_offset": inode_offset,
        "inode_home": inode_home,
        "inode_block_offset": inode_block_offset,
        "inode_size": inode_size,
        "inode_number": inode_number,
        "block_size": block_size,
        "old_size": old_size,
        "old_blocks": old_blocks,
        "generation": generation,
        "root_generation": root_generation,
        "links": links,
        "extent_entries": extent_entries,
        "data_block": data_block,
        "xattr_block": xattr_block,
        "data_candidate": data_candidate,
        "leaf_candidate": leaf_candidate,
        "original_blocks": original_blocks,
        "original_data_candidate": original_data_candidate,
        "original_leaf_candidate": original_leaf_candidate,
        "expected_file_prefix": expected_file_prefix,
    }


@pytest.fixture(scope="session")
def staged_public_compact_saturated_depth0_prestate(
    compact_primary_writer_activation_fixture: dict[str, object],
) -> dict[str, object]:
    """Build a full linked root on the compact primary-profile image."""
    fixture = compact_primary_writer_activation_fixture
    path = fixture["image"]
