def test_staged_public_multi_leaf_split_passes_external_oracles(
    staged_public_multi_leaf_split_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    fixture = staged_public_multi_leaf_split_fixture
    image = fixture["image"]
    expected_file = fixture["expected_file"]
    inode_number = fixture["inode_number"]
    untouched_leaf = fixture["untouched_leaf"]
    selected_leaf = fixture["selected_leaf"]
    leaf_candidate = fixture["leaf_candidate"]
    data_candidate = fixture["data_candidate"]
    target_logical = fixture["target_logical"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert all(
        isinstance(value, int)
        for value in (
            inode_number,
            untouched_leaf,
            selected_leaf,
            leaf_candidate,
            data_candidate,
            target_logical,
        )
    )
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)
    right_entries = fixture["right_entries"]
    assert isinstance(right_entries, tuple)
    right_first_physical = right_entries[0][3]
    assert isinstance(right_first_physical, int)
    readback = subprocess.run(
        [
            str(debugfs),
            "-R",
            "cat /fixture/extent-tree.bin",
            str(image),
        ],
        env=env,
        capture_output=True,
        check=False,
    )
    assert readback.returncode == 0, readback.stdout + readback.stderr
    assert readback.stdout == expected_file
    for logical, expected in (
        (target_logical, data_candidate),
        (84, right_first_physical),
    ):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/extent-tree.bin {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == expected
    stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            "stat /fixture/extent-tree.bin",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert re.search(r"Links:\s+1\s+Blockcount:\s+178", stat.stdout)
    for leaf in (untouched_leaf, selected_leaf, leaf_candidate):
        assert f"(ETB0):{leaf}" in stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


@pytest.fixture(scope="session")
def staged_full_depth1_root_prestate(
    staged_public_multi_leaf_split_fixture: dict[str, object],
) -> dict[str, object]:
    """Prepare a clean four-index depth-one root without another public write."""
    prior = staged_public_multi_leaf_split_fixture
    path = prior["image"]
    inode_number = prior["inode_number"]
    block_size = prior["block_size"]
    generation = prior["generation"]
    root_generation = prior["root_generation"]
    first_leaf = prior["untouched_leaf"]
    second_leaf = prior["selected_leaf"]
    third_leaf = prior["leaf_candidate"]
    assert isinstance(path, Path)
    assert all(
        isinstance(value, int)
        for value in (
            inode_number,
            block_size,
            generation,
            root_generation,
            first_leaf,
            second_leaf,
            third_leaf,
        )
    )
    assert block_size == 1024
    assert (first_leaf, second_leaf, third_leaf) == (1353, 1454, 1456)

    superblock, inode, inode_offset = _ext4_inode_record(path, inode_number)
    inode_home, inode_block_offset = divmod(inode_offset, block_size)
    assert inode_home == prior["inode_home"]
    assert inode_block_offset == 256
    assert struct.unpack_from("<I", inode, 0x04)[0] == 167 * block_size
    assert struct.unpack_from("<I", inode, 0x1C)[0] == 178
    assert struct.unpack_from("<HHHHI", inode, 0x28) == (
        0xF30A,
        3,
        4,
        1,
        root_generation,
    )
    assert tuple(
        struct.unpack_from("<IIHH", inode, 0x34 + index * 12)
        for index in range(3)
    ) == (
        (0, first_leaf, 0, 0),
        (1, second_leaf, 0, 0),
        (84, third_leaf, 0, 0),
    )

    leaf_homes_before = (first_leaf, second_leaf, third_leaf)
    leaf_images_before = tuple(
        _read_ext4_home(path, home, block_size=block_size)
        for home in leaf_homes_before
    )
    leaf_entries_before = tuple(
        _extent_leaf_entries(image) for image in leaf_images_before
    )
    assert tuple(len(entries) for entries in leaf_entries_before) == (
        1,
        42,
        43,
    )
    all_entries = tuple(
        entry for entries in leaf_entries_before for entry in entries
    )
    assert len(all_entries) == 86
    assert [entry[0] for entry in all_entries] == [
        0,
        1,
        *range(2, 84, 2),
        84,
        85,
        *range(86, 168, 2),
    ]

    fourth_leaf = 1457
    allocated_patches, physical_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol="modern",
        extent_specs=((0, 1, False),),
        inode_number=inode_number,
        physical_starts=(fourth_leaf,),
        base_patches=((1024, superblock), (inode_offset, inode)),
    )
    assert physical_ranges == ((fourth_leaf, 1),)
    patch_map = dict(allocated_patches)
    prepared_superblock = patch_map[1024]

    third_entries = leaf_entries_before[2]
    retained_third_entries = third_entries[:21]
    fourth_entries = third_entries[21:]
    assert len(retained_third_entries) == 21
    assert len(fourth_entries) == 22
    assert retained_third_entries[0][0] == 84
    assert retained_third_entries[-1][0] == 122
    assert fourth_entries[0][0] == 124
    assert fourth_entries[-1][0] == 166
    patch_map[third_leaf * block_size] = _extent_leaf_with_entries(
        prepared_superblock,
        inode_number,
        generation,
        root_generation,
        retained_third_entries,
    )
    patch_map[fourth_leaf * block_size] = _extent_leaf_with_entries(
        prepared_superblock,
        inode_number,
        generation,
        root_generation,
        fourth_entries,
    )

    prepared_inode = bytearray(inode)
    struct.pack_into("<H", prepared_inode, 0x2A, 4)
    struct.pack_into(
        "<IIHH",
        prepared_inode,
        0x58,
        fourth_entries[0][0],
        fourth_leaf,
        0,
        0,
    )
    struct.pack_into("<I", prepared_inode, 0x1C, 180)
    prepared_inode[:] = _inode_with_checksum(
        prepared_superblock,
        inode_number,
        prepared_inode,
    )
    patch_map[inode_offset] = bytes(prepared_inode)
    prepared_patches = tuple(patch_map.items())

    bitmap = _patched_ext4_home(
        path,
        prepared_patches,
        259,
        block_size=block_size,
    )
    first_data = struct.unpack_from("<I", prepared_superblock, 0x14)[0]
    fourth_bit = fourth_leaf - first_data
    candidate = fourth_leaf + 1
    candidate_bit = candidate - first_data
    assert bitmap[fourth_bit // 8] & (1 << (fourth_bit % 8))
    assert not bitmap[candidate_bit // 8] & (1 << (candidate_bit % 8))

    leaf_homes = (*leaf_homes_before, fourth_leaf)
    leaf_entries = (
        leaf_entries_before[0],
        leaf_entries_before[1],
        retained_third_entries,
        fourth_entries,
    )
    assert tuple(len(entries) for entries in leaf_entries) == (1, 42, 21, 22)
    return {
        **prior,
        "image": path,
        "patches": prepared_patches,
        "inode_offset": inode_offset,
        "leaf_homes": leaf_homes,
        "leaf_entries": leaf_entries,
        "all_entries": all_entries,
        "root_keys": (0, 1, 84, 124),
        "fourth_leaf": fourth_leaf,
        "candidate": candidate,
        "new_blocks": 180,
    }


def test_full_depth1_root_edits_selected_leaf_with_room_without_io(
    staged_full_depth1_root_prestate: dict[str, object],
) -> None:
    """A saturated resident root still permits a selected-leaf insertion."""
    geometry = staged_full_depth1_root_prestate
    path = geometry["image"]
    patches = geometry["patches"]
    inode_number = geometry["inode_number"]
    generation = geometry["generation"]
    block_size = geometry["block_size"]
    selected_leaf = geometry["fourth_leaf"]
    candidate = geometry["candidate"]
    root_keys = geometry["root_keys"]
    assert isinstance(path, Path)
    assert isinstance(patches, tuple)
    assert isinstance(root_keys, tuple)
    assert all(
        isinstance(value, int)
        for value in (
            inode_number,
            generation,
            block_size,
            selected_leaf,
            candidate,
        )
    )
    assert block_size == 1024
    assert root_keys == (0, 1, 84, 124)
    assert selected_leaf == 1457
    assert candidate == 1458

    write_offset = 125 * block_size + 100
    output = run_forth(
        path,
        [
            "T-ARENA CONSTANT _FRE-ARENA",
            (
                "_FRE-ARENA T-VOLUME EXT4-NEW "
                "CONSTANT _FRE-MOUNT-IOR CONSTANT _FRE-V"
            ),
            "_FRE-V _EXT4-CTX CONSTANT _FRE-CTX",
            (
                "5 1 0 _FRE-CTX _EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _FRE-WRITER-IOR CONSTANT _FRE-WRITER"
            ),
            "_FRE-ARENA ARENA-USED CONSTANT _FRE-USED-BEFORE",
            (
                "5 1 0 _FRE-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _FRE-BEGIN-IOR CONSTANT _FRE-TX"
            ),
            "DEPTH CONSTANT _FRE-DEPTH-BEFORE",
            (
                f'S" E" {write_offset} {inode_number} '
                f"{generation} 1 2 _FRE-TX "
                "_EXT4-JTX-STAGE-REGULAR-ONEBLOCK-HOLE-FILL "
                "CONSTANT _FRE-STAGE-IOR"
            ),
            "DEPTH CONSTANT _FRE-DEPTH-AFTER",
            "_XH-ROOT @ 2 + W@ CONSTANT _FRE-ROOT-COUNT",
            "_XH-ROOT @ 12 + L@ CONSTANT _FRE-ROOT-KEY0",
            "_XH-ROOT @ 24 + L@ CONSTANT _FRE-ROOT-KEY1",
            "_XH-ROOT @ 36 + L@ CONSTANT _FRE-ROOT-KEY2",
            "_XH-ROOT @ 48 + L@ CONSTANT _FRE-ROOT-KEY3",
            (
                "_FRE-WRITER _EXT4-JWR.META-USED + @ "
                "CONSTANT _FRE-META-USED"
            ),
            (
                "_FRE-WRITER _EXT4-JWR.DATA-USED + @ "
                "CONSTANT _FRE-DATA-USED"
            ),
            "_FRE-TX _EXT4-JTX-ABORT CONSTANT _FRE-ABORT-IOR",
            (
                _forth_conjunction(
                    [
                        "_FRE-MOUNT-IOR 0=",
                        "_FRE-WRITER-IOR 0=",
                        "_FRE-BEGIN-IOR 0=",
                        "_FRE-DEPTH-BEFORE _FRE-DEPTH-AFTER =",
                        "_FRE-STAGE-IOR 0=",
                        "_XH-TREE-DEPTH @ 1 =",
                        "_XH-ROOT-ENTRIES @ 4 =",
                        "_XH-ROOT-INDEX @ 3 =",
                        f"_XH-EXISTING-LEAF @ {selected_leaf} =",
                        "_XH-ENTRIES @ 23 =",
                        "_XH-INSERT @ 1 =",
                        "_XH-EDIT @ _XH-EDIT-INSERT =",
                        "_XH-LEAF-FIRST @ 124 =",
                        "_FRE-ROOT-COUNT 4 =",
                        "_FRE-ROOT-KEY0 0=",
                        "_FRE-ROOT-KEY1 1 =",
                        "_FRE-ROOT-KEY2 84 =",
                        "_FRE-ROOT-KEY3 124 =",
                        f"_XH-CANDIDATE @ {candidate} =",
                        "_XH-LEAF-CANDIDATE @ 0=",
                        "_XH-ROOT-GROW @ 0=",
                        "_XH-LEAF-SPLIT @ 0=",
                        "_XH-META-CREDIT @ 5 =",
                        "_XH-NEW-BLOCKS @ 182 =",
                        "_XH-PUBLISHED @ 0<",
                        "_FRE-META-USED 5 =",
                        "_FRE-DATA-USED 1 =",
                        "_FRE-WRITER _EXT4-JWR.META-USED + @ 0=",
                        "_FRE-WRITER _EXT4-JWR.META-ACTIVE + @ 0=",
                        "_FRE-WRITER _EXT4-JWR.DATA-USED + @ 0=",
                        "_FRE-WRITER _EXT4-JWR.DATA-ACTIVE + @ 0=",
                        "_FRE-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        "_FRE-ABORT-IOR 0=",
                        "_FRE-WRITER _EXT4-JWR-IDLE-CLEAN?",
                        "_FRE-WRITER _EXT4-JWR-VALID?",
                        "_FRE-ARENA ARENA-USED _FRE-USED-BEFORE =",
                    ]
                )
                + ' IF ." EXT4-FULL-ROOT-LEAF-EDIT-STAGED" THEN'
            ),
            "0 _FRE-V VFS-UNMOUNT CONSTANT _FRE-UNMOUNT-IOR",
            (
                "_FRE-UNMOUNT-IOR 0= _FRE-V V.LIFECYCLE @ "
                "VFS-L-UNMOUNTED = AND "
                'IF ." EXT4-FULL-ROOT-LEAF-EDIT-UNMOUNT" THEN'
            ),
        ],
        patches=patches,
    )
    _assert_emitted(output, "EXT4-FULL-ROOT-LEAF-EDIT-STAGED")
    _assert_emitted(output, "EXT4-FULL-ROOT-LEAF-EDIT-UNMOUNT")


def test_full_depth1_root_full_leaf_refuses_growth_without_io(
    staged_full_depth1_root_prestate: dict[str, object],
) -> None:
    """A full selected leaf under a full root refuses structural growth."""
    geometry = staged_full_depth1_root_prestate
    path = geometry["image"]
    base_patches = geometry["patches"]
    inode_number = geometry["inode_number"]
    inode_offset = geometry["inode_offset"]
    block_size = geometry["block_size"]
    generation = geometry["generation"]
    root_generation = geometry["root_generation"]
    leaf_homes = geometry["leaf_homes"]
    all_entries = geometry["all_entries"]
    assert isinstance(path, Path)
    assert isinstance(base_patches, tuple)
    assert isinstance(leaf_homes, tuple)
    assert isinstance(all_entries, tuple)
    assert all(
        isinstance(value, int)
        for value in (
            inode_number,
            inode_offset,
            block_size,
            generation,
            root_generation,
        )
    )
    assert leaf_homes == (1353, 1454, 1456, 1457)
    assert len(all_entries) == 86

    allocated_data = 1458
    allocated_patches, physical_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol="modern",
        extent_specs=((0, 1, False),),
        inode_number=inode_number,
        physical_starts=(allocated_data,),
        base_patches=base_patches,
    )
    assert physical_ranges == ((allocated_data, 1),)
    patch_map = dict(allocated_patches)
    prepared_superblock = patch_map[1024]
    prepared_entries = (
        *all_entries,
        (
            168,
            1,
            allocated_data >> 32,
            allocated_data & 0xFFFF_FFFF,
        ),
    )
    assert len(prepared_entries) == 87
    assert all(
        prepared_entries[index - 1][0] < prepared_entries[index][0]
        for index in range(1, len(prepared_entries))
    )
    leaf_entries = (
        prepared_entries[:1],
        prepared_entries[1:2],
        prepared_entries[2:3],
        prepared_entries[3:],
    )
    assert tuple(len(entries) for entries in leaf_entries) == (1, 1, 1, 84)
    assert tuple(entries[0][0] for entries in leaf_entries) == (0, 1, 2, 4)
    for home, entries in zip(leaf_homes, leaf_entries, strict=True):
        patch_map[home * block_size] = _extent_leaf_with_entries(
            prepared_superblock,
            inode_number,
            generation,
            root_generation,
            entries,
        )

    prepared_inode = bytearray(patch_map[inode_offset])
    assert struct.unpack_from("<HHHHI", prepared_inode, 0x28) == (
        0xF30A,
        4,
        4,
        1,
        root_generation,
    )
    for index, (home, entries) in enumerate(
        zip(leaf_homes, leaf_entries, strict=True)
    ):
        struct.pack_into(
            "<IIHH",
            prepared_inode,
            0x34 + index * 12,
            entries[0][0],
            home,
            0,
            0,
        )
    full_size = 169 * block_size
    struct.pack_into("<I", prepared_inode, 0x04, full_size)
    struct.pack_into("<I", prepared_inode, 0x6C, 0)
    struct.pack_into("<I", prepared_inode, 0x1C, 182)
    struct.pack_into("<H", prepared_inode, 0x74, 0)
    prepared_inode[:] = _inode_with_checksum(
        prepared_superblock,
        inode_number,
        prepared_inode,
    )
    patch_map[inode_offset] = bytes(prepared_inode)
    prepared_patches = tuple(patch_map.items())

    candidate = 1459
    bitmap = _patched_ext4_home(
        path,
        prepared_patches,
        259,
        block_size=block_size,
    )
    first_data = struct.unpack_from("<I", prepared_superblock, 0x14)[0]
    allocated_bit = allocated_data - first_data
    candidate_bit = candidate - first_data
    assert bitmap[allocated_bit // 8] & (1 << (allocated_bit % 8))
    assert not bitmap[candidate_bit // 8] & (1 << (candidate_bit % 8))

    write_offset = 5 * block_size + 100
    output = run_forth(
        path,
        [
            "T-ARENA CONSTANT _FRF-ARENA",
            (
                "_FRF-ARENA T-VOLUME EXT4-NEW "
                "CONSTANT _FRF-MOUNT-IOR CONSTANT _FRF-V"
            ),
            "_FRF-V _EXT4-CTX CONSTANT _FRF-CTX",
            (
                "6 1 0 _FRF-CTX _EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _FRF-WRITER-IOR CONSTANT _FRF-WRITER"
            ),
            "_FRF-ARENA ARENA-USED CONSTANT _FRF-USED-BEFORE",
            (
                "6 1 0 _FRF-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _FRF-BEGIN-IOR CONSTANT _FRF-TX"
            ),
            "DEPTH CONSTANT _FRF-DEPTH-BEFORE",
            (
                f'S" R" {write_offset} {inode_number} '
                f"{generation} 1 2 _FRF-TX "
                "_EXT4-JTX-STAGE-REGULAR-ONEBLOCK-HOLE-FILL "
                "CONSTANT _FRF-STAGE-IOR"
            ),
            "DEPTH CONSTANT _FRF-DEPTH-AFTER",
            (
                "_FRF-WRITER _EXT4-JWR.STATE + @ "
                "CONSTANT _FRF-STATE-BEFORE-ABORT"
            ),
            (
                "_FRF-WRITER _EXT4-JWR.META-USED + @ "
                "CONSTANT _FRF-META-USED"
            ),
            (
                "_FRF-WRITER _EXT4-JWR.DATA-USED + @ "
                "CONSTANT _FRF-DATA-USED"
            ),
            "_FRF-TX _EXT4-JTX-ABORT CONSTANT _FRF-ABORT-IOR",
            (
                _forth_conjunction(
                    [
                        "_FRF-MOUNT-IOR 0=",
                        "_FRF-WRITER-IOR 0=",
                        "_FRF-BEGIN-IOR 0=",
                        "_FRF-DEPTH-BEFORE _FRF-DEPTH-AFTER =",
                        (
                            "_FRF-STAGE-IOR VFS-IOR-REASON "
                            "VFS-R-UNSUPPORTED ="
                        ),
                        (
                            "_FRF-STAGE-IOR VFS-IOR-DETAIL "
                            "EXT4-D-DATA-MAP ="
                        ),
                        (
                            "_FRF-STAGE-IOR VFS-IOR-REASON "
                            "VFS-R-NOSPC <>"
                        ),
                        "_XH-TREE-DEPTH @ 1 =",
                        "_XH-ROOT-ENTRIES @ 4 =",
                        "_XH-ROOT-INDEX @ 3 =",
                        "_XH-EXISTING-LEAF @ 1457 =",
                        "_XH-ENTRIES @ 84 =",
                        "_XH-ENTRY-MAX @ 84 =",
                        "_XH-INSERT @ 1 =",
                        "_XH-LEFT-OK @ 0=",
                        "_XH-RIGHT-OK @ 0=",
                        f"_XH-CANDIDATE @ {candidate} =",
                        "_XH-LEAF-CANDIDATE @ 0=",
                        "_XH-ROOT-GROW @ 0=",
                        "_XH-LEAF-SPLIT @ 0=",
                        "_XH-META-CREDIT @ 0=",
                        "_XH-PUBLISHED @ 0=",
                        (
                            "_FRF-STATE-BEFORE-ABORT "
                            "_EXT4-JWR-STAGING ="
                        ),
                        "_FRF-META-USED 0=",
                        "_FRF-DATA-USED 0=",
                        "_FRF-WRITER _EXT4-JWR.META-USED + @ 0=",
                        "_FRF-WRITER _EXT4-JWR.META-ACTIVE + @ 0=",
                        "_FRF-WRITER _EXT4-JWR.DATA-USED + @ 0=",
                        "_FRF-WRITER _EXT4-JWR.DATA-ACTIVE + @ 0=",
                        "_FRF-WRITER _EXT4-JWR.REVOKE-USED + @ 0=",
                        "_FRF-WRITER _EXT4-JWR.REVOKE-ACTIVE + @ 0=",
                        "_FRF-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        "_FRF-ABORT-IOR 0=",
                        "_FRF-WRITER _EXT4-JWR-IDLE-CLEAN?",
                        "_FRF-WRITER _EXT4-JWR-VALID?",
                        "_FRF-ARENA ARENA-USED _FRF-USED-BEFORE =",
                    ]
                )
                + ' IF ." EXT4-FULL-ROOT-FULL-LEAF-REFUSED" THEN'
            ),
            "0 _FRF-V VFS-UNMOUNT CONSTANT _FRF-UNMOUNT-IOR",
            (
                "_FRF-UNMOUNT-IOR 0= _FRF-V V.LIFECYCLE @ "
                "VFS-L-UNMOUNTED = AND "
                'IF ." EXT4-FULL-ROOT-FULL-LEAF-UNMOUNT" THEN'
            ),
        ],
        patches=prepared_patches,
    )
    _assert_emitted(output, "EXT4-FULL-ROOT-FULL-LEAF-REFUSED")
    _assert_emitted(output, "EXT4-FULL-ROOT-FULL-LEAF-UNMOUNT")


def test_staged_public_extent_leaf_split_passes_external_oracles(
    staged_public_extent_leaf_split_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    fixture = staged_public_extent_leaf_split_fixture
    image = fixture["image"]
    expected_file = fixture["expected_file"]
    inode_number = fixture["inode_number"]
    existing_leaf = fixture["existing_leaf"]
    data_candidate = fixture["data_candidate"]
    leaf_candidate = fixture["leaf_candidate"]
    right_entries = fixture["right_entries"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(existing_leaf, int)
    assert isinstance(data_candidate, int)
    assert isinstance(leaf_candidate, int)
    assert isinstance(right_entries, tuple)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    readback = subprocess.run(
        [
            str(debugfs),
            "-R",
            "cat /fixture/extent-tree.bin",
            str(image),
        ],
        env=env,
        capture_output=True,
        check=False,
    )
    assert readback.returncode == 0, readback.stdout + readback.stderr
    assert readback.stdout == expected_file

    for logical, expected in (
        (1, data_candidate),
        (82, right_entries[0][3]),
    ):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/extent-tree.bin {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == expected

    stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            "stat /fixture/extent-tree.bin",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert "Flags: 0x80000" in stat.stdout
    assert re.search(r"Links:\s+1\s+Blockcount:\s+174", stat.stdout)
    assert f"(ETB0):{existing_leaf}" in stat.stdout
    assert f"(ETB0):{leaf_candidate}" in stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def _staged_extent_leaf_split_fault_lines(
    *,
    epoch_ms: int,
    replacement: bytes,
    write_offset: int,
    file_size: int,
    new_blocks: int,
    data_candidate: int,
    existing_leaf: int,
    leaf_candidate: int,
    leaf_max: int,
) -> list[str]:
    """Build the public split journey for a committed new-leaf tear."""
    seconds, milliseconds = divmod(epoch_ms, 1000)
    nanoseconds = milliseconds * 1_000_000
    expected_cursor = write_offset + len(replacement)
    return [
        "VARIABLE _LST-CLOCK-CALLS",
        (
            ": _LST-NOW ( context -- epoch-ms ior ) "
            f"DROP 1 _LST-CLOCK-CALLS +! {epoch_ms} 0 ;"
        ),
        "T-ARENA CONSTANT _LST-ARENA",
        (
            "_LST-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
            "CONSTANT _LST-MOUNT-IOR CONSTANT _LST-V"
        ),
        "_LST-V _EXT4-CTX CONSTANT _LST-CTX",
        (
            "' _LST-NOW 0 _LST-V EXT4-BIND-WRITE-CLOCK? "
            "CONSTANT _LST-CLOCK-IOR"
        ),
        *_ext4_dedicated_writer_profile_forth(
            "_LST-PROFILE", "_LST-V", 6, 1, 0
        ),
        (
            'S" /fixture/payload.txt" '
            "VFS-FF-READ VFS-FF-WRITE OR _LST-V VFS-OPEN? "
            "CONSTANT _LST-ACT-OPEN-IOR CONSTANT _LST-ACT-FD"
        ),
        (
            'S" A" _LST-ACT-FD VFS-WRITE? '
            "CONSTANT _LST-ACT-WRITE-IOR CONSTANT _LST-ACT-ACTUAL"
        ),
        (
            'S" /fixture/extent-tree.bin" '
            "VFS-FF-READ VFS-FF-WRITE OR _LST-V VFS-OPEN? "
            "CONSTANT _LST-OPEN-IOR CONSTANT _LST-FD"
        ),
        "_LST-FD FD.INODE @ D.VNODE @ CONSTANT _LST-VN",
        "_LST-VN VN.GEN @ CONSTANT _LST-OLD-GEN",
        "_LST-VN VN.NLINK @ CONSTANT _LST-OLD-NLINK",
        (
            f"{write_offset} _LST-FD VFS-SEEK? "
            "CONSTANT _LST-SEEK-IOR"
        ),
        (
            f'S" {replacement.decode("ascii")}" _LST-FD '
            "VFS-WRITE? CONSTANT _LST-WRITE-IOR CONSTANT _LST-ACTUAL"
        ),
        "_LST-V V.LAST-IOR @ CONSTANT _LST-LAST-IOR",
        "_LST-FD FD.CUR-LO @ CONSTANT _LST-CURSOR",
        "_LST-CTX _EXT4-C.J.WRITER + @ CONSTANT _LST-WRITER",
        "_LST-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _LST-HOMES",
        "_LST-FD VFS-CLOSE? CONSTANT _LST-CLOSE-IOR",
        (
            "_LST-ACT-FD VFS-CLOSE? "
            "CONSTANT _LST-ACT-CLOSE-IOR"
        ),
        (
            _forth_conjunction(
                [
                    "_LST-MOUNT-IOR 0=",
                    "_LST-CLOCK-IOR 0=",
                    "_LST-PROFILE-SIZE-IOR 0=",
                    "_LST-PROFILE-BIND-IOR 0=",
                    "_LST-ACT-OPEN-IOR 0=",
                    "_LST-ACT-WRITE-IOR 0=",
                    "_LST-ACT-ACTUAL 1 =",
                    "_LST-OPEN-IOR 0=",
                    "_LST-SEEK-IOR 0=",
                    f"_LST-ACTUAL {len(replacement)} =",
                    (
                        "_LST-WRITE-IOR VFS-IOR-DOMAIN "
                        "VFS-IOR-D-VOLUME ="
                    ),
                    "_LST-WRITE-IOR VFS-IOR-REASON VFS-R-IO =",
                    (
                        "_LST-WRITE-IOR VFS-IOR-FLAGS "
                        "VFS-IOR-F-PARTIAL VFS-IOR-F-READONLY OR ="
                    ),
                    "_LST-LAST-IOR _LST-WRITE-IOR =",
                    f"_LST-CURSOR {expected_cursor} =",
                    "_LST-CLOCK-CALLS @ 2 =",
                    f"_LST-VN VN.SIZE-LO @ {file_size} =",
                    "_LST-VN VN.SIZE-HI @ 0=",
                    f"_LST-VN VN.BLOCKS @ {new_blocks} =",
                    "_LST-VN VN.GEN @ _LST-OLD-GEN =",
                    "_LST-VN VN.NLINK @ _LST-OLD-NLINK =",
                    f"_LST-VN VN.MTIME @ {seconds} =",
                    f"_LST-VN VN.MTIME-NS @ {nanoseconds} =",
                    f"_LST-VN VN.CTIME @ {seconds} =",
                    f"_LST-VN VN.CTIME-NS @ {nanoseconds} =",
                    "_LST-WRITER _LST-PROFILE-BASE =",
                    (
                        "_LST-WRITER _EXT4-JWR.STATE + @ "
                        "_EXT4-JWR-FAULTED ="
                    ),
                    (
                        "_LST-WRITER _EXT4-JWR.PHASE + @ "
                        "_EXT4-JWP-CHECKPOINT-HOME ="
                    ),
                    "_LST-WRITER _EXT4-JWR-VALID?",
                    (
                        "_LST-WRITER _EXT4-JWR.FAULT + @ "
                        "VFS-IOR-FLAGS VFS-IOR-F-PARTIAL ="
                    ),
                    "_LST-WRITER _EXT4-JWR.META-ACTIVE + @ 6 =",
                    "_LST-WRITER _EXT4-JWR.DATA-ACTIVE + @ 1 =",
                    "_LST-WRITER _EXT4-JWR.REVOKE-ACTIVE + @ 0=",
                    "_LST-HOMES 4 =",
                    "_LST-CTX _EXT4-C.J.COMMITTED + @ 1 =",
                    "_LST-CTX _EXT4-C.RECOVERY + @ 0<>",
                    "_LST-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0<>",
                    "_LST-V V.FLAGS @ VFS-F-RO AND 0<>",
                    "_LST-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                    "_EXT4-MOW-CREDIT @ -6 =",
                    "_EXT4-WR-KIND @ _EXT4-WRK-HOLE-FILL =",
                    f"_EXT4-WR-COUNT @ {len(replacement)} =",
                    f"_EXT4-WR-OFFSET @ {write_offset} =",
                    f"_EXT4-WR-REQUEST-END @ {expected_cursor} =",
                    f"_EXT4-WR-NEW-SIZE @ {file_size} =",
                    f"_EXT4-WR-NEW-BLOCKS @ {new_blocks} =",
                    f"_EXT4-WR-ACTUAL @ {len(replacement)} =",
                    f"_EXT4-MOW-ACTUAL @ {len(replacement)} =",
                    "_XH-TREE-DEPTH @ 1 =",
                    f"_XH-EXISTING-LEAF @ {existing_leaf} =",
                    f"_XH-CANDIDATE @ {data_candidate} =",
                    f"_XH-LEAF-CANDIDATE @ {leaf_candidate} =",
                    "_XH-ROOT-GROW @ 0=",
                    "_XH-LEAF-SPLIT @ 0<",
                    "_XH-EDIT @ _XH-EDIT-SPLIT-LEAF =",
                    "_XH-INSERT @ 1 =",
                    "_XH-SPLIT-LEFT @ 42 =",
                    "_XH-SPLIT-RIGHT @ 43 =",
                    f"_XH-ENTRIES @ {leaf_max} =",
                    "_XH-ROOT-ENTRIES @ 2 =",
                    "_XH-ROOT-INDEX @ 0=",
                    f"_XH-ENTRY-MAX @ {leaf_max} =",
                    f"_XH-LEAF-MAX @ {leaf_max} =",
                    "_XH-LEAF-FIRST @ 0=",
                    "_XH-LEAF-SECOND-FIRST @ 82 =",
                    "_XH-META-CREDIT @ 6 =",
                    "_XH-PUBLISHED @ 0<",
                    "_LST-CLOSE-IOR 0=",
                    "_LST-ACT-CLOSE-IOR 0=",
                    (
                        "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                        "_EXT4-BYTES-ZERO?"
                    ),
                    "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                    *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                ]
            )
            + ' IF ." EXT4-PUBLIC-EXTENT-LEAF-SPLIT-FAULT" THEN'
        ),
    ]


def test_staged_public_extent_leaf_split_tear_replays_both_leaves(
    staged_public_extent_leaf_split_prestate: dict[str, object],
    staged_public_extent_leaf_split_fixture: dict[str, object],
    tmp_path: Path,
) -> None:
    """Replay all six metadata homes after the new split leaf tears."""
    geometry = staged_public_extent_leaf_split_prestate
    success = staged_public_extent_leaf_split_fixture
    path = geometry["image"]
    patches = geometry["patches"]
    success_image = success["image"]
    success_trace = success["trace"]
    dirty_super = geometry["dirty_super"]
    expected_file = geometry["expected_file"]
    replacement = geometry["replacement"]
    write_offset = geometry["write_offset"]
    file_size = geometry["full_size"]
    new_blocks = geometry["new_blocks"]
    epoch_ms = success["epoch_ms"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    block_size = geometry["block_size"]
    generation = geometry["generation"]
    existing_leaf = geometry["existing_leaf"]
    data_candidate = geometry["data_candidate"]
    leaf_candidate = geometry["leaf_candidate"]
    bitmap_home = geometry["bitmap_home"]
    gdt_home = geometry["gdt_home"]
    super_home = geometry["super_home"]
    leaf_max = geometry["leaf_max"]
    assert isinstance(path, Path)
    assert isinstance(patches, tuple)
    assert isinstance(success_image, Path)
    assert isinstance(success_trace, tuple)
    assert isinstance(dirty_super, bytes)
    assert isinstance(expected_file, bytes)
    assert isinstance(replacement, bytes)
    assert all(
        isinstance(value, int)
        for value in (
            write_offset,
            file_size,
            new_blocks,
            epoch_ms,
            inode_number,
            inode_home,
            block_size,
            generation,
            existing_leaf,
            data_candidate,
            leaf_candidate,
            bitmap_home,
            gdt_home,
            super_home,
            leaf_max,
        )
    )

    expected_homes = {
        home: _read_ext4_home(success_image, home, block_size=block_size)
        for home in (
            data_candidate,
            bitmap_home,
            gdt_home,
            super_home,
            existing_leaf,
            leaf_candidate,
            inode_home,
        )
    }
    prestate_homes = {
        home: _patched_ext4_home(
            path, patches, home, block_size=block_size
        )
        for home in (leaf_candidate, inode_home)
    }
    leaf_ordinals = _write_ordinals_for_ext4_home(
        success_trace, leaf_candidate, block_size=block_size
    )
    assert len(leaf_ordinals) == 1
    leaf_ordinal = leaf_ordinals[0]
    leaf_event_index = _trace_event_index_for_ordinal(
        success_trace, "write", leaf_ordinal
    )
    assert success_trace[leaf_event_index] == (
        "write",
        leaf_candidate * (block_size // 512),
        block_size // 512,
    )

    tear_offset = 13
    expected_leaf = expected_homes[leaf_candidate]
    prestate_leaf = prestate_homes[leaf_candidate]
    expected_torn_leaf = (
        expected_leaf[:tear_offset] + prestate_leaf[tear_offset:]
    )
    assert expected_torn_leaf not in {expected_leaf, prestate_leaf}
    assert _extent_node_with_checksum(
        expected_homes[super_home],
        inode_number,
        generation,
        expected_torn_leaf,
    ) != expected_torn_leaf

    expected_faulted_super = bytearray(dirty_super)
    expected_super = expected_homes[super_home]
    expected_faulted_super[0x0C:0x10] = expected_super[0x0C:0x10]
    expected_faulted_super[0x158:0x15C] = expected_super[0x158:0x15C]
    expected_faulted_super[:] = _ext4_super_with_checksum(
        expected_faulted_super
    )

    faulted = tmp_path / "staged-extent-leaf-split-faulted.img"
    recovered = tmp_path / "staged-extent-leaf-split-recovered.img"
    try:
        output, failed_trace, _ = run_recovery_forth(
            path,
            faulted,
            _staged_extent_leaf_split_fault_lines(
                epoch_ms=epoch_ms,
                replacement=replacement,
                write_offset=write_offset,
                file_size=file_size,
                new_blocks=new_blocks,
                data_candidate=data_candidate,
                existing_leaf=existing_leaf,
                leaf_candidate=leaf_candidate,
                leaf_max=leaf_max,
            ),
            patches=patches,
            write_faults_by_ordinal={
                leaf_ordinal: {
                    "stage": "media",
                    "sector_index": 0,
                    "byte_index": tear_offset,
                    "result": STORAGE_RESULT_MEDIA_FAILURE,
                    "command": STORAGE_CMD_WRITE,
                }
            },
            capture_media=faulted,
        )
        _assert_emitted(output, "EXT4-PUBLIC-EXTENT-LEAF-SPLIT-FAULT")
        assert failed_trace == success_trace[: leaf_event_index + 1]
        assert _ext4_block_allocation_state(
            faulted, (data_candidate, leaf_candidate)
        ) == {data_candidate: True, leaf_candidate: True}
        for home in (
            data_candidate,
            bitmap_home,
            gdt_home,
            existing_leaf,
        ):
            assert _read_ext4_home(
                faulted, home, block_size=block_size
            ) == expected_homes[home]
        assert _read_ext4_home(
            faulted, super_home, block_size=block_size
        ) == bytes(expected_faulted_super)
        assert _read_ext4_home(
            faulted, leaf_candidate, block_size=block_size
        ) == expected_torn_leaf
        assert _read_ext4_home(
            faulted, inode_home, block_size=block_size
        ) == prestate_homes[inode_home]

        _, recovery_trace, _ = _extent_tree_crc_readback(
            faulted,
            recovered,
            expected_size=file_size,
            expected_read_offset=block_size,
            expected_read_crc=_crc32c_raw(
                expected_file[block_size : 2 * block_size]
            ),
            expected_epoch_ms=epoch_ms,
            expected_blocks=new_blocks,
            expected_home_writes=6,
            expected_replayed=True,
            prefix="_LST-R",
            marker="EXT4-PUBLIC-EXTENT-LEAF-SPLIT-RECOVERED",
        )
        assert ("write", data_candidate * 2, 2) not in recovery_trace
        replay_role_events = tuple(
            event
            for event in recovery_trace
            if event
            in {
                ("write", bitmap_home * 2, 2),
                ("write", gdt_home * 2, 2),
                ("write", super_home * 2, 2),
                ("write", existing_leaf * 2, 2),
                ("write", leaf_candidate * 2, 2),
                ("write", inode_home * 2, 2),
            }
        )
        assert replay_role_events == (
            ("write", bitmap_home * 2, 2),
            ("write", gdt_home * 2, 2),
            ("write", super_home * 2, 2),
            ("write", existing_leaf * 2, 2),
            ("write", leaf_candidate * 2, 2),
            ("write", inode_home * 2, 2),
            ("write", super_home * 2, 2),
        )
        for home, expected in expected_homes.items():
            assert _read_ext4_home(
                recovered, home, block_size=block_size
            ) == expected
        assert _ext4_block_allocation_state(
            recovered, (data_candidate, leaf_candidate)
        ) == {data_candidate: True, leaf_candidate: True}
    finally:
        faulted.unlink(missing_ok=True)
        recovered.unlink(missing_ok=True)


def _staged_extent_root_growth_leaf_fault_lines(
    *,
    epoch_ms: int,
    old_size: int,
    new_size: int,
    new_blocks: int,
    data_candidate: int,
    leaf_candidate: int,
    leaf_max: int,
) -> list[str]:
    """Build the public journey for a root-growth leaf-home fault."""
    replacement = _STAGED_ALIGNED_APPEND_REPLACEMENT.decode("ascii")
    expected_actual = len(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    return [
        "VARIABLE _RGL-CLOCK-CALLS",
        (
            ": _RGL-NOW ( context -- epoch-ms ior ) "
            f"DROP 1 _RGL-CLOCK-CALLS +! {epoch_ms} 0 ;"
        ),
        "T-ARENA CONSTANT _RGL-ARENA",
        (
            "_RGL-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
            "CONSTANT _RGL-MOUNT-IOR CONSTANT _RGL-V"
        ),
        "_RGL-V _EXT4-CTX CONSTANT _RGL-CTX",
        (
            "' _RGL-NOW 0 _RGL-V EXT4-BIND-WRITE-CLOCK? "
            "CONSTANT _RGL-CLOCK-IOR"
        ),
        *_ext4_dedicated_writer_profile_forth(
            "_RGL-PROFILE", "_RGL-V", 5, 1, 0
        ),
        (
            'S" /fixture/hardlink.txt" '
            "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
            "_RGL-V VFS-OPEN? "
            "CONSTANT _RGL-OPEN-IOR CONSTANT _RGL-FD"
        ),
        "_RGL-FD FD.INODE @ D.VNODE @ CONSTANT _RGL-VN",
        "_RGL-FD FD.CUR-LO @ CONSTANT _RGL-INITIAL-CURSOR",
        (
            f'S" {replacement}" _RGL-FD VFS-WRITE? '
            "CONSTANT _RGL-WRITE-IOR CONSTANT _RGL-ACTUAL"
        ),
        "_RGL-FD FD.CUR-LO @ CONSTANT _RGL-CURSOR",
        "_RGL-V V.LAST-IOR @ CONSTANT _RGL-LAST-IOR",
        "_RGL-CTX _EXT4-C.J.WRITER + @ CONSTANT _RGL-WRITER",
        "_RGL-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _RGL-HOMES",
        "_RGL-FD VFS-CLOSE? CONSTANT _RGL-CLOSE-IOR",
        (
            _forth_conjunction(
                [
                    "_RGL-MOUNT-IOR 0=",
                    "_RGL-CLOCK-IOR 0=",
                    "_RGL-PROFILE-SIZE-IOR 0=",
                    "_RGL-PROFILE-BIND-IOR 0=",
                    "_RGL-PROFILE-USED _RGL-PROFILE-SIZE =",
                    "_RGL-OPEN-IOR 0=",
                    f"_RGL-INITIAL-CURSOR {old_size} =",
                    f"_RGL-ACTUAL {expected_actual} =",
                    (
                        "_RGL-WRITE-IOR VFS-IOR-DOMAIN "
                        "VFS-IOR-D-VOLUME ="
                    ),
                    (
                        "_RGL-WRITE-IOR VFS-IOR-REASON "
                        "VFS-R-IO ="
                    ),
                    (
                        "_RGL-WRITE-IOR VFS-IOR-FLAGS "
                        "VFS-IOR-F-PARTIAL VFS-IOR-F-READONLY OR ="
                    ),
                    "_RGL-LAST-IOR _RGL-WRITE-IOR =",
                    f"_RGL-CURSOR {new_size} =",
                    "_RGL-CLOCK-CALLS @ 1 =",
                    f"_RGL-VN VN.SIZE-LO @ {new_size} =",
                    "_RGL-VN VN.SIZE-HI @ 0=",
                    f"_RGL-VN VN.BLOCKS @ {new_blocks} =",
                    "_RGL-WRITER _RGL-PROFILE-BASE =",
                    (
                        "_RGL-WRITER _EXT4-JWR.STATE + @ "
                        "_EXT4-JWR-FAULTED ="
                    ),
                    (
                        "_RGL-WRITER _EXT4-JWR.PHASE + @ "
                        "_EXT4-JWP-CHECKPOINT-HOME ="
                    ),
                    "_RGL-WRITER _EXT4-JWR-VALID?",
                    (
                        "_RGL-WRITER _EXT4-JWR.FAULT + @ "
                        "VFS-IOR-FLAGS VFS-IOR-F-PARTIAL ="
                    ),
                    "_RGL-WRITER _EXT4-JWR.META-ACTIVE + @ 5 =",
                    "_RGL-WRITER _EXT4-JWR.DATA-ACTIVE + @ 1 =",
                    "_RGL-WRITER _EXT4-JWR.REVOKE-ACTIVE + @ 0=",
                    "_RGL-HOMES 3 =",
                    "_RGL-CTX _EXT4-C.J.COMMITTED + @ 1 =",
                    "_RGL-CTX _EXT4-C.RECOVERY + @ 0<>",
                    "_RGL-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0<>",
                    "_RGL-V V.FLAGS @ VFS-F-RO AND 0<>",
                    "_RGL-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                    "_EXT4-MOW-CREDIT @ -5 =",
                    "_XH-ROOT-GROW @ 0<",
                    "_XH-META-CREDIT @ 5 =",
                    f"_XH-CANDIDATE @ {data_candidate} =",
                    f"_XH-LEAF-CANDIDATE @ {leaf_candidate} =",
                    "_XH-EDIT @ _XH-EDIT-GROW-ROOT =",
                    "_XH-ENTRIES @ 1 =",
                    f"_XH-LEAF-MAX @ {leaf_max} =",
                    "_XH-LEAF-FIRST @ 0=",
                    "_XH-PUBLISHED @ 0<",
                    f"_EXT4-WR-NEW-BLOCKS @ {new_blocks} =",
                    f"_EXT4-WR-ACTUAL @ {expected_actual} =",
                    f"_EXT4-MOW-ACTUAL @ {expected_actual} =",
                    "_RGL-CLOSE-IOR 0=",
                    (
                        "_RGL-PROFILE-ARENA ARENA-USED "
                        "_RGL-PROFILE-USED ="
                    ),
                    (
                        "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                        "_EXT4-BYTES-ZERO?"
                    ),
                    "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                    *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                ]
            )
            + ' IF ." EXT4-PUBLIC-EXTENT-ROOT-LEAF-FAULT" THEN'
        ),
    ]


def test_staged_public_extent_root_growth_composes_depth_one_tree(
    staged_public_extent_root_growth_fixture: dict[str, object],
) -> None:
    image = staged_public_extent_root_growth_fixture["image"]
    expected_file = staged_public_extent_root_growth_fixture["expected_file"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert image.is_file()
    assert len(expected_file) == 6 * 1024 + len(
        _STAGED_ALIGNED_APPEND_REPLACEMENT
    )
    assert expected_file.endswith(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    assert staged_public_extent_root_growth_fixture["data_candidate"] == 1354
    assert staged_public_extent_root_growth_fixture["leaf_candidate"] == 1355


def test_staged_public_extent_root_growth_spans_seven_metadata_homes(
    staged_public_extent_root_growth_seven_home_fixture: dict[str, object],
) -> None:
    """Exercise the maximum deduplicated one-leaf allocation topology."""
    fixture = staged_public_extent_root_growth_seven_home_fixture
    image = fixture["image"]
    expected_file = fixture["expected_file"]
    trace = fixture["trace"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(trace, tuple)
    assert image.is_file()
    assert len(expected_file) == 6 * 1024 + len(
        _STAGED_ALIGNED_APPEND_REPLACEMENT
    )
    assert fixture["data_candidate"] == 73988
    assert fixture["leaf_candidate"] == 131333
    assert fixture["bitmap_home"] == 269
    assert fixture["gdt_home"] == 2
    assert fixture["leaf_bitmap_home"] == 131073
    assert fixture["leaf_gdt_home"] == 3
    assert trace.count(("write", 269 * 2, 2)) == 1
    assert trace.count(("write", 2 * 2, 2)) == 1
    assert trace.count(("write", 131073 * 2, 2)) == 1
    assert trace.count(("write", 3 * 2, 2)) == 1


def test_staged_public_extent_root_growth_fills_in_size_hole(
    staged_public_extent_root_growth_prestate: dict[str, object],
    tmp_path: Path,
) -> None:
    """Drive overwrite refusal into a five-home public root transition."""
    geometry = staged_public_extent_root_growth_prestate
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    activation_trace = geometry["activation_trace"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    block_size = geometry["block_size"]
    old_size = geometry["old_size"]
    old_blocks = geometry["old_blocks"]
    generation = geometry["generation"]
    root_generation = geometry["root_generation"]
    links = geometry["links"]
    extent_entries = geometry["extent_entries"]
    data_candidate = geometry["data_candidate"]
    leaf_candidate = geometry["leaf_candidate"]
    expected_file_prefix = geometry["expected_file_prefix"]
    original_blocks = geometry["original_blocks"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(activation_trace, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(block_size, int)
    assert isinstance(old_size, int)
    assert isinstance(old_blocks, int)
    assert isinstance(generation, int)
    assert isinstance(root_generation, int)
    assert isinstance(links, int)
    assert isinstance(extent_entries, tuple)
    assert isinstance(data_candidate, int)
    assert isinstance(leaf_candidate, int)
    assert isinstance(expected_file_prefix, bytes)
    assert isinstance(original_blocks, dict)
    assert generation != root_generation

    replacement = b"ROOT-HOLE"
    block_offset = 321
    write_offset = block_size + block_offset
    expected_data = bytearray(block_size)
    expected_data[
        block_offset : block_offset + len(replacement)
    ] = replacement
    expected_file = (
        expected_file_prefix[:block_size]
        + bytes(expected_data)
        + expected_file_prefix[2 * block_size :]
    )
    expected_file_crc = _crc32c_raw(expected_file)
    new_blocks = old_blocks + 2 * (block_size // 512)
    epoch_ms = 3_000_000_823_456
    seconds, milliseconds = divmod(epoch_ms, 1000)
    nanoseconds = milliseconds * 1_000_000
    leaf_max = (block_size - 12) // 12
    leaf_entries = (
        extent_entries[0],
        (1, 1, data_candidate),
        *extent_entries[1:],
    )
    expected_leaf = bytearray(block_size)
    struct.pack_into(
        "<HHHHI",
        expected_leaf,
        0,
        0xF30A,
        len(leaf_entries),
        leaf_max,
        0,
        root_generation,
    )
    for entry_index, (logical, length, physical) in enumerate(leaf_entries):
        struct.pack_into(
            "<IHHI",
            expected_leaf,
            12 + entry_index * 12,
            logical,
            length,
            physical >> 32,
            physical & 0xFFFF_FFFF,
        )
    expected_leaf[:] = _extent_node_with_checksum(
        superblock,
        inode_number,
        generation,
        expected_leaf,
    )

    media_path = tmp_path / "staged-public-root-growth-hole-fill.img"
    stable_path = tmp_path / "staged-public-root-growth-hole-fill-stable.img"
    try:
        output, trace, media_sha256 = run_recovery_forth(
            path,
            media_path,
            [
                f"CREATE _RH-READ {old_size} ALLOT",
                "CREATE _RH-STAT VFS-STATFS-SIZE ALLOT",
                "VARIABLE _RH-CLOCK-CALLS",
                (
                    ": _RH-NOW ( context -- epoch-ms ior ) "
                    f"DROP 1 _RH-CLOCK-CALLS +! {epoch_ms} 0 ;"
                ),
                "T-ARENA CONSTANT _RH-ARENA",
                (
                    "_RH-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _RH-MOUNT-IOR CONSTANT _RH-V"
                ),
                "_RH-V _EXT4-CTX CONSTANT _RH-CTX",
                (
                    "' _RH-NOW 0 _RH-V EXT4-BIND-WRITE-CLOCK? "
                    "CONSTANT _RH-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_RH-PROFILE", "_RH-V", 5, 1, 0
                ),
                (
                    'S" /fixture/hardlink.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR _RH-V VFS-OPEN? "
                    "CONSTANT _RH-OPEN-IOR CONSTANT _RH-FD"
                ),
                "_RH-FD FD.INODE @ D.VNODE @ CONSTANT _RH-VN",
                "_RH-VN VN.ATIME @ CONSTANT _RH-OLD-ATIME",
                "_RH-VN VN.ATIME-NS @ CONSTANT _RH-OLD-ATIME-NS",
                "_RH-VN VN.GEN @ CONSTANT _RH-OLD-GEN",
                "_RH-VN VN.NLINK @ CONSTANT _RH-OLD-NLINK",
                (
                    "_RH-STAT VFS-STATFS-SIZE _RH-V VFS-STATFS "
                    "CONSTANT _RH-STAT-BEFORE-IOR"
                ),
                "_RH-STAT VSF.BFREE @ CONSTANT _RH-FREE-BEFORE",
                (
                    f"{write_offset} _RH-FD VFS-SEEK? "
                    "CONSTANT _RH-SEEK-IOR"
                ),
                (
                    f'S" {replacement.decode("ascii")}" _RH-FD '
                    "VFS-WRITE? CONSTANT _RH-WRITE-IOR "
                    "CONSTANT _RH-ACTUAL"
                ),
                "_RH-FD FD.CUR-LO @ CONSTANT _RH-CURSOR",
                "_RH-CTX _EXT4-C.J.WRITER + @ CONSTANT _RH-WRITER",
                "_RH-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _RH-HOMES",
                (
                    "_RH-STAT VFS-STATFS-SIZE _RH-V VFS-STATFS "
                    "CONSTANT _RH-STAT-AFTER-IOR"
                ),
                "_RH-STAT VSF.BFREE @ CONSTANT _RH-FREE-AFTER",
                "0 _RH-FD VFS-SEEK? CONSTANT _RH-READ-SEEK-IOR",
                (
                    f"_RH-READ {old_size} _RH-FD VFS-READ? "
                    "CONSTANT _RH-READ-IOR CONSTANT _RH-READ-ACTUAL"
                ),
                "0xFFFFFFFF _EXT4-CRC-START",
                (
                    f"_RH-READ {old_size} _EXT4-CRC-ADD "
                    "CONSTANT _RH-CRC-IOR"
                ),
                "_EXT4-CRC@ CONSTANT _RH-CRC",
                (
                    _forth_conjunction(
                        [
                            "_RH-MOUNT-IOR 0=",
                            "_RH-CLOCK-IOR 0=",
                            "_RH-PROFILE-SIZE-IOR 0=",
                            "_RH-PROFILE-BIND-IOR 0=",
                            "_RH-PROFILE-USED _RH-PROFILE-SIZE =",
                            "_RH-OPEN-IOR 0=",
                            "_RH-SEEK-IOR 0=",
                            "_RH-WRITE-IOR 0=",
                            f"_RH-ACTUAL {len(replacement)} =",
                            (
                                f"_RH-CURSOR "
                                f"{write_offset + len(replacement)} ="
                            ),
                            "_RH-CLOCK-CALLS @ 1 =",
                            f"_RH-VN VN.SIZE-LO @ {old_size} =",
                            "_RH-VN VN.SIZE-HI @ 0=",
                            f"_RH-VN VN.BLOCKS @ {new_blocks} =",
                            "_RH-VN VN.GEN @ _RH-OLD-GEN =",
                            "_RH-VN VN.NLINK @ _RH-OLD-NLINK =",
                            f"_RH-VN VN.MTIME @ {seconds} =",
                            f"_RH-VN VN.MTIME-NS @ {nanoseconds} =",
                            f"_RH-VN VN.CTIME @ {seconds} =",
                            f"_RH-VN VN.CTIME-NS @ {nanoseconds} =",
                            "_RH-VN VN.ATIME @ _RH-OLD-ATIME =",
                            "_RH-VN VN.ATIME-NS @ _RH-OLD-ATIME-NS =",
                            "_RH-STAT-BEFORE-IOR 0=",
                            "_RH-STAT-AFTER-IOR 0=",
                            "_RH-FREE-AFTER _RH-FREE-BEFORE 2 - =",
                            "_RH-HOMES 5 =",
                            "_RH-WRITER _RH-PROFILE-BASE =",
                            "_RH-WRITER _EXT4-JWR-IDLE-CLEAN?",
                            "_EXT4-WR-KIND @ _EXT4-WRK-HOLE-FILL =",
                            "_EXT4-MOW-CREDIT @ -5 =",
                            "_XH-META-CREDIT @ 5 =",
                            "_XH-ROOT-GROW @ 0<",
                            "_XH-EDIT @ _XH-EDIT-GROW-ROOT =",
                            "_XH-INSERT @ 1 =",
                            f"_XH-CANDIDATE @ {data_candidate} =",
                            f"_XH-LEAF-CANDIDATE @ {leaf_candidate} =",
                            "_XH-ENTRIES @ 1 =",
                            f"_XH-LEAF-MAX @ {leaf_max} =",
                            "_XH-LEAF-FIRST @ 0=",
                            "_XH-PUBLISHED @ 0<",
                            "_RH-READ-SEEK-IOR 0=",
                            "_RH-READ-IOR 0=",
                            f"_RH-READ-ACTUAL {old_size} =",
                            "_RH-CRC-IOR 0=",
                            f"_RH-CRC {expected_file_crc} =",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                            *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        ]
                    )
                    + ' IF ." EXT4-PUBLIC-ROOT-GROWTH-HOLE" THEN'
                ),
                "_RH-FD VFS-CLOSE? CONSTANT _RH-CLOSE-IOR",
                "0 _RH-V VFS-UNMOUNT CONSTANT _RH-UNMOUNT-IOR",
                (
                    "_RH-CLOSE-IOR 0= _RH-UNMOUNT-IOR 0= AND "
                    "_RH-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                    "_RH-PROFILE-ARENA ARENA-USED 0= AND "
                    "_RH-PROFILE-ARENA A.PTR @ _RH-PROFILE-BASE = AND "
                    'IF ." EXT4-PUBLIC-ROOT-GROWTH-HOLE-UNMOUNT" THEN'
                ),
            ],
            patches=input_patches,
            capture_media=media_path,
        )
        _assert_emitted(output, "EXT4-PUBLIC-ROOT-GROWTH-HOLE")
        _assert_emitted(output, "EXT4-PUBLIC-ROOT-GROWTH-HOLE-UNMOUNT")
        assert trace[: len(activation_trace)] == activation_trace
        transaction_trace = trace[len(activation_trace) :]
        role_events = tuple(
            event
            for event in transaction_trace
            if event
            in {
                ("write", data_candidate * 2, 2),
                ("write", 259 * 2, 2),
                ("write", 2 * 2, 2),
                ("write", 1 * 2, 2),
                ("write", leaf_candidate * 2, 2),
                ("write", inode_home * 2, 2),
            }
        )
        assert role_events == (
            ("write", data_candidate * 2, 2),
            ("write", 259 * 2, 2),
            ("write", 2 * 2, 2),
            ("write", 1 * 2, 2),
            ("write", leaf_candidate * 2, 2),
            ("write", inode_home * 2, 2),
            ("write", 1 * 2, 2),
        )
        for untouched in original_blocks:
            assert transaction_trace.count(("write", untouched * 2, 2)) == 0

        final_superblock, final_inode, _ = _ext4_inode_record(
            media_path,
            inode_number,
        )
        assert struct.unpack_from("<I", final_superblock, 0x0C)[0] == (
            struct.unpack_from("<I", superblock, 0x0C)[0] - 2
        )
        assert struct.unpack_from("<I", final_inode, 0x04)[0] == old_size
        assert struct.unpack_from("<I", final_inode, 0x1C)[0] == new_blocks
        assert struct.unpack_from("<H", final_inode, 0x1A)[0] == links
        assert struct.unpack_from("<I", final_inode, 0x64)[0] == generation
        assert struct.unpack_from("<HHHHI", final_inode, 0x28) == (
            0xF30A,
            1,
            4,
            1,
            root_generation,
        )
        assert _read_ext4_home(
            media_path,
            leaf_candidate,
            block_size=block_size,
        ) == bytes(expected_leaf)
        assert _read_ext4_home(
            media_path,
            data_candidate,
            block_size=block_size,
        ) == bytes(expected_data)
        assert _ext4_block_allocation_state(
            media_path,
            (data_candidate, leaf_candidate),
        ) == {data_candidate: True, leaf_candidate: True}

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            media_path,
            stable_path,
            expected_file=expected_file,
            expected_epoch_ms=epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=new_blocks,
            prefix="_RH-S",
            marker="EXT4-PUBLIC-ROOT-GROWTH-HOLE-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == media_sha256
    finally:
        media_path.unlink(missing_ok=True)
        stable_path.unlink(missing_ok=True)


def test_staged_public_extent_root_growth_passes_external_oracles(
    staged_public_extent_root_growth_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    image = staged_public_extent_root_growth_fixture["image"]
    expected_file = staged_public_extent_root_growth_fixture["expected_file"]
    inode_number = staged_public_extent_root_growth_fixture["inode_number"]
    leaf_candidate = staged_public_extent_root_growth_fixture["leaf_candidate"]
    extent_entries = staged_public_extent_root_growth_fixture["extent_entries"]
    xattr_block = staged_public_extent_root_growth_fixture["xattr_block"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(leaf_candidate, int)
    assert isinstance(extent_entries, tuple)
    assert isinstance(xattr_block, int)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    for target in ("/fixture/payload.txt", "/fixture/hardlink.txt"):
        readback = subprocess.run(
            [str(debugfs), "-R", f"cat {target}", str(image)],
            env=env,
            capture_output=True,
            check=False,
        )
        assert readback.returncode == 0, readback.stdout + readback.stderr
        assert readback.stdout == expected_file

    expected_map = {logical: physical for logical, _, physical in extent_entries}
    for logical in range(7):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/payload.txt {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == expected_map.get(
            logical,
            0,
        )

    stat = subprocess.run(
        [str(debugfs), "-R", "stat /fixture/payload.txt", str(image)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert "Flags: 0x80000" in stat.stdout
    assert re.search(r"Links:\s+2\s+Blockcount:\s+14", stat.stdout)
    assert f"File ACL: {xattr_block}" in stat.stdout
    assert f"(ETB0):{leaf_candidate}" in stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def test_staged_public_extent_root_growth_seven_home_external_oracles(
    staged_public_extent_root_growth_seven_home_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    """Check the maximum topology with independent ext4 tooling."""
    fixture = staged_public_extent_root_growth_seven_home_fixture
    image = fixture["image"]
    expected_file = fixture["expected_file"]
    inode_number = fixture["inode_number"]
    leaf_candidate = fixture["leaf_candidate"]
    extent_entries = fixture["extent_entries"]
    xattr_block = fixture["xattr_block"]
    ballast_inode_number = fixture["ballast_inode_number"]
    ballast_leaf_home = fixture["ballast_leaf_home"]
    prepared_ballast_i_blocks = fixture["prepared_ballast_i_blocks"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(leaf_candidate, int)
    assert isinstance(extent_entries, tuple)
    assert isinstance(xattr_block, int)
    assert isinstance(ballast_inode_number, int)
    assert isinstance(ballast_leaf_home, int)
    assert isinstance(prepared_ballast_i_blocks, int)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    for target in ("/fixture/payload.txt", "/fixture/hardlink.txt"):
        readback = subprocess.run(
            [str(debugfs), "-R", f"cat {target}", str(image)],
            env=env,
            capture_output=True,
            check=False,
        )
        assert readback.returncode == 0, readback.stdout + readback.stderr
        assert readback.stdout == expected_file

    expected_map = {
        logical: physical for logical, _, physical in extent_entries
    }
    for logical in range(7):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/payload.txt {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == expected_map.get(
            logical,
            0,
        )

    stat = subprocess.run(
        [str(debugfs), "-R", "stat /fixture/payload.txt", str(image)],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert re.search(r"Links:\s+2\s+Blockcount:\s+14", stat.stdout)
    assert f"File ACL: {xattr_block}" in stat.stdout
    assert f"(ETB0):{leaf_candidate}" in stat.stdout

    ballast_stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            f"stat <{ballast_inode_number}>",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert ballast_stat.returncode == 0, (
        ballast_stat.stdout + ballast_stat.stderr
    )
    assert "Size: 3072" in ballast_stat.stdout
    assert f"Blockcount: {prepared_ballast_i_blocks}" in ballast_stat.stdout
    assert f"(ETB0):{ballast_leaf_home}" in ballast_stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def test_staged_public_extent_root_growth_refuses_profile_four_without_io(
    staged_public_extent_root_growth_prestate: dict[str, object],
    tmp_path: Path,
) -> None:
    """A four-home profile cannot partially publish five-home root growth."""
    geometry = staged_public_extent_root_growth_prestate
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    block_size = geometry["block_size"]
    old_size = geometry["old_size"]
    old_blocks = geometry["old_blocks"]
    data_candidate = geometry["data_candidate"]
    leaf_candidate = geometry["leaf_candidate"]
    original_blocks = geometry["original_blocks"]
    original_data_candidate = geometry["original_data_candidate"]
    original_leaf_candidate = geometry["original_leaf_candidate"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(block_size, int)
    assert isinstance(old_size, int)
    assert isinstance(old_blocks, int)
    assert isinstance(data_candidate, int)
    assert isinstance(leaf_candidate, int)
    assert isinstance(original_blocks, dict)
    assert isinstance(original_data_candidate, bytes)
    assert isinstance(original_leaf_candidate, bytes)

    replacement = _STAGED_ALIGNED_APPEND_REPLACEMENT.decode("ascii")
    backing = tmp_path / "staged-public-extent-root-profile4.img"
    try:
        output, trace, _ = run_recovery_forth(
            path,
            backing,
            [
                "CREATE _RG4-STAT VFS-STATFS-SIZE ALLOT",
                "VARIABLE _RG4-CLOCK-CALLS",
                (
                    ": _RG4-NOW ( context -- epoch-ms ior ) "
                    "DROP 1 _RG4-CLOCK-CALLS +! 3000000523456 0 ;"
                ),
                "T-ARENA CONSTANT _RG4-ARENA",
                (
                    "_RG4-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _RG4-MOUNT-IOR CONSTANT _RG4-V"
                ),
                "_RG4-V _EXT4-CTX CONSTANT _RG4-CTX",
                (
                    "' _RG4-NOW 0 _RG4-V EXT4-BIND-WRITE-CLOCK? "
                    "CONSTANT _RG4-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_RG4-PROFILE", "_RG4-V", 4, 1, 0
                ),
                (
                    'S" /fixture/hardlink.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                    "_RG4-V VFS-OPEN? "
                    "CONSTANT _RG4-OPEN-IOR CONSTANT _RG4-FD"
                ),
                "_RG4-FD FD.INODE @ D.VNODE @ CONSTANT _RG4-VN",
                "_RG4-FD FD.CUR-LO @ CONSTANT _RG4-INITIAL-CURSOR",
                "_RG4-VN VN.ATIME @ CONSTANT _RG4-OLD-ATIME",
                "_RG4-VN VN.ATIME-NS @ CONSTANT _RG4-OLD-ATIME-NS",
                "_RG4-VN VN.MTIME @ CONSTANT _RG4-OLD-MTIME",
                "_RG4-VN VN.MTIME-NS @ CONSTANT _RG4-OLD-MTIME-NS",
                "_RG4-VN VN.CTIME @ CONSTANT _RG4-OLD-CTIME",
                "_RG4-VN VN.CTIME-NS @ CONSTANT _RG4-OLD-CTIME-NS",
                "_RG4-VN VN.GEN @ CONSTANT _RG4-OLD-GEN",
                "_RG4-VN VN.NLINK @ CONSTANT _RG4-OLD-NLINK",
                (
                    "_RG4-STAT VFS-STATFS-SIZE _RG4-V VFS-STATFS "
                    "CONSTANT _RG4-STAT-BEFORE-IOR"
                ),
                "_RG4-STAT VSF.BFREE @ CONSTANT _RG4-FREE-BEFORE",
                (
                    f'S" {replacement}" _RG4-FD '
                    "VFS-WRITE? CONSTANT _RG4-WRITE-IOR "
                    "CONSTANT _RG4-WRITE-ACTUAL"
                ),
                "_RG4-FD FD.CUR-LO @ CONSTANT _RG4-CURSOR",
                "_RG4-CTX _EXT4-C.J.WRITER + @ CONSTANT _RG4-WRITER",
                "_RG4-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _RG4-HOMES",
                (
                    "_RG4-STAT VFS-STATFS-SIZE _RG4-V VFS-STATFS "
                    "CONSTANT _RG4-STAT-AFTER-IOR"
                ),
                "_RG4-STAT VSF.BFREE @ CONSTANT _RG4-FREE-AFTER",
                (
                    _forth_conjunction(
                        [
                            "_RG4-MOUNT-IOR 0=",
                            "_RG4-CLOCK-IOR 0=",
                            "_RG4-PROFILE-SIZE-IOR 0=",
                            "_RG4-PROFILE-BIND-IOR 0=",
                            "_RG4-PROFILE-USED _RG4-PROFILE-SIZE =",
                            "_RG4-OPEN-IOR 0=",
                            f"_RG4-INITIAL-CURSOR {old_size} =",
                            "_RG4-WRITE-IOR VFS-E-NOSPC =",
                            "_RG4-WRITE-ACTUAL 0=",
                            "_RG4-V V.LAST-IOR @ 0=",
                            f"_RG4-CURSOR {old_size} =",
                            "_RG4-CLOCK-CALLS @ 1 =",
                            f"_RG4-VN VN.SIZE-LO @ {old_size} =",
                            "_RG4-VN VN.SIZE-HI @ 0=",
                            f"_RG4-VN VN.BLOCKS @ {old_blocks} =",
                            "_RG4-VN VN.GEN @ _RG4-OLD-GEN =",
                            "_RG4-VN VN.NLINK @ _RG4-OLD-NLINK =",
                            "_RG4-VN VN.ATIME @ _RG4-OLD-ATIME =",
                            "_RG4-VN VN.ATIME-NS @ _RG4-OLD-ATIME-NS =",
                            "_RG4-VN VN.MTIME @ _RG4-OLD-MTIME =",
                            "_RG4-VN VN.MTIME-NS @ _RG4-OLD-MTIME-NS =",
                            "_RG4-VN VN.CTIME @ _RG4-OLD-CTIME =",
                            "_RG4-VN VN.CTIME-NS @ _RG4-OLD-CTIME-NS =",
                            "_RG4-STAT-BEFORE-IOR 0=",
                            "_RG4-STAT-AFTER-IOR 0=",
                            "_RG4-FREE-AFTER _RG4-FREE-BEFORE =",
                            "_RG4-WRITER _RG4-PROFILE-BASE =",
                            "_RG4-WRITER _EXT4-JWR-IDLE-CLEAN?",
                            "_RG4-HOMES 0=",
                            "_EXT4-MOW-CREDIT @ -5 =",
                            "_XH-ROOT-GROW @ 0<",
                            "_XH-META-CREDIT @ 5 =",
                            f"_XH-CANDIDATE @ {data_candidate} =",
                            f"_XH-LEAF-CANDIDATE @ {leaf_candidate} =",
                            "_EXT4-WR-ACTUAL @ 0=",
                            "_EXT4-MOW-ACTUAL @ 0=",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                            *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        ]
                    )
                    + ' IF ." EXT4-PUBLIC-EXTENT-ROOT-PROFILE4" THEN'
                ),
                "_RG4-FD VFS-CLOSE? CONSTANT _RG4-CLOSE-IOR",
                "0 _RG4-V VFS-UNMOUNT CONSTANT _RG4-UNMOUNT-IOR",
                (
                    "_RG4-CLOSE-IOR 0= _RG4-UNMOUNT-IOR 0= AND "
                    "_RG4-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                    "_RG4-PROFILE-ARENA ARENA-USED 0= AND "
                    "_RG4-PROFILE-ARENA A.PTR @ _RG4-PROFILE-BASE = AND "
                    'IF ." EXT4-PUBLIC-EXTENT-ROOT-PROFILE4-UNMOUNT" THEN'
                ),
            ],
            patches=input_patches,
            capture_media=backing,
        )
        _assert_emitted(output, "EXT4-PUBLIC-EXTENT-ROOT-PROFILE4")
        _assert_emitted(output, "EXT4-PUBLIC-EXTENT-ROOT-PROFILE4-UNMOUNT")
        assert trace == ()
        final_superblock, final_inode, _ = _ext4_inode_record(
            backing,
            inode_number,
        )
        assert final_superblock == superblock
        assert final_inode == inode
        assert _ext4_block_allocation_state(
            backing,
            (data_candidate, leaf_candidate),
        ) == {data_candidate: False, leaf_candidate: False}
        assert _read_ext4_home(
            backing,
            data_candidate,
            block_size=block_size,
        ) == original_data_candidate
        assert _read_ext4_home(
            backing,
            leaf_candidate,
            block_size=block_size,
        ) == original_leaf_candidate
        for physical, original in original_blocks.items():
            assert _read_ext4_home(
                backing,
                physical,
                block_size=block_size,
            ) == original
        assert _read_ext4_home(
            backing,
            inode_home,
            block_size=block_size,
        )[0x100:0x200] == inode
    finally:
        backing.unlink(missing_ok=True)


def test_staged_public_extent_root_growth_refuses_single_free_block_without_io(
    staged_public_extent_root_growth_prestate: dict[str, object],
    tmp_path: Path,
) -> None:
    """Require a distinct leaf block after selecting the sole free block."""
    geometry = staged_public_extent_root_growth_prestate
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    block_size = geometry["block_size"]
    old_size = geometry["old_size"]
    old_blocks = geometry["old_blocks"]
    data_candidate = geometry["data_candidate"]
    original_blocks = geometry["original_blocks"]
    original_data_candidate = geometry["original_data_candidate"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(block_size, int)
    assert isinstance(old_size, int)
    assert isinstance(old_blocks, int)
    assert isinstance(data_candidate, int)
    assert isinstance(original_blocks, dict)
    assert isinstance(original_data_candidate, bytes)

    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_count = struct.unpack_from("<I", superblock, 0x04)[0] | (
        struct.unpack_from("<I", superblock, 0x150)[0] << 32
    )
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    descriptor_size = struct.unpack_from("<H", superblock, 0xFE)[0]
    descriptors_per_block = block_size // descriptor_size
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    group_count = (
        blocks_count - first_data + blocks_per_group - 1
    ) // blocks_per_group
    candidate_group, candidate_index = divmod(
        data_candidate - first_data,
        blocks_per_group,
    )
    assert block_size == 1024
    assert group_count == 8
    assert descriptor_size == 64
    assert descriptors_per_block == 16
    assert (candidate_group, candidate_index) == (0, 1353)

    prepared_gdt = bytearray(
        _patched_ext4_home(
            path,
            input_patches,
            2,
            block_size=block_size,
        )
    )
    bitmap_patches: list[tuple[int, bytes]] = []
    expected_bitmaps: dict[int, bytes] = {}
    for group in range(group_count):
        descriptor_offset = group * descriptor_size
        descriptor = bytearray(
            prepared_gdt[
                descriptor_offset : descriptor_offset + descriptor_size
            ]
        )
        bitmap_home = struct.unpack_from("<I", descriptor, 0x00)[0] | (
            struct.unpack_from("<I", descriptor, 0x20)[0] << 32
        )
        assert bitmap_home > 0
        bitmap = bytearray(bytes((0xFF,)) * block_size)
        expected_free = 0
        if group == candidate_group:
            bitmap[candidate_index // 8] &= ~(
                1 << (candidate_index % 8)
            )
            expected_free = 1
        bitmap_checksum = _crc32c_raw(bitmap, seed)
        flags = struct.unpack_from("<H", descriptor, 0x12)[0]
        struct.pack_into("<H", descriptor, 0x12, flags & ~0x02)
        struct.pack_into("<H", descriptor, 0x0C, expected_free)
        struct.pack_into("<H", descriptor, 0x2C, 0)
        struct.pack_into(
            "<H", descriptor, 0x18, bitmap_checksum & 0xFFFF
        )
        struct.pack_into(
            "<H", descriptor, 0x38, bitmap_checksum >> 16
        )
        descriptor[:] = _group_descriptor_with_checksum(
            superblock,
            descriptor,
            group,
        )
        prepared_gdt[
            descriptor_offset : descriptor_offset + descriptor_size
        ] = descriptor
        bitmap_patches.append((bitmap_home * block_size, bytes(bitmap)))
        expected_bitmaps[bitmap_home] = bytes(bitmap)

    prepared_super = bytearray(superblock)
    struct.pack_into("<I", prepared_super, 0x0C, 1)
    struct.pack_into("<I", prepared_super, 0x158, 0)
    prepared_super[:] = _ext4_super_with_checksum(prepared_super)
    prepared_patches = input_patches + (
        (1024, bytes(prepared_super)),
        (2 * block_size, bytes(prepared_gdt)),
        *bitmap_patches,
    )

    backing = tmp_path / "staged-public-root-growth-single-free.img"
    try:
        output, trace, _ = run_recovery_forth(
            path,
            backing,
            [
                "CREATE _R1-STAT VFS-STATFS-SIZE ALLOT",
                "VARIABLE _R1-CLOCK-CALLS",
                (
                    ": _R1-NOW ( context -- epoch-ms ior ) "
                    "DROP 1 _R1-CLOCK-CALLS +! 3000000923456 0 ;"
                ),
                "T-ARENA CONSTANT _R1-ARENA",
                (
                    "_R1-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _R1-MOUNT-IOR CONSTANT _R1-V"
                ),
                "_R1-V _EXT4-CTX CONSTANT _R1-CTX",
                (
                    "' _R1-NOW 0 _R1-V EXT4-BIND-WRITE-CLOCK? "
                    "CONSTANT _R1-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_R1-PROFILE", "_R1-V", 5, 1, 0
                ),
                (
                    'S" /fixture/hardlink.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                    "_R1-V VFS-OPEN? "
                    "CONSTANT _R1-OPEN-IOR CONSTANT _R1-FD"
                ),
                "_R1-FD FD.INODE @ D.VNODE @ CONSTANT _R1-VN",
                "_R1-FD FD.CUR-LO @ CONSTANT _R1-INITIAL-CURSOR",
                "_R1-VN VN.MTIME @ CONSTANT _R1-OLD-MTIME",
                "_R1-VN VN.MTIME-NS @ CONSTANT _R1-OLD-MTIME-NS",
                "_R1-VN VN.CTIME @ CONSTANT _R1-OLD-CTIME",
                "_R1-VN VN.CTIME-NS @ CONSTANT _R1-OLD-CTIME-NS",
                (
                    "_R1-STAT VFS-STATFS-SIZE _R1-V VFS-STATFS "
                    "CONSTANT _R1-STAT-BEFORE-IOR"
                ),
                "_R1-STAT VSF.BFREE @ CONSTANT _R1-FREE-BEFORE",
                (
                    f'S" {_STAGED_ALIGNED_APPEND_REPLACEMENT.decode("ascii")}" '
                    "_R1-FD VFS-WRITE? CONSTANT _R1-WRITE-IOR "
                    "CONSTANT _R1-ACTUAL"
                ),
                "_R1-FD FD.CUR-LO @ CONSTANT _R1-CURSOR",
                "_R1-CTX _EXT4-C.J.WRITER + @ CONSTANT _R1-WRITER",
                "_R1-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _R1-HOMES",
                (
                    "_R1-STAT VFS-STATFS-SIZE _R1-V VFS-STATFS "
                    "CONSTANT _R1-STAT-AFTER-IOR"
                ),
                "_R1-STAT VSF.BFREE @ CONSTANT _R1-FREE-AFTER",
                (
                    _forth_conjunction(
                        [
                            "_R1-MOUNT-IOR 0=",
                            "_R1-CLOCK-IOR 0=",
                            "_R1-PROFILE-SIZE-IOR 0=",
                            "_R1-PROFILE-BIND-IOR 0=",
                            "_R1-PROFILE-USED _R1-PROFILE-SIZE =",
                            "_R1-OPEN-IOR 0=",
                            f"_R1-INITIAL-CURSOR {old_size} =",
                            "_R1-WRITE-IOR VFS-E-NOSPC =",
                            "_R1-ACTUAL 0=",
                            "_R1-V V.LAST-IOR @ 0=",
                            f"_R1-CURSOR {old_size} =",
                            "_R1-CLOCK-CALLS @ 1 =",
                            f"_R1-VN VN.SIZE-LO @ {old_size} =",
                            "_R1-VN VN.SIZE-HI @ 0=",
                            f"_R1-VN VN.BLOCKS @ {old_blocks} =",
                            "_R1-VN VN.MTIME @ _R1-OLD-MTIME =",
                            "_R1-VN VN.MTIME-NS @ _R1-OLD-MTIME-NS =",
                            "_R1-VN VN.CTIME @ _R1-OLD-CTIME =",
                            "_R1-VN VN.CTIME-NS @ _R1-OLD-CTIME-NS =",
                            "_R1-STAT-BEFORE-IOR 0=",
                            "_R1-STAT-AFTER-IOR 0=",
                            "_R1-FREE-BEFORE 1 =",
                            "_R1-FREE-AFTER _R1-FREE-BEFORE =",
                            "_R1-WRITER _R1-PROFILE-BASE =",
                            "_R1-WRITER _EXT4-JWR-IDLE-CLEAN?",
                            "_R1-HOMES 0=",
                            "_EXT4-MOW-CREDIT @ 0=",
                            "_XH-META-CREDIT @ 0=",
                            "_XH-ROOT-GROW @ 0<",
                            "_XH-EDIT @ _XH-EDIT-GROW-ROOT =",
                            f"_XH-CANDIDATE @ {data_candidate} =",
                            "_XH-LEAF-CANDIDATE @ 0=",
                            "_EXT4-FFB-EXCLUDE-ACTIVE @ 0<",
                            "_EXT4-WR-ACTUAL @ 0=",
                            "_EXT4-MOW-ACTUAL @ 0=",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                            *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        ]
                    )
                    + ' IF ." EXT4-PUBLIC-ROOT-GROWTH-SINGLE-FREE" THEN'
                ),
                "_R1-FD VFS-CLOSE? CONSTANT _R1-CLOSE-IOR",
                "0 _R1-V VFS-UNMOUNT CONSTANT _R1-UNMOUNT-IOR",
                (
                    "_R1-CLOSE-IOR 0= _R1-UNMOUNT-IOR 0= AND "
                    "_R1-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                    "_R1-PROFILE-ARENA ARENA-USED 0= AND "
                    "_R1-PROFILE-ARENA A.PTR @ _R1-PROFILE-BASE = AND "
                    'IF ." EXT4-PUBLIC-ROOT-GROWTH-SINGLE-UNMOUNT" THEN'
                ),
            ],
            patches=prepared_patches,
            capture_media=backing,
        )
        _assert_emitted(output, "EXT4-PUBLIC-ROOT-GROWTH-SINGLE-FREE")
        _assert_emitted(output, "EXT4-PUBLIC-ROOT-GROWTH-SINGLE-UNMOUNT")
        assert trace == ()
        final_superblock, final_inode, _ = _ext4_inode_record(
            backing,
            inode_number,
        )
        assert final_superblock == bytes(prepared_super)
        assert final_inode == inode
        assert _read_ext4_home(
            backing,
            2,
            block_size=block_size,
        ) == bytes(prepared_gdt)
        for bitmap_home, expected_bitmap in expected_bitmaps.items():
            assert _read_ext4_home(
                backing,
                bitmap_home,
                block_size=block_size,
            ) == expected_bitmap
        assert _read_ext4_home(
            backing,
            data_candidate,
            block_size=block_size,
        ) == original_data_candidate
        for physical, original in original_blocks.items():
            assert _read_ext4_home(
                backing,
                physical,
                block_size=block_size,
            ) == original
        assert _read_ext4_home(
            backing,
            inode_home,
            block_size=block_size,
        )[0x100:0x200] == inode
    finally:
        backing.unlink(missing_ok=True)


def test_typed_extent_root_growth_measures_six_shared_gdt_homes(
    staged_public_extent_root_growth_prestate: dict[str, object],
    tmp_path: Path,
) -> None:
    """Compose two bitmap edits through one retained primary-GDT image."""
    geometry = staged_public_extent_root_growth_prestate
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    inode_block_offset = geometry["inode_block_offset"]
    inode_size = geometry["inode_size"]
    block_size = geometry["block_size"]
    old_size = geometry["old_size"]
    old_blocks = geometry["old_blocks"]
    generation = geometry["generation"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(inode_block_offset, int)
    assert isinstance(inode_size, int)
    assert isinstance(block_size, int)
    assert isinstance(old_size, int)
    assert isinstance(old_blocks, int)
    assert isinstance(generation, int)

    ballast_inode_number = 17
    _, ballast_inode, ballast_inode_offset = _ext4_inode_record(
        path,
        ballast_inode_number,
    )
    ballast_inode_home, ballast_inode_block_offset = divmod(
        ballast_inode_offset,
        block_size,
    )
    assert ballast_inode_home == 279
    assert ballast_inode_block_offset == 0
    assert struct.unpack_from("<I", ballast_inode, 0x04)[0] == 3 * block_size
    assert struct.unpack_from("<I", ballast_inode, 0x1C)[0] == 4
    assert struct.unpack_from("<HHHH", ballast_inode, 0x28) == (
        0xF30A,
        2,
        4,
        0,
    )
    assert struct.unpack_from("<IHHI", ballast_inode, 0x34) == (
        0,
        1,
        0,
        1348,
    )
    assert struct.unpack_from("<IHHI", ballast_inode, 0x40) == (
        2,
        1,
        0,
        1350,
    )

    data_candidate = 1354
    leaf_candidate = 8451
    ballast_start = 1355
    ballast_blocks = 8192 - ballast_start + 1
    assert ballast_blocks == 6838
    base_patch_map = dict(input_patches)
    base_patch_map[ballast_inode_offset] = ballast_inode
    ballast_patches, ballast_ranges = _allocate_unlinked_extent_ranges(
        path,
        protocol="modern",
        extent_specs=((3, ballast_blocks, True),),
        inode_number=ballast_inode_number,
        physical_starts=(ballast_start,),
        base_patches=tuple(base_patch_map.items()),
    )
    assert ballast_ranges == ((ballast_start, ballast_blocks),)
    patch_map = dict(ballast_patches)
    staged_superblock = patch_map[1024]

    patched_ballast_inode = bytearray(ballast_inode)
    struct.pack_into("<H", patched_ballast_inode, 0x2A, 3)
    struct.pack_into(
        "<IHHI",
        patched_ballast_inode,
        0x4C,
        3,
        0x8000 + ballast_blocks,
        0,
        ballast_start,
    )
    ballast_i_blocks = 4 + ballast_blocks * (block_size // 512)
    assert ballast_i_blocks == 13680
    struct.pack_into("<I", patched_ballast_inode, 0x1C, ballast_i_blocks)
    patched_ballast_inode[:] = _inode_with_checksum(
        staged_superblock,
        ballast_inode_number,
        patched_ballast_inode,
    )
    patch_map[ballast_inode_offset] = bytes(patched_ballast_inode)
    original_data_candidate = bytes((0xA5,)) * block_size
    original_leaf_candidate = bytes((0x3C,)) * block_size
    patch_map[data_candidate * block_size] = original_data_candidate
    patch_map[leaf_candidate * block_size] = original_leaf_candidate
    staged_patches = tuple(patch_map.items())

    first_data = struct.unpack_from("<I", staged_superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", staged_superblock, 0x20)[0]
    descriptor_size = struct.unpack_from("<H", staged_superblock, 0xFE)[0]
    seed = struct.unpack_from("<I", staged_superblock, 0x270)[0]
    assert first_data == 1
    assert blocks_per_group == 8192
    assert descriptor_size == 64
    data_group, data_index = divmod(
        data_candidate - first_data,
        blocks_per_group,
    )
    leaf_group, leaf_index = divmod(
        leaf_candidate - first_data,
        blocks_per_group,
    )
    assert (data_group, data_index) == (0, 1353)
    assert (leaf_group, leaf_index) == (1, 258)
    bitmap_homes = (259, 260)
    gdt_home = 2
    super_home = 1

    initial_bitmaps = tuple(
        bytearray(
            _patched_ext4_home(
                path,
                staged_patches,
                home,
                block_size=block_size,
            )
        )
        for home in bitmap_homes
    )
    for bitmap, index in zip(
        initial_bitmaps,
        (data_index, leaf_index),
        strict=True,
    ):
        assert not bitmap[index // 8] & (1 << (index % 8))
    assert sum(
        not initial_bitmaps[0][index // 8] & (1 << (index % 8))
        for index in range(blocks_per_group)
    ) == 1
    expected_bitmaps = tuple(bytearray(bitmap) for bitmap in initial_bitmaps)
    for bitmap, index in zip(
        expected_bitmaps,
        (data_index, leaf_index),
        strict=True,
    ):
        bitmap[index // 8] |= 1 << (index % 8)

    initial_gdt = _patched_ext4_home(
        path,
        staged_patches,
        gdt_home,
        block_size=block_size,
    )
    expected_gdt = bytearray(initial_gdt)
    group_free_before: list[int] = []
    for group, bitmap in zip(
        (data_group, leaf_group),
        expected_bitmaps,
        strict=True,
    ):
        descriptor_offset = group * descriptor_size
        descriptor = bytearray(
            expected_gdt[
                descriptor_offset : descriptor_offset + descriptor_size
            ]
        )
        free_before = struct.unpack_from("<H", descriptor, 0x0C)[0] | (
            struct.unpack_from("<H", descriptor, 0x2C)[0] << 16
        )
        group_free_before.append(free_before)
        assert free_before > 0
        free_after = free_before - 1
        struct.pack_into("<H", descriptor, 0x0C, free_after & 0xFFFF)
        struct.pack_into("<H", descriptor, 0x2C, free_after >> 16)
        bitmap_checksum = _crc32c_raw(bitmap, seed)
        struct.pack_into("<H", descriptor, 0x18, bitmap_checksum & 0xFFFF)
        struct.pack_into("<H", descriptor, 0x38, bitmap_checksum >> 16)
        descriptor[:] = _group_descriptor_with_checksum(
            staged_superblock,
            descriptor,
            group,
        )
        expected_gdt[
            descriptor_offset : descriptor_offset + descriptor_size
        ] = descriptor
    assert group_free_before[0] == 1

    expected_super = bytearray(staged_superblock)
    free_blocks_before = struct.unpack_from("<I", expected_super, 0x0C)[0]
    struct.pack_into("<I", expected_super, 0x0C, free_blocks_before - 2)
    expected_super[:] = _ext4_super_with_checksum(expected_super)

    leaf_entries = (
        (0, 1, 1346),
        (2, 1, 1352),
        (3, 1, data_candidate),
        (4, 1, 1353),
        (5, 1, 1351),
    )
    leaf_max = (block_size - 12) // 12
    root_generation = struct.unpack_from("<I", inode, 0x30)[0]
    expected_leaf = bytearray(block_size)
    struct.pack_into(
        "<HHHHI",
        expected_leaf,
        0,
        0xF30A,
        len(leaf_entries),
        leaf_max,
        0,
        root_generation,
    )
    for index, (logical, length, physical) in enumerate(leaf_entries):
        struct.pack_into(
            "<IHHI",
            expected_leaf,
            12 + index * 12,
            logical,
            length,
            physical >> 32,
            physical & 0xFFFF_FFFF,
        )
    expected_leaf[:] = _extent_node_with_checksum(
        staged_superblock,
        inode_number,
        generation,
        expected_leaf,
    )

    seconds = 3_000_000_777
    nanoseconds = 456_000_000
    expected_inode = bytearray(inode)
    struct.pack_into("<I", expected_inode, 0x1C, old_blocks + 4)
    expected_inode[0x28:0x64] = bytes(60)
    struct.pack_into(
        "<HHHHI",
        expected_inode,
        0x28,
        0xF30A,
        1,
        4,
        1,
        root_generation,
    )
    struct.pack_into(
        "<IIHH",
        expected_inode,
        0x34,
        0,
        leaf_candidate,
        0,
        0,
    )
    original_inode_home = _patched_ext4_home(
        path,
        staged_patches,
        inode_home,
        block_size=block_size,
    )
    expected_inode_home = _staged_write_timestamped_inode_home(
        staged_superblock,
        expected_inode,
        original_inode_home,
        inode_number=inode_number,
        inode_block_offset=inode_block_offset,
        epoch_ms=seconds * 1000 + nanoseconds // 1_000_000,
        expected_size=old_size,
    )
    expected_data = b"MIDDLE" + bytes(block_size - len(b"MIDDLE"))
    expected_meta_crcs = tuple(
        _crc32c_raw(image)
        for image in (
            expected_bitmaps[0],
            expected_gdt,
            expected_super,
            expected_leaf,
            expected_bitmaps[1],
            expected_inode_home,
        )
    )
    expected_data_crc = _crc32c_raw(expected_data)

    media_path = tmp_path / "typed-extent-root-growth-six-homes.img"
    output, trace, _ = run_recovery_forth(
        path,
        media_path,
        [
            "T-ARENA CONSTANT _S6-ARENA",
            (
                "_S6-ARENA T-VOLUME EXT4-NEW "
                "CONSTANT _S6-MOUNT-IOR CONSTANT _S6-V"
            ),
            "_S6-V _EXT4-CTX CONSTANT _S6-CTX",
            (
                "6 1 0 _S6-CTX _EXT4-JWR-ALLOCATE-MOUNT "
                "CONSTANT _S6-WRITER-IOR CONSTANT _S6-WRITER"
            ),
            "_S6-ARENA ARENA-USED CONSTANT _S6-USED-BEFORE",
            (
                "6 1 0 _S6-WRITER _EXT4-JTX-BEGIN "
                "CONSTANT _S6-BEGIN-IOR CONSTANT _S6-TX"
            ),
            "DEPTH CONSTANT _S6-DEPTH-BEFORE",
            (
                f'S" MIDDLE" {3 * block_size} {inode_number} '
                f"{generation} {seconds} {nanoseconds} _S6-TX "
                "_EXT4-JTX-STAGE-REGULAR-ONEBLOCK-HOLE-FILL "
                "CONSTANT _S6-STAGE-IOR"
            ),
            "DEPTH CONSTANT _S6-DEPTH-AFTER",
            "3 _S6-WRITER _EXT4-JWR-META-IMAGE CONSTANT _S6-LEAF",
            "5 _S6-WRITER _EXT4-JWR-META-IMAGE CONSTANT _S6-INODE-HOME",
            (
                f"_S6-INODE-HOME {inode_block_offset} + "
                "CONSTANT _S6-INODE"
            ),
            (
                _forth_conjunction(
                    [
                        "_S6-MOUNT-IOR 0=",
                        "_S6-WRITER-IOR 0=",
                        "_S6-BEGIN-IOR 0=",
                        "_S6-STAGE-IOR 0=",
                        "_S6-DEPTH-BEFORE _S6-DEPTH-AFTER =",
                        "_XH-META-CREDIT @ 6 =",
                        "_XH-ROOT-GROW @ 0<",
                        "_XH-EDIT @ _XH-EDIT-GROW-ROOT =",
                        "_XH-INSERT @ 2 =",
                        f"_XH-CANDIDATE @ {data_candidate} =",
                        "_XH-CANDIDATE-GROUP @ 0=",
                        f"_XH-LEAF-CANDIDATE @ {leaf_candidate} =",
                        "_XH-LEAF-GROUP @ 1 =",
                        "_XH-BITMAP-HOME @ 259 =",
                        "_XH-LEAF-BITMAP-HOME @ 260 =",
                        "_XH-GDT-HOME @ 2 =",
                        "_XH-LEAF-GDT-HOME @ 2 =",
                        "_XH-ENTRIES @ 1 =",
                        f"_XH-LEAF-MAX @ {leaf_max} =",
                        "_XH-LEAF-FIRST @ 0=",
                        "_XH-PUBLISHED @ 0<",
                        "_S6-WRITER _EXT4-JWR.META-USED + @ 6 =",
                        "_S6-WRITER _EXT4-JWR.META-ACTIVE + @ 6 =",
                        "_S6-WRITER _EXT4-JWR.DATA-USED + @ 1 =",
                        "_S6-WRITER _EXT4-JWR.DATA-ACTIVE + @ 1 =",
                        "_S6-WRITER _EXT4-JWR.REVOKE-USED + @ 0=",
                        "_S6-WRITER _EXT4-JWR.REVOKE-ACTIVE + @ 0=",
                        "_S6-WRITER _EXT4-JTX-TABLES-VALID?",
                        *(
                            f"{index} _S6-WRITER "
                            f"_EXT4-JWR-META-ENTRY @ {home} ="
                            for index, home in enumerate(
                                (259, 2, 1, leaf_candidate, 260, inode_home)
                            )
                        ),
                        (
                            "0 _S6-WRITER _EXT4-JWR-DATA-ENTRY @ "
                            f"{data_candidate} ="
                        ),
                        *(
                            f"{index} _S6-WRITER _EXT4-JWR-META-IMAGE "
                            "_S6-WRITER _EXT4-JTX-IMAGE-CRC 0= SWAP "
                            f"{crc} = AND"
                            for index, crc in enumerate(expected_meta_crcs)
                        ),
                        (
                            "0 _S6-WRITER _EXT4-JWR-DATA-IMAGE "
                            "_S6-WRITER _EXT4-JTX-IMAGE-CRC 0= SWAP "
                            f"{expected_data_crc} = AND"
                        ),
                        "_S6-LEAF W@ _EXT4-EXTENT-MAGIC =",
                        f"_S6-LEAF 2 + W@ {len(leaf_entries)} =",
                        f"_S6-LEAF 4 + W@ {leaf_max} =",
                        "_S6-LEAF 6 + W@ 0=",
                        "_S6-INODE _EXT4-I.BLOCKS-LO + L@ 14 =",
                        "_S6-INODE _EXT4-I.BLOCKS-HI + W@ 0=",
                        f"_S6-INODE _EXT4-I.SIZE-LO + L@ {old_size} =",
                        "_S6-INODE _EXT4-I.SIZE-HI + L@ 0=",
                        (
                            "_S6-INODE _EXT4-I.BLOCK + 6 + W@ 1 ="
                        ),
                        "_S6-CTX _EXT4-C.J.HOME-WRITES + @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                    ]
                )
                + ' IF ." EXT4-TYPED-ROOT-GROWTH-SIX-HOMES" THEN'
            ),
            "_S6-TX _EXT4-JTX-ABORT CONSTANT _S6-ABORT-IOR",
            (
                _forth_conjunction(
                    [
                        "_S6-ABORT-IOR 0=",
                        "_S6-WRITER _EXT4-JWR-IDLE-CLEAN?",
                        "_S6-WRITER _EXT4-JWR-VALID?",
                        "_S6-WRITER _EXT4-JWR.META-USED + @ 0=",
                        "_S6-WRITER _EXT4-JWR.DATA-USED + @ 0=",
                        "_S6-WRITER _EXT4-JWR.REVOKE-USED + @ 0=",
                        "_S6-ARENA ARENA-USED _S6-USED-BEFORE =",
                        (
                            "_S6-WRITER _EXT4-JWR.META-IMAGES + @ "
                            f"{6 * block_size} _EXT4-BYTES-ZERO?"
                        ),
                        (
                            "_S6-WRITER _EXT4-JWR.DATA-IMAGES + @ "
                            f"{block_size} _EXT4-BYTES-ZERO?"
                        ),
                        (
                            "_S6-WRITER _EXT4-JWR.SCRATCH-A + @ "
                            f"{block_size} _EXT4-BYTES-ZERO?"
                        ),
                        (
                            "_S6-WRITER _EXT4-JWR.SCRATCH-B + @ "
                            f"{block_size} _EXT4-BYTES-ZERO?"
                        ),
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                    ]
                )
                + ' IF ." EXT4-TYPED-ROOT-GROWTH-SIX-ABORTED" THEN'
            ),
            "0 _S6-V VFS-UNMOUNT CONSTANT _S6-UNMOUNT-IOR",
            (
                "_S6-UNMOUNT-IOR 0= _S6-V V.LIFECYCLE @ "
                "VFS-L-UNMOUNTED = AND "
                'IF ." EXT4-TYPED-ROOT-GROWTH-SIX-UNMOUNTED" THEN'
            ),
        ],
        patches=staged_patches,
        capture_media=media_path,
    )
    _assert_emitted(output, "EXT4-TYPED-ROOT-GROWTH-SIX-HOMES")
    _assert_emitted(output, "EXT4-TYPED-ROOT-GROWTH-SIX-ABORTED")
    _assert_emitted(output, "EXT4-TYPED-ROOT-GROWTH-SIX-UNMOUNTED")
    assert trace == ()
    assert _ext4_block_allocation_state(
        media_path,
        (data_candidate, leaf_candidate),
    ) == {data_candidate: False, leaf_candidate: False}
    assert _read_ext4_home(
        media_path,
        data_candidate,
        block_size=block_size,
    ) == original_data_candidate
    assert _read_ext4_home(
        media_path,
        leaf_candidate,
        block_size=block_size,
    ) == original_leaf_candidate
    assert _read_ext4_home(
        media_path,
        gdt_home,
        block_size=block_size,
    ) == initial_gdt
    assert _read_ext4_home(
        media_path,
        inode_home,
        block_size=block_size,
    ) == original_inode_home


def test_staged_public_extent_root_growth_leaf_tear_replays_tree(
    staged_public_extent_root_growth_prestate: dict[str, object],
    staged_public_extent_root_growth_fixture: dict[str, object],
    writer_activation_fixture: dict[str, object],
    tmp_path: Path,
) -> None:
    """Replay all five metadata homes after the new leaf home tears."""
    geometry = staged_public_extent_root_growth_prestate
    success = staged_public_extent_root_growth_fixture
    path = geometry["path"]
    input_patches = geometry["input_patches"]
    activation_trace = geometry["activation_trace"]
    superblock = geometry["superblock"]
    inode = geometry["inode"]
    inode_number = geometry["inode_number"]
    inode_home = geometry["inode_home"]
    inode_block_offset = geometry["inode_block_offset"]
    inode_size = geometry["inode_size"]
    block_size = geometry["block_size"]
    old_size = geometry["old_size"]
    old_blocks = geometry["old_blocks"]
    data_candidate = geometry["data_candidate"]
    leaf_candidate = geometry["leaf_candidate"]
    original_leaf = geometry["original_leaf_candidate"]
    success_image = success["image"]
    success_trace = success["trace"]
    epoch_ms = success["epoch_ms"]
    expected_file = success["expected_file"]
    dirty_super = writer_activation_fixture["dirty_super"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(activation_trace, tuple)
    assert isinstance(superblock, bytes)
    assert isinstance(inode, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(inode_block_offset, int)
    assert isinstance(inode_size, int)
    assert isinstance(block_size, int)
    assert isinstance(old_size, int)
    assert isinstance(old_blocks, int)
    assert isinstance(data_candidate, int)
    assert isinstance(leaf_candidate, int)
    assert isinstance(original_leaf, bytes)
    assert isinstance(success_image, Path)
    assert isinstance(success_trace, tuple)
    assert isinstance(epoch_ms, int)
    assert isinstance(expected_file, bytes)
    assert isinstance(dirty_super, bytes)

    bitmap_home = 259
    gdt_home = 2
    super_home = 1
    new_blocks = old_blocks + 2 * (block_size // 512)
    new_size = len(expected_file)
    leaf_max = (block_size - 12) // 12
    assert inode_home == 278
    assert data_candidate == 1354
    assert leaf_candidate == 1355
    assert new_blocks == 14
    assert new_size == old_size + len(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    assert success_trace[: len(activation_trace)] == activation_trace

    expected_homes = {
        home: _read_ext4_home(success_image, home, block_size=block_size)
        for home in (
            data_candidate,
            bitmap_home,
            gdt_home,
            super_home,
            leaf_candidate,
            inode_home,
        )
    }
    original_inode_home = _patched_ext4_home(
        path,
        input_patches,
        inode_home,
        block_size=block_size,
    )
    assert original_inode_home[
        inode_block_offset : inode_block_offset + inode_size
    ] == inode
    assert expected_homes[data_candidate] == (
        _STAGED_ALIGNED_APPEND_REPLACEMENT
        + bytes(block_size - len(_STAGED_ALIGNED_APPEND_REPLACEMENT))
    )

    data_ordinals = _write_ordinals_for_ext4_home(
        success_trace,
        data_candidate,
        block_size=block_size,
    )
    bitmap_ordinals = _write_ordinals_for_ext4_home(
        success_trace,
        bitmap_home,
        block_size=block_size,
    )
    gdt_ordinals = _write_ordinals_for_ext4_home(
        success_trace,
        gdt_home,
        block_size=block_size,
    )
    super_ordinals = _write_ordinals_for_ext4_home(
        success_trace,
        super_home,
        block_size=block_size,
    )
    leaf_ordinals = _write_ordinals_for_ext4_home(
        success_trace,
        leaf_candidate,
        block_size=block_size,
    )
    inode_ordinals = _write_ordinals_for_ext4_home(
        success_trace,
        inode_home,
        block_size=block_size,
    )
    assert data_ordinals == (7,)
    assert bitmap_ordinals == (20,)
    assert gdt_ordinals == (21,)
    assert super_ordinals[1] == 22
    assert leaf_ordinals == (23,)
    assert inode_ordinals == (24,)
    leaf_event_index = _trace_event_index_for_ordinal(
        success_trace,
        "write",
        leaf_ordinals[0],
    )
    assert success_trace[leaf_event_index] == (
        "write",
        leaf_candidate * (block_size // 512),
        block_size // 512,
    )

    tear_offset = 13
    expected_leaf = expected_homes[leaf_candidate]
    expected_torn_leaf = (
        expected_leaf[:tear_offset] + original_leaf[tear_offset:]
    )
    assert expected_torn_leaf not in {expected_leaf, original_leaf}

    expected_faulted_super = bytearray(dirty_super)
    expected_super = expected_homes[super_home]
    expected_faulted_super[0x0C:0x10] = expected_super[0x0C:0x10]
    expected_faulted_super[0x158:0x15C] = expected_super[0x158:0x15C]
    expected_faulted_super[:] = _ext4_super_with_checksum(
        expected_faulted_super
    )
    assert bytes(expected_faulted_super) != expected_super

    faulted = tmp_path / "staged-extent-root-leaf-w23-faulted.img"
    recovered = tmp_path / "staged-extent-root-leaf-w23-recovered.img"
    stable = tmp_path / "staged-extent-root-leaf-w23-stable.img"
    try:
        output, failed_trace, _ = run_recovery_forth(
            path,
            faulted,
            _staged_extent_root_growth_leaf_fault_lines(
                epoch_ms=epoch_ms,
                old_size=old_size,
                new_size=new_size,
                new_blocks=new_blocks,
                data_candidate=data_candidate,
                leaf_candidate=leaf_candidate,
                leaf_max=leaf_max,
            ),
            patches=input_patches,
            write_faults_by_ordinal={
                leaf_ordinals[0]: {
                    "stage": "media",
                    "sector_index": 0,
                    "byte_index": tear_offset,
                    "result": STORAGE_RESULT_MEDIA_FAILURE,
                    "command": STORAGE_CMD_WRITE,
                }
            },
            capture_media=faulted,
        )
        _assert_emitted(output, "EXT4-PUBLIC-EXTENT-ROOT-LEAF-FAULT")
        assert failed_trace == success_trace[: leaf_event_index + 1]
        assert _ext4_block_allocation_state(
            faulted,
            (data_candidate, leaf_candidate),
        ) == {data_candidate: True, leaf_candidate: True}
        assert _read_ext4_home(
            faulted,
            data_candidate,
            block_size=block_size,
        ) == expected_homes[data_candidate]
        assert _read_ext4_home(
            faulted,
            bitmap_home,
            block_size=block_size,
        ) == expected_homes[bitmap_home]
        assert _read_ext4_home(
            faulted,
            gdt_home,
            block_size=block_size,
        ) == expected_homes[gdt_home]
        assert _read_ext4_home(
            faulted,
            super_home,
            block_size=block_size,
        ) == bytes(expected_faulted_super)
        assert _read_ext4_home(
            faulted,
            leaf_candidate,
            block_size=block_size,
        ) == expected_torn_leaf
        assert _read_ext4_home(
            faulted,
            inode_home,
            block_size=block_size,
        ) == original_inode_home
        faulted_superblock, faulted_inode, _ = _ext4_inode_record(
            faulted,
            inode_number,
        )
        assert faulted_superblock == bytes(expected_faulted_super)
        assert faulted_inode == inode

        _, recovery_trace, recovery_sha256 = (
            _staged_write_recovery_readback(
                faulted,
                recovered,
                expected_file=expected_file,
                expected_epoch_ms=epoch_ms,
                expected_home_writes=5,
                expected_replayed=True,
                expected_blocks=new_blocks,
                prefix="_RGL-R",
                marker="EXT4-PUBLIC-EXTENT-ROOT-LEAF-RECOVERED",
            )
        )
        assert not _write_ordinals_for_ext4_home(
            recovery_trace,
            data_candidate,
            block_size=block_size,
        )
        replay_role_events = tuple(
            event
            for event in recovery_trace
            if event
            in {
                ("write", bitmap_home * 2, 2),
                ("write", gdt_home * 2, 2),
                ("write", super_home * 2, 2),
                ("write", leaf_candidate * 2, 2),
                ("write", inode_home * 2, 2),
            }
        )
        assert replay_role_events == (
            ("write", bitmap_home * 2, 2),
            ("write", gdt_home * 2, 2),
            ("write", super_home * 2, 2),
            ("write", leaf_candidate * 2, 2),
            ("write", inode_home * 2, 2),
            # Recovery replays five transaction homes, then lands its clean
            # primary-super endpoint as a separate non-replay write.
            ("write", super_home * 2, 2),
        )
        for home, expected in expected_homes.items():
            assert _read_ext4_home(
                recovered,
                home,
                block_size=block_size,
            ) == expected
        assert _ext4_block_allocation_state(
            recovered,
            (data_candidate, leaf_candidate),
        ) == {data_candidate: True, leaf_candidate: True}
        assert recovery_sha256 == _sha256(recovered)

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            recovered,
            stable,
            expected_file=expected_file,
            expected_epoch_ms=epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=new_blocks,
            prefix="_RGL-S",
            marker="EXT4-PUBLIC-EXTENT-ROOT-LEAF-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == recovery_sha256
        for home, expected in expected_homes.items():
            assert _read_ext4_home(
                stable,
                home,
                block_size=block_size,
            ) == expected
    finally:
        faulted.unlink(missing_ok=True)
        recovered.unlink(missing_ok=True)
        stable.unlink(missing_ok=True)


_STAGED_CROSS_TAIL_REPLACEMENT = b"TAILPART" + _STAGED_ALIGNED_APPEND_REPLACEMENT
_STAGED_CROSS_TAIL_FIRST_EPOCH_MS = 3_000_000_123_456
_STAGED_CROSS_TAIL_SECOND_EPOCH_MS = 3_000_000_128_888


@pytest.fixture(scope="session")
def staged_public_cross_tail_exact_fixture(
    writer_activation_fixture: dict[str, object],
    tmp_path_factory: pytest.TempPathFactory,
) -> dict[str, object]:
    """Compose partial-tail RMW and one aligned allocation exactly once."""
    path = writer_activation_fixture["image"]
    source_patches = writer_activation_fixture["source_patches"]
    activation_trace = writer_activation_fixture["success_trace"]
    clean_super = writer_activation_fixture["clean_super"]
    assert isinstance(path, Path)
    assert isinstance(source_patches, tuple)
    assert isinstance(activation_trace, tuple)
    assert isinstance(clean_super, bytes)

    inode_number = 14
    candidate = 1351
    bitmap_home = 259
    gdt_home = 2
    super_home = 1
    superblock, inode, inode_offset = _ext4_inode_record(path, inode_number)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    inode_size = struct.unpack_from("<H", superblock, 0x58)[0]
    inode_home, inode_block_offset = divmod(inode_offset, block_size)
    data_block = _extent_root_physical(inode, 0)
    xattr_block = struct.unpack_from("<I", inode, 0x68)[0]
    canonical_size = struct.unpack_from("<I", inode, 0x04)[0]
    old_blocks = struct.unpack_from("<I", inode, 0x1C)[0]
    old_links = struct.unpack_from("<H", inode, 0x1A)[0]
    old_generation = struct.unpack_from("<I", inode, 0x64)[0]
    free_blocks_before = struct.unpack_from("<I", superblock, 0x0C)[0]
    tail_count = len(b"TAILPART")
    old_size = block_size - tail_count
    replacement = _STAGED_CROSS_TAIL_REPLACEMENT
    allocation_count = len(replacement) - tail_count
    new_size = old_size + len(replacement)
    assert clean_super == superblock
    assert block_size == 1024
    assert inode_size == 256
    assert inode_home == 278
    assert inode_block_offset == 256
    assert data_block == 1346
    assert xattr_block == 1349
    assert canonical_size == 54
    assert old_blocks == 4
    assert old_links == 2
    assert old_generation == 0
    assert 0 < tail_count < block_size
    assert old_size % block_size == block_size - tail_count
    assert allocation_count == len(_STAGED_ALIGNED_APPEND_REPLACEMENT)
    assert 0 < allocation_count <= block_size
    assert old_size + tail_count == block_size
    assert new_size == block_size + allocation_count
    assert struct.unpack_from("<HHHH", inode, 0x28) == (
        0xF30A,
        1,
        4,
        0,
    )
    assert not _ext4_block_allocation_state(path, (candidate,))[candidate]

    patched_inode = bytearray(inode)
    struct.pack_into("<I", patched_inode, 0x04, old_size)
    struct.pack_into("<I", patched_inode, 0x6C, 0)
    patched_inode[:] = _inode_with_checksum(
        superblock, inode_number, patched_inode
    )
    input_patches = source_patches + ((inode_offset, bytes(patched_inode)),)
    original_data = _patched_ext4_home(
        path, input_patches, data_block, block_size=block_size
    )
    original_xattr = _patched_ext4_home(
        path, input_patches, xattr_block, block_size=block_size
    )
    original_inode_home = _patched_ext4_home(
        path, input_patches, inode_home, block_size=block_size
    )
    assert original_data[canonical_size:] == bytes(
        block_size - canonical_size
    )
    assert (
        original_inode_home[
            inode_block_offset : inode_block_offset + inode_size
        ]
        == bytes(patched_inode)
    )

    expected_data = bytearray(original_data)
    expected_data[old_size:block_size] = replacement[:tail_count]
    expected_candidate = (
        replacement[tail_count:] + bytes(block_size - allocation_count)
    )
    expected_file = bytes(expected_data) + replacement[tail_count:]
    first_inode_home = _staged_write_timestamped_inode_home(
        superblock,
        patched_inode,
        original_inode_home,
        inode_number=inode_number,
        inode_block_offset=inode_block_offset,
        epoch_ms=_STAGED_CROSS_TAIL_FIRST_EPOCH_MS,
        expected_size=block_size,
    )

    expected_inode = bytearray(patched_inode)
    struct.pack_into("<I", expected_inode, 0x1C, old_blocks + 2)
    struct.pack_into("<H", expected_inode, 0x2A, 2)
    struct.pack_into(
        "<IHHI", expected_inode, 0x40, 1, 1, 0, candidate
    )
    expected_inode_home = _staged_write_timestamped_inode_home(
        superblock,
        expected_inode,
        original_inode_home,
        inode_number=inode_number,
        inode_block_offset=inode_block_offset,
        epoch_ms=_STAGED_CROSS_TAIL_SECOND_EPOCH_MS,
        expected_size=new_size,
    )

    first_data = struct.unpack_from("<I", superblock, 0x14)[0]
    blocks_per_group = struct.unpack_from("<I", superblock, 0x20)[0]
    seed = struct.unpack_from("<I", superblock, 0x270)[0]
    group, block_index = divmod(candidate - first_data, blocks_per_group)
    assert group == 0
    byte_index, bit_index = divmod(block_index, 8)
    expected_bitmap = bytearray(
        _patched_ext4_home(
            path, input_patches, bitmap_home, block_size=block_size
        )
    )
    assert not expected_bitmap[byte_index] & (1 << bit_index)
    expected_bitmap[byte_index] |= 1 << bit_index
    bitmap_checksum = _crc32c_raw(expected_bitmap, seed)

    expected_gdt = bytearray(
        _patched_ext4_home(
            path, input_patches, gdt_home, block_size=block_size
        )
    )
    descriptor = bytearray(expected_gdt[:64])
    group_free_before = struct.unpack_from("<H", descriptor, 0x0C)[0] | (
        struct.unpack_from("<H", descriptor, 0x2C)[0] << 16
    )
    assert group_free_before > 0
    group_free_after = group_free_before - 1
    struct.pack_into("<H", descriptor, 0x0C, group_free_after & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x2C, group_free_after >> 16)
    struct.pack_into("<H", descriptor, 0x18, bitmap_checksum & 0xFFFF)
    struct.pack_into("<H", descriptor, 0x38, bitmap_checksum >> 16)
    descriptor[:] = _group_descriptor_with_checksum(
        superblock, descriptor, group
    )
    expected_gdt[:64] = descriptor

    expected_super = bytearray(clean_super)
    assert struct.unpack_from("<I", expected_super, 0x158)[0] == 0
    struct.pack_into("<I", expected_super, 0x0C, free_blocks_before - 1)
    expected_super[:] = _ext4_super_with_checksum(expected_super)

    first_seconds, first_milliseconds = divmod(
        _STAGED_CROSS_TAIL_FIRST_EPOCH_MS, 1000
    )
    first_nanoseconds = first_milliseconds * 1_000_000
    second_seconds, second_milliseconds = divmod(
        _STAGED_CROSS_TAIL_SECOND_EPOCH_MS, 1000
    )
    second_nanoseconds = second_milliseconds * 1_000_000
    directory = tmp_path_factory.mktemp("ext4-public-cross-tail-exact")
    media_path = directory / "staged-public-cross-tail-exact.img"
    stable_path = directory / "staged-public-cross-tail-exact-stable.img"
    try:
        output, trace, media_sha256 = run_recovery_forth(
            path,
            media_path,
            [
                "CREATE _CT-STAT VFS-STATFS-SIZE ALLOT",
                (
                    f"CREATE _CT-CLOCK "
                    f"{_STAGED_CROSS_TAIL_FIRST_EPOCH_MS} , "
                    f"{_STAGED_CROSS_TAIL_SECOND_EPOCH_MS} ,"
                ),
                "VARIABLE _CT-CLOCK-CALLS",
                (
                    ": _CT-NOW ( clock -- epoch-ms ior ) "
                    "_CT-CLOCK-CALLS @ CELLS + @ "
                    "1 _CT-CLOCK-CALLS +! 0 ;"
                ),
                "T-ARENA CONSTANT _CT-ARENA",
                (
                    "_CT-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _CT-MOUNT-IOR CONSTANT _CT-V"
                ),
                "_CT-V _EXT4-CTX CONSTANT _CT-CTX",
                (
                    "' _CT-NOW _CT-CLOCK _CT-V "
                    "EXT4-BIND-WRITE-CLOCK? CONSTANT _CT-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_CT-PROFILE", "_CT-V", 4, 1, 0
                ),
                (
                    'S" /fixture/payload.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                    "_CT-V VFS-OPEN? "
                    "CONSTANT _CT-OPEN-IOR CONSTANT _CT-FD"
                ),
                "_CT-FD FD.INODE @ D.VNODE @ CONSTANT _CT-VN",
                "_CT-FD FD.CUR-LO @ CONSTANT _CT-INITIAL-CURSOR",
                (
                    "_CT-STAT VFS-STATFS-SIZE _CT-V VFS-STATFS "
                    "CONSTANT _CT-STAT-BEFORE-IOR"
                ),
                "_CT-STAT VSF.BFREE @ CONSTANT _CT-FREE-BEFORE",
                "0 _CT-FD VFS-SEEK? CONSTANT _CT-SEEK-IOR",
                (
                    f'S" {replacement.decode("ascii")}" _CT-FD '
                    "VFS-WRITE-EXACT CONSTANT _CT-EXACT-IOR"
                ),
                "_CT-FD FD.CUR-LO @ CONSTANT _CT-CURSOR",
                "_EXT4-WR-ACTUAL @ CONSTANT _CT-ACTUAL",
                "_EXT4-MOW-ACTUAL @ CONSTANT _CT-MOW-ACTUAL",
                "_CT-CTX _EXT4-C.J.WRITER + @ CONSTANT _CT-WRITER",
                "_CT-CTX _EXT4-C.J.HOME-WRITES + @ CONSTANT _CT-HOMES",
                (
                    "_CT-STAT VFS-STATFS-SIZE _CT-V VFS-STATFS "
                    "CONSTANT _CT-STAT-AFTER-IOR"
                ),
                "_CT-STAT VSF.BFREE @ CONSTANT _CT-FREE-AFTER",
                (
                    _forth_conjunction(
                        [
                            "_CT-MOUNT-IOR 0=",
                            "_CT-CLOCK-IOR 0=",
                            "_CT-PROFILE-SIZE-IOR 0=",
                            "_CT-PROFILE-BIND-IOR 0=",
                            "_CT-PROFILE-USED _CT-PROFILE-SIZE =",
                            "_CT-OPEN-IOR 0=",
                            f"_CT-INITIAL-CURSOR {old_size} =",
                            "_CT-SEEK-IOR 0=",
                            "_CT-EXACT-IOR 0=",
                            "_CT-V V.LAST-IOR @ 0=",
                            f"_CT-CURSOR {new_size} =",
                            "_CT-CLOCK-CALLS @ 2 =",
                            f"_CT-VN VN.SIZE-LO @ {new_size} =",
                            "_CT-VN VN.SIZE-HI @ 0=",
                            "_CT-VN VN.BLOCKS @ 6 =",
                            f"_CT-VN VN.MTIME @ {second_seconds} =",
                            f"_CT-VN VN.MTIME-NS @ {second_nanoseconds} =",
                            f"_CT-VN VN.CTIME @ {second_seconds} =",
                            f"_CT-VN VN.CTIME-NS @ {second_nanoseconds} =",
                            "_CT-VN VN.FLAGS @ VFS-IF-DIRTY AND 0=",
                            (
                                "_EXT4-WR-KIND @ "
                                "_EXT4-WRK-ALIGNED-APPEND ="
                            ),
                            f"_EXT4-WR-COUNT @ {allocation_count} =",
                            f"_EXT4-WR-OFFSET @ {block_size} =",
                            f"_EXT4-WR-REQUEST-END @ {new_size} =",
                            f"_EXT4-WR-NEW-SIZE @ {new_size} =",
                            "_EXT4-WR-NEW-BLOCKS @ 6 =",
                            f"_EXT4-WR-CHUNK @ {allocation_count} =",
                            f"_CT-ACTUAL {allocation_count} =",
                            f"_CT-MOW-ACTUAL {allocation_count} =",
                            "_EXT4-MOW-CREDIT @ -4 =",
                            "_XH-GROW @ 0<",
                            f"_XH-SIZE @ {block_size} =",
                            f"_XH-NEW-SIZE @ {new_size} =",
                            "_XH-NEW-BLOCKS @ 6 =",
                            "_XH-LOGICAL @ 1 =",
                            "_XH-BLOCK-OFF @ 0=",
                            f"_XH-CANDIDATE @ {candidate} =",
                            "_XH-ENTRIES @ 2 =",
                            "_XH-PUBLISHED @ 0<",
                            "_CT-STAT-BEFORE-IOR 0=",
                            "_CT-STAT-AFTER-IOR 0=",
                            f"_CT-FREE-BEFORE {free_blocks_before} =",
                            "_CT-FREE-AFTER _CT-FREE-BEFORE 1- =",
                            "_CT-HOMES 4 =",
                            "_CT-WRITER _CT-PROFILE-BASE =",
                            "_CT-WRITER _EXT4-JWR-IDLE-CLEAN?",
                            "_CT-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                            "_CT-CTX _EXT4-C.O.ACTIVE + @ 0=",
                            "_CT-CTX _EXT4-C.O.MODERN-ACTIVE + @ 0=",
                            "_CT-CTX _EXT4-C.O.LEGACY-ACTIVE + @ 0=",
                            "_CT-CTX _EXT4-C.O.CLEAR-PENDING + @ 0=",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                        ]
                    )
                    + ' IF ." EXT4-PUBLIC-CROSS-TAIL-EXACT" THEN'
                ),
                "_CT-FD VFS-CLOSE? CONSTANT _CT-CLOSE-IOR",
                "0 _CT-V VFS-UNMOUNT CONSTANT _CT-UNMOUNT-IOR",
                (
                    "_CT-CLOSE-IOR 0= _CT-UNMOUNT-IOR 0= AND "
                    "_CT-V V.LIFECYCLE @ VFS-L-UNMOUNTED = AND "
                    "_CT-PROFILE-ARENA ARENA-USED 0= AND "
                    "_CT-PROFILE-ARENA A.PTR @ _CT-PROFILE-BASE = AND "
                    'IF ." EXT4-PUBLIC-CROSS-TAIL-UNMOUNTED" THEN'
                ),
            ],
            patches=input_patches
            + ((candidate * block_size, bytes((0xA5,)) * block_size),),
            capture_media=media_path,
        )
        _assert_emitted(output, "EXT4-PUBLIC-CROSS-TAIL-EXACT")
        _assert_emitted(output, "EXT4-PUBLIC-CROSS-TAIL-UNMOUNTED")
        assert trace[: len(activation_trace)] == activation_trace
        assert trace.count(("write", data_block * 2, 2)) == 1
        assert trace.count(("write", candidate * 2, 2)) == 1
        assert trace.count(("write", bitmap_home * 2, 2)) == 1
        assert trace.count(("write", gdt_home * 2, 2)) == 1
        assert trace.count(("write", inode_home * 2, 2)) == 2
        assert trace.count(("write", xattr_block * 2, 2)) == 0
        assert _write_ordinals_for_ext4_home(trace, data_block) == (7,)
        assert _write_ordinals_for_ext4_home(trace, inode_home) == (16, 37)
        assert _write_ordinals_for_ext4_home(trace, candidate) == (22,)

        final_superblock, final_inode, _ = _ext4_inode_record(
            media_path, inode_number
        )
        assert _ext4_block_allocation_state(
            media_path, (candidate,)
        )[candidate]
        assert final_superblock == bytes(expected_super)
        assert struct.unpack_from("<I", final_inode, 0x04)[0] == new_size
        assert struct.unpack_from("<I", final_inode, 0x6C)[0] == 0
        assert struct.unpack_from("<I", final_inode, 0x1C)[0] == 6
        assert struct.unpack_from("<H", final_inode, 0x1A)[0] == old_links
        assert struct.unpack_from("<I", final_inode, 0x64)[0] == old_generation
        assert _extent_root_physical(final_inode, 0) == data_block
        assert _extent_root_physical(final_inode, 1) == candidate
        assert struct.unpack_from("<I", final_inode, 0x68)[0] == xattr_block
        assert _read_ext4_home(
            media_path, data_block, block_size=block_size
        ) == bytes(expected_data)
        assert _read_ext4_home(
            media_path, candidate, block_size=block_size
        ) == expected_candidate
        assert _read_ext4_home(
            media_path, xattr_block, block_size=block_size
        ) == original_xattr
        assert _read_ext4_home(
            media_path, bitmap_home, block_size=block_size
        ) == bytes(expected_bitmap)
        assert _read_ext4_home(
            media_path, gdt_home, block_size=block_size
        ) == bytes(expected_gdt)
        assert _read_ext4_home(
            media_path, inode_home, block_size=block_size
        ) == expected_inode_home

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            media_path,
            stable_path,
            expected_file=expected_file,
            expected_epoch_ms=_STAGED_CROSS_TAIL_SECOND_EPOCH_MS,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=6,
            prefix="_CT-S",
            marker="EXT4-PUBLIC-CROSS-TAIL-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == media_sha256
        return {
            "image": stable_path,
            "source": path,
            "input_patches": input_patches,
            "expected_file": expected_file,
            "replacement": replacement,
            "trace": trace,
            "inode_number": inode_number,
            "inode_home": inode_home,
            "inode_block_offset": inode_block_offset,
            "data_block": data_block,
            "candidate": candidate,
            "bitmap_home": bitmap_home,
            "gdt_home": gdt_home,
            "super_home": super_home,
            "xattr_block": xattr_block,
            "old_size": old_size,
            "new_size": new_size,
            "first_inode_home": first_inode_home,
            "expected_inode_home": expected_inode_home,
            "expected_data": bytes(expected_data),
            "expected_candidate": expected_candidate,
            "expected_bitmap": bytes(expected_bitmap),
            "expected_gdt": bytes(expected_gdt),
            "expected_super": bytes(expected_super),
            "free_blocks_before": free_blocks_before,
            "first_epoch_ms": _STAGED_CROSS_TAIL_FIRST_EPOCH_MS,
            "second_epoch_ms": _STAGED_CROSS_TAIL_SECOND_EPOCH_MS,
            "first_seconds": first_seconds,
            "first_nanoseconds": first_nanoseconds,
        }
    finally:
        media_path.unlink(missing_ok=True)


def test_staged_public_cross_tail_exact_allocates_one_next_block(
    staged_public_cross_tail_exact_fixture: dict[str, object],
) -> None:
    image = staged_public_cross_tail_exact_fixture["image"]
    expected_file = staged_public_cross_tail_exact_fixture["expected_file"]
    replacement = staged_public_cross_tail_exact_fixture["replacement"]
    old_size = staged_public_cross_tail_exact_fixture["old_size"]
    new_size = staged_public_cross_tail_exact_fixture["new_size"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(replacement, bytes)
    assert isinstance(old_size, int)
    assert isinstance(new_size, int)
    assert image.is_file()
    assert len(replacement) == 32
    assert old_size == 1016
    assert new_size == len(expected_file) == 1048
    assert expected_file[old_size:new_size] == replacement


def test_staged_public_cross_tail_exact_passes_external_oracles(
    staged_public_cross_tail_exact_fixture: dict[str, object],
    jbd2_toolchain: dict[str, object],
) -> None:
    image = staged_public_cross_tail_exact_fixture["image"]
    expected_file = staged_public_cross_tail_exact_fixture["expected_file"]
    inode_number = staged_public_cross_tail_exact_fixture["inode_number"]
    data_block = staged_public_cross_tail_exact_fixture["data_block"]
    candidate = staged_public_cross_tail_exact_fixture["candidate"]
    xattr_block = staged_public_cross_tail_exact_fixture["xattr_block"]
    debugfs = jbd2_toolchain["debugfs"]
    env = jbd2_toolchain["env"]
    assert isinstance(image, Path)
    assert isinstance(expected_file, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(data_block, int)
    assert isinstance(candidate, int)
    assert isinstance(xattr_block, int)
    assert isinstance(debugfs, Path)
    assert isinstance(env, dict)

    for target in ("/fixture/payload.txt", "/fixture/hardlink.txt"):
        readback = subprocess.run(
            [str(debugfs), "-R", f"cat {target}", str(image)],
            env=env,
            capture_output=True,
            check=False,
        )
        assert readback.returncode == 0, readback.stdout + readback.stderr
        assert readback.stdout == expected_file

    for logical, physical in ((0, data_block), (1, candidate)):
        mapped = subprocess.run(
            [
                str(debugfs),
                "-R",
                f"bmap /fixture/payload.txt {logical}",
                str(image),
            ],
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        assert mapped.returncode == 0, mapped.stdout + mapped.stderr
        assert int(mapped.stdout.strip().splitlines()[-1]) == physical

    stat = subprocess.run(
        [
            str(debugfs),
            "-R",
            "stat /fixture/payload.txt",
            str(image),
        ],
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )
    assert stat.returncode == 0, stat.stdout + stat.stderr
    assert f"Inode: {inode_number}" in stat.stdout
    assert f"Size: {len(expected_file)}" in stat.stdout
    assert "Flags: 0x80000" in stat.stdout
    assert re.search(r"Links:\s+2\s+Blockcount:\s+6", stat.stdout)
    assert f"File ACL: {xattr_block}" in stat.stdout
    assert f"(0):{data_block}" in stat.stdout
    assert f"(1):{candidate}" in stat.stdout
    _assert_e2fsck_clean(image, jbd2_toolchain)


def test_staged_public_cross_tail_exact_ordered_candidate_tear_preserves_committed_prefix(
    writer_activation_fixture: dict[str, object],
    staged_public_cross_tail_exact_fixture: dict[str, object],
    tmp_path: Path,
) -> None:
    """A torn second-leg candidate cannot erase the committed tail prefix."""
    fixture = staged_public_cross_tail_exact_fixture
    path = fixture["source"]
    input_patches = fixture["input_patches"]
    success_trace = fixture["trace"]
    replacement = fixture["replacement"]
    inode_number = fixture["inode_number"]
    inode_home = fixture["inode_home"]
    data_block = fixture["data_block"]
    candidate = fixture["candidate"]
    bitmap_home = fixture["bitmap_home"]
    gdt_home = fixture["gdt_home"]
    xattr_block = fixture["xattr_block"]
    old_size = fixture["old_size"]
    new_size = fixture["new_size"]
    first_inode_home = fixture["first_inode_home"]
    expected_data = fixture["expected_data"]
    expected_candidate = fixture["expected_candidate"]
    free_blocks_before = fixture["free_blocks_before"]
    first_epoch_ms = fixture["first_epoch_ms"]
    first_seconds = fixture["first_seconds"]
    first_nanoseconds = fixture["first_nanoseconds"]
    journal0_physical = writer_activation_fixture["journal0_physical"]
    guard_physical = writer_activation_fixture["guard_physical"]
    assert isinstance(path, Path)
    assert isinstance(input_patches, tuple)
    assert isinstance(success_trace, tuple)
    assert isinstance(replacement, bytes)
    assert isinstance(inode_number, int)
    assert isinstance(inode_home, int)
    assert isinstance(data_block, int)
    assert isinstance(candidate, int)
    assert isinstance(bitmap_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(xattr_block, int)
    assert isinstance(old_size, int)
    assert isinstance(new_size, int)
    assert isinstance(first_inode_home, bytes)
    assert isinstance(expected_data, bytes)
    assert isinstance(expected_candidate, bytes)
    assert isinstance(free_blocks_before, int)
    assert isinstance(first_epoch_ms, int)
    assert isinstance(first_seconds, int)
    assert isinstance(first_nanoseconds, int)
    assert isinstance(journal0_physical, int)
    assert isinstance(guard_physical, int)

    superblock, inode, _ = _ext4_inode_record(path, inode_number)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    tail_count = block_size - old_size
    remaining_count = len(replacement) - tail_count
    assert block_size == 1024
    assert tail_count == 8
    assert remaining_count == 24
    assert len(expected_data) == block_size
    assert expected_data.endswith(replacement[:tail_count])
    assert _extent_root_physical(inode, 0) == data_block

    original_bitmap = _patched_ext4_home(
        path, input_patches, bitmap_home, block_size=block_size
    )
    original_gdt = _patched_ext4_home(
        path, input_patches, gdt_home, block_size=block_size
    )
    original_xattr = _patched_ext4_home(
        path, input_patches, xattr_block, block_size=block_size
    )
    poisoned_candidate = bytes((0xA5,)) * block_size
    torn_prefix = 512 + 6
    torn_candidate = bytearray(poisoned_candidate)
    torn_candidate[:torn_prefix] = expected_candidate[:torn_prefix]

    candidate_ordinals = _write_ordinals_for_ext4_home(
        success_trace, candidate, block_size=block_size
    )
    assert candidate_ordinals == (22,)
    candidate_event_index = _trace_event_index_for_ordinal(
        success_trace, "write", candidate_ordinals[0]
    )
    assert success_trace[candidate_event_index] == (
        "write",
        candidate * 2,
        2,
    )

    faulted = tmp_path / "staged-cross-tail-w22-faulted.img"
    recovered = tmp_path / "staged-cross-tail-w22-recovered.img"
    stable = tmp_path / "staged-cross-tail-w22-stable.img"
    try:
        output, trace, _ = run_recovery_forth(
            path,
            faulted,
            [
                "CREATE _CTW-STAT VFS-STATFS-SIZE ALLOT",
                (
                    f"CREATE _CTW-CLOCK {first_epoch_ms} , "
                    f"{fixture['second_epoch_ms']} ,"
                ),
                "VARIABLE _CTW-CLOCK-CALLS",
                (
                    ": _CTW-NOW ( clock -- epoch-ms ior ) "
                    "_CTW-CLOCK-CALLS @ CELLS + @ "
                    "1 _CTW-CLOCK-CALLS +! 0 ;"
                ),
                "T-ARENA CONSTANT _CTW-ARENA",
                (
                    "_CTW-ARENA T-VOLUME EXT4-STAGED-WRITE-NEW "
                    "CONSTANT _CTW-MOUNT-IOR CONSTANT _CTW-V"
                ),
                "_CTW-V _EXT4-CTX CONSTANT _CTW-CTX",
                (
                    "' _CTW-NOW _CTW-CLOCK _CTW-V "
                    "EXT4-BIND-WRITE-CLOCK? CONSTANT _CTW-CLOCK-IOR"
                ),
                *_ext4_dedicated_writer_profile_forth(
                    "_CTW-PROFILE", "_CTW-V", 4, 1, 0
                ),
                (
                    'S" /fixture/payload.txt" _CTW-V VFS-RESOLVE? '
                    "CONSTANT _CTW-P-IOR CONSTANT _CTW-P"
                ),
                (
                    'S" /fixture/hardlink.txt" _CTW-V VFS-RESOLVE? '
                    "CONSTANT _CTW-H-IOR CONSTANT _CTW-H"
                ),
                (
                    'S" /fixture/hardlink.txt" '
                    "VFS-FF-READ VFS-FF-WRITE OR VFS-FF-APPEND OR "
                    "_CTW-V VFS-OPEN? "
                    "CONSTANT _CTW-OPEN-IOR CONSTANT _CTW-FD"
                ),
                "_CTW-H D.VNODE @ CONSTANT _CTW-VN",
                "_CTW-FD FD.CUR-LO @ CONSTANT _CTW-INITIAL-CURSOR",
                "_CTW-VN VN.ATIME @ CONSTANT _CTW-OLD-ATIME",
                "_CTW-VN VN.ATIME-NS @ CONSTANT _CTW-OLD-ATIME-NS",
                "_CTW-VN VN.GEN @ CONSTANT _CTW-OLD-GEN",
                "_CTW-VN VN.NLINK @ CONSTANT _CTW-OLD-NLINK",
                (
                    "_CTW-STAT VFS-STATFS-SIZE _CTW-V VFS-STATFS "
                    "CONSTANT _CTW-STAT-BEFORE-IOR"
                ),
                "_CTW-STAT VSF.BFREE @ CONSTANT _CTW-FREE-BEFORE",
                (
                    f'S" {replacement.decode("ascii")}" _CTW-FD '
                    "VFS-WRITE-EXACT CONSTANT _CTW-EXACT-IOR"
                ),
                "_CTW-FD FD.CUR-LO @ CONSTANT _CTW-CURSOR",
                "_CTW-V V.LAST-IOR @ CONSTANT _CTW-LAST-IOR",
                "_CTW-CTX _EXT4-C.J.WRITER + @ CONSTANT _CTW-WRITER",
                "_CTW-ARENA ARENA-USED CONSTANT _CTW-MAIN-AFTER",
                (
                    "_CTW-STAT VFS-STATFS-SIZE _CTW-V VFS-STATFS "
                    "CONSTANT _CTW-STAT-AFTER-IOR"
                ),
                "_CTW-STAT VSF.BFREE @ CONSTANT _CTW-FREE-AFTER",
                "_CTW-FD VFS-CLOSE? CONSTANT _CTW-CLOSE-IOR",
                (
                    _forth_conjunction(
                        [
                            "_CTW-MOUNT-IOR 0=",
                            "_CTW-CLOCK-IOR 0=",
                            "_CTW-PROFILE-SIZE-IOR 0=",
                            "_CTW-PROFILE-BIND-IOR 0=",
                            "_CTW-PROFILE-USED _CTW-PROFILE-SIZE =",
                            "_CTW-P-IOR 0=",
                            "_CTW-H-IOR 0=",
                            "_CTW-P D.VNODE @ _CTW-H D.VNODE @ =",
                            "_CTW-OPEN-IOR 0=",
                            f"_CTW-INITIAL-CURSOR {old_size} =",
                            (
                                "_CTW-EXACT-IOR VFS-IOR-DOMAIN "
                                "VFS-IOR-D-VOLUME ="
                            ),
                            (
                                "_CTW-EXACT-IOR VFS-IOR-REASON "
                                "VFS-R-IO ="
                            ),
                            (
                                "_CTW-EXACT-IOR VFS-IOR-FLAGS "
                                "VFS-IOR-F-PARTIAL "
                                "VFS-IOR-F-READONLY OR ="
                            ),
                            "_CTW-LAST-IOR _CTW-EXACT-IOR =",
                            f"_CTW-CURSOR {block_size} =",
                            "_CTW-CLOCK-CALLS @ 2 =",
                            f"_CTW-VN VN.SIZE-LO @ {block_size} =",
                            "_CTW-VN VN.SIZE-HI @ 0=",
                            "_CTW-VN VN.BLOCKS @ 4 =",
                            "_CTW-VN VN.GEN @ _CTW-OLD-GEN =",
                            "_CTW-VN VN.NLINK @ _CTW-OLD-NLINK =",
                            "_CTW-VN VN.ATIME @ _CTW-OLD-ATIME =",
                            (
                                "_CTW-VN VN.ATIME-NS @ "
                                "_CTW-OLD-ATIME-NS ="
                            ),
                            f"_CTW-VN VN.MTIME @ {first_seconds} =",
                            (
                                f"_CTW-VN VN.MTIME-NS @ "
                                f"{first_nanoseconds} ="
                            ),
                            f"_CTW-VN VN.CTIME @ {first_seconds} =",
                            (
                                f"_CTW-VN VN.CTIME-NS @ "
                                f"{first_nanoseconds} ="
                            ),
                            "_CTW-VN VN.FLAGS @ VFS-IF-DIRTY AND 0=",
                            "_CTW-STAT-BEFORE-IOR 0=",
                            "_CTW-STAT-AFTER-IOR 0=",
                            f"_CTW-FREE-BEFORE {free_blocks_before} =",
                            "_CTW-FREE-AFTER _CTW-FREE-BEFORE =",
                            "_CTW-WRITER _CTW-PROFILE-BASE =",
                            (
                                "_CTW-WRITER _EXT4-JWR.STATE + @ "
                                "_EXT4-JWR-FAULTED ="
                            ),
                            (
                                "_CTW-WRITER _EXT4-JWR.PHASE + @ "
                                "_EXT4-JWP-ORDERED-DATA ="
                            ),
                            "_CTW-WRITER _EXT4-JWR-VALID?",
                            (
                                "_CTW-WRITER _EXT4-JWR.FAULT + @ "
                                "VFS-IOR-FLAGS VFS-IOR-F-PARTIAL ="
                            ),
                            (
                                "_CTW-PROFILE-ARENA ARENA-USED "
                                "_CTW-PROFILE-USED ="
                            ),
                            "_CTW-CTX _EXT4-C.J.HOME-WRITES + @ 1 =",
                            "_CTW-CTX _EXT4-C.RECOVERY + @ 0<>",
                            "_CTW-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0<>",
                            "_CTW-V V.FLAGS @ VFS-F-RO AND 0<>",
                            "_CTW-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                            (
                                "_EXT4-WR-KIND @ "
                                "_EXT4-WRK-ALIGNED-APPEND ="
                            ),
                            f"_EXT4-WR-COUNT @ {remaining_count} =",
                            f"_EXT4-WR-OFFSET @ {block_size} =",
                            f"_EXT4-WR-REQUEST-END @ {new_size} =",
                            f"_EXT4-WR-NEW-SIZE @ {new_size} =",
                            "_EXT4-WR-NEW-BLOCKS @ 4 =",
                            f"_EXT4-WR-CHUNK @ {remaining_count} =",
                            "_EXT4-WR-ACTUAL @ 0=",
                            "_EXT4-MOW-ACTUAL @ 0=",
                            "_EXT4-MOW-CREDIT @ -4 =",
                            f"_XH-CANDIDATE @ {candidate} =",
                            "_XH-PUBLISHED @ 0<",
                            "_EXT4-IO-COMPLETED @ 1 =",
                            "_EXT4-IO-EXPECTED @ 2 =",
                            "_CTW-CLOSE-IOR 0=",
                            (
                                "_EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK "
                                "_EXT4-BYTES-ZERO?"
                            ),
                            "_XB _EXT4-MAX-BLOCK _EXT4-BYTES-ZERO?",
                        ]
                    )
                    + ' IF ." EXT4-PUBLIC-CROSS-TAIL-W22-FAULT" THEN'
                ),
            ],
            patches=input_patches
            + ((candidate * block_size, poisoned_candidate),),
            write_faults_by_ordinal={
                candidate_ordinals[0]: {
                    "stage": "media",
                    "sector_index": 1,
                    "byte_index": 6,
                    "result": STORAGE_RESULT_MEDIA_FAILURE,
                    "command": STORAGE_CMD_WRITE,
                }
            },
            capture_media=faulted,
        )
        _assert_emitted(output, "EXT4-PUBLIC-CROSS-TAIL-W22-FAULT")
        assert trace == success_trace[: candidate_event_index + 1]
        assert _write_ordinals_for_ext4_home(
            trace, data_block, block_size=block_size
        ) == (7,)
        assert _write_ordinals_for_ext4_home(
            trace, inode_home, block_size=block_size
        ) == (16,)
        assert _write_ordinals_for_ext4_home(
            trace, candidate, block_size=block_size
        ) == (22,)
        for untouched_home in (bitmap_home, gdt_home):
            assert not _write_ordinals_for_ext4_home(
                trace, untouched_home, block_size=block_size
            )

        faulted_super, faulted_inode, _ = _ext4_inode_record(
            faulted, inode_number
        )
        assert struct.unpack_from("<I", faulted_super, 0x0C)[0] == (
            free_blocks_before
        )
        assert struct.unpack_from("<I", faulted_inode, 0x04)[0] == block_size
        assert struct.unpack_from("<I", faulted_inode, 0x1C)[0] == 4
        assert _extent_root_physical(faulted_inode, 0) == data_block
        with pytest.raises(AssertionError, match="logical block 1 is unmapped"):
            _extent_root_physical(faulted_inode, 1)
        assert not _ext4_block_allocation_state(
            faulted, (candidate,)
        )[candidate]
        assert _read_ext4_home(
            faulted, data_block, block_size=block_size
        ) == expected_data
        assert _read_ext4_home(
            faulted, inode_home, block_size=block_size
        ) == first_inode_home
        assert _read_ext4_home(
            faulted, candidate, block_size=block_size
        ) == bytes(torn_candidate)
        assert _read_ext4_home(
            faulted, bitmap_home, block_size=block_size
        ) == original_bitmap
        assert _read_ext4_home(
            faulted, gdt_home, block_size=block_size
        ) == original_gdt
        assert _read_ext4_home(
            faulted, xattr_block, block_size=block_size
        ) == original_xattr

        _, recovery_trace, recovery_sha256 = (
            _staged_write_recovery_readback(
                faulted,
                recovered,
                expected_file=expected_data,
                expected_epoch_ms=first_epoch_ms,
                expected_home_writes=0,
                expected_replayed=True,
                expected_blocks=4,
                prefix="_CTW-R",
                marker="EXT4-PUBLIC-CROSS-TAIL-W22-RECOVERED",
            )
        )
        _assert_activation_cleanup_trace(
            recovery_trace,
            journal0_physical=journal0_physical,
            guard_physical=guard_physical,
        )
        _assert_activation_landed_media(
            recovered, writer_activation_fixture, expected_features=0x13
        )
        assert not _ext4_block_allocation_state(
            recovered, (candidate,)
        )[candidate]
        recovered_super, recovered_inode, _ = _ext4_inode_record(
            recovered, inode_number
        )
        assert struct.unpack_from("<I", recovered_super, 0x0C)[0] == (
            free_blocks_before
        )
        assert struct.unpack_from("<I", recovered_inode, 0x04)[0] == block_size
        assert struct.unpack_from("<I", recovered_inode, 0x1C)[0] == 4
        with pytest.raises(AssertionError, match="logical block 1 is unmapped"):
            _extent_root_physical(recovered_inode, 1)
        for home, expected in (
            (data_block, expected_data),
            (inode_home, first_inode_home),
            (candidate, bytes(torn_candidate)),
            (bitmap_home, original_bitmap),
            (gdt_home, original_gdt),
            (xattr_block, original_xattr),
        ):
            assert _read_ext4_home(
                recovered, home, block_size=block_size
            ) == expected

        _, stable_trace, stable_sha256 = _staged_write_recovery_readback(
            recovered,
            stable,
            expected_file=expected_data,
            expected_epoch_ms=first_epoch_ms,
            expected_home_writes=0,
            expected_replayed=False,
            expected_blocks=4,
            prefix="_CTW-S",
            marker="EXT4-PUBLIC-CROSS-TAIL-W22-STABLE",
        )
        assert stable_trace == ()
        assert stable_sha256 == recovery_sha256
        assert not _ext4_block_allocation_state(stable, (candidate,))[candidate]
        _, stable_inode, _ = _ext4_inode_record(stable, inode_number)
        assert struct.unpack_from("<I", stable_inode, 0x04)[0] == block_size
        assert struct.unpack_from("<I", stable_inode, 0x1C)[0] == 4
        assert _read_ext4_home(
            stable, inode_home, block_size=block_size
        ) == first_inode_home
        assert _read_ext4_home(
            stable, candidate, block_size=block_size
        ) == bytes(torn_candidate)
    finally:
        faulted.unlink(missing_ok=True)
        recovered.unlink(missing_ok=True)
        stable.unlink(missing_ok=True)


def test_staged_public_cross_tail_exact_committed_inode_tear_replays_final_state(
    writer_activation_fixture: dict[str, object],
    staged_public_cross_tail_exact_fixture: dict[str, object],
    tmp_path: Path,
) -> None:
    """Replay the committed allocation over a first-leg inode suffix."""
    fixture = staged_public_cross_tail_exact_fixture
    path = fixture["source"]
    input_patches = fixture["input_patches"]
    success_trace = fixture["trace"]
    expected_file = fixture["expected_file"]
    replacement = fixture["replacement"]
    inode_number = fixture["inode_number"]
    inode_home = fixture["inode_home"]
    inode_block_offset = fixture["inode_block_offset"]
    data_block = fixture["data_block"]
