    _, _, new_inode_offset = _ext4_inode_record(path, 33)
    block_size = 1024 << struct.unpack_from("<I", superblock, 0x18)[0]
    parent_inode_home = root_inode_offset // block_size
    new_inode_home = new_inode_offset // block_size
