                        "_CR-CLOCK-CALLS @ 1 =",
                        "_CR-STAT-AFTER-IOR 0=",
                        "_CR-FREE-AFTER _CR-FREE-BEFORE 1- =",
                        "_CR-META-COUNT 6 =",
                        "_CR-INODE 33 =",
                        "_CR-GEN 1 =",
                        "_CR-WRITER-STATE _EXT4-JWR-IDLE =",
                        "_CR-UNMOUNT-IOR 0=",
