                        "_FCH-ADD-HOMES 5 =",
                        "_FCH-AFTER 0=",
                        (
                            "_FCH-AFTER-IOR VFS-IOR-REASON "
                            "VFS-R-NOENT ="
                        ),
                        "_FCH-ADD-NLINK 0=",
                        "_FCH-ADD-OPEN-REFS 1 =",
                        f"_FCH-ADD-SIZE {old_size} =",
                        f"_FCH-ADD-BLOCKS {old_blocks} =",
