def test_ext4_free_block_scan_uses_shared_bounded_queries() -> None:
    source = _ext4_source_text()

    def word_body(name: str) -> str:
        match = re.search(
            rf"(?ms)^:[ \t]+{re.escape(name)}(?=[ \t\r\n(])"
            rf"(?P<body>.*?)[ \t]+;",
            source,
        )
        assert match is not None, f"missing Forth word {name}"
        return match.group("body")

    find_from = word_body("_EXT4-FFB-FIND-CLEAR-FROM")
    scan = word_body("_EXT4-FFB-SCAN-BITMAP")
    recheck = word_body("_EXT4-FFB-REQUIRE-SAME-CLEAR-BIT")

    assert "-1 _EXT4-FFB-FIRST-CLEAR !" in find_from
    assert "_EXT4-FFB-GROUP-BLOCKS @ ROT BITSET-FIND-CLEAR?" in find_from
    assert "2DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT" in find_from
    assert "IF _EXT4-FFB-FIRST-CLEAR ! ELSE DROP THEN" in find_from
    assert scan.count("BITSET-COUNT-SET?") == 1
    assert (
        "_EXT4-FFB-CTX @ _EXT4-C.BLOCK +\n"
        "    _EXT4-FFB-GROUP-BLOCKS @ BITSET-COUNT-SET?"
    ) in scan
    assert "_EXT4-FFB-GROUP-BLOCKS @ SWAP -" in scan
    assert "_EXT4-FFB-GROUP-FREE @ <>" in scan
    assert scan.count("_EXT4-FFB-FIND-CLEAR-FROM") == 2
    assert scan.index("BITSET-COUNT-SET?") < scan.index(
        "_EXT4-FFB-FIND-CLEAR-FROM"
    )
    assert "_EXT4-FFB-FIRST-CLEAR @ -1 = IF 0 EXIT THEN" in scan
    assert "_EXT4-FFB-EXCLUDE-ACTIVE @" in scan
    assert "_EXT4-FFB-GROUP @ _EXT4-FFB-EXCLUDE-GROUP @ = AND" in scan
    assert "_EXT4-FFB-FIRST-CLEAR @ _EXT4-FFB-EXCLUDE-INDEX @ = AND" in scan
    assert "_EXT4-FFB-EXCLUDE-INDEX @ 1+ _EXT4-FFB-FIND-CLEAR-FROM" in scan
    assert (
        "_EXT4-FFB-GROUP-BLOCKS @ _EXT4-FFB-FIRST-CLEAR @ BITSET-TEST?"
        in recheck
    )
    assert "DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT" in recheck
    assert "VFS-E-CONFLICT EXIT" in recheck
    assert "_EXT4-FFB-INDEX" not in source
    assert "_EXT4-FFB-CLEAR-COUNT" not in source


def test_ext4_single_block_allocation_uses_checked_bitset_mutation() -> None:
    source = _ext4_source_text()

    def word_body(name: str) -> str:
        match = re.search(
            rf"(?ms)^:[ \t]+{re.escape(name)}(?=[ \t\r\n(])"
            rf"(?P<body>.*?)[ \t]+;",
            source,
        )
        assert match is not None, f"missing Forth word {name}"
        return match.group("body")

    acquire = word_body("_EXT4-JAB-ACQUIRE-BITMAP")
    stage = word_body("_EXT4-JAB-STAGE-GROUP")
    raw, retained = acquire.split("_EXT4-JTX-META-ACQUIRE", 1)

    assert acquire.count("BITSET-TEST?") == 2
    for view in (raw, retained):
        assert (
            "_EXT4-JAB-GROUP-BLOCKS @ _EXT4-JAB-INDEX @ BITSET-TEST?"
        ) in view
        assert "DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT" in view
    assert "EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT" in raw
    assert "VFS-E-CONFLICT EXIT" in retained
    assert "_EXT4-BIT-RANGE-CLEAR?" not in acquire

    assert (
        "_EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @\n"
        "    _EXT4-JAB-GROUP-BLOCKS @ _EXT4-JAB-INDEX @ BITSET-BIT-SET?"
    ) in stage
    assert "0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN" in stage
    assert stage.index("BITSET-BIT-SET?") < stage.index(
        "_EXT4-BLOCK-BITMAP-CRC"
    ) < stage.index("_EXT4-JTX-META-REPLACE")
    assert "_EXT4-SET-BIT-RANGE" not in stage


def test_ext4_block_range_free_uses_checked_bitset_mutation() -> None:
    source = _ext4_source_text()

    def word_body(name: str) -> str:
        match = re.search(
            rf"(?ms)^:[ \t]+{re.escape(name)}(?=[ \t\r\n(])"
            rf"(?P<body>.*?)[ \t]+;",
            source,
        )
        assert match is not None, f"missing Forth word {name}"
        return match.group("body")

    preflight = word_body("_EXT4-JFB-PREFLIGHT-GROUP")
    after_home = word_body("_EXT4-JFB-PREFLIGHT-GROUP-AFTER-HOME")
    stage = word_body("_EXT4-JFB-STAGE-GROUP")
    staged = word_body("_EXT4-JFB-STAGE-PREFLIGHTED")

    for body in (preflight, after_home):
        raw, retained = body.split("_EXT4-JTX-META-ACQUIRE", 1)
        assert body.count("BITSET-ALL-SET?") == 2
        for view in (raw, retained):
            assert (
                "_EXT4-JFB-GROUP-BLOCKS @\n"
                "    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ "
                "BITSET-ALL-SET?"
            ) in view
            assert "DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT" in view
        assert "EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT" in raw
        assert "VFS-E-CONFLICT EXIT" in retained
        assert "_EXT4-BIT-RANGE-SET?" not in body

    assert (
        "_EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @\n"
        "    _EXT4-JFB-GROUP-BLOCKS @\n"
        "    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ "
        "BITSET-RANGE-CLEAR?"
    ) in stage
    assert "0= IF\n        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT\n    THEN" in stage
    mutation = stage.index("BITSET-RANGE-CLEAR?")
    crc_calls = [
        match.start()
        for match in re.finditer("_EXT4-BLOCK-BITMAP-CRC", stage)
    ]
    assert len(crc_calls) == 2
    assert crc_calls[0] < mutation < crc_calls[1]
    assert mutation < stage.index("_EXT4-JFB-ACQUIRE-DESC")
    assert mutation < stage.index("_EXT4-JTX-META-REPLACE")
    assert "_EXT4-CLEAR-BIT-RANGE" not in stage
    assert (
        "_EXT4-JFB-STAGE-GROUP ?DUP IF\n"
        "            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT"
    ) in staged


def test_ext4_block_allocation_reads_use_exact_checked_bitset_views() -> None:
    source = _ext4_source_text()

    def word_body(name: str) -> str:
        match = re.search(
            rf"(?ms)^:[ \t]+{re.escape(name)}(?=[ \t\r\n(])"
            rf"(?P<body>.*?)[ \t]+;",
            source,
        )
        assert match is not None, f"missing Forth word {name}"
        return match.group("body")

    assert source.count(": _EXT4-UADD?") == 1
    assert source.count(": _EXT4-UMUL?") == 1
    assert source.count(": _EXT4-GROUP-BLOCK-COUNT") == 1
    assert source.index(": _EXT4-UADD?") < source.index(
        ": _EXT4-GROUP-BLOCK-COUNT"
    ) < source.index(": _EXT4-BLOCK-ALLOCATED?")
    assert source.index(": _EXT4-UMUL?") < source.index(
        ": _EXT4-GROUP-BLOCK-COUNT"
    )

    allocated = word_body("_EXT4-BLOCK-ALLOCATED?")
    allocated_range = word_body("_EXT4-REQUIRE-ALLOCATED-RANGE")

    assert allocated.count("_EXT4-GROUP-BLOCK-COUNT") == 1
    assert (
        "_EXT4-BA-GROUP-BLOCKS @ _EXT4-BA-INDEX @ BITSET-TEST?"
        in allocated
    )
    assert "DROP FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT" in allocated
    assert "_EXT4-BG-BLOCK-UNINIT AND IF FALSE 0 EXIT THEN" in allocated

    assert allocated_range.count("_EXT4-GROUP-BLOCK-COUNT") == 1
    assert (
        "_EXT4-RAR-FIRST @ _EXT4-RAR-CTX @ _EXT4-C.FIRST + @ U< IF"
        in allocated_range
    )
    assert (
        "_EXT4-RAR-INDEX @ _EXT4-RAR-GROUP-BLOCKS @ U< 0= IF"
        in allocated_range
    )
    assert (
        "_EXT4-RAR-GROUP-BLOCKS @ _EXT4-RAR-INDEX @ -\n"
        "        _EXT4-RAR-REMAIN @ MIN _EXT4-RAR-CHUNK !"
        in allocated_range
    )
    assert (
        "_EXT4-RAR-GROUP-BLOCKS @\n"
        "        _EXT4-RAR-INDEX @ _EXT4-RAR-CHUNK @ "
        "BITSET-ALL-SET?"
        in allocated_range
    )
    assert "DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT" in allocated_range
    assert "0= IF _EXT4-RAR-DETAIL @ _EXT4-CORRUPT EXIT THEN" in (
        allocated_range
    )
    for body in (allocated, allocated_range):
        assert "C@" not in body
        assert "LSHIFT" not in body
        assert "?DO" not in body
        assert "UNLOOP" not in body


